CREATE VIEW [dbo].[Chengxing_View] AS select A.BARCODE,A.FAC,B.BOMDIV DIV ,B.ITNBR,B.ITDSC,LOTID,a.BUDAT WDAT,a.BUTIM WTIM,a.BUSHT WSHT,a.BUBAN WBAN,a.BUMCH MCHID,A.BUNAMCOD,A.BUNAM WNAM,BUITNBR,BUITDSC,A.SPEC BUSPEC 
