	DROP VIEW [dbo].[CU_TRANS_ANGLE]
GO

CREATE VIEW [dbo].[CU_TRANS_ANGLE] AS SELECT TOP 1000
	STA0012.RECIPE_ID,
	STA0012.FAC,
	STA0012.RECIPE_NAME,
	STA0013.ANGLE,
	STA0013.TEST_NUM 
FROM
	STA0012
	LEFT JOIN STA0013 ON STA0012.RECIPE_ID = STA0013.RECIPE_ID 
WHERE
	STA0012.IS_USE = 0
	ORDER BY STA0012.FAC,STA0012.RECIPE_ID ASC
GO


-- ----------------------------
-- View structure for CX_Schedule
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CX_Schedule]') AND type IN ('V'))
	DROP VIEW [dbo].[CX_Schedule]
GO

CREATE VIEW [dbo].[CX_Schedule] AS select PPB0202.ITNBR,PPB0202.ITDSC,PPB0202.LDIV,PPB0202.BOMDIV,lta0001.BUITDSC,lta0001.BUITNBR,lta0001.BUMCH,lta0001.BUPLANCOD,lta0001.SPEC,lta0001.BARCODE,LTA0001.BUNAM,lta0001.BUNAMCOD
 from PPB0202 , PPB0201 , lta0001
 where PPB0202.ITEMID=PPB0201.id
 and LTA0001.BUPLANCOD<>''
 and PPB0202.FAC='02'
 and lta0001.FAC=PPB0202.FAC
 and PPB0202.FAC=PPB0201.FAC
 and  PPB0201.ORDERNOB=LTA0001.BUPLANCOD
 union all
 select  PPB0202.ITNBR,PPB0202.ITDSC,PPB0202.LDIV,PPB0202.BOMDIV,lta0001.BUITDSC,lta0001.BUITNBR,lta0001.BUMCH,lta0001.BUPLANCOD,lta0001.SPEC,lta0001.BARCODE,LTA0001.BUNAM,lta0001.BUNAMCOD 
 from PPB0202 , PPB0201 , lta0001
 where PPB0202.ITEMID=PPB0201.id
 and LTA0001.BUPLANCOD<>''
 and PPB0202.FAC='02'
 and lta0001.FAC=PPB0202.FAC
 and PPB0202.FAC=PPB0201.FAC
 and  PPB0201.ORDERNOA=LTA0001.BUPLANCOD
 union all
 select  PPB0202.ITNBR,PPB0202.ITDSC,PPB0202.LDIV,PPB0202.BOMDIV,lta0001.BUITDSC,lta0001.BUITNBR,lta0001.BUMCH,lta0001.BUPLANCOD,lta0001.SPEC,lta0001.BARCODE,LTA0001.BUNAM,lta0001.BUNAMCOD 
 from PPB0202 , PPB0201 , lta0001
 where PPB0202.ITEMID=PPB0201.id
 and LTA0001.BUPLANCOD<>''
 and PPB0202.FAC='02'
 and lta0001.FAC=PPB0202.FAC
 and PPB0202.FAC=PPB0201.FAC
 and PPB0201.ORDERNOC=LTA0001.BUPLANCOD
GO


