      ,[BARCODE]
      ,[ITNBR]
      ,[ITDSC]
      ,[STA] 
      ,[WDATE]
      ,[WTIME] 
      ,[STOAREA]
      ,[INLOC]
      ,[VERSION]
      ,[CRTIM]
      ,[SPEC]
      ,[IS_LOCK]
      ,[REMARK]  
  FROM [dbo].[WIP0002] WITH(NOLOCK) WHERE ISNULL(IS_DELETE,0)=0 AND SPEC<>''  and ISNULL(GTDIV,'2')='2'
GO


