GO

CREATE VIEW [dbo].[GT_InventorySumly_View] AS SELECT FAC,SPEC,COUNT(*) QTY FROM WIP0002 WITH(NOLOCK) WHERE  IS_DELETE is not null and IS_DELETE=0 AND  isnull(GTDIV,'2')='2' AND SPEC<>'' GROUP BY SPEC,FAC
GO


