CREATE VIEW [dbo].[GT_ProdCompletion_View] AS SELECT  FAC, MCHID, SEQ, SPEC, WDATE, WSHT, PLANCOD, ITNBR, VERSION, SUM(PLLOT) AS PLLOT, SUM(MESLOT) 
                   AS MESLOT
FROM      dbo.PAD0201_GT
GROUP BY FAC, MCHID, SEQ, SPEC, WDATE, WSHT, PLANCOD, ITNBR, VERSION
GO


-- ----------------------------
-- View structure for GTPLAN_ACT_VIEW
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GTPLAN_ACT_VIEW]') AND type IN ('V'))
	DROP VIEW [dbo].[GTPLAN_ACT_VIEW]
GO

CREATE VIEW [dbo].[GTPLAN_ACT_VIEW] AS SELECT
    p.FAC,
    p.PLANCOD,
    p.MCHID,
    p.ITNBR,
    p.WSHT,
    p.PLQTY,
    p.MESQTY AS REQTY,
    p.STA,
    p.WDATE,
    t.butim AS BUTIM
FROM dbo.PAD0201 p WITH(NOLOCK)
OUTER APPLY (
    SELECT TOP 1 butim
    FROM dbo.LTA0001 t WITH(NOLOCK)
    WHERE t.FAC = p.FAC
      AND t.BUPLANCOD = p.PLANCOD
      AND t.BUDAT = p.WDATE
      AND t.BUPLANCOD <> ''
    ORDER BY t.butim ASC
) t
WHERE p.ATTRIBUTE1 = 'GT'
  --AND p.WDATE BETWEEN '2026-07-27' AND '2026-07-28'
  --AND p.fac = '02';
GO


