-- ----------------------------
-- View structure for HALF_InventoryDetail_View
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[HALF_InventoryDetail_View]') AND type IN ('V'))
	DROP VIEW [dbo].[HALF_InventoryDetail_View]
GO

CREATE VIEW [dbo].[HALF_InventoryDetail_View] AS SELECT  A.FAC, A.DIV, B.ITTYPENAM, A.LOTID, A.MCHID, A.WSHT, A.WBAN, A.ITNBR, A.ITDSC, A.TOOLNO, A.QTY, A.STA, A.WDATE, 
                   A.WTIME, A.STKSTS, A.STOAREA, A.INLOC, A.LOCKYN, A.LR, A.REMARK, A.TOOLSTA, A.USEMCH, A.ERPCODE, A.STONO, 
                   A.STOAREANO, C.REMARK AS WE, L.ORDERNO, CASE WHEN ST.CARTID IS NULL THEN A.CARTYPE ELSE ST.CARTTYPE END  CARTYPE, A.REMARK4
FROM      dbo.WIP0001(nolock) AS A LEFT OUTER JOIN
                   dbo.EDD0003(nolock) AS B ON A.DIV = B.ITTYPECOD LEFT OUTER JOIN
                       (SELECT DISTINCT a.LOCATION, b.REMARK, a.FAC, a.STOAREA
                        FROM       dbo.STA0001(nolock) AS a LEFT OUTER JOIN
                                           dbo.STA0111(nolock) AS b ON a.STOAREA = b.STOAREA where b.DIV not in ('99')) AS C ON A.INLOC = C.LOCATION AND A.FAC = C.FAC AND 
                   A.STOAREA = C.STOAREA LEFT JOIN
                   dbo.LTC0001(nolock) AS L ON A.LOTID = L.LOTID
									 LEFT JOIN ( select ROW_NUMBER() OVER (PARTITION BY newlotId ORDER BY crtim )lotseq ,* from  WIP0032 where IS_BCAK=0) AS CJ  on A.lotid=CJ.NEWLOTID and  CJ.lotseq=1
				   LEFT JOIN STA0002(nolock) ST ON A.TOOLNO=ST.CARTID AND a.FAC=st.FAC AND ST.FAC in ('03','01')
WHERE   (ISNULL(A.IS_DELETE, 0) = 0) AND (A.ITNBR <> '') AND (L.LOTID IS NOT NULL OR CJ.NEWLOTID IS NOT NULL) AND B.ITTYPENAM IS NOT NULL
GO


-- ----------------------------
-- View structure for HALF_InventoryDetailUP_View
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[HALF_InventoryDetailUP_View]') AND type IN ('V'))
	DROP VIEW [dbo].[HALF_InventoryDetailUP_View]
GO

CREATE VIEW [dbo].[HALF_InventoryDetailUP_View] AS SELECT * FROM (
select A.FAC FAC,A.BARCODE LOTID,A.OPDIV OPDIV,A.CRTIM CRTIM,A.MSG MSG,B.ITNBR,B.ITDSC,B.QTY,B.TOOLNO from LT_OPERATE(nolock) AS  A 
INNER JOIN WIP0001 (nolock) AS B ON A.FAC = B.FAC AND B.LOTID = A.BARCODE
WHERE A.CRTIM BETWEEN GETDATE()-1 AND GETDATE() AND OPDIV = 'UPD'
UNION
select A.FAC FAC,A.BARCODE LOTID,A.OPDIV OPDIV,A.CRTIM CRTIM,A.MSG MSG,'' ITNBR,''ITDSC, 0 QTY,''TOOLNO from LT_OPERATE(nolock) AS A 
INNER JOIN WIP0001 (nolock) AS B ON A.FAC = B.FAC AND B.LOTID = A.BARCODE
WHERE A.CRTIM BETWEEN GETDATE()-1 AND GETDATE() AND OPDIV = 'DEL'
) AS HALF_InventoryDetailUP_View_1
GO


-- ----------------------------
-- View structure for HALF_InventorySumly_View
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[HALF_InventorySumly_View]') AND type IN ('V'))
	DROP VIEW [dbo].[HALF_InventorySumly_View]
GO

CREATE VIEW [dbo].[HALF_InventorySumly_View] AS SELECT  DIV, COUNT(ID) AS MESLOT, FAC, ITNBR, DIV AS Expr1, SUM(QTY) AS QTY, CASE WHEN DIV IN ('TD', 'PTQ', 'PBW', 'BDR', 
                   'PD', 'BD', 'BDW', 'TR') THEN 'EA' ELSE 'M' END AS UNIT
FROM      dbo.WIP0001 WITH (nolock)
WHERE   (ISNULL(IS_DELETE, 0) = 0) AND (ITNBR <> '')
GROUP BY FAC, ITNBR, DIV
GO


