-- ----------------------------
-- View structure for LH_ANGLE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LH_ANGLE]') AND type IN ('V'))
	DROP VIEW [dbo].[LH_ANGLE]
GO

CREATE VIEW [dbo].[LH_ANGLE] AS SELECT MCHID,LR,ITNBR,JD FROM (SELECT ROW_NUMBER() OVER (  
            PARTITION BY MCHID, LR,ITNBR  
            ORDER BY TOTAL DESC, CW_RFV_OA_AMOUNTa, CW_RFV_OA_AMOUNTc, CW_RFV_OA_AMOUNTb 
        ) AS rn ,MCHID,LR,ITNBR,JD,RO,UF,DB,TOTAL,CW_RFV_OA_AMOUNTa,CW_RFV_OA_AMOUNTb,CW_RFV_OA_AMOUNTc FROM (SELECT COUNT(*) OVER (PARTITION BY MCHID,LR,ITNBR) AS SL,* FROM (SELECT COUNT(*) OVER (PARTITION BY MCHID,LR,ITNBR) AS PFSL,A.*,B.JD,B.TEST_NUM from (select MCHID,LR,ITNBR,ANGLE AS PFANGLE  from EDC0020 WHERE  FAC ='02' AND ITNBR IS NOT NULL AND ITNBR !='') A  left join (select RECIPE_ID,ANGLE AS JD,TEST_NUM from STA0013 where fac='02') B ON A.PFANGLE=B.RECIPE_ID WHERE JD IS NOT NULL )A LEFT JOIN(
SELECT
		MATERCODE,
		SulfEquipCode,
		LeftOrRight,
		ANGLE,
		COUNT,
		ROUND( CAST ( RO AS FLOAT ) / COUNT * 100, 2 ) AS RO,
		ROUND( CAST ( UF AS FLOAT ) / COUNT * 100, 2 ) AS UF,
		ROUND( CAST ( DB AS FLOAT ) / COUNT * 100, 2 ) AS DB,
		ROUND( CAST ( TOTAL AS FLOAT ) / COUNT * 100, 2 ) AS TOTAL,
		CW_RFV_OA_AMOUNTa,
		CW_RFV_OA_AMOUNTb,
		CW_RFV_OA_AMOUNTc
	FROM
		(
		SELECT
			A.MaxTime,
			A.MinTime,
			A.BUITNBR,
			A.MATERCODE,
			A.SulfEquipCode,
			A.LeftOrRight,
			A.ANGLE,
			COUNT ( * ) AS COUNT,
			SUM ( CASE WHEN A.RO_RANK_2= '1' THEN 1 ELSE 0 END ) AS RO,
			SUM ( CASE WHEN A.UF_RANK_2= '1' THEN 1 ELSE 0 END ) AS UF,
			SUM ( CASE WHEN A.DB_RANK_2= '1' THEN 1 ELSE 0 END ) AS DB,
			SUM ( CASE WHEN A.UFDBRANK_2= '1' THEN 1 ELSE 0 END ) AS TOTAL,
			CAST ( ROUND( AVG ( A.CW_RFV_OA_AMOUNT ), 2 ) AS DECIMAL ( 10, 2 ) ) AS CW_RFV_OA_AMOUNTa,
			CAST ( ROUND( MAX ( A.CW_RFV_OA_AMOUNT ) - MIN ( A.CW_RFV_OA_AMOUNT ), 2 ) AS DECIMAL ( 10, 2 ) ) AS CW_RFV_OA_AMOUNTb,
			CAST ( ROUND( STDEV( A.CW_RFV_OA_AMOUNT ), 2 ) AS DECIMAL ( 10, 2 ) ) AS CW_RFV_OA_AMOUNTc
		FROM
			(
			SELECT MAX
				( CASE WHEN MaxTime1 IS NULL THEN '4444-01-01 00:00:00.000' ELSE MaxTime1 END ) OVER ( PARTITION BY BUITNBR, MATERCODE, SulfEquipCode, LeftOrRight ) AS MaxTime,* 
			FROM
				(
				SELECT MAX
					( CASE WHEN CountTime = 3 THEN UPLOADTIME ELSE NULL END ) OVER ( PARTITION BY BUITNBR, MATERCODE, SulfEquipCode, LeftOrRight, ANGLE ) AS MaxTime1,* 
				FROM
					(
					SELECT
						ROW_NUMBER ( ) OVER ( PARTITION BY BUITNBR, MATERCODE, SulfEquipCode, LeftOrRight, ANGLE ORDER BY UPLOADTIME ) AS CountTime,
						MIN ( BeginTime ) OVER ( PARTITION BY BUITNBR, MATERCODE, SulfEquipCode, LeftOrRight ) AS MinTime,* 
					FROM
						( SELECT * FROM UBTestHistory WHERE UPLOADTIME BETWEEN DATEADD(DAY, -1, GETDATE()) AND GETDATE()) A
						LEFT JOIN (
						SELECT
							TyreNo,
							CASE 
								WHEN CHARINDEX('-', ISNULL(BUITNBR,'')) > 0 
								THEN LEFT(BUITNBR, CHARINDEX('-', BUITNBR) - 1)
								ELSE BUITNBR 
							END AS BUITNBR,
							SulfEquipCode,
							LeftOrRight,
							WDATE AS BWDATE,
							SulfShift AS BWSHT,
							SulfTeam AS BWBAN,
						CASE
								
								WHEN CureCode IS NULL THEN
								MaterialID ELSE CureCode 
							END AS BDITNBR,
							MaterialName AS BDITDSC,
							BeginTime,
							MouldID AS BMouldID 
						FROM
							tb_PP_CuringOutPut PP
							LEFT JOIN (
							SELECT
								B.ITNBR SapCode,
								C.CureCode 
							FROM
								(
								SELECT
									A.ITNBR,
									A.ITDSC,
									ATTRVAL 
								FROM
									( SELECT ID, ITNBR, ITDSC, ROW_NUMBER ( ) OVER ( PARTITION BY ITNBR ORDER BY CRTIM DESC ) N FROM EDD0001 ) A
									LEFT JOIN EDD0002 B ON A.ID= B.ITEMID 
								WHERE
									N = '1' 
									AND ATTRCOD = 'PCSReprocessingMethod' 
									AND ATTRVAL != '' 
								) B
								LEFT JOIN EDD0025 C ON B.ITNBR = C.SapCode 
							) PF ON PF.SapCode= PP.MaterialID 

						) B ON A.BARCODE= B.TyreNo
						LEFT JOIN ( SELECT BARCODE AS EBARCODE, BUMCH AS EBUMCH FROM LTA0001 ) E ON E.EBARCODE= A.BARCODE
						LEFT JOIN ( SELECT BARCODE AS COD, ANGLE FROM QMB0025 ) C ON A.BARCODE= C.COD 
					WHERE
						ANGLE IS NOT NULL 
						AND BUITNBR IS NOT NULL 
					) A 
				) A 
			) A 
		GROUP BY
			MaxTime,
			MinTime,
			BUITNBR,
			MATERCODE,
			SulfEquipCode,
			LeftOrRight,
			ANGLE 
		) A 
	)B ON B.SulfEquipCode=A.MCHID AND B.MATERCODE=A.ITNBR AND B.LeftOrRight=A.LR AND B.ANGLE=A.JD AND B.COUNT>=A.TEST_NUM WHERE MATERCODE IS NOT NULL)A WHERE SL=PFSL AND ITNBR IN (SELECT ITNBR from
(
SELECT  ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId,* from EDD0001
 )A INNER JOIN EDD0002 B ON A.ID = B.ITEMID AND A.FAC = B.FAC
WHERE  A.RowId=1 AND A.FAC = '02' AND ITGRPCOD = 'FERT'  AND ATTRCOD ='PCSPCROE' and B.ATTRVAL='Y') )A WHERE rn=1
GO


