	DROP VIEW [dbo].[MaterialVersion_View]
GO

CREATE VIEW [dbo].[MaterialVersion_View] AS with tby as
(select ITNBR,ITDSC,VERSION,CLASSDIV,ITGRPCOD
      from(SELECT  ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId,* from EDD0001 
           where   SHFLAG='Y'   and ITGRPCOD='GT'   AND IS_USE=0 
				) A WHERE  A.RowId=1  ),
tb as
(select ITNBR,ITDSC,VERSION,CLASSDIV,ITGRPCOD
      from(SELECT  ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId,* from EDD0001 
           where      ITGRPCOD='GT'    AND IS_USE=0
				) A WHERE  A.RowId=1 )
select tb.*,tby.VERSION as VERSION_Y from tb left join tby on tb.ITNBR=tby.ITNBR 
 UNION ALL
select ITNBR,ITDSC,VERSION,CLASSDIV,ITGRPCOD,VERSION as VERSION_Y
      from(SELECT  ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId,* from EDD0001 
           where     ITGRPCOD<>'GT'    AND IS_USE=0
				) A WHERE  A.RowId=1
GO


