-- ----------------------------
-- View structure for Nonconforming_Inspection_Result
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Nonconforming_Inspection_Result]') AND type IN ('V'))
	DROP VIEW [dbo].[Nonconforming_Inspection_Result]
GO

CREATE VIEW [dbo].[Nonconforming_Inspection_Result] AS SELECT mater_Code,CONVERT(NVARCHAR(10),plan_date, 120) plan_date,Equip_Code,S10 as REMARK ,S20 as BZBZ,CheckEquip,Check_ID,
case when shift_id = '1' then '夜班'
     when shift_id = '2' then '白班'
     else '中班' end SHT,serial_id,CONVERT(DECIMAL(8,2),ML)ML,CONVERT(DECIMAL(8,2),MH)MH,CONVERT(DECIMAL(8,2),T30)T30,
CONVERT(DECIMAL(8,2),T60)T60,CONVERT(DECIMAL(8,2),T95)T95,
SUBSTRING (FinalCheck_result,1,1) S1,SUBSTRING ( FinalCheck_result,2,1) S2,SUBSTRING ( FinalCheck_result,3,1) S3,SUBSTRING ( FinalCheck_result,4,1) S4,SUBSTRING ( FinalCheck_result,5,1) S5, FinalCheck_result Res,
(CONVERT(NVARCHAR(20),Check_time,120)+'/'+Worker_barcode)Worker_barcodeInfo,CONVERT(DECIMAL(8,3),BZ) BZ,CONVERT(DECIMAL(8,1),YD) YD, Check_time,check_date,shift_id DCOD,
CASE WHEN PATINDEX('%*%', Test_type)>0 THEN SUBSTRING(Test_type,1,PATINDEX('%*%', Test_type)-1) ELSE '' END Temperature,
CASE WHEN PATINDEX('%*%', Test_type)>0 THEN SUBSTRING(Test_type,PATINDEX('%*%', Test_type)+1,LEN(Test_type)-PATINDEX('%*%', Test_type)) ELSE '' END Duration,
   (SELECT CASE 
   WHEN BZ=0 THEN NULL
   WHEN BZ<q2.LWVALUE_M OR BZ>q2.UPRVALUE_P THEN '不合格'
   END S6
  FROM QMA0007 AS q
  INNER JOIN QMA0011 AS q2 ON q.ID=q2.[SID]
  WHERE q.ITNBR=mater_Code AND q2.PID='BZ') BZJG,
   (SELECT CASE 
    WHEN YD=0 THEN NULL
   WHEN YD<q2.LWVALUE_M OR YD>q2.UPRVALUE_P THEN '不合格'
   END S7
  FROM QMA0007 AS q
  INNER JOIN QMA0011 AS q2 ON q.ID=q2.[SID]
  WHERE q.ITNBR=mater_Code AND q2.PID='YD') YDJG,
FinalCheck_result Judge,CLASSDIV FROM (
SELECT * FROM (
SELECT X.*,Y.item_cd,Y.Item_check,Z.YD,Z.BZ,M.S10,N.S20 FROM (
SELECT A.*,ROW_NUMBER() OVER (PARTITION BY A.plan_date,A.Equip_Code,A.shift_id,A.mater_Code,A.serial_id ORDER BY Check_time DESC) RN FROM QMD0005 A
INNER JOIN QMD0009 B 
ON A.plan_date=B.plan_date 
AND A.Equip_Code=B.Equip_Code 
AND A.shift_id=B.shift_id 
AND A.mater_Code=B.mater_Code 
AND A.serial_id=B.serial_id 
AND Test_type Not in ('ML(1+4)','ML ( 1+4 )','ML(1+8)','门尼','门尼结果')
WHERE (A.FinalCheck_result<>'VVVVVV' and  A.FinalCheck_result<>'' AND B.FinalCheck_result!='合格') or ( BZJG = '不合格'  or YDJG = '不合格' )
) X
INNER JOIN QMD0006 Y ON X.Seq_no=Y.Seq_no
INNER JOIN ( SELECT q.ITNBR,(convert(NVARCHAR(10),CONVERT(DECIMAL(8,1),q2.LWVALUE_M))+'~'+convert(NVARCHAR(10),CONVERT(DECIMAL(8,1),q2.UPRVALUE_P))) S10 FROM QMA0007 AS q INNER JOIN QMA0011 AS q2 ON q.ID=q2.[SID] WHERE q2.PID IN('YD')) AS M on X.mater_Code = M.ITNBR
INNER JOIN ( SELECT q.ITNBR,(convert(NVARCHAR(10),CONVERT(DECIMAL(8,3),q2.LWVALUE_M))+'~'+convert(NVARCHAR(10),CONVERT(DECIMAL(8,3),q2.UPRVALUE_P))) S20 FROM QMA0007 AS q INNER JOIN QMA0011 AS q2 ON q.ID=q2.[SID] WHERE q2.PID IN('BZ')) AS N on X.mater_Code = N.ITNBR
INNER JOIN QMD0009 Z ON X.plan_date=Z.plan_date and X.Equip_Code=Z.Equip_Code and X.shift_id=Z.shift_id and X.mater_Code=Z.mater_Code and X.serial_id=Z.serial_id  
WHERE X.RN=1
) T
PIVOT 
(
  AVG(T.Item_check) FOR 
    T.item_cd IN ([ML],[MH],[T30],[T60],[T95])
) T1
) T2
GO


-- ----------------------------
-- View structure for Nonconforming_Inspection_Result_MN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Nonconforming_Inspection_Result_MN]') AND type IN ('V'))
	DROP VIEW [dbo].[Nonconforming_Inspection_Result_MN]
GO

CREATE VIEW [dbo].[Nonconforming_Inspection_Result_MN] AS SELECT mater_Code,CONVERT(NVARCHAR(10),plan_date, 120) plan_date,Equip_Code,
case when shift_id = '1' then '夜班'
     when shift_id = '2' then '白班'
     else '中班' end SHT,serial_id,CONVERT(DECIMAL(8,2),ML)ML,CONVERT(DECIMAL(8,2),MH)MH,CONVERT(DECIMAL(8,2),T30)T30,
CONVERT(DECIMAL(8,2),T60)T60,CONVERT(DECIMAL(8,2),T95)T95,
SUBSTRING (FinalCheck_result,1,1) S1,SUBSTRING ( FinalCheck_result,2,1) S2,SUBSTRING ( FinalCheck_result,3,1) S3,SUBSTRING ( FinalCheck_result,4,1) S4,SUBSTRING ( FinalCheck_result,5,1) S5, FinalCheck_result Res,
(CONVERT(NVARCHAR(20),Check_time,120)+'/'+Worker_barcode)Worker_barcodeInfo,CONVERT(DECIMAL(8,3),BZ) BZ,CONVERT(DECIMAL(8,1),YD) YD, Check_time,check_date,shift_id DCOD,CheckEquip,
CASE WHEN PATINDEX('%*%', Test_type)>0 THEN SUBSTRING(Test_type,1,PATINDEX('%*%', Test_type)-1) ELSE '' END Temperature,
CASE WHEN PATINDEX('%*%', Test_type)>0 THEN SUBSTRING(Test_type,PATINDEX('%*%', Test_type)+1,LEN(Test_type)-PATINDEX('%*%', Test_type)) ELSE '' END Duration,
   (SELECT CASE 
   WHEN BZ=0 THEN NULL
   WHEN BZ<q2.LWVALUE_M OR BZ>q2.UPRVALUE_P THEN '不合格'
   END S6
  FROM QMA0007 AS q
  INNER JOIN QMA0011 AS q2 ON q.ID=q2.[SID]
  WHERE q.ITNBR=mater_Code AND q2.PID='BZ') BZJG,
   (SELECT CASE 
    WHEN YD=0 THEN NULL
   WHEN YD<q2.LWVALUE_M OR YD>q2.UPRVALUE_P THEN '不合格'
   END S7
  FROM QMA0007 AS q
  INNER JOIN QMA0011 AS q2 ON q.ID=q2.[SID]
  WHERE q.ITNBR=mater_Code AND q2.PID='YD') YDJG,
FinalCheck_result Judge,CLASSDIV FROM (
SELECT * FROM (
SELECT X.*,Y.item_cd,Y.Item_check,Z.YD,Z.BZ FROM (
SELECT A.*,ROW_NUMBER() OVER (PARTITION BY A.plan_date,A.Equip_Code,A.shift_id,A.mater_Code,A.serial_id ORDER BY Check_time DESC) RN FROM QMD0005 A
INNER JOIN QMD0009 B 
ON A.plan_date=B.plan_date 
AND A.Equip_Code=B.Equip_Code 
AND A.shift_id=B.shift_id 
AND A.mater_Code=B.mater_Code 
AND A.serial_id=B.serial_id 
WHERE A.FinalCheck_result<>'VVVVVV' and  A.FinalCheck_result<>'' 
AND B.FinalCheck_result='不合格' 
) X
INNER JOIN QMD0006 Y ON X.Seq_no=Y.Seq_no
INNER JOIN QMD0009 Z ON X.plan_date=Z.plan_date and X.Equip_Code=Z.Equip_Code and X.shift_id=Z.shift_id and X.mater_Code=Z.mater_Code and X.serial_id=Z.serial_id  
WHERE X.RN=1
) T
PIVOT 
(
  AVG(T.Item_check) FOR 
    T.item_cd IN ([ML],[MH],[T30],[T60],[T95])
) T1
) T2
GO


