-- ----------------------------
-- View structure for TestTireOut
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[TestTireOut]') AND type IN ('V'))
	DROP VIEW [dbo].[TestTireOut]
GO

CREATE VIEW [dbo].[TestTireOut] AS SELECT  ID, FAC, DIV, OUTREASON, BARCODE, TyreNo, LRFLAG, MCHID, ITNBR, ITDSC, WDATE, WTIME, WSHT, WBAN, 
                   COLLECTTIM, DOT, ENAM, LOGINNAM, UPDTIM, CRTIM, REMARK, STA, CONFIRMER, CONFIRMERTIM, RETURNNAM, 
                   RETURNTIM, RETURNREASON, REMARK1, REMARK2, REMARK3, REMARK4, REMARK5, CUSTATE, FLAG
FROM      dbo.STC0053
WHERE   (DIV = 1) AND (TyreNo NOT IN
                       (SELECT  TYRENO
