-- ----------------------------
-- View structure for V_EDD0001_MAXVERSION
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_EDD0001_MAXVERSION]') AND type IN ('V'))
	DROP VIEW [dbo].[V_EDD0001_MAXVERSION]
GO

CREATE VIEW [dbo].[V_EDD0001_MAXVERSION] AS WITH CTE AS (
    SELECT *,
           TRY_CAST([VERSION] AS INT) AS VersionNumber,
           CASE WHEN TRY_CAST([VERSION] AS INT) IS NULL THEN 1 ELSE 0 END AS IsAlphaVersion,
           ROW_NUMBER() OVER (
               PARTITION BY ITNBR, ITTYPECOD
               ORDER BY 
                   CASE WHEN TRY_CAST([VERSION] AS INT) IS NULL THEN 1 ELSE 0 END, -- 数字优先
                   TRY_CAST([VERSION] AS INT) DESC,
                   [VERSION] DESC
           ) AS RN
    FROM dbo.EDD0001
)
SELECT *
FROM CTE
WHERE RN = 1;
GO


