-- ----------------------------
-- View structure for V_HALF_BOM_PCR
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_HALF_BOM_PCR]') AND type IN ('V'))
	DROP VIEW [dbo].[V_HALF_BOM_PCR]
GO

CREATE VIEW [dbo].[V_HALF_BOM_PCR] AS WITH TEMP AS
(
    -- EDD0001按ITNBR分区，取VERSION数字值最大的最新记录
    SELECT ITNBR,ITTYPECOD,ERPCODE
    FROM (
        SELECT 
            ITNBR,ITTYPECOD,ERPCODE,
         
            ROW_NUMBER() OVER(PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId 
        FROM EDD0001 A 
    ) a
    WHERE RowId=1
)
	SELECT 
    A.*,B.ERPCODE,C.ERPCODE SUBERPCODE 
FROM EDD0061 A 
-- 父/子件关联TEMP表，匹配物料编码+类型
LEFT JOIN TEMP B ON A.ParentMatID=B.ITNBR  and a.ParentMatType=b.ITTYPECOD
LEFT JOIN TEMP C ON A.SubMatID=C.ITNBR   and a.SubMatTypeName=c.ITTYPECOD
WHERE 
    PNAM ='半钢' 
    --AND ParentMatID like '%0805-G-Y%'
    -- 核心新增：筛选ParentMatEditionNo为该ParentMatID下的最大值
    AND A.ParentMatEditionNo = (SELECT MAX(ISNULL(ParentMatEditionNo,0)) 
                               FROM EDD0061 
                               WHERE ParentMatID = A.ParentMatID 
                                 AND PNAM ='半钢'  -- 同主查询过滤，避免跨分类取最大值
                                 --AND ParentMatID like '%0805-G-Y%'
																 )
GO


