-- ----------------------------
-- View structure for V_JIASHICANG_EQPFault
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_JIASHICANG_EQPFault]') AND type IN ('V'))
	DROP VIEW [dbo].[V_JIASHICANG_EQPFault]
GO

CREATE VIEW [dbo].[V_JIASHICANG_EQPFault] AS select FAC AS 工厂编码,FACNAM AS 工厂, MCHID AS 设备编码,MCHNAM AS 设备名称,FAULT_DETAILS AS 故障原因,HAPPEN_DATE AS 报修时间, REPAIR_USERID AS 工号, EQP AS 设备类型 from (
select F.FAC,FACNAM,A.MCHID,MCHNAM,FAULT_DETAILS,HAPPEN_DATE,A.REPAIR_USERID, '检测机' EQP from IF_EAM_MACHINE_REPAIR A INNER JOIN EDC0001(NOLOCK) E ON E.MCHID COLLATE Chinese_PRC_90_CI_AI_WS = A.MCHID
LEFT JOIN LSFW_FACTORY F ON F.FAC = E.FAC
where HAPPEN_DATE > GETDATE()-1 and REPAIR_END_TIME is  null   and cast(datediff(HOUR,HAPPEN_DATE,GETDATE()) as int)>2
and FAA = 'ZJ' and TYPECOD IN ('DP001','XG001''JY001','DJ') AND FAULT_SOURCE = '设备突发故障'
union
select F.FAC,FACNAM,A.MCHID,MCHNAM,FAULT_DETAILS,HAPPEN_DATE,A.REPAIR_USERID, '硫化机' EQP from IF_EAM_MACHINE_REPAIR A INNER JOIN EDC0001(NOLOCK) E ON E.MCHID COLLATE Chinese_PRC_90_CI_AI_WS = A.MCHID
LEFT JOIN LSFW_FACTORY F ON F.FAC = E.FAC
where HAPPEN_DATE > GETDATE()-1 and REPAIR_END_TIME is  null   and cast(datediff(HOUR,HAPPEN_DATE,GETDATE()) as int)>2
and FAA = 'LH' AND FAULT_SOURCE = '设备突发故障'
union
select F.FAC,FACNAM,A.MCHID,MCHNAM,FAULT_DETAILS,HAPPEN_DATE,A.REPAIR_USERID, '成型机' EQP from IF_EAM_MACHINE_REPAIR A INNER JOIN EDC0001(NOLOCK) E ON E.MCHID COLLATE Chinese_PRC_90_CI_AI_WS = A.MCHID
LEFT JOIN LSFW_FACTORY F ON F.FAC = E.FAC
where HAPPEN_DATE > GETDATE()-1 and REPAIR_END_TIME is  null   and cast(datediff(HOUR,HAPPEN_DATE,GETDATE()) as int)>4
and FAA = 'CX' AND FAULT_SOURCE = '设备突发故障'
union
select F.FAC,FACNAM,A.MCHID,MCHNAM,FAULT_DETAILS,HAPPEN_DATE,A.REPAIR_USERID, '压延机' EQP from IF_EAM_MACHINE_REPAIR A INNER JOIN EDC0001(NOLOCK) E ON E.MCHID COLLATE Chinese_PRC_90_CI_AI_WS = A.MCHID
LEFT JOIN LSFW_FACTORY F ON F.FAC = E.FAC
where HAPPEN_DATE > GETDATE()-1 and REPAIR_END_TIME is  null  
and TYPECOD IN ('SI21','GY001') AND FAULT_SOURCE = '设备突发故障'
union
select F.FAC,FACNAM,A.MCHID,MCHNAM,FAULT_DETAILS,HAPPEN_DATE,A.REPAIR_USERID, '挤出机' EQP from IF_EAM_MACHINE_REPAIR A INNER JOIN EDC0001(NOLOCK) E ON E.MCHID COLLATE Chinese_PRC_90_CI_AI_WS = A.MCHID
LEFT JOIN LSFW_FACTORY F ON F.FAC = E.FAC
where HAPPEN_DATE > GETDATE()-1 and REPAIR_END_TIME is  null   
and TYPECOD IN ('TS21','AL21','IT21','JC001','NC001','TC001','TM001') AND FAULT_SOURCE = '设备突发故障'
union
select F.FAC,FACNAM,A.MCHID,MCHNAM,FAULT_DETAILS,HAPPEN_DATE,A.REPAIR_USERID, '密炼机' EQP from IF_EAM_MACHINE_REPAIR A INNER JOIN EDC0001(NOLOCK) E ON E.MCHID COLLATE Chinese_PRC_90_CI_AI_WS = A.MCHID
LEFT JOIN LSFW_FACTORY F ON F.FAC = E.FAC
where HAPPEN_DATE > GETDATE()-1 and REPAIR_END_TIME is  null   and cast(datediff(HOUR,HAPPEN_DATE,GETDATE()) as int)>2
and TYPECOD IN ('GK270','GK400','GE580','GE420/800T') AND FAULT_SOURCE = '设备突发故障'
) as V_JIASHICANG_EQPFault1
GO


