CREATE VIEW [dbo].[V_MESLOG] AS SELECT   A.ID, A.WTIME, A.DEPNAM, A.USERID, A.USERNAM, A.MENUID, A.MENUNAM, 
                CASE WHEN A.WSPAC > 14400 THEN NULL ELSE A.CTIME END AS CTIME, 
                CASE WHEN A.WSPAC > 14400 THEN 0 ELSE A.WSPAC END AS WSPAC, A.MODNAM, B.DIV
FROM      (SELECT   ID, WTIME, DEPNAM, USERID, USERNAM, MENUID, MENUNAM, CTIME, WSPAC, MODNAM
                 FROM      dbo.LSLOG_OPENLOG
                 WHERE   (LEN(USERID) > 1) AND (LEN(USERID) <= 10)) AS A LEFT OUTER JOIN
                dbo.MENUTAG AS B ON A.MENUID = B.MENUID
WHERE   (A.MENUNAM <> A.MODNAM)
GO


