CREATE VIEW [dbo].[V_MIXenergy] AS select  ATTRIBUTE1, ATTRIBUTE2,PlanId,EquipId,MatCode,sum(KW1)KW
 FROM 
 (select  a.ATTRIBUTE1,a.ATTRIBUTE2, a.PlanId,a.EquipId,a.MatCode,a.KW1,a.WT/1000 WT,case when isnull(KW1,0)=0 then 0.00 else KW1/(wt/1000) end qty,MCHNAM,a.ATTRIBUTE5
