-- ----------------------------
-- View structure for V_PAD0001
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_PAD0001]') AND type IN ('V'))
	DROP VIEW [dbo].[V_PAD0001]
GO

CREATE VIEW [dbo].[V_PAD0001] AS SELECT
	* 
FROM
	(
	SELECT
		ROW_NUMBER ( ) OVER ( PARTITION BY p.MCHID ORDER BY WTIME DESC ) RowId,MCHID,LR, CASE
    WHEN CHARINDEX('-', ISNULL(AITNBR,'')) > 0
    THEN LEFT(AITNBR, CHARINDEX('-', AITNBR) - 1)
    ELSE AITNBR
END AS AITNBR,AITDSC,CRTIM
	FROM
		PAD0001 p 
	WHERE
		FAC = '02' 
		AND inout = '2' 
		AND DIV LIKE '%GT' 
		AND WTIME >= DATEADD( DAY, - 3, GETDATE( ) ) 
	) tt 
WHERE
	tt.RowId =1
GO


