-- ----------------------------
-- View structure for V_PLM_PCR_ScheduleSheet
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_PLM_PCR_ScheduleSheet]') AND type IN ('V'))
	DROP VIEW [dbo].[V_PLM_PCR_ScheduleSheet]
GO

CREATE VIEW [dbo].[V_PLM_PCR_ScheduleSheet] AS SELECT  DISTINCT
       [zhizaojianmingcheng] AS 制造件名称, SUBSTRING(zhizaojianmingcheng,1,4) AS SPEC
      ,[shigongbianhao] AS 施工编号
	  ,[SpecialPurpose] AS 特殊用途
      ,[guige] AS 规格
      ,[fuhezhishusudujibie] AS 负荷指数速度级别
      ,[huawen]	AS 花纹	
      ,[gangsilianxian] AS 钢丝帘线
      ,[gangsilianbu] AS 钢丝帘布
      ,[Belt1daishucengfuhejiandaima] AS Belt1#带束层复合件代码
      ,[yicengdaishucenghoudu] AS 一层带束层厚度
      ,[yicengdaishucengjiaodu] AS 一层带束层角度
      ,[yicengdaishucengkuandu] AS 一层带束层宽度
      ,cast(yicengdaishucengzhangdu as float)/1000 AS 一层带束层长度
      ,[Belt2daishucengfuhejiandaima] AS Belt2#带束层复合件代码
      ,[ercengdaishucenghoudu] AS 二层带束层厚度
      ,[ercengdaishucengjiaodu] AS 二层带束层角度
      ,[ercengdaishucengkuandu] AS 二层带束层宽度
      ,cast(ercengdaishucengzhangdu as float)/1000 AS 二层带束层长度
      ,[yicengbaotiebianjiaodaima] AS 一层包贴边胶代码
      ,[yicengbaotiebianjiaohoudu] AS 一层包贴边胶厚度
      ,[yicengbaotiebianjiaokuandu] AS 一层包贴边胶宽度
      ,cast(yicengbaotiebianjiaozhangdu as float)/1000 AS 一层包贴边胶长度
      ,[yicengbaotiebianjiaoyayanjiaopian] AS 一层包贴边胶压延胶片
      ,[ercengbaotiebianjiaodaima] AS 二层包贴边胶代码
      ,[ercengbaotiebianjiaohoudu] AS 二层包贴边胶厚度
      ,[ercengbaotiebianjiaokuandu] AS 二层包贴边胶宽度
      ,cast(ercengbaotiebianjiaozhangdu as float)/1000 AS 二层包贴边胶长度
      ,[ercengbaotiebianjiaoyayanjiaopian] AS 二层包贴边胶压延胶片
      ,[guandaixianweilianxian] AS 冠带纤维帘线
      ,[guandaixianweilianbu] AS 纤维帘布
      ,[guandaijuan] AS 冠带卷
      ,[guandaihoudu] AS 冠带厚度
      ,[guandaikuandu] AS 冠带宽度
      ,cast(guandaizhangdu as float)/1000 AS 冠带长度
      ,[guandaichanraofangshi] AS 冠带缠绕方式
      ,[neichencengjuandaima] AS 内衬层卷代码
      ,[qimicenghoudu] AS 气密层厚度
      ,[qimicengkuandu] AS 气密层宽度
      ,cast(qimicengzhangdu as float)/1000 AS 气密层长度
      ,[qimicengjiaoliao] AS 气密层胶料
      ,[guoducenghoudu] AS 过渡层厚度
      ,[guoducengkuandu] AS 过渡层宽度
      ,cast(guoducengzhangdu as float)/1000 AS 过渡层长度
      ,[guoducengjiaoliao] AS 过渡层胶料
      ,[taitixianweilianxian] AS 一层胎体纤维帘线
	  ,[taitixianweilianxian2] AS 二层胎体纤维帘线
      ,[taitiguige] AS 胎体规格
      ,[yicengtaitizuhejiandaima] AS 一层胎体代码
      ,[yicengtaitijiaodu] AS 一层胎体角度
      ,[yicengtaitihoudu] AS 一层胎体厚度
      ,[yicengtaitikuandu] AS 一层胎体宽度
      ,cast(yicengtaitizhangdu as float)/1000 AS 一层胎体长度
      ,[ercengtaitizuhejiandaima] AS 二层胎体代码
      ,[ercengtaitihoudu] AS 二层胎体厚度
      ,[ercengtaitikuandu] AS 二层胎体宽度
      ,cast(ercengtaitizhangdu as float)/1000 AS 二层胎体长度
      ,[sancengtaitizuhejiandaima] AS 三层胎体代码
      ,[sancengtaitihoudu] AS 三层胎体厚度
      ,[sancengtaitikuandu] AS 三层胎体宽度
      ,cast(sancengtaitizhangdu as float)/1000 AS 三层胎体长度
	   --,[sancengtaitizhangdu] AS 三层胎体长度
      ,[jiaopiandaima] AS 胶片代码
      ,[jiaopianweizhi] AS 胶片位置
      ,[jiaopianhoudu] AS 胶片厚度
      ,[jiaopiankuandu] AS 胶片宽度
      ,cast(jiaopianzhangdu as float)/1000 AS 胶片长度
      ,[yayanjiaopian] AS 压延胶片
      ,[taiquanfuhejian] AS 胎圈复合件
      ,[taiquanjuan] AS 胎圈卷
      ,[gangsiquan] AS 钢丝圈
      ,[neizhouzhang] AS 内周长
      ,[pailiejianxie] AS 排列简写
      ,[sanjiaojiao] AS 三角胶
      ,[kouxingbianhao] AS 口型编号
      ,[taiquanbaobudaima] AS 胎圈包布代码
      ,[taiquanbaobuxianweilianbu] AS 胎圈包布纤维帘布
      ,[taiquanbaobukuandu] AS 胎圈包布宽度
      ,[taimiandaima] AS 胎面代码
      ,[taimiankouxinghao] AS 胎面口型号
	  ,B.MCHID_TD AS 胎面机台
      ,[taimiankuandu] AS 胎面宽度
      ,cast(taimianzhangdu as float)/1000 AS 胎面长度
      ,[taimiandayahoukuandu] AS 胎面打压后宽度
      ,[taiguanjiaojiaoliao] AS 胎冠胶胶料
      ,[xiaotaicejiaoliao] AS 小胎侧胶料
      ,[jibujiaojiaoliao] AS 基部胶胶料
      ,[taicedaima] AS 胎侧代码
      ,[taicekouxinghao] AS 胎侧口型号
	  ,B.MCHID_SW AS 胎侧机台
      ,[taicekuandu] AS 胎侧宽度
      ,cast(taicezhangdu as float)/1000 AS 胎侧长度
      ,[jiandianjiaojiaoliao] AS 肩垫胶胶料
      ,[taicejiaoliao] AS 胎侧胶料
      ,[zikoujiaoliao] AS 子口胶料
      ,[jiaqiangcengdaima] AS 加强层代码
      ,[jiaqiangcengxianweilianbu] AS 加强层纤维帘布
      ,[jiaqiangcengkuandu] AS 加强层宽度
      ,[fugaijiaodaima] AS 覆盖胶代码
      ,[fugaijiaokuandu] AS 覆盖胶宽度
      ,cast(fugaijiaozhangdu as float)/1000 AS 覆盖胶长度
      ,[zhichengjiaodaima] AS 支撑胶代码
      ,[zhichengjiaokuandu] AS 支撑胶宽度
      ,[taipizongzhong] AS 胎坯总重
	  --,[Write_Time] AS 写入时间
FROM   [ifdb].[PLMIFDB].[db_owner].[V_PLM_PCR_ScheduleSheet] A 
left join [dbo].[PCRPLAN_TD_SW] B on CASE WHEN CHARINDEX('-', zhizaojianmingcheng) > 0 
     THEN LEFT(zhizaojianmingcheng, CHARINDEX('-', zhizaojianmingcheng)-1) 
     ELSE zhizaojianmingcheng 
END collate chinese_prc_ci_as =B.ITNBR
INNER JOIN (select ITNBR from EDD0014(NOLOCK) where SubClassID = 'PGT') E ON zhizaojianmingcheng collate chinese_prc_ci_as =E.ITNBR
INNER JOIN (SELECT ITNBR  from (SELECT  ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId,* from EDD0001  )A WHERE  A.RowId=1 	AND IS_USE = '0') F ON zhizaojianmingcheng collate chinese_prc_ci_as =F.ITNBR
GO


