-- ----------------------------
-- View structure for v_ProductFertPlanForWMS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[v_ProductFertPlanForWMS]') AND type IN ('V'))
	DROP VIEW [dbo].[v_ProductFertPlanForWMS]
GO

CREATE VIEW [dbo].[v_ProductFertPlanForWMS] AS SELECT  T1.*,T2.SPEC,t2.PCSTotalTime   FROM
(
SELECT ID,(CASE WHEN A.WDATE IS NULL THEN B.WDATE ELSE A.WDATE END) WDATE
,(CASE WHEN A.WSHT IS NULL THEN B.SulfShift ELSE A.WSHT END) WSHT
      ,(CASE WHEN A.MCHID IS NULL THEN B.SulfEquipCode ELSE A.MCHID END) MCHID
      ,(CASE WHEN A.ITNBR IS NULL THEN B.MaterialID ELSE A.ITNBR END) ITNBR
      ,(CASE WHEN A.ITDSC IS NULL THEN B.MaterialName ELSE A.ITDSC END) ITDSC
	  ,LR,PN ,N
FROM
(
		SELECT  ID,WDATE,WSHT,MCHID,LR,ITNBR,ITDSC,SUM(PLLOT) PN FROM
						(
						SELECT ID,MCHID,ITNBRL ITNBR,ITDSCL ITDSC,SUM(PLLOT)/2 PLLOT,'L' LR,WDATE,WSHT FROM PAD0201 WITH(NOLOCK) 
						  WHERE FAC IN ('02') AND ATTRIBUTE1='FERT' AND WDATE=CONVERT(nvarchar(50),GETDATE(),23)  --AND ITNBRL LIKE '%{1}%' AND ITDSCL LIKE '%{2}%'
						  GROUP BY ID,MCHID,ITNBRL,ITDSCL,WSHT,WDATE--左规格计划量
						UNION ALL
						SELECT ID,MCHID,ITNBRR ITNBR,ITDSCR ITDSC,SUM(PLLOT)/2 PLLOT,'R' LR,WDATE,WSHT FROM PAD0201 WITH(NOLOCK) 
						  WHERE FAC IN ('02') AND ATTRIBUTE1='FERT' AND WDATE=CONVERT(nvarchar(50),GETDATE(),23) -- AND ITNBRR LIKE '%{1}%' AND ITDSCR LIKE '%{2}%'
						  GROUP BY ID,MCHID,ITNBRR,ITDSCR,WSHT,WDATE--右规格计划量
						) T
			GROUP BY ID,WDATE,WSHT,MCHID,LR,ITNBR,ITDSC
) A--计划量
left JOIN
(
	SELECT WDATE,SulfShift,SulfEquipCode,MaterialID,MaterialName,LeftOrRight,COUNT(*) N FROM tb_PP_CuringOutPut WITH(NOLOCK)
	WHERE WDATE =CONVERT(nvarchar(50),GETDATE(),23) AND FAC IN ('02')   AND ISNUMERIC(TyreNo)=1--去掉胎号含字母的数据
	GROUP BY WDATE,SulfShift,SulfEquipCode,MaterialID,MaterialName,LeftOrRight
) B--产量
ON A.WDATE=B.WDATE AND A.MCHID=B.SulfEquipCode AND A.WSHT = B.SulfShift  AND A.ITNBR=B.MaterialID AND A.LR=B.LeftOrRight
)T1
	LEFT JOIN 
(SELECT * FROM (
SELECT  PCSTotalTime,B.GreenTyreSPEC SPEC,TyreMaterialID ,row_number() over (partition by TyreMaterialID,b.GreenTyreSPEC order by [EditionNo] desc ) rm
   FROM PLM_PCR_TIRE_VUL_ROUTINT A inner join 
                ( 
				select * from(
				SELECT A.ITDSC, A.ITNBR TyreMaterialID ,row_number() over (partition by itnbr order by [version] desc ) rm,B.ATTRVAL GreenTyreSPEC  FROM EDD0001 A
				LEFT JOIN EDD0002 B ON A.id=b.ITEMID and b.ATTRCOD='GreenTyreSPEC' WHERE ITTYPECOD='PCRTYRE'  ) t where rm=1) B 
                ON A.GreenTyreSPEC=B.GreenTyreSPEC  WHERE PCSMachineType='B型硫化机' ) T WHERE rm=1) T2 ON T1.ITNBR=T2.TyreMaterialID--带出硫化对应胎坯SPEC，及胎坯描述
GO


