CREATE VIEW [dbo].[V_QMB0012] AS SELECT  a.FAC, BARCODE, DEPCOD, DEPNAM, [PERCENT], PERSON1, PERSON2, PERSON3, PERSONRAT1, PERSONRAT2, 
                   PERSONRAT3, ENAM, LOGINNAM, ETIM, MAX(a.CRTIM) AS CRTIM, CRDATE, DIV, RESULT, BCOD, a.TYRENO,case when isnull(b.CUSTATE,1)='' then 1 else isnull(b.CUSTATE,1) end as  [state]
