GO


-- ----------------------------
-- View structure for V_QMB004_QMB009
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_QMB004_QMB009]') AND type IN ('V'))
	DROP VIEW [dbo].[V_QMB004_QMB009]
GO

CREATE VIEW [dbo].[V_QMB004_QMB009] AS SELECT 
CASE WHEN ABS(WT-STDWEGHT) /(CASE WHEN STDWEGHT = 0.000 THEN 0.1 ELSE STDWEGHT END)*100  <= 3 THEN 'Y' ELSE 'N' END  AS YN,
cast((WT-STDWEGHT)/(CASE WHEN STDWEGHT = 0.000 THEN 0.1 ELSE STDWEGHT END)*100 as decimal(13,2)) AS DIF,*  from
(
 select T.TYRENO,ITNBR,ITDSC,WT,STDWEGHT,T.CRTIM from 
 (
  select A.TYRENO,A.ITNBR,A.ITDSC,A.WT,A.[DEFAULT] STDWEGHT,A.CRTIM 	 
  from QMB0009 A WITH(NOLOCK) 
  union
  select  B.TYRENO,B.ITNBR,B.ITDSC,B.WT,B.[DEFAULT] STDWEGHT,B.CRTIM 
  from QMB0004 B WITH(NOLOCK) 
 )T inner join 
 ( 
  select TYRENO,MAX(CRTIM) CRTIM from 
 (
  select A.TYRENO,A.ITNBR,A.ITDSC,A.WT,A.[DEFAULT] STDWEGHT,A.CRTIM 	 
  from QMB0009 A WITH(NOLOCK) 
  union
  select  B.TYRENO,B.ITNBR,B.ITDSC,B.WT,B.[DEFAULT] STDWEGHT,B.CRTIM 
  from QMB0004 B WITH(NOLOCK) 
  )S GROUP BY  TYRENO)X
 ON T.TYRENO = X.TYRENO AND T.CRTIM = X.CRTIM
 )W
 WHERE ITNBR <>'2100011027'
 union
 SELECT 
CASE WHEN ABS(WT-STDWEGHT) /(CASE WHEN STDWEGHT = 0.000 THEN 0.1 ELSE STDWEGHT END)*100  <= 2 THEN 'Y' ELSE 'N' END  AS YN,
cast((WT-STDWEGHT)/(CASE WHEN STDWEGHT = 0.000 THEN 0.1 ELSE STDWEGHT END)*100 as decimal(13,2)) AS DIF,*  from
(
 select T.TYRENO,ITNBR,ITDSC,WT,STDWEGHT,T.CRTIM from 
 (
  select A.TYRENO,A.ITNBR,A.ITDSC,A.WT,A.[DEFAULT] STDWEGHT,A.CRTIM 	 
  from QMB0009 A WITH(NOLOCK) 
  union
  select  B.TYRENO,B.ITNBR,B.ITDSC,B.WT,B.[DEFAULT] STDWEGHT,B.CRTIM 
  from QMB0004 B WITH(NOLOCK) 
 )T inner join 
 ( 
  select TYRENO,MAX(CRTIM) CRTIM from 
 (
  select A.TYRENO,A.ITNBR,A.ITDSC,A.WT,A.[DEFAULT] STDWEGHT,A.CRTIM 	 
  from QMB0009 A WITH(NOLOCK) 
  union
  select  B.TYRENO,B.ITNBR,B.ITDSC,B.WT,B.[DEFAULT] STDWEGHT,B.CRTIM 
  from QMB0004 B WITH(NOLOCK) 
  )S GROUP BY  TYRENO)X
 ON T.TYRENO = X.TYRENO AND T.CRTIM = X.CRTIM
 )W
 WHERE ITNBR = '2100011027'
GO


