-- ----------------------------
-- View structure for V_TB_ENVIRONMENT_DETAIL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[V_TB_ENVIRONMENT_DETAIL]') AND type IN ('V'))
	DROP VIEW [dbo].[V_TB_ENVIRONMENT_DETAIL]
GO

CREATE VIEW [dbo].[V_TB_ENVIRONMENT_DETAIL] AS SELECT*
FROM (SELECT DATETIME, C0001_ITEM_CODE, 
CASE WHEN C0001_ITEM_CODE='210.0' THEN ROUND(CONVERT(FLOAT,C1703_VALUE)/3600,2)
ELSE CONVERT(FLOAT,C1703_VALUE) END C1703_VALUE
FROM DBO.TB_ENVIRONMENT_DETAIL
WHERE C0007_SUBSTATION_ID ='14417.0'AND DATEDIFF (DD, DATETIME, GETDATE ()) <=1 ) T
PIVOT (AVG(C1703_VALUE)
FOR C0001_ITEM_CODE
IN ("209.0",
"210.0",--流量(M3/S)
"211.0",--流速
"383.0",--非甲烷总烃(MG/M3)
"525.0",--烟气温度(℃)
"526.0",--烟气压力(千帕)
"527.0")) A--烟气湿度(％RH)
GO


