CREATE VIEW [dbo].[V_TechView] AS SELECT *
FROM (
    SELECT *
    FROM (
        SELECT MCHID, AITNBR, WTIME, ROW_NUMBER() OVER (PARTITION BY MCHID ORDER BY WTIME DESC) RN1
        FROM PAD0001
        WHERE FAC = '02' AND DIV LIKE '%GT'
    ) a
    WHERE a.RN1 = 1
) a
LEFT JOIN (
    SELECT *
    FROM (
        SELECT *, ROW_NUMBER() OVER (PARTITION BY PLM_CODE ORDER BY CONVERT(int, PCSSheetVersion) DESC) RN
        FROM PGT_EDD02
    ) Z
    WHERE RN = 1
) b ON a.AITNBR = b.PLM_CODE
--ORDER BY CONVERT(int, b.PCSSheetVersion) DESC
GO


