-- ----------------------------
-- View structure for VIEW_EDD0001_MAX_VERSION
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VIEW_EDD0001_MAX_VERSION]') AND type IN ('V'))
	DROP VIEW [dbo].[VIEW_EDD0001_MAX_VERSION]
GO

CREATE VIEW [dbo].[VIEW_EDD0001_MAX_VERSION] AS SELECT  A.ID, A.FAC, A.ITNBR, A.ITDSC, A.ITGRPCOD, A.ITGRPNAM, A.ITCLSFYCOD, A.ITCLSFYNAM, A.ITTYPECOD, A.ITTYPENAM, A.VERSION, A.UNIT, A.SPEC, 
               A.INCH, A.CHARGE, A.PRESSURE, A.CONFIG, A.SHAPE, A.SLEVAL, A.TDTYPE, A.TDLINE, A.GRADE, A.[LOAD], A.SPEED, A.PLY, A.PATTERN, A.BRAND, 
               A.SERIES, A.IS_USE, A.CYCLTIM, A.STRUCTURE, A.SECTWIDTH, A.ASPRATIO, A.UOM, A.EXPTIM, A.IS_HEAT, A.IS_FLAG, A.REMARK, A.ENTUSERID, 
               A.LOGINNAM, A.ENAM, A.UPDTIM, A.CRTIM, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5, A.SHFLAG, A.SHLOGINNAM, 
               A.SHNAM, A.SHTIM, A.ERPCODE, A.Equip_Code, A.DQTY, A.CLASSDIV, A.SAPBOM, A.KJ_FLAG, A.U1_FLAG, A.U2_FLAG, A.U3_FLAG, A.MCC_FLAG, 
               A.EAMFLAG, A.WLXF
FROM     dbo.EDD0001 AS A INNER JOIN
                   (SELECT  ITNBR, MAX(REPLICATE('0', 3 - LEN(VERSION)) + VERSION) AS VERSION
                   FROM     dbo.EDD0001
                   GROUP BY ITNBR) AS B ON A.ITNBR = B.ITNBR AND A.VERSION = REPLACE(B.VERSION, '0', '')
GO


