GO

CREATE VIEW [dbo].[VIEW_EDD0061_INPUT] AS SELECT A.ParentMatType AS PDIV,A.ParentMatID AS PITNBR,
A.SubMatTypeName DIV, 
B.ITTYPENAM AS DIVNAM,
A.SubMatID AS ITNBR,ISNULL(A.SubMatName,A.SubMatID) AS ITDSC 
FROM VIEW_EDD0061_LatestVersion A
LEFT JOIN EDD0003 B
ON A.SubMatTypeName =B.ITTYPECOD
GO


-- ----------------------------
-- View structure for VIEW_EDD0061_LatestVersion
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VIEW_EDD0061_LatestVersion]') AND type IN ('V'))
	DROP VIEW [dbo].[VIEW_EDD0061_LatestVersion]
GO

CREATE VIEW [dbo].[VIEW_EDD0061_LatestVersion] AS WITH Ranked AS (
    SELECT ParentMatID, ParentMatEditionNo,
           RANK() OVER (
               PARTITION BY ParentMatID
               ORDER BY
                   CASE 
                       WHEN PATINDEX('%[0-9]%', ParentMatEditionNo) > 0 THEN
                           LEFT(ParentMatEditionNo, PATINDEX('%[0-9]%', ParentMatEditionNo) - 1)
                           + RIGHT(REPLICATE('0', 10) + 
                                   SUBSTRING(ParentMatEditionNo, PATINDEX('%[0-9]%', ParentMatEditionNo), LEN(ParentMatEditionNo)), 10)
                       ELSE ParentMatEditionNo
                   END DESC
           ) AS rk
    FROM EDD0061
)
SELECT e.*
FROM EDD0061 e
WHERE EXISTS (
    SELECT 1
    FROM Ranked r
    WHERE r.rk = 1
      AND r.ParentMatID = e.ParentMatID
      AND r.ParentMatEditionNo = e.ParentMatEditionNo
);
GO


