CREATE VIEW [dbo].[view_FTPRODUCT] AS select BeginTime,TyreNo,MaterialID,MaterialName,b.CLASSDIV,b.ZL
from tb_PP_CuringOutPut a left join (SELECT E.ITNBR,E.CLASSDIV,E2.ATTRVAL ZL 
						 FROM EDD0001 E
					LEFT JOIN EDD0002  E2 ON E.ID=E2.ITEMID AND E2.ATTRCOD='M771'
						WHERE E.ID IN (SELECT id FROM (SELECT ID,row_number() over (partition by itnbr order by RIGHT('0000000000'+REPLACE(e.[VERSION], ' ', ''),10) desc) ROWNUM 
														 FROM EDD0001 AS e 
														WHERE ITGRPCOD='FERT' AND SHFLAG='Y') T
						WHERE T.ROWNUM=1)) B on a.MaterialID=b.ITNBR
