-- ----------------------------
-- View structure for VIEW_MLRM_BOM
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VIEW_MLRM_BOM]') AND type IN ('V'))
	DROP VIEW [dbo].[VIEW_MLRM_BOM]
GO

CREATE VIEW [dbo].[VIEW_MLRM_BOM] AS SELECT TOP 1000 A.MatCode,A.EquipId,A.CMatCode,A.CMatName,A.SetWeight FROM EDD0075 A
LEFT JOIN VIEW_EDD0001_MAX_VERSION B
ON (A.CMatCode=B.ITNBR OR A.CMatCode = B.ITDSC)
WHERE ITTYPECOD NOT IN ('JL','ML','SL','XL','RB') AND CMatCode<>''
UNION ALL
SELECT A.MatCode, A.EquipId, REPLACE(REPLACE(C.SUBITNBR,'-1',''),'-2',''),C.SUBITDSC,C.SetWeight FROM EDD0075 A
LEFT JOIN VIEW_EDD0001_MAX_VERSION B
ON (A.CMatCode=B.ITNBR OR A.CMatCode = B.ITDSC)
LEFT JOIN 
(
SELECT t.*
FROM EDD0070 t
INNER JOIN (
    SELECT JITNBR, MIN(EquipId) AS MinEquipId
    FROM EDD0070
    GROUP BY JITNBR
) m ON t.JITNBR = m.JITNBR AND t.EquipId = m.MinEquipId
)C
ON A.CMatCode=C.JITNBR
WHERE ITTYPECOD ='XL'
GO


