-- ----------------------------
-- View structure for VIEW_TABLE_COLUMNS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VIEW_TABLE_COLUMNS]') AND type IN ('V'))
	DROP VIEW [dbo].[VIEW_TABLE_COLUMNS]
GO

CREATE VIEW [dbo].[VIEW_TABLE_COLUMNS] AS SELECT 
    t.name AS 表名,
    c.name AS 列名,
    CASE 
        WHEN ty.name IN ('varchar', 'char') 
            THEN ty.name + '(' + IIF(c.max_length = -1, 'MAX', CAST(c.max_length AS VARCHAR)) + ')'
	    WHEN ty.name IN ('nvarchar', 'nchar') 
            THEN ty.name + '(' + IIF(c.max_length = -1, 'MAX', CAST(c.max_length/2 AS VARCHAR)) + ')'
        WHEN ty.name IN ('decimal', 'numeric') 
            THEN ty.name + '(' + CAST(c.precision AS VARCHAR) + ',' + CAST(c.scale AS VARCHAR) + ')'
        WHEN ty.name = 'float' 
            THEN ty.name + '(' + CAST(c.precision AS VARCHAR) + ')'
        ELSE ty.name
    END AS 数据类型,
    c.is_nullable AS 允许空值,
    c.is_identity AS 自增列,
    ISNULL(d.definition, '无') AS 默认值,
    ISNULL(ep.value, '无') AS 列说明
FROM 
    sys.tables t
INNER JOIN 
    sys.columns c ON t.object_id = c.object_id
INNER JOIN 
    sys.types ty ON c.user_type_id = ty.user_type_id
OUTER APPLY (
    SELECT TOP 1 definition 
    FROM sys.default_constraints 
    WHERE object_id = c.default_object_id
) d
OUTER APPLY (
    SELECT TOP 1 value 
    FROM sys.extended_properties 
    WHERE major_id = c.object_id 
        AND minor_id = c.column_id 
        AND name = 'MS_Description'
) ep
GO


-- ----------------------------
-- View structure for VIEW_TABLES
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VIEW_TABLES]') AND type IN ('V'))
	DROP VIEW [dbo].[VIEW_TABLES]
GO

CREATE VIEW [dbo].[VIEW_TABLES] AS SELECT 
    SCHEMA_NAME(t.schema_id) AS schema_name,
    t.name AS table_name,
    CAST(ep.value AS NVARCHAR(4000)) AS table_description
FROM 
    sys.tables t WITH (NOLOCK)
LEFT JOIN 
    sys.extended_properties ep WITH (NOLOCK)
    ON ep.major_id = t.object_id
    AND ep.minor_id = 0
    AND ep.class = 1  -- 对象级属性
    AND ep.name = 'MS_Description'
GO


