                   tpcop.BeginTime, tpcop.EndTime, tpcop.QualityLevel, tpcop.MouldID, tpcop.BladderCount, tpcop.MouldAmt, 
                   tpcop.LeftOrRight, tpcop.ArtID, tpcop.DelayTime, tpcop.Remark, tpcop.RecorderID, tpcop.RecordTime, tpcop.CuringState, 
                   tpcop.RealEndTime, tpcop.IsFirstTyre, tpcop.SulfEquipCode, tpcop.SulfShift, tpcop.SulfTeam, tpcop.EmpName, 
                   tpcop.EmpID, tpcop.AllTime, tpcop.DelayOpenMouldTime, tpcop.JDEUPDATEFLAG, tpcop.AssistTempState, 
                   tpcop.GreenTyreTemp, tpcop.EnvironmentTemp, tpcop.TechChangeTime, tpcop.StopTime, tpcop.DingXing1, 
                   tpcop.DingXing2, tpcop.N2Value, tpcop.S1, tpcop.S2, tpcop.S3, tpcop.S4, tpcop.FAC, tpcop.DOT, tpcop.MaterialName, 
