-- ----------------------------
-- View structure for VIEW_WIP0001_FIFO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[VIEW_WIP0001_FIFO]') AND type IN ('V'))
	DROP VIEW [dbo].[VIEW_WIP0001_FIFO]
GO

CREATE VIEW [dbo].[VIEW_WIP0001_FIFO] AS WITH LastOutData AS (
    SELECT 
        CARTID,
        MAX(OUTDAT) AS LastOUTDAT
    FROM ifdb.plmesinterface.dbo.IF_WMS_HALB_08
    GROUP BY CARTID
)
SELECT 
    W.*,
    CASE 
        WHEN W.STKSTS = '17' AND 
             EXISTS (
                SELECT 1 
                FROM LastOutData L 
                WHERE L.CARTID = W.TOOLNO COLLATE Chinese_PRC_90_CI_AI_WS
                AND DATEDIFF(MINUTE, L.LastOUTDAT, GETDATE()) > 120
             ) 
        THEN '18' 
        ELSE W.STKSTS 
    END AS STKSTS1
FROM WIP0001 W
GO


