		a.CRTIM as QMA1001CRTIM,
		a.UPDTIM as QMA1001UPDTIM,
		B.CRTIM as EDA0004CRTIM,
		B.UPDTIM as EDA0004UPDTIM,
		T.CRTIM as QMA1002CRTIM,
		T.UPDTIM as QMA1002UPDTIM,
		tQMA1000.CRTIM as QMA1000CRTIM,
		tQMA1000.UPDTIM as QMA1000UPDTIM
FROM dbo.QMA1001 A WITH(NOLOCK)
INNER JOIN dbo.EDA0004 B WITH(NOLOCK)
ON A.DIV = B.DCOD
INNER JOIN dbo.QMA1002 T WITH(NOLOCK)
