CREATE VIEW [dbo].[vw_weight] AS select a.BARCODE,c.ATTRVAL,d.LIMPER,d.LOWPER,LIMPER_Q,LOWPER_Q from LTA0001 a  
 left join (    select a1.* from 
   ( select convert(varchar(50),max(convert (numeric(18,0),VERSION))) as  VERSION,ITNBR from EDD0001 
   where  SHFLAG='Y'and ITCLSFYCOD='GT' 
   group by ITNBR   
   union
   select max(VERSION)as  VERSION,itnbr from EDD0001 where  SHFLAG='Y'and ITCLSFYCOD='FERT'
   group by VERSION,itnbr 
   
   )b1 left join EDD0001 a1  on a1.itnbr=b1.itnbr and a1.VERSION=b1.VERSION) b on a.buitnbr=b.ITNBR  
left join (select * from EDD0002 where ATTRCOD='M77') c on b.id=c.ITEMID
left join (select * from EDd0004 where attrcod = 'M771_PCR') d on  d.ATTRNAM='半钢成品胎重量'
