-- ----------------------------
-- View structure for WMS_GTPLAN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[WMS_GTPLAN]') AND type IN ('V'))
	DROP VIEW [dbo].[WMS_GTPLAN]
GO

CREATE VIEW [dbo].[WMS_GTPLAN] AS SELECT  T.ITNBR, T.MCHID, T.WSHT, T.VERSION, T.WDATE, T.ITDSC, T.xqty, T.SubMatTypeName, T.SubMatID, T.EditionNo, 
                   edd.ITDSC AS SubMatName,PLQTY,SubMatNum,PCSCuttinglength
FROM      (SELECT  a.ITNBR, a.MCHID, a.WSHT, a.VERSION, a.WDATE, a.ITDSC,
CASE WHEN  SubMatTypeName<>'PTQ' THEN 
CONVERT(float, CASE WHEN b.PCSCuttinglength='' THEN 1 ELSE b.PCSCuttinglength END) * CONVERT(float, b.SubMatNum) * a.PLQTY / 1000
ELSE CONVERT(float, CASE WHEN b.PCSCuttinglength='' THEN 1 ELSE b.PCSCuttinglength END) * CONVERT(float, b.SubMatNum) * a.PLQTY END 
 AS xqty, b.SubMatTypeName, b.SubMatID, b.EditionNo,PLQTY,SubMatNum,PCSCuttinglength
                   FROM       (SELECT  MCHID, SUM(PLQTY) AS PLQTY, ITNBR, WSHT, VERSION, WDATE, ITDSC
                                       FROM       dbo.PAD0201_GT
                                       WHERE    (FAC = '02')
                                       GROUP BY ITNBR, MCHID, WSHT, VERSION, WDATE, ITDSC) AS a LEFT OUTER JOIN
                                          (SELECT  ParentMatID, ParentMatEditionNo, SubMatTypeName, SubMatID, SubMatNum, PCSCuttinglength, 
                                                              EditionNo
                                           FROM       dbo.EDD0061
                                           WHERE    (ParentMatType = 'PGT')) AS b ON a.ITNBR = b.ParentMatID AND 
                                      a.VERSION = b.ParentMatEditionNo
                   WHERE    (a.PLQTY > 0)) AS T LEFT OUTER JOIN
                   dbo.EDD0001 AS edd ON T.SubMatID = edd.ITNBR AND T.EditionNo = edd.VERSION
GO


-- ----------------------------
-- View structure for WMS_HALFSTOCK_VIEW
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[WMS_HALFSTOCK_VIEW]') AND type IN ('V'))
	DROP VIEW [dbo].[WMS_HALFSTOCK_VIEW]
GO

CREATE VIEW [dbo].[WMS_HALFSTOCK_VIEW] AS SELECT  STODIV, [ITGRPCOD3], [Location], [LOTNO], [CARTID], ITNBR, ITDSC, [LOTSTATUS], WDATE, WTIME, WSHT, WBAN, INDT, 
                   INUSER, USERID, LOCKYN, Usefull, QTY, STKSTS
FROM      (SELECT  'HALF' STODIV, W.DIV AS [ITGRPCOD3], W.INLOC AS [Location], W.LOTID AS [LOTNO], TOOLNO AS [CARTID], 
                                      W.ITNBR, W.ITDSC, STA AS [LOTSTATUS], W.WDATE, WTIME, WSHT, W.WBAN, S.CRTIM AS INDT, 
                                      S.USERID AS INUSER, L.AUNAM USERID, W.LOCKYN, 0 Usefull, W.QTY, 'AW' AS STKSTS, ROW_NUMBER() 
                                      OVER (partition BY W.LOTID
                   ORDER BY S.CRTIM DESC) RW
FROM      WIP0001(nolock) W LEFT JOIN
                   STB0003(nolock) S ON W.LOTID = S.BARCODE LEFT JOIN
                   LTC0001(nolock) L ON W.LOTID = L.LOTID
WHERE   W.FAC = '02' AND ISNULL(W.IS_DELETE, 0) = 0  AND len(W.INLOC) = 6
UNION
SELECT  'HALF' STODIV, W.DIV AS [ITGRPCOD3], W.INLOC AS [Location], W.LOTID AS [LOTNO], TOOLNO AS [CARTID], W.ITNBR, 
                   W.ITDSC, STA AS [LOTSTATUS], W.WDATE, WTIME, WSHT, W.WBAN, S.CRTIM AS INDT, S.USERID AS INUSER, 
                   L.AUNAM USERID, W.LOCKYN, 0 Usefull, W.QTY, W.STKSTS AS STKSTS, ROW_NUMBER() OVER (partition BY 
                   W.LOTID
ORDER BY S.CRTIM DESC) RW
FROM      WIP0001(nolock) W LEFT JOIN
                   STB0003(nolock) S ON W.LOTID = S.BARCODE LEFT JOIN
                   LTC0001(nolock) L ON W.LOTID = L.LOTID
WHERE   W.FAC = '02' AND ISNULL(W.IS_DELETE, 0) = 0  AND len(W.INLOC) != 6) T
WHERE   RW = 1
GO


-- ----------------------------
-- procedure structure for SET_GTPPB0202
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SET_GTPPB0202]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SET_GTPPB0202]
GO

CREATE PROCEDURE [dbo].[SET_GTPPB0202] 
	 @PLANCOD NVARCHAR(50)
AS
BEGIN
	DECLARE @MCHID NVARCHAR(10);
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
declare @pid nvarchar(200);   



SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_GT WHERE PLANCOD=@PLANCOD;

select @pid=B.ID from PPB0201 B left join PAD0201_GT C on C.PLANCOD = B.ORDERNOA OR C.PLANCOD = B.ORDERNOB OR C.PLANCOD = B.ORDERNOC  
                WHERE  C.PLANCOD=@PLANCOD


SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR ;
 
with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth)
as
(
--初始查询
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
union all
--递归条件
select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth
from EDD0061 a 
inner join
temp b
on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
and b.EditionNo=a.ParentMatEditionNo)
)
select distinct * INTO #TT3  from temp 
DECLARE @CC INT
SELECT @CC=COUNT(*) FROM #TT3 WHERE SubMatTypeName='DE'
IF @CC>1
 BEGIN 
  DELETE   #TT3 WHERE SubMatID IN (SELECT TOP 1 SubMatID FROM #TT3 WHERE SubMatTypeName='DE')  AND SubMatTypeName='DE'
 END

update #TT3 set PCSCuttinglength='' WHERE ParentMatType=@outtypecod AND   SubMatTypeName='TD'
if(exists( select * from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='ZB'))
begin 
	--update #TT3 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #TT3 set PCSCuttinglength=(select PCSCuttinglength from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
END
 
--UPDATE LTC0002 SET NBRST='',DSCST='',XQTY=1 WHERE MCHID=@MCHID
--UPDATE LTC0002 WITH(UPDLOCK)
--                  SET SDIV=C.TYPECOD,
--                      NBRST=C.SubMatID,
--                     DSCST=C.SubMatID,
--                      XQTY=  C.XQTY
--                  FROM LTC0002 D 
--                      INNER JOIN ( SELECT q.TCOD,q.TYPECOD,t.SubMatID,CASE WHEN  t.PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty FROM QMA0014 q 
--					inner join #TT3 t on q.TYPECOD=t.subMatTypeName and q.COMPLOCATION=t.Usage  
--					WHERE MCHID=@MCHID  ) C ON D.LDIV = C.TCOD
--                  WHERE D.MCHID=@MCHID 
--UPDATE LTC0002 SET DIV=6 WHERE NBRRE<>NBRST AND LOTID<>'' AND MCHID=@MCHID

merge into PPB0202 A
USING(select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,0 QTY,TYPECOD BOMDIV,CASE WHEN  PCSCuttinglength='' 
THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1] from #TT3 
INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 
ON #TT3.SubMatTypeName=T1.TYPECOD AND #TT3.Usage=T1.COMPLOCATION) XX
ON A.ITEMID=@PID AND A.LDIV=XX.LDIV AND A.BOMDIV=XX.BOMDIV
WHEN MATCHED THEN
UPDATE SET A.ITNBR=XX.ITNBR ,A.[ATTRIBUTE1]=XX.[ATTRIBUTE1],A.ITDSC=XX.ITDSC;
 
 DROP TABLE #TT3
 

END
GO


-- ----------------------------
-- procedure structure for SettleWIP0004_Pro
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SettleWIP0004_Pro]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SettleWIP0004_Pro]
GO

CREATE PROCEDURE [dbo].[SettleWIP0004_Pro] 
AS
BEGIN
	--INSERT语句-数据字典生成工具自动生成 RE0005 - 原材料库存每日结算 生成时间：2021-04-20 11:40:03
INSERT INTO [RE0005]
( 
WDATE, --厂内日期,
DIV, --物料分类 成品库和硫化区分管理,
ITNBR, --规格代码,
ITDSC, --规格名称,
STA, --库存状态,
SQTY, --批次数,
WT, --总数量,
CRTIM --写入时间
)
  SELECT convert(nvarchar,getdate(),23) wdate, DIV,ITNBR,ITDSC,STA,COUNT(*) SQTY,cast(SUM(WT) as int) AS WT,GETDATE() CRTIM
                FROM WIP0004 WHERE ISNULL(IS_DELETE,0)=0   GROUP BY FAC,DIV,ITNBR,ITDSC,STA ;

