-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SET_LTC0002_PRO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SET_LTC0002_PRO]
GO

CREATE PROCEDURE [dbo].[SET_LTC0002_PRO] 
	 @PLANCOD NVARCHAR(50),
	 @SECTION NVARCHAR(1)='0'
AS
BEGIN
	DECLARE @MCHID NVARCHAR(10);
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10); 

SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_GT WHERE PLANCOD=@PLANCOD;

 


--with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
--,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth)
--as
--(
----初始查询
--select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
--SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth
--from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
--union all
----递归条件
--select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
--a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth
--from EDD0061 a 
--inner join
--temp b
--on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
--and b.EditionNo=a.ParentMatEditionNo)
--)
--select distinct * INTO #T2  from temp 

select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,PCSBOMWeight,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth INTO #T2 
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod

if(exists(select * from #T2))
	begin
		if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='PD'))
begin 
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='PD' WHERE MCHID=@MCHID  AND  TCOD='4-1'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='WG' WHERE MCHID=@MCHID  AND  TCOD='4-1'
END 
		if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB'))
begin 
	if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='SB' AND Usage='Belt #4'))
	BEGIN
		UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
	ELSE
	BEGIN
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
END
		if(exists( select * from #T2 where ParentMatType=@outtypecod and SubMatTypeName='DE'  and Usage<>'Standard'))
begin 
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage ASC)  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage DESC)  WHERE MCHID=@MCHID  AND  TCOD='9-2'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-2'
END 

	--声明表变量
	 declare @qma14tb table
	 (tcod nvarchar(50),TYPECOD nvarchar(50),COMPLOCATION nvarchar(150),LRFLAG nvarchar(150))
	 insert into @qma14tb (TCOD,COMPLOCATION,TYPECOD,LRFLAG  )
	 select TCOD,COMPLOCATION,TYPECOD,LRFLAG  from QMA0014 t with(nolock)  where MCHID=@MCHID

	update #T2 set PCSCuttinglength='' WHERE ParentMatType=@outtypecod AND   SubMatTypeName IN ('TD','PD')
	UPDATE LTC0002 SET NBRST='',DSCST='',XQTY=1,PLANCOD=@PLANCOD WHERE MCHID=@MCHID AND SECTION=@SECTION
	MERGE INTO LTC0002 A
	USING( SELECT q.TCOD,q.TYPECOD,t.SubMatID,CASE WHEN q.TYPECOD ='JL' THEN convert(decimal(9,3), t.PCSBOMWeight)  WHEN q.TYPECOD IN ('PTQ','BD') THEN 1.000  WHEN t.PCSCuttinglength='' THEN 1.000  ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000  end xqty,EditionNo FROM QMA0014 q 
				inner join #T2 t on q.TYPECOD=t.subMatTypeName and q.COMPLOCATION=t.Usage  
				WHERE MCHID=@MCHID ) B ON A.LDIV=B.TCOD AND A.MCHID=@MCHID AND A.SECTION=@SECTION
	WHEN MATCHED THEN
	UPDATE SET SDIV=B.TYPECOD,NBRST=B.SubMatID,DSCST=B.SubMatID, XQTY=  B.XQTY,TVERSION=B.EditionNo;

	update LTC0002 SET DIV=6
	FROM LTC0002 A LEFT JOIN (SELECT MatID,SubMatID from edd0663 
UNION ALL
SELECT MatID,SubMatID FROM EDD0664 WHERE MCHID=@MCHID AND ParentMatID=@ITNBR AND USEYN='Y') B ON A.NBRST=B.MatID WHERE 
	(NBRRE<>NBRST AND ISNULL(B.SubMatID,'')<>A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID AND SECTION=@SECTION

	update LTC0002 SET DIV=1
	FROM LTC0002 A LEFT JOIN (SELECT MatID,SubMatID from edd0663 
UNION ALL
SELECT MatID,SubMatID FROM EDD0664 WHERE MCHID=@MCHID AND ParentMatID=@ITNBR AND USEYN='Y') B ON A.NBRST=B.MatID WHERE 
	(NBRST=NBRRE OR ISNULL(B.SubMatID,'')=A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID AND SECTION=@SECTION


		--UPDATE LTC0002 SET NBRST='',DSCST='',XQTY=1 WHERE MCHID=@MCHID
		--UPDATE LTC0002 WITH(UPDLOCK)
  --                SET SDIV=C.TYPECOD,
  --                    NBRST=C.SubMatID,
  --                   DSCST=C.SubMatID,
  --                    XQTY=  C.XQTY
  --                FROM LTC0002 D 
  --                    INNER JOIN ( SELECT q.TCOD,q.TYPECOD,t.SubMatID,CASE WHEN  t.PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty FROM QMA0014 q 
		--			inner join #T2 t on q.TYPECOD=t.subMatTypeName and q.COMPLOCATION=t.Usage  
		--			WHERE MCHID=@MCHID  ) C ON D.LDIV = C.TCOD
  --                WHERE D.MCHID=@MCHID 
		--UPDATE LTC0002 SET DIV=6 WHERE NBRRE<>NBRST AND LOTID<>'' AND MCHID=@MCHID

--merge into PPB0202 A
--USING(select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,CASE WHEN  PCSCuttinglength='' 
--THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1] from #T2 
--INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 
--ON #T2.SubMatTypeName=T1.TYPECOD AND #T2.Usage=T1.COMPLOCATION) XX
--ON A.ITEMID=@PID AND A.LDIV=XX.LDIV AND A.BOMDIV=XX.BOMDIV
--WHEN MATCHED THEN
--UPDATE SET A.ITNBR=XX.ITNBR ,A.[ATTRIBUTE1]=XX.[ATTRIBUTE1],A.ITDSC=XX.ITDSC;


	drop table #T2
	--优化追溯错误问题
	--UPDATE LTC0002 SET LTSQTY=0 WHERE MCHID=@MCHID and  NBRRE<>LTITNBR AND LTSQTY>0 AND NBRRE<>''
	--2025-11-20 上面语句存在问题，余量返回之后，再做产出交替，他就不清空LTSQTY导致追溯绑定错误了。
	--增加如果说标准不一致直接清0
	UPDATE LTC0002 SET LTSQTY=0 WHERE MCHID=@MCHID and  NBRST<>LTITNBR AND LTSQTY>0
	end
else
	begin
		SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR AND SHFLAG='Y';
--		with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
--,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth)
--as
