-- ----------------------------
-- function structure for GetBanCi
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetBanCi]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetBanCi]
GO

CREATE FUNCTION [dbo].[GetBanCi]
( 
		@wdate 											DATETIME		
)
RETURNS INT
AS
BEGIN
	--获取当前班次
		declare @shift 														INT
		IF @wdate>=CONVERT(datetime,FORMAT(@wdate,'yyyy-MM-dd 07:45:00')) AND @wdate<CONVERT(datetime,FORMAT(GETDATE(),'yyyy-MM-dd 15:45:00'))
		BEGIN
			SET @shift=2
		END
		ELSE IF @wdate>=CONVERT(datetime,FORMAT(@wdate,'yyyy-MM-dd 15:45:00')) AND @wdate<CONVERT(datetime,FORMAT(GETDATE(),'yyyy-MM-dd 23:45:00'))
		BEGIN
			SET @shift=3
		END
		ELSE
		BEGIN
			SET @shift=1
		END
		return @shift
END
GO


-- ----------------------------
-- procedure structure for sp_qc_alarm_scrap
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_qc_alarm_scrap]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_qc_alarm_scrap]
GO

CREATE PROCEDURE [dbo].[sp_qc_alarm_scrap]
@FAC nvarchar(10), @BCOD nvarchar(20), @BNAM nvarchar(50), @RESULT nvarchar(10), @BARCODE nvarchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间
   DECLARE @ITNBR   NVARCHAR (50)                                     --规格代码
   DECLARE @ITDSC   NVARCHAR (100)                                    --规格名称
   DECLARE @DEPNAM   NVARCHAR (20)                                      --缺陷部门
   DECLARE @CUMCHID NVARCHAR (10)                                        --设备号
   DECLARE @LR nvarchar(1)                                              --左右
   DECLARE @RULECODE nvarchar(10)                                         --预警规则代码
   DECLARE @RULENAME nvarchar(100)                                         --预警规则描述
   DECLARE @BUMCHID NVARCHAR (10)                                        --设备号
   --DECLARE @LEVLCODE nvarchar(50)                                         --预警等级代码
   
   --获取当前时间的班次开始时间和班次结束时间
   --声明一个表用于获取班次信息
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;
   --若不良代码为空，则返回
   IF (@BCOD = '' or @BCOD is null)
     RETURN
   --基于不良代码获取其预警规则
   SELECT @RULECODE = ATTRIBUTE2 FROM QMA0006_DD WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','));
   --若规则代码为空，则返回
   IF (@RULECODE = '' or @RULECODE is null)
     RETURN
     
   DECLARE @BADCNT   INT
   DECLARE @ALMCNT   INT
   DECLARE @BARCODE_S NVARCHAR(MAX)
   
   IF @RULECODE = 'LH'--若规则是：同一硫化规格
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE1, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE1
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
        END
   IF @RULECODE = 'LHMJ'--若规则是：同一硫化规格，同一模具（机台）
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE1, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE1
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CX'
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一成型规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE1, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE1
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE1, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE1
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXGGJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH,@ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型规格+机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE1, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE1
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'MJ'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE1, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012  QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE1
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   --若报警标准数量为0或空，则返回
   IF @ALMCNT = 0
     RETURN
   --获取预警规则描述
   SELECT @RULENAME=DNAM FROM  EDA0004 WHERE DIV = 'ALARM_RULE_PCR' AND DCOD =@RULECODE
   --获取缺陷部门
   SELECT @DEPNAM = DEPNAM FROM QMB0012 WHERE BARCODE = @BARCODE
   --若缺陷数超过了报警标准数量，则继续
   IF @BADCNT >= @ALMCNT AND @DEPNAM!='' AND @DEPNAM!='无责任部门' AND @DEPNAM IS NOT NULL
      BEGIN
               --各字段不能是null，转换为空
               IF @DEPNAM IS NULL
                BEGIN
                  SET @DEPNAM =''
                END
               IF @CUMCHID IS NULL
                BEGIN
                  SET @CUMCHID =''
                END
               IF @LR IS NULL
                BEGIN
                  SET @LR =''
                END    
               IF @ITNBR IS NULL
                BEGIN
                  SET @ITNBR =''
                END    
               IF @ITDSC IS NULL
                BEGIN
                  SET @ITDSC =''
                END      
               IF @BUMCHID IS NULL
                BEGIN
                  SET @BUMCHID =''
                END     
				
				IF @BARCODE_S IS NULL
                BEGIN
                  SET @BARCODE_S =''
                END    

				IF @BARCODE IS NULL
                BEGIN
                  SET @BARCODE =''
                END    

               INSERT INTO SJC0003_PCR (FAC,
                                        CHKDIV,
                                        DIV,
                                        MCHID,
                                        LR,
                                        WDATE,
                                        WSHT,
                                        ITNBR,
                                        ITDSC,
                                        BCOD,
                                        BNAM,
                                        CONTENT,
                                        TXNTIME,
                                        HDFLAG,
                                        HDTIM,
                                        BUMCH,
                                        BARCODES,
                                        NOW_BARCODE)
               VALUES (@FAC,
                       'VI',
                       @DEPNAM,
                       @CUMCHID,
                       @LR,
                       @WDATE,
                       @SHT,
                       @ITNBR,
                       @ITDSC,
                       @BCOD,
                       @BNAM,
                       '['+@RULENAME+']废次品达到了' + CONVERT(NVARCHAR(10),@BADCNT) + '条',
                       GETDATE (),
                       'N',
                       NULL,
                       @BUMCHID,
                       @BARCODE_S,
                       @BARCODE);
      END
END
GO


-- ----------------------------
-- procedure structure for proChengXingChanLiang
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proChengXingChanLiang]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proChengXingChanLiang]
GO

CREATE PROCEDURE [dbo].[proChengXingChanLiang]
AS
BEGIN
	DECLARE @tiQianMi													INT=0, -- dbo.gettiqianMi(),
					@wdate														DATETIME=GETDATE();
	DECLARE @wTDate														datetime=DATEADD(mi, @tiQianMi, @wdate);
	DECLARE @shift														INT=dbo.GetBanCi(@wdate);
	DECLARE @beginHour												INT,
					@endHour													INT,
					@ShtName													nvarchar(1000);
	SELECT @beginHour=MIN(tbc.TimeHour),
					@endHour=MAX(tbc.TimeHour),
					@ShtName=tbc.ShtName
	  FROM vSystimeHour tBc with(nolock)
	 WHERE tbc.sht=@shift
	 GROUP BY tbc.ShtName;
	 SELECT @ShtName=ISNULL(@ShtName, '');
	
	with mainData as (
		SELECT DATEADD(mi, @tiQianMi, CUTIM) as hbCUTIM,
						DATEADD(mi, @tiQianMi, BUTIM) as hbBUTIM,
						DATEPART(HH, DATEADD(mi, @tiQianMi, CUTIM)) as hCUTIM,
						DATEPART(HH, DATEADD(mi, @tiQianMi, BUTIM)) as hBUTIM,
						ID
			FROM LTA0001 (NOLOCK)			
		 WHERE FAC != '02'
	),
  mainGroupData as (
	SELECT N'硫化'+@ShtName+N'产量' as timType, -- CUTIM	硫化时间
				 tsh.TimeHour,
				COUNT(t.ID) as LTA0001Count
	 from [dbo].vSystimeHour tsh with(nolock)
	LEFT JOIN	mainData t WITH(NOLOCK)
	on tsh.TimeHour=t.hCUTIM
	 and t.hbCUTIM BETWEEN FORMAT(@wdate,'yyyy-MM-dd 00:00:00')
	 and FORMAT(@wdate,'yyyy-MM-dd 23:59:59')
	 and t.hCUTIM BETWEEN @beginHour and @endHour
	 WHERE tsh.sht=@shift
	GROUP BY tsh.TimeHour
	UNION ALL
	SELECT N'成型'+@ShtName+N'产量' as timType, -- BUTIM	硫化时间
				tsh.TimeHour,
				COUNT(t.ID) as LTA0001Count
	 from [dbo].vSystimeHour tsh with(nolock)
	LEFT JOIN mainData t WITH(NOLOCK)
	on tsh.TimeHour=t.hBUTIM
	and t.hbBUTIM BETWEEN FORMAT(@wdate,'yyyy-MM-dd 00:00:00')
	 and FORMAT(@wdate,'yyyy-MM-dd 23:59:59')
	 and t.hBUTIM BETWEEN @beginHour and @endHour
	 WHERE tsh.sht=@shift
	GROUP BY tsh.TimeHour
	)
	SELECT t.*
	  from mainGroupData t with(nolock)
	ORDER BY t.timType,
					 t.TimeHour;
END
GO


