	DROP PROCEDURE [dbo].[sp_qc_alarm_repair]
GO

CREATE PROCEDURE [dbo].[sp_qc_alarm_repair]
@FAC nvarchar(10), @BCOD nvarchar(20), @BNAM nvarchar(50), @RESULT nvarchar(10), @BARCODE nvarchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间
   DECLARE @ITNBR   NVARCHAR (50)                                     --规格代码
   DECLARE @ITDSC   NVARCHAR (100)                                    --规格名称
   DECLARE @DEPNAM   NVARCHAR (20)                                      --缺陷部门
   DECLARE @CUMCHID NVARCHAR (10)                                        --设备号
   DECLARE @LR nvarchar(1)                                              --左右
   DECLARE @RULECODE nvarchar(10)                                         --预警规则代码
   DECLARE @RULENAME nvarchar(100)                                         --预警规则描述
   DECLARE @BUMCHID NVARCHAR (10)                                        --设备号
   --DECLARE @LEVLCODE nvarchar(50)                                         --预警等级代码
   
   --获取当前时间的班次开始时间和班次结束时间
   --声明一个表用于获取班次信息
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;
   --若不良代码为空，则返回
   IF (@BCOD = '' or @BCOD is null)
     RETURN
   --基于不良代码获取其预警规则
   SELECT @RULECODE = ATTRIBUTE2 FROM QMA0006_DD WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','));
   --若规则代码为空，则返回
   IF (@RULECODE = '' or @RULECODE is null)
     RETURN
     
   DECLARE @BADCNT   INT
   DECLARE @ALMCNT   INT
   DECLARE @BARCODE_S NVARCHAR(MAX)
   
   IF @RULECODE = 'LH'--若规则是：同一硫化规格
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE4, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE4
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
        END
   IF @RULECODE = 'LHMJ'--若规则是：同一硫化规格，同一模具（机台）
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE4, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE4
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CX'
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一成型规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE4, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE4
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE4, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE4
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXGGJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH,@ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型规格+机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE4, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE4
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'MJ'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE4, 0),
                    @BARCODE_S = BARCODES 
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE4
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   --若报警标准数量为0或空，则返回
   IF @ALMCNT = 0
     RETURN
   --获取预警规则描述
   SELECT @RULENAME=DNAM FROM  EDA0004 WHERE DIV = 'ALARM_RULE_PCR' AND DCOD =@RULECODE
   --获取缺陷部门
   SELECT @DEPNAM = DEPNAM FROM QMB0012 WHERE BARCODE = @BARCODE
   --若缺陷数超过了报警标准数量，则继续
   IF @BADCNT >= @ALMCNT AND @DEPNAM!='' AND @DEPNAM!='无责任部门' AND @DEPNAM IS NOT NULL
      BEGIN
               --各字段不能是null，转换为空
               IF @DEPNAM IS NULL
                BEGIN
                  SET @DEPNAM =''
                END
               IF @CUMCHID IS NULL
                BEGIN
                  SET @CUMCHID =''
                END
               IF @LR IS NULL
                BEGIN
                  SET @LR =''
                END    
               IF @ITNBR IS NULL
                BEGIN
                  SET @ITNBR =''
                END    
               IF @ITDSC IS NULL
                BEGIN
                  SET @ITDSC =''
                END      
               IF @BUMCHID IS NULL
                BEGIN
                  SET @BUMCHID =''
                END   
                
               INSERT INTO SJC0003_PCR (FAC,
                                        CHKDIV,
                                        DIV,
                                        MCHID,
                                        LR,
                                        WDATE,
                                        WSHT,
                                        ITNBR,
                                        ITDSC,
                                        BCOD,
                                        BNAM,
                                        CONTENT,
                                        TXNTIME,
                                        HDFLAG,
                                        HDTIM,
                                        BUMCH,
                                        BARCODES,
                                        NOW_BARCODE)
               VALUES (@FAC,
                       'VI',
                       @DEPNAM,
                       @CUMCHID,
                       @LR,
                       @WDATE,
                       @SHT,
                       @ITNBR,
                       @ITDSC,
                       @BCOD,
                       @BNAM,
                       '['+@RULENAME+']修理品达到了' + CONVERT(NVARCHAR(10),@BADCNT) + '条',
                       GETDATE (),
                       'N',
                       NULL,
                       @BUMCHID,
                       @BARCODE_S,
                       @BARCODE);
      END
END
GO


-- ----------------------------
-- procedure structure for sp_qc_alarm_grind
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_qc_alarm_grind]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_qc_alarm_grind]
GO

CREATE PROCEDURE [dbo].[sp_qc_alarm_grind]
@FAC nvarchar(10), @BCOD nvarchar(20), @BNAM nvarchar(50), @RESULT nvarchar(10), @BARCODE nvarchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间
   DECLARE @ITNBR   NVARCHAR (50)                                     --规格代码
   DECLARE @ITDSC   NVARCHAR (100)                                    --规格名称
   DECLARE @DEPNAM   NVARCHAR (20)                                      --缺陷部门
   DECLARE @CUMCHID NVARCHAR (10)                                        --设备号
   DECLARE @LR nvarchar(1)                                              --左右
   DECLARE @RULECODE nvarchar(10)                                         --预警规则代码
   DECLARE @RULENAME nvarchar(100)                                         --预警规则描述
   DECLARE @BUMCHID NVARCHAR (10)                                        --设备号
   --DECLARE @LEVLCODE nvarchar(50)                                         --预警等级代码
   
   --获取当前时间的班次开始时间和班次结束时间
   --声明一个表用于获取班次信息
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;
   --若不良代码为空，则返回
   IF (@BCOD = '' or @BCOD is null)
     RETURN
   --基于不良代码获取其预警规则
   SELECT @RULECODE = ATTRIBUTE2 FROM QMA0006_DD WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','));
   --若规则代码为空，则返回
   IF (@RULECODE = '' or @RULECODE is null)
     RETURN
     
   DECLARE @BADCNT   INT
   DECLARE @ALMCNT   INT
   DECLARE @BARCODE_S NVARCHAR(MAX)
   
   
   IF @RULECODE = 'LH'--若规则是：同一硫化规格
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE5, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE5
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
        END
   IF @RULECODE = 'LHMJ'--若规则是：同一硫化规格，同一模具（机台）
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE5, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE5 
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CX'
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一成型规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE5, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE5
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE5, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE5
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXGGJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH,@ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型规格+机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE5, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE5
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'MJ'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ATTRIBUTE5, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W3')) BADCNT
                  LEFT JOIN (SELECT ATTRIBUTE5
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   --若报警标准数量为0或空，则返回
   IF @ALMCNT = 0
     RETURN
   --获取预警规则描述
   SELECT @RULENAME=DNAM FROM  EDA0004 WHERE DIV = 'ALARM_RULE_PCR' AND DCOD =@RULECODE
   --获取缺陷部门
   SELECT @DEPNAM = DEPNAM FROM QMB0012 WHERE BARCODE = @BARCODE
   --若缺陷数超过了报警标准数量，则继续
   IF @BADCNT >= @ALMCNT AND @DEPNAM!='' AND @DEPNAM!='无责任部门' AND @DEPNAM IS NOT NULL
      BEGIN
               --各字段不能是null，转换为空
               IF @DEPNAM IS NULL
                BEGIN
                  SET @DEPNAM =''
                END
               IF @CUMCHID IS NULL
                BEGIN
                  SET @CUMCHID =''
                END
               IF @LR IS NULL
                BEGIN
                  SET @LR =''
                END    
               IF @ITNBR IS NULL
                BEGIN
                  SET @ITNBR =''
                END    
               IF @ITDSC IS NULL
                BEGIN
                  SET @ITDSC =''
                END      
               IF @BUMCHID IS NULL
                BEGIN
                  SET @BUMCHID =''
                END   
                
               INSERT INTO SJC0003_PCR (FAC,
                                        CHKDIV,
                                        DIV,
                                        MCHID,
                                        LR,
                                        WDATE,
                                        WSHT,
                                        ITNBR,
                                        ITDSC,
                                        BCOD,
                                        BNAM,
                                        CONTENT,
                                        TXNTIME,
                                        HDFLAG,
                                        HDTIM,
                                        BUMCH,
                                        BARCODES,
                                        NOW_BARCODE)
               VALUES (@FAC,
                       'VI',
                       @DEPNAM,
                       @CUMCHID,
                       @LR,
                       @WDATE,
                       @SHT,
                       @ITNBR,
                       @ITDSC,
                       @BCOD,
                       @BNAM,
                       '['+@RULENAME+']打磨品达到了' + CONVERT(NVARCHAR(10),@BADCNT) + '条',
                       GETDATE (),
                       'N',
                       NULL,
                       @BUMCHID,
                       @BARCODE_S,
                       @BARCODE);
      END
END
GO


-- ----------------------------
-- procedure structure for Proc_Util_GetLenOverflowColumns
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Proc_Util_GetLenOverflowColumns]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Proc_Util_GetLenOverflowColumns]
GO

CREATE PROCEDURE [dbo].[Proc_Util_GetLenOverflowColumns]
	@targetTableName NVARCHAR(100),	--要插入的目标表
	@tmpTableName NVARCHAR(100)	--插入数据生成的临时表
AS
BEGIN
	SET NOCOUNT ON;
	;WITH t1 AS (
		SELECT * FROM sys.columns AS a WHERE a.object_id=OBJECT_ID(@targetTableName)
	),t2 AS (
		SELECT * FROM sys.columns AS b WHERE b.object_id=OBJECT_ID(@tmpTableName)
	)
	SELECT
		OBJECT_NAME(t1.OBJECT_ID)As targetTableName
		,OBJECT_NAME(t2.OBJECT_ID) AS tmpTableName
		,t1.name AS columnName
		,t1.max_length AS targetMaxlen
		,t2.max_length AS tmpMaxlen
		,tp1.name AS targetColType
		,tp2.name As tmpColType
	FROM t1 INNER JOIN t2 ON t1.name=t2 .name 
		INNER JOIN sys.types As tp1 ON t1.system_type_id=tp1.system_type_id
		INNER JOIN sys.types AS tp2 ON t2.system_type_id=tp2.system_type_id
	WHERE t1.max_length<t2.max_length
AND t1.max_length!=-1	--排除原表字段为 max 的情况
AND tp1.name!='sysname'
AND tp2.name!='sysname'

END
GO


-- ----------------------------
-- procedure structure for reBuildIndex
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[reBuildIndex]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[reBuildIndex]
GO

CREATE PROCEDURE [dbo].[reBuildIndex]
AS
DECLARE @objectid INT;
DECLARE @indexid INT;
DECLARE @partitioncount BIGINT;
DECLARE @schemaname sysname;
DECLARE @objectname sysname;
DECLARE @indexname sysname;
DECLARE @partitionnum BIGINT;
DECLARE @partitions BIGINT;
DECLARE @frag FLOAT;
DECLARE @command VARCHAR(8000);
IF EXISTS (SELECT name FROM sys.objects WHERE name = 'work_to_do')
    DROP TABLE work_to_do;
SELECT object_id AS objectid,
       index_id AS indexid,
       partition_number AS partitionnum,
       avg_fragmentation_in_percent AS frag
INTO work_to_do
FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED')
WHERE avg_fragmentation_in_percent > 10.0
      AND index_id > 0;
 
SELECT *
FROM dbo.work_to_do;
 
DECLARE @count INT;
SELECT @count = COUNT(1)
FROM work_to_do;
PRINT '共计需要处理的索引数量为：' + CAST(@count AS VARCHAR);
 
DECLARE @begin DATETIME;
SET @begin = GETDATE();
 
DECLARE partitions CURSOR FOR SELECT * FROM work_to_do;
OPEN partitions;
FETCH NEXT FROM partitions
INTO @objectid,
     @indexid,
     @partitionnum,
     @frag;
WHILE @@FETCH_STATUS = 0
BEGIN;
    SELECT @objectname = o.name,
           @schemaname = s.name
    FROM sys.objects AS o
        JOIN sys.schemas AS s
            ON s.schema_id = o.schema_id
    WHERE o.object_id = @objectid;
    SELECT @indexname = name
    FROM sys.indexes
    WHERE object_id = @objectid
          AND index_id = @indexid;
    SELECT @partitioncount = COUNT(*)
    FROM sys.partitions
    WHERE object_id = @objectid
          AND index_id = @indexid;
    
    IF @frag <= 30.0 AND  @frag >= 10.0
    BEGIN;
		PRINT '正在处理索引 ' + @objectname + ' -> ' + @indexname + ' 碎片率 ' + CAST(@frag AS VARCHAR) + '%';
        SELECT @command = 'ALTER INDEX ' + @indexname + ' ON ' + @schemaname + '.' + @objectname + ' REORGANIZE';
        IF @partitioncount > 1
            SELECT @command = @command + ' PARTITION=' + CONVERT(CHAR, @partitionnum);
        PRINT '正在重新组织...';
        EXEC (@command);
    END;
    IF @frag > 30.0
    BEGIN;
		PRINT '正在处理索引 ' + @objectname + ' -> ' + @indexname + ' 碎片率 ' + CAST(@frag AS VARCHAR) + '%';
        SELECT @command = 'ALTER INDEX ' + @indexname + ' ON ' + @schemaname + '.' + @objectname + ' REBUILD';
        IF @partitioncount > 1
            SELECT @command = @command + ' PARTITION=' + CONVERT(CHAR, @partitionnum);
        PRINT '正在重新生成...';
        EXEC (@command);
    END;
    FETCH NEXT FROM partitions
    INTO @objectid,
         @indexid,
         @partitionnum,
         @frag;
END;
-- Close and deallocate the cursor.
CLOSE partitions;
DEALLOCATE partitions;
 
PRINT '处理完毕，共计耗时：' + CAST(DATEDIFF(SECOND, @begin, GETDATE()) AS VARCHAR) + '秒';
 
IF EXISTS (SELECT name FROM sys.objects WHERE name = 'work_to_do')
    DROP TABLE work_to_do;
GO


-- ----------------------------
-- procedure structure for Proc_GetSEQ
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Proc_GetSEQ]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Proc_GetSEQ]
GO

CREATE PROCEDURE [dbo].[Proc_GetSEQ] (@TableName NVARCHAR(50)) WITH EXECUTE AS OWNER  -- 以所有者权限运行
as
BEGIN
DECLARE @SQL NVARCHAR(500)
SET @SQL=N'INSERT INTO ' + @TableName+ ' (VALUE) SELECT '''';
SELECT @@IDENTITY AS NUM;
IF @@IDENTITY >=9999
BEGIN
DBCC CHECKIDENT('+@TableName+', RESEED, 0);
END
DELETE '+@TableName+';'
exec sp_executesql @SQL
END
GO


-- ----------------------------
-- procedure structure for pr_gettire_sort_PCR
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pr_gettire_sort_PCR]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pr_gettire_sort_PCR]
GO

CREATE PROCEDURE [dbo].[pr_gettire_sort_PCR]
@barcode varchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   --设置事务为读
   SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

   DECLARE
      @itnbr       VARCHAR (50),
      @itdsc       VARCHAR (80),
      @is_hold     CHAR (1),
      @is_trial    CHAR (1),
      @is_xray     CHAR (1),
      @is_sds      CHAR (1),
      @is_recheck  CHAR (1),
      @is_freeinsp CHAR (1),
      @ub_mchine   VARCHAR (255),
      @prior_mch   VARCHAR (255),
      @cnt         INT,
      @cnt_prior   INT,
      @ufyn        CHAR (1),
      @dbyn        CHAR (1),
      @mchid       VARCHAR (20),
      @mchid_p     VARCHAR (20),
	  @mchid_16    VARCHAR (20),
      @mchid_17    VARCHAR (20),
      @recheck_rule VARCHAR(2),
      @recheck_rule_val INT,
      @recheck_no  VARCHAR(30),
      @xray_rule   VARCHAR(2),
	  --@xray_rule_val INT,
      @xray_rule_val FLOAT,
      @sds_rule   VARCHAR(2),
      @sds_rule_val INT,
	  @recheck_mch VARCHAR(10),
      @current_mch VARCHAR(10),
	  @recheck_bad_val INT,
	  @recheck_per VARCHAR(10),
	  @recheck_per_val INT

   SET @itnbr = ''
   SET @itdsc = ''
   SET @is_hold = ''
   SET @is_trial = ''
   SET @is_xray = 'N'--默认不X光
   SET @is_sds = 'N'--默认不SDS
   SET @is_recheck = 'N'--默认不复检
   SET @is_freeinsp = 'N'--默认非免检
   SET @ub_mchine = ''
   SET @prior_mch = ''
   SET @mchid_16 = '02DJ016'
   SET @mchid_17 = '02DJ017'
   SET @recheck_mch = ''--复检全检指定生效硫化机台
   SET @current_mch = ''--当前条码硫化机台
   SET @recheck_per = ''--质检人员工号


   SET @cnt = 0
   SET @cnt_prior = 0
   SET @mchid = ''
   SET @ufyn = ''
   SET @dbyn = ''
   SET @mchid_p = ''
   SET @recheck_no = ''

   --获取条码信息
   SELECT TOP 1
          @itnbr = TB.MATERIALID,
          @itdsc = TB.MATERIALNAME,
		  @current_mch = ISNULL(TB.SulfEquipCode,''),
          @is_trial =
             CASE WHEN (ISNULL (LT.CUSTATE, '') = '2' OR ISNULL (LT.ATTRIBUTE2, '') = 'Y')
                        THEN 'Y' ELSE 'N' END,
          @is_hold = ISNULL (WIP.LOCKYN, N'N')
   FROM tb_PP_CuringOutPut AS TB
        LEFT OUTER JOIN LTA0001 AS LT ON TB.TYRENO = LT.TYRENO
        LEFT OUTER JOIN WIP0010 AS WIP ON TB.TYRENO = WIP.TYRENO
   WHERE TB.TYRENO = @barcode
   --获取条码最后一次外观质检人员工号
   SELECT TOP 1 @recheck_per = LOGINNAM  FROM QMB0001 WHERE DIV='1' AND FAC='02' AND BARCODE=@barcode ORDER BY CHECKTIM
   --判断能去哪个UB机
   SELECT A.MCHID,
          A.LNUM,
          B.RIMNO,
          A.UFYN,
          A.DBYN
   INTO #TEMP_T1
   FROM CKA0003 A, QMB0203 B
   WHERE     A.MCHID = B.MCHID
         AND A.LNUM = B.RIMNO
         AND B.MCHID NOT IN ('02DJ001',
                             '02DJ002',
                             '02DJ003',
                             '02DJ004')                        --老区动均设备不参与自动分拣
         AND A.ITNBR = @itnbr


   SELECT @cnt = count (1) FROM #TEMP_T1

   IF @cnt > 0
      BEGIN
         DECLARE
            cur_temp1 CURSOR FOR SELECT MCHID, UFYN, DBYN FROM #TEMP_T1

         OPEN cur_temp1
         FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn

         WHILE @@FETCH_STATUS = 0
         BEGIN
            --若均匀性和动平衡为N,则为免检
            IF (@ufyn = 'N' AND @dbyn = 'N')
               BEGIN
                  SET @ub_mchine = ''
                  SET @is_freeinsp = 'Y'
                  BREAK
               END
            ELSE
               BEGIN
                  SET @ub_mchine = @ub_mchine + @mchid + ','
               END

            FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn        --下一个
         END

         IF @ub_mchine ! = ''
            BEGIN
               SET @ub_mchine = LEFT (@ub_mchine, LEN (@ub_mchine) - 1)
            END

         CLOSE cur_temp1
         DEALLOCATE cur_temp1
      END

   --设备优先.
   IF (@ub_mchine ! = '' AND @ub_mchine ! = 'NONE')
      BEGIN
         --SELECT DISTINCT MCHID
         --INTO #TEMP_T2
         --FROM CKA0004
         --WHERE itnbr = @itnbr AND ONEYN = 'Y'
         
        SELECT DISTINCT C1.MCHID INTO #TEMP_T2 FROM CKA0003 C1 LEFT JOIN CKA0004 C2
        ON C1.MCHID=C2.MCHID AND C1.TCOD=C2.TCOD AND C1.ITNBR=C2.ITNBR 
        WHERE C1.ITNBR=@itnbr AND C2.ONEYN = 'Y'

        SELECT @cnt_prior = count (1) FROM #TEMP_T2

         IF @cnt_prior > 0
            BEGIN
               DECLARE
                  cur_temp2 CURSOR FOR SELECT MCHID FROM #TEMP_T2

               OPEN cur_temp2
               FETCH NEXT FROM cur_temp2   INTO @mchid_p

               WHILE @@FETCH_STATUS = 0
               BEGIN
                  SET @prior_mch = @prior_mch + @mchid_p + ','
                  FETCH NEXT FROM cur_temp2   INTO @mchid_p              --下一个
               END

               IF @prior_mch ! = ''
                  BEGIN
                     SET @prior_mch = LEFT (@prior_mch, LEN (@prior_mch) - 1)
                  END

               CLOSE cur_temp2
               DEALLOCATE cur_temp2
--Add By GCZhang 20250310 
--对于同一规格有多检测机检测的情况，虽优先级已设为16,17动均机，但由于原分拣上位机不识别16,17动均机，仍会将胎分拨到其它机台。
--为解决上述问题，系统增加处理逻辑，若优先机台包含16,17动均机的，首次扫描则认为是冻结，以便继续向南运输，使其分拣到16,17机台，第二次时则恢复正常逻辑
			   IF (@mchid_16 IN (SELECT MCHID FROM #TEMP_T2) OR @mchid_17 IN (SELECT MCHID FROM #TEMP_T2) ) 
                  BEGIN
--若物流调用记录中已存在<冻结>并且<分科捷>，则代表物流线由于某些原因（主要是道口满）上次没分科捷，则之后不再分往科捷。
					  IF NOT EXISTS (select ID from CKA0009 where Barcode = @barcode AND IS_HOLD = 'Y' AND is_freeinsp = 'K') 
						  BEGIN
						  SET @is_hold = 'Y'
						  SET @is_freeinsp = 'K'	
						  END
					  ELSE
						  BEGIN
                          SET @is_hold = @is_hold
						  SET @is_freeinsp = @is_freeinsp		
						  END
                  END
--END By GCZhang 20250310 

            END
        DROP TABLE #TEMP_T2
      END

   --删除临时表
   DROP TABLE #TEMP_T1
   
   --判断是否复检,X光,SDS
   IF (@itnbr!='' and @itnbr is not null)
     BEGIN
      DECLARE @rchk_cnt_per INT,
              @rchk_sum_cnt INT,
              @xray_cnt_per INT,
              @xray_sum_cnt INT,
              @sds_cnt_per INT,
              @sds_sum_cnt INT
      --根据规格获取分拣策略
      SELECT @recheck_rule=RECHECK_RULE,
             @recheck_rule_val=RECHECK_RULE_VAL,
             @recheck_no=RECHECK_NO,
             @xray_rule = XRAY_RULE,
             @xray_rule_val = XRAY_RULE_VAL,
             @sds_rule = SDS_RULE,
             @sds_rule_val = SDS_RULE_VAL,
			 @recheck_mch = ISNULL(RECHECK_MCH,'')
             FROM CKA0006
             WHERE  ITNBR = @itnbr

      --获取缺陷代码结算复检比例，复检口用[半钢]终检分拣策略默认值 20260527 add by xupguo
	  SELECT @recheck_bad_val = ISNULL(PUSH_RATIO_FINAL,'0') FROM XJB0009 WHERE ITNBR = @itnbr
	  IF @recheck_bad_val > @recheck_rule_val
	    BEGIN
		  SET @recheck_rule = '1'
		  SET @recheck_rule_val = @recheck_bad_val
		END
      --判断复检口
      IF @recheck_rule = '0'--若规则是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
            BEGIN
			  IF @recheck_mch = ''--复检硫化机台为空时，所有都要复检
				  SET @is_recheck = 'Y'
			  ELSE
			    BEGIN
				  IF @recheck_mch = @current_mch--复检硫化机台匹配的复检
					SET @is_recheck = 'Y'
				END
			END
        END
      IF @recheck_rule = '2'--若规则是不检
        BEGIN
          SET @is_recheck = 'N'
          SET @recheck_no = ''
        END
      IF @recheck_rule = '1' --若规则是抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,1,0,0)
          ELSE
            UPDATE CKA0060 SET RECHECKSUMQTY = RECHECKSUMQTY+1 WHERE ITNBR = @itnbr
          SET @rchk_cnt_per = round(100/cast(@recheck_rule_val as float),0)--获取每多少个检测一个（复检）
          SELECT @rchk_sum_cnt = RECHECKSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
                SET @is_recheck = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_recheck = 'N'
              SET @recheck_no = ''
            END
        END
	  --规格复检检查完毕后，对质检人员复检检查 20250527 add by xupguo
	  IF @is_recheck = 'N'
	    BEGIN
	      --获取人员复检比例
		  SELECT @recheck_per_val=RATIO_VALUE,@recheck_rule=RATIO,@recheck_no=RE_INSPECTION_PORT FROM XJB0008 WHERE LOGINNAME=@recheck_per
          IF @recheck_rule = '0'--全检
			BEGIN
			 IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
		      SET @is_recheck='Y'
			END
		  IF @recheck_rule = '1'--抽检
		   BEGIN
            IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @recheck_per)
             INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@recheck_per,1,0,0)
            ELSE
             UPDATE CKA0060 SET RECHECKSUMQTY = RECHECKSUMQTY+1 WHERE ITNBR = @recheck_per
            SET @rchk_cnt_per = round(100/cast(@recheck_per_val as float),0)--获取每多少个检测一个（复检）
            SELECT @rchk_sum_cnt = RECHECKSUMQTY FROM CKA0060 WHERE ITNBR = @recheck_per
            IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
              BEGIN
               IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
                SET @is_recheck = 'Y'
              END
            ELSE --若未达到
              BEGIN
               SET @is_recheck = 'N'
               SET @recheck_no = ''
              END
           END
		END

      --判断X光
      IF @xray_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
            SET @is_xray = 'Y'
        END
      IF @xray_rule = '2'--若不检
        BEGIN
          SET @is_xray = 'N'
        END
      IF @xray_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,1,0)
          ELSE
            UPDATE CKA0060 SET XRAYSUMQTY = XRAYSUMQTY+1 WHERE ITNBR = @itnbr
          SET @xray_cnt_per = round(100/cast(@xray_rule_val as float),0)--获取每多少个检测一个（X光）
          SELECT @xray_sum_cnt = XRAYSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@xray_sum_cnt % @xray_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
                SET @is_xray = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_xray = 'N'
            END
          --若物流调用记录中已存在<不冻结>并且<分X光>，则代表物流线由于某些原因（主要是X光道口满）上次没分X光，则之后不再分往X光。2021-10-01 质检车间要求
          IF EXISTS(SELECT BARCODE FROM CKA0009 WHERE BARCODE = @barcode AND IS_HOLD = 'N' AND IS_XRAY = 'Y')
            BEGIN
              SET @is_xray = 'N'
            END
        END
        
      --判断SDS
      IF @sds_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
            SET @is_sds = 'Y'
        END
      IF @sds_rule = '2'--若不检
        BEGIN
          SET @is_sds = 'N'
        END
      IF @sds_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,0,1)
          ELSE
            UPDATE CKA0060 SET SDSSUMQTY = SDSSUMQTY+1 WHERE ITNBR = @itnbr
          SET @sds_cnt_per = round(100/cast(@sds_rule_val as float),0)--获取每多少个检测一个（SDS）
          SELECT @sds_sum_cnt = SDSSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@sds_sum_cnt % @sds_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
                SET @is_sds = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_sds = 'N'
            END
        END
     END
   --记录物流线调用履历(先只记录需检X光的) MODIFYED By GCZhang 20250310 增加优先级含16、17动均机的分拣履历
   --IF(@is_xray = 'Y')
   IF(@is_xray = 'Y' OR @is_freeinsp = 'K') 
      BEGIN
        INSERT INTO CKA0009
       (FAC, BARCODE, ITNBR, ITDSC, IS_HOLD, IS_TRIAL, IS_XRAY, IS_RECHECK, IS_FREEINSP, UB_MCHINE, PRIOR_MCH, RECHECK_NO, IS_SDS, CALLTIM) 
       VALUES ('02', @barcode, @itnbr, @itdsc, @is_hold, @is_trial, @is_xray, @is_recheck, @is_freeinsp, @ub_mchine, @prior_mch, @recheck_no, @is_sds, getdate())
      END
   --若规格为空则返回空行.MODIFYED By GCZhang 20240613 DC胎改为从无信息下胎口下胎
   --IF @itnbr='' or @itnbr is null
   IF @itnbr='' or @itnbr is null or @is_trial = 'Y'
     BEGIN
         SELECT '' barcode,
                '' itnbr,
                '' itdsc,
                '' is_hold,
                '' is_trial,
                '' is_xray,
                '' is_recheck,
                '' is_freeinsp,
                '' ub_mchine,
                '' prior_mch,
                '' recheck_no,
                '' is_sds
                WHERE 0 = 1
     END
   ELSE
     BEGIN
         --返回测试代号.
         SELECT @barcode barcode,
                @itnbr itnbr,
                @itdsc itdsc,
                @is_hold is_hold,
                @is_trial is_trial,
                @is_xray is_xray,
                @is_recheck is_recheck,
                @is_freeinsp is_freeinsp,
                @ub_mchine ub_mchine,
                @prior_mch prior_mch,
                @recheck_no recheck_no,
                @is_sds is_sds
     END
END
GO


-- ----------------------------
-- procedure structure for GET_PPB0202_GTPRO_BYPLANCOD_BOM
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GET_PPB0202_GTPRO_BYPLANCOD_BOM]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GET_PPB0202_GTPRO_BYPLANCOD_BOM]
GO

CREATE PROCEDURE [dbo].[GET_PPB0202_GTPRO_BYPLANCOD_BOM] 
	 @PLANCOD NVARCHAR(50)
AS
BEGIN

SET NOCOUNT ON;

DECLARE @MCHID NVARCHAR(20)	 
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
  
SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD 
FROM PAD0201_GT WHERE PLANCOD=@PLANCOD;

IF(@VERSION='')
BEGIN
	SELECT @VERSION= MAX(CONVERT(INT,VERSION))  
	FROM EDD0001 WHERE ITNBR=@ITNBR  AND SHFLAG='Y';
END 

SELECT 
	ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo,
	PCSBOMWeight,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,
	PCSCuttinglength,PCSCuttingWidth 
INTO #T2 
FROM EDD0061 
WHERE ParentMatID=@itnbr 
  AND ParentMatEditionNo=@version  
  AND ParentMatType=@outtypecod


-- 最终查询（无任何UPDATE、无写入数据库）
select distinct 
	SubMatID ITNBR,
	SubMatID ITDSC,
	0 QTY
from #T2 temp 
 
drop table #T2
END
GO


-- ----------------------------
-- function structure for GetPLANNO_LHPPB
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetPLANNO_LHPPB]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetPLANNO_LHPPB]
GO

CREATE FUNCTION [dbo].[GetPLANNO_LHPPB]
(
	@WDATE DATETIME,			--早中晚
	@LR NVARCHAR(1),			--左右
	@MCHID NVARCHAR(30),			--机台号
	@SEQ NVARCHAR(3)  --顺序
)
RETURNS NVARCHAR(30)
AS 
BEGIN
	 DECLARE @Result NVARCHAR(30),@YMD NVARCHAR(8),@MaxNum INT,@Zero NVARCHAR(10),@Counts INT,@NumL INT,@NumR INT,@Maxnumppb INT
	 SET @Zero='';
	 SET @Counts=0;
	 SET @NumL=0;
	 SET @NumR=0;  
	 --获取当天工单号，当包含D或者E时，会被系统判断为数字，调整过滤条件（2025-11-12 Guoxp）	
	 SELECT @MaxNum = CASE WHEN ISNULL(MAX(RIGHT(ORDERNOA,5))+1,0)=0 THEN 1 ELSE MAX(RIGHT(ORDERNOA,5))+1 END
			FROM PPB0201 AS p 
			WHERE p.WDATE=@WDATE AND ISNULL(ORDERNOA,'')<>''   and ISNUMERIC(RIGHT(ORDERNOA,5))=1 AND UPPER(RIGHT(ORDERNOA,5)) NOT LIKE '%D%'  AND UPPER(RIGHT(ORDERNOA,5)) NOT LIKE '%E%' 
	 --查询同机台号左机台计划数量
	 --判断如果是左边的，就去找右边的顺序相同并且同机台的工单号。反之就去找左边的 
	 IF @LR='L'
	 BEGIN
	 	SELECT @MaxNum=CASE WHEN RIGHT(ORDERNOA,5) IS NULL THEN @MaxNum ELSE RIGHT(ORDERNOA,5) END  FROM PPB0201 
                WHERE MCHID=@MCHID AND WDATE=@WDATE AND LR='R' AND SEQA=@SEQ
             ORDER BY ETIM DESC
	 END
	 ELSE
	 BEGIN
	 	
	 	SELECT @MaxNum=CASE WHEN RIGHT(ORDERNOA,5) IS NULL THEN @MaxNum ELSE RIGHT(ORDERNOA,5) END  FROM PPB0201 
                WHERE MCHID=@MCHID AND WDATE=@WDATE AND LR='L' AND SEQA=@SEQ
             ORDER BY ETIM DESC
	  
	 END
	 
			-- SELECT @NumL=COUNT(1) FROM PLA0009 AS p 
-- 			WHERE p.WDATE=@WDATE AND ISNULL(ORDERNOA,'')<>''  AND p.MCHID=@MCHID AND p.LR='L'
-- 			--查询同机台号右机台计划数量
-- 			SELECT @NumR=COUNT(1) FROM PLA0009 AS p 
-- 			WHERE p.WDATE=@WDATE AND ISNULL(ORDERNOA,'')<>''  AND p.MCHID=@MCHID AND p.LR='R'
-- 			IF @NumL=@NumR OR @NumL<@NumR
-- 				BEGIN
-- 					SET @MaxNum = @MaxNum+1;
-- 				END
     --获取年月日
     SELECT @YMD=SUBSTRING(CONVERT(NVARCHAR(4),YEAR(GETDATE())),3 , 2)
     	+CASE WHEN LEN(CONVERT(NVARCHAR(2),MONTH(@WDATE)))>1 THEN CONVERT(NVARCHAR(2),MONTH(@WDATE)) ELSE '0'+CONVERT(NVARCHAR(2),MONTH(@WDATE)) END
		+CASE WHEN LEN(CONVERT(NVARCHAR(2),DAY(@WDATE)))>1 THEN CONVERT(NVARCHAR(2),DAY(@WDATE)) ELSE '0'+CONVERT(NVARCHAR(2),DAY(@WDATE)) END;
	 --长度不足补零
	 SET @Counts = LEN(@MaxNum)
	 WHILE @Counts<5
	 BEGIN
	 	SET @ZERO =@Zero+'0';
	 	SET @Counts = @Counts+1;
	 END
     SET @Result=@YMD+@Zero+CONVERT(NVARCHAR(5),@MaxNum);
     RETURN @Result
END
GO


-- ----------------------------
-- procedure structure for SETNEWCARNO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SETNEWCARNO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SETNEWCARNO]
GO

CREATE PROCEDURE [dbo].[SETNEWCARNO] 
AS
BEGIN
	declare @Transfercardnumber nvarchar(30);
	declare @ShelfNumber nvarchar(30);
	declare @newTransfercardnumber nvarchar(30);
	declare @Serialnumber nvarchar(30);

	if exists( select top 1 t1.Transfercardnumber from 
	(
	SELECT  Transfercardnumber, COUNT(ID) num FROM STC0017 WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop IN ('01','03')   GROUP BY Transfercardnumber 
	) t1
	inner join
	(SELECT Transfercardnumber,COUNT(id) num FROM STC0017  WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop IN ('01','03')  GROUP BY Transfercardnumber,ShelfNumber
	) t2 on t1.Transfercardnumber=t2.Transfercardnumber and t1.num>t2.num)
	begin
			select top 1 @Transfercardnumber=t1.Transfercardnumber from 
		(
		SELECT  Transfercardnumber, COUNT(ID) num FROM STC0017 WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop IN ('01','03')    GROUP BY Transfercardnumber 
		) t1
		inner join
		(SELECT Transfercardnumber,COUNT(id) num FROM STC0017  WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop IN ('01','03')   GROUP BY Transfercardnumber,ShelfNumber
		) t2 on t1.Transfercardnumber=t2.Transfercardnumber and t1.num>t2.num
			select top 1 @ShelfNumber=ShelfNumber from STC0017 where Transfercardnumber=@Transfercardnumber

			SELECT  @Serialnumber=right('0000'+cast(MAX(NM)+1  as varchar),5)   FROM (
		SELECT SUBSTRING(Transfercardnumber,11,5) AS NM FROM STC0017 WHERE Transfercardnumber LIKE CONVERT(VARCHAR(100),GETDATE(),112)+'01%'
		UNION ALL
		SELECT SUBSTRING(Transfercardnumber,11,5) AS NM FROM STC0017 WHERE Transfercardnumber LIKE CONVERT(VARCHAR(100),GETDATE(),112)+'03%'
		) AS TBB 
		SELECT @newTransfercardnumber=CONVERT(varchar(8),GETDATE(),112)+'01'+@Serialnumber

		UPDATE STC0017 SET Transfercardnumber=@newTransfercardnumber ,Serialnumber=@Serialnumber,UPDTIM=GETDATE() WHERE Transfercardnumber=@Transfercardnumber AND ShelfNumber=@ShelfNumber AND workshop IN ('01','03') 
		UPDATE STC0019 SET Transfercardnumber=@newTransfercardnumber,UPDTIM=GETDATE()  WHERE Transfercardnumber=@Transfercardnumber AND ShelfNumber=@ShelfNumber AND workshop IN ('01','03') 


		
	--	update STC0017 set GOODSSTATE='5' where Transfercardnumber in (SELECT distinct Transfercardnumber FROM STC0019  a inner join STC0018 b on a.Warehousereceipt=b.Warehousereceipt and b.STATE='3'  ) and CRTIM>DATEADd(MI,-10,getdate()) ;

	end 
END
GO


-- ----------------------------
-- procedure structure for CURE_TECH_CHECK_FIRST
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CURE_TECH_CHECK_FIRST]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CURE_TECH_CHECK_FIRST]
GO

CREATE PROCEDURE [dbo].[CURE_TECH_CHECK_FIRST]
	@QQQID NVARCHAR(50),@REGNAM NVARCHAR(50)
AS
BEGIN 
	declare @Cnt int
    set @Cnt = (
                       SELECT COUNT(1) AS CNT
                         FROM QMA0005 
                        WHERE QAID =( SELECT QAID FROM QMA0005 WHERE ID=@QQQID) AND IS_OK ='0')
    if(@Cnt = 0)
      begin
        UPDATE QMA0004 
           SET CONF_YN ='',REGNAM=@REGNAM, CHKTIM=GETDATE()
          FROM QMA0004 A
               INNER JOIN (SELECT QAID FROM QMA0005 WHERE ID=@QQQID) B  ON A.ID = B.QAID
      end
    if(@Cnt > 0)
      begin
        UPDATE QMA0004 
           SET CONF_YN ='Y',REGNAM=@REGNAM, CHKTIM=GETDATE()
          FROM QMA0004 A
               INNER JOIN (SELECT QAID FROM QMA0005 WHERE ID=@QQQID) B  ON A.ID = B.QAID
      end
END
GO


