CREATE PROCEDURE [dbo].[PRO_GTProFailure]
AS
BEGIN
	select fac,BARCODE,ITNBR,ITDSC,MCHID,WDATE,getdate() crtim,WSHT,WTIME INTO #GTFTB1 from  WIP0002 where  CRTIM<dateadd(HOUR,-168,GETDATE()) and isnull(IS_DELETE,0)=0   and IS_LOCK='N'
AND FAC ='03'
 

INSERT INTO GTProFailure (FAC,BARCODE,ITNBR,ITDSC,MCHID,WDATE,CRTIM,WSHT)
SELECT FAC,BARCODE,ITNBR,ITDSC,MCHID,WDATE,CRTIM,WSHT FROM #GTFTB1
UPDATE  WIP0002  SET IS_DELETE=1 WHERE  BARCODE IN (SELECT BARCODE FROM #GTFTB1) 

DROP TABLE #GTFTB1
END
GO


-- ----------------------------
-- procedure structure for Get_Mes_Tyre_Alarm
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Get_Mes_Tyre_Alarm]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Get_Mes_Tyre_Alarm]
GO

CREATE PROCEDURE [dbo].[Get_Mes_Tyre_Alarm] @TyreNo varchar(20)
AS
BEGIN
   --设置事务为读
   SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

   DECLARE
      @IsAlarm       INT
   --默认非报警胎
   SET @IsAlarm = 0
   --报警记录中标记是报警胎
   IF EXISTS (select TYRENO from GYA0001 where TYRENO = @TyreNo and ConfYN = 'Y')
     begin
       set @IsAlarm=1
	   	   --报警胎又被放行的，则不再是报警
	   IF EXISTS (select TYRENO from QMB0101 where TYRENO = @TyreNo and WARRES = '1')
	     begin
			set @IsAlarm=0
		 end
     end
   else
     begin
	   set @IsAlarm=0
	 end
   

   --返回数据，胎号+是否为报警胎
   SELECT @TyreNo AS TYRENO,@IsAlarm AS ISALARM
END
GO


-- ----------------------------
-- procedure structure for Proc_DBA_AlwaysonWarning
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Proc_DBA_AlwaysonWarning]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Proc_DBA_AlwaysonWarning]
GO

CREATE PROCEDURE [dbo].[Proc_DBA_AlwaysonWarning]
    @syncMode BIT=NULL,                --"同步模式" 是否为同步提交，是1否0，如为NULL则不处理。默认为 NULL (不处理是否异步)
    @syncStateIsFinished BIT=0,        --"同步状态" 是否为 "SYNCHRONIZED"，是1否0，如为NULL则不处理。默认为 0 (如同步状态为未完成则预警)
    @syncHealth BIT=0,                --"同步健康状态" 是否为健康, 是1否0，如为NULL则不处理。默认为 0 否 (如健康状态为不健康则预警)
    @redoDelaySeconds INT=600,        --"Redo延迟(秒)"         > 多少则预警。默认为 600 (s)
    @logDelaySeconds INT=600,        --"Log传送延迟(秒)"      > 多少则预警。默认为 600 (s)
    @redoWaitQueueKB BIGINT=10240,    --"Redo等待队列(KB)"     > 多少则预警。默认为 10240 (10MB)
    @logWaitQueueKB BIGINT=524288    --"Log传送等待队列(KB)"  > 多少则预警。默认为 524288 (512MB)
AS
BEGIN
    SET NOCOUNT ON;
    ;WITH t AS (
        SELECT  
                ar.replica_server_name AS [副本名称] ,
                ar.availability_mode_desc as [同步模式],
                DB_NAME(dbr.database_id) AS [数据库名称] ,
                dbr.database_state_desc AS [数据库状态],
                dbr.synchronization_state_desc AS [同步状态],
                dbr.synchronization_health_desc AS [同步健康状态],
                ISNULL(CASE dbr.redo_rate
                         WHEN 0 THEN -1
                         ELSE CAST(dbr.redo_queue_size AS FLOAT) / dbr.redo_rate
                       END, -1) AS [Redo延迟(秒)] ,
                ISNULL(CASE dbr.log_send_rate
                         WHEN 0 THEN -1
                         ELSE CAST(dbr.log_send_queue_size AS FLOAT)
                              / dbr.log_send_rate
                       END, -1) AS [Log传送延迟(秒)] ,
                dbr.redo_queue_size AS [Redo等待队列(KB)] ,
                dbr.redo_rate AS [Redo速率(KB/S)] ,
                dbr.log_send_queue_size AS [Log传送等待队列(KB)] ,
                dbr.log_send_rate AS [Log传送速率(KB/S)]
        FROM    [master].sys.availability_replicas AS AR
                INNER JOIN [master].sys.dm_hadr_database_replica_states AS dbr 
                ON ar.replica_id = dbr.replica_id
        WHERE   dbr.redo_queue_size IS NOT NULL
    )
    /*
    @syncMode BIT=NULL,                --"同步模式" 是否为同步提交，是1否0，如为NULL则不处理。默认为 NULL (不处理是否异步)
    @syncStateIsFinished BIT=0,        --"同步状态" 是否为 "SYNCHRONIZED"，是1否0，如为NULL则不处理。默认为 0 (如同步状态为未完成则预警)
    @syncHealth BIT=0,                --"同步健康状态" 是否为健康, 是1否0，如为NULL则不处理。默认为 0 否 (如健康状态为不健康则预警)
    @redoDelaySeconds INT=60,        --"Redo延迟(秒)"         > 多少则预警。默认为 60  (s)
    @logDelaySeconds INT=600,        --"Log传送延迟(秒)"      > 多少则预警。默认为 600 (s)
    @redoWaitQueueKB BIGINT=10240,    --"Redo等待队列(KB)"     > 多少则预警。默认为 10240 (10MB)
    @logWaitQueueKB BIGINT=524288,    --"Log传送等待队列(KB)"  > 多少则预警。默认为 524288 (512MB)
    */
    SELECT  
        CASE WHEN
            ( (@syncMode=0 AND [同步模式]!='SYNCHRONOUS_COMMIT') or ( @syncMode=1 AND [同步模式]='SYNCHRONOUS_COMMIT' ) )
            OR
            ( (@syncStateIsFinished=0 AND [同步状态]!='SYNCHRONIZED') or ( @syncStateIsFinished=1 AND [同步状态]='SYNCHRONIZED' ) )
            OR
            ( (@syncHealth=0 AND [同步健康状态]!='HEALTHY') or ( @syncHealth=1 AND [同步健康状态]='HEALTHY' ) )
            OR
            ( [Redo延迟(秒)] > @redoDelaySeconds )
            OR
            ( [Log传送延迟(秒)] > @logDelaySeconds )
            OR
            ( [Redo等待队列(KB)] > @redoWaitQueueKB )
            OR
            ( [Log传送等待队列(KB)] > @logWaitQueueKB )
            THEN 1 ELSE 0 END AS Warning,
        [副本名称],
        [同步模式],
        [数据库名称],
        [数据库状态],
        [同步状态],
        [同步健康状态],
        [Redo延迟(秒)],
        [Log传送延迟(秒)],
        [Redo等待队列(KB)],
        [Redo速率(KB/S)],
        [Log传送等待队列(KB)],
        [Log传送速率(KB/S)]
    FROM t
END
GO


-- ----------------------------
-- procedure structure for CURE_TECH_CHECK_LAST
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CURE_TECH_CHECK_LAST]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CURE_TECH_CHECK_LAST]
GO

CREATE PROCEDURE [dbo].[CURE_TECH_CHECK_LAST]
	@QQQID NVARCHAR(50),@REGNAM NVARCHAR(50)
AS
BEGIN 
	declare @Cnt int
    set @Cnt = (
                       SELECT COUNT(1) AS CNT
                         FROM QMA0005 
                        WHERE QAID =( SELECT QAID FROM QMA0005 WHERE ID=@QQQID) AND LSTOK ='0')
    if(@Cnt = 0)
      begin
        UPDATE QMA0004 
           SET CONL_YN ='',UPDNAM=@REGNAM, UPDTIM=GETDATE()
          FROM QMA0004 A
               INNER JOIN (SELECT QAID FROM QMA0005 WHERE ID=@QQQID) B  ON A.ID = B.QAID
      end
    if(@Cnt > 0)
      begin
        UPDATE QMA0004 
           SET CONL_YN ='Y',UPDNAM=@REGNAM, UPDTIM=GETDATE()
          FROM QMA0004 A
               INNER JOIN (SELECT QAID FROM QMA0005 WHERE ID=@QQQID) B  ON A.ID = B.QAID
      end
END
GO


-- ----------------------------
-- function structure for GetTableByInListStr
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTableByInListStr]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTableByInListStr]
GO

CREATE FUNCTION [dbo].[GetTableByInListStr]
(	
	-- Add the parameters for the function here
	@inListStr												NVARCHAR(2000)		 -- ('A','B')									
)
RETURNS @t TABLE
(
    [col] VARCHAR(200) NULL -- COLLATE Chinese_PRC_CI_AS
)
AS
BEGIN
	DECLARE @inListStr1								NVARCHAR(2000)=@inListStr
	SELECT @inListStr1=[dbo].ltrimChar(@inListStr,'(')
	SELECT @inListStr1=[dbo].rtrimChar(@inListStr1,')')
	SELECT @inListStr1=REPLACE(@inListStr1,'''','')

	INSERT @t
	SELECT [col]
	FROM dbo.f_split(@inListStr1,',');

    RETURN 
END;
GO


-- ----------------------------
-- procedure structure for proInitializeDB
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proInitializeDB]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proInitializeDB]
GO

CREATE PROCEDURE [dbo].[proInitializeDB]
(
		@DBNAME						NVARCHAR(500)=NULL,
		@dbUser						NVARCHAR(500)='sa',
		@SystemDataDb				NVARCHAR(100)='SystemData' --为了改库中存的连接字符串
)
AS
BEGIN
	EXEC sp_configure 'show advanced options', '1';
	RECONFIGURE;
	EXEC sp_configure 'clr enabled', '1'
	RECONFIGURE;    --如果执行失败,就用这个RECONFIGURE WITH OVERRIDE;
	EXEC sp_configure 'show advanced options', '1';
	
	IF(ISNULL(@DBNAME,'')='')
	BEGIN
		SELECT @DBNAME=DB_NAME()
	END
	
	DECLARE @sql							NVARCHAR(4000)
	SELECT @sql='ALTER DATABASE '+@DBNAME+' SET TRUSTWORTHY on;'
	EXECUTE sp_executesql @sql

	EXEC sp_changedbowner @dbUser
	
	-- 允许Service Broker,生成拼音 PinYinDictionary 表数据用,相当于异步的存储过程
	SELECT @sql='ALTER DATABASE '+@DBNAME+' SET NEW_BROKER WITH ROLLBACK IMMEDIATE;'
			   +'ALTER DATABASE '+@DBNAME+' SET ENABLE_BROKER;'
	EXECUTE sp_executesql @sql	
	
END
GO


-- ----------------------------
-- function structure for trimChar
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[trimChar]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[trimChar]
GO

CREATE FUNCTION [dbo].[trimChar]
(
    @Source nvarchar(MAX),
    @Char nvarchar(50)
)
RETURNS nvarchar(max)
AS
BEGIN
	DECLARE @returnString			NVARCHAR(max)
	SELECT @returnString=@Source
    SELECT @returnString=[dbo].[rtrimChar](@returnString,@Char)
    SELECT @returnString=[dbo].[ltrimChar](@returnString,@Char)
    return @returnString
END
GO


-- ----------------------------
-- function structure for ltrimChar
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ltrimChar]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ltrimChar]
GO

CREATE FUNCTION [dbo].[ltrimChar]
(	
    @Source nvarchar(MAX),--要trim的字符
    @Char nvarchar(1000) --要trim掉什么字符
)
RETURNS NVARCHAR(max)
AS
BEGIN
	DECLARE @i int;
    DECLARE @returnString NVARCHAR(max)
    SET @returnString = @Source
    --删除左侧字符
    SET @i = 0
    WHILE @i=0
    BEGIN
        IF @returnString LIKE @Char+'%'
        BEGIN
        	SET @returnString = RIGHT(@returnString,LEN(@returnString)-LEN(@Char))
        END
        ELSE
        BEGIN
			SET @i=1
		END
    END
    RETURN @returnString;
END
GO


-- ----------------------------
-- procedure structure for LHGetShiftByTime
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LHGetShiftByTime]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[LHGetShiftByTime]
GO

CREATE PROCEDURE [dbo].[LHGetShiftByTime] @MCHID NVARCHAR(50),@dTime datetime


as 
declare @STime datetime;
declare @ETime datetime;
declare @DateN datetime; 
set @DateN=getdate();
set @STime=getdate();
set @ETime=getdate();
declare @sht varchar(10);
declare @nsht varchar(10);
declare @ban varchar(10);
declare @fac varchar(10);
DECLARE @MGROUP NVARCHAR(20);
SELECT @MGROUP=ATTRVAL FROM EDC0011 e left join EDC0001 b on e.ITEMID=b.ID WHERE MCHID=@MCHID and ATTRCOD='R1'
SELECT top 1 @FAC=FAC FROM EDC0001 WHERE MCHID=@MCHID order by FAC
SET @sht='1';
SET @ban='A';
DECLARE @WDATE DATETIME, @SHT1 CHAR(1),@SHT2 CHAR(1),@SHT3 CHAR(1),@DT1 DATETIME,@DT2 DATETIME,@DT3 DATETIME  
declare cursor_edb03 CURSOR SCROLL FOR SELECT WDATE,SHT1,SHT2,SHT3,TIM1,TIM2,TIM3 FROM EDB0005 WHERE WDATE BETWEEN @dTime-1 and @dTime+1 AND MGROUP=@MGROUP AND FAC=@fac ORDER BY WDATE 
open cursor_edb03   
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
WHILE(@@FETCH_STATUS=0)
BEGIN 
		if(@dTime >= @DT1 and @dTime < @DT2)
		begin 
		   set @sht = '1' ;
		   set @nsht = '2' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT1;
		   set @STime = @DT1;
		   SET @ETime = DATEADD(Second,-1,@DT2);
		END 
		if(@dTime >= @DT2 and @dTime < @DT3 )
		begin 
		   set @sht = '2' ;
		   set @nsht = '3' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT2;
		   set @STime = @DT2;  
		   SET @ETime = DATEADD(Second,-1,@DT3);
		END  
		if(@dTime >= @DT3  )
		begin 
		   set @sht = '3' ;
		   set @nsht = '1' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT3;
		   set @STime = @DT3;
		   SET @ETime = DATEADD(Second,-1,@DT1);
		end    
		IF(@sht=3 AND @stime<@DT1 AND @ETime<@STime)
		BEGIN 
		   SET @ETime = DATEADD(Second,-1,@DT1);
		END      
  
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
END


CLOSE cursor_edb03
deallocate cursor_edb03  

SELECT @DateN WDATE,@sht SHT,@nsht NSHT,@ban BAN,@STime STIME,@ETime ETIME,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac=@FAC AND dcod=@sht) SHTNAM,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac=@FAC AND dcod=@Nsht) NSHTNAM,@FAC AS FAC
GO


-- ----------------------------
-- procedure structure for LCCGetShift
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LCCGetShift]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[LCCGetShift]
GO

CREATE PROCEDURE [dbo].[LCCGetShift]  @MCHID NVARCHAR(20), @loginname NVARCHAR(30),@intim NVARCHAR(30)=''


as
declare @dTime datetime;
declare @STime datetime;
declare @ETime datetime;
declare @DateN datetime;
if @intim=''
begin
	set @dTime=getdate();
	set @DateN=getdate();
	set @STime=getdate();
	set @ETime=getdate();
end
else
begin
	set @dTime=CONVERT(datetime,@intim,120);
	set @DateN=CONVERT(datetime,@intim,120);
	set @STime=CONVERT(datetime,@intim,120);
	set @ETime=CONVERT(datetime,@intim,120);
end
declare @sht varchar(10);
declare @nsht varchar(10);
declare @ban varchar(10);
declare @fac varchar(10);

if exists(SELECT TOP 1 fac FROM EDC0001 WHERE  MCHID=@MCHID)
begin 
  SELECT @FAC=FAC FROM EDC0001 WHERE MCHID=@MCHID
end
else
begin
  set @fac=@MCHID;
end

SET @sht='1';
SET @ban='A';

DECLARE @WDATE DATETIME, @SHT1 CHAR(1),@SHT2 CHAR(1),@SHT3 CHAR(1),@DT1 DATETIME,@DT2 DATETIME,@DT3 DATETIME  
declare cursor_edb03 CURSOR SCROLL FOR SELECT WDATE,SHT1,SHT2,SHT3,TIM1,TIM2,TIM3 FROM EDB0003 WHERE WDATE BETWEEN @dTime-1 and @dTime+1 AND FAC=@FAC ORDER BY WDATE 
open cursor_edb03   
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
WHILE(@@FETCH_STATUS=0)
BEGIN 
		if(@dTime >= @DT1 and @dTime < @DT2)
		begin 
		   set @sht = '1' ;
		   set @nsht = '2' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT1;
		   set @STime = @DT1;
		   SET @ETime = DATEADD(Second,-1,@DT2);
		END 
		if(@dTime >= @DT2 and @dTime < @DT3 )
		begin 
		   set @sht = '2' ;
		   set @nsht = '3' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT2;
		   set @STime = @DT2;  
		   SET @ETime = DATEADD(Second,-1,@DT3);
		END  
		if(@dTime >= @DT3  )
		begin 
		   set @sht = '3' ;
		   set @nsht = '1' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT3;
		   set @STime = @DT3;
		   SET @ETime = DATEADD(Second,-1,@DT1);
		end    
		IF(@sht=3 AND @stime<@DT1 AND @ETime<@STime)
		BEGIN 
		   SET @ETime = DATEADD(Second,-1,@DT1);
		END      
  
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
END


CLOSE cursor_edb03
deallocate cursor_edb03  


SELECT @ban=BAN FROM LCCUserTeam WHERE LOGINNAME=@loginname and FAC=@fac

SELECT @FAC FAC,@DateN WDATE,@sht SHT,@nsht NSHT,@ban BAN,@STime STIME,@ETime ETIME,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac=@FAC AND dcod=@sht) SHTNAM,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac=@FAC AND dcod=@Nsht) NSHTNAM
GO


-- ----------------------------
-- function structure for rtrimChar
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[rtrimChar]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[rtrimChar]
GO

CREATE FUNCTION [dbo].[rtrimChar]
(	
    @Source NVARCHAR(MAX),--要trim的字符
    @Char NVARCHAR(1000) --要trim掉什么字符
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
	DECLARE @i INT;
    DECLARE @returnString NVARCHAR(MAX)
    SET @returnString = @Source
    --删除左侧字符
    SET @i = 0
    WHILE @i=0
    BEGIN
        IF @returnString LIKE '%'+@Char
        BEGIN
        	SET @returnString = LEFT(@returnString,LEN(@returnString)-LEN(@Char))
        END
        ELSE
        BEGIN
			SET @i=1
		END
    END
    RETURN @returnString;
END
GO


-- ----------------------------
-- function structure for f_split
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[f_split]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[f_split]
GO

CREATE FUNCTION [dbo].[f_split]
(@c VARCHAR(2000), @split VARCHAR(2))
RETURNS @t TABLE
(
[col] VARCHAR(200) 
)
WITH EXEC AS CALLER
AS
BEGIN
WHILE (CHARINDEX (@split, @c) <> 0)
   BEGIN
      INSERT @t (col)
      VALUES (SUBSTRING (@c, 1, CHARINDEX (@split, @c) - 1))

      SET @c =
             STUFF (@c,
                    1,
                    CHARINDEX (@split, @c),
                    '')
   END

   INSERT @t (col)
   VALUES (@c)

   RETURN
END
GO


-- ----------------------------
-- function structure for SplitIn
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SplitIn]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SplitIn]
GO

CREATE FUNCTION [dbo].[SplitIn](@c   varchar(2000),@split   varchar(2))   
returns   @t   table(col   varchar(20))   
as   
begin    
  while(charindex(@split,@c)<>0)   
    begin   
      insert   @t(col)   values   (substring(@c,1,charindex(@split,@c)-1))   
      set   @c   =   stuff(@c,1,charindex(@split,@c),'')   
    end   
  insert   @t(col)   values   (@c)   
  return   
end
GO


-- ----------------------------
-- procedure structure for dotchange_pro
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[dotchange_pro]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[dotchange_pro]
GO

CREATE PROCEDURE [dbo].[dotchange_pro] as
begin 
 declare 
 @fac nvarchar(10),
 @dot nvarchar(10),
 @mchid NVARCHAR(50),--机台号
 @matcode NVARCHAR(50),--规格代码
 @lr NVARCHAR(50),--左右
 @stime datetime,--开始时间
 @etime datetime --结束时间
   

--游标声明,首先是把搞正常得，就是数据完成得单号拿出来
declare DOTCHANGE_yb cursor fast_forward for
SELECT   fac,dot,mchid,lr,stime,etime,matcode FROM DOTCHANGETB with(nolock) where useyn='Y'  AND ISNULL(DOT,'')<>'' AND   ISNULL(matcode,'')<>'' and etime>GETDATE()
open DOTCHANGE_yb --打开游标
--循环取得记录
FETCH NEXT FROM DOTCHANGE_yb into @fac,@dot,@mchid,@lr,@stime,@etime,@matcode
while @@FETCH_STATUS=0
begin
	UPDATE WIP0010 SET DOT=@dot where  FAC=@fac and MCHID=@mchid and ITNBR=@matcode and  LRFLAG=@lr and wtime between @stime and  @etime ; 
	UPDATE tb_PP_CuringOutPut SET DOT=@dot where   FAC=@fac and BeginTime between @stime and  @etime and MaterialID=@matcode and SulfEquipCode=@mchid and LeftOrRight=@lr 
	UPDATE LTA0001 SET DOT=@dot from LTA0001 WITH(INDEX(idx_Nonclustered_LTA0001_CUTIM)) where CUTIM  between @stime and  @etime  and ATTRIBUTE1=@fac and LR=@lr  and CUMCH=@mchid and CUITNBR=@matcode;
	--	print 'UPDATE WIP0010 SET DOT='''+@dot+''' where  FAC='''+@fac+''' and MCHID='''+@mchid+''' and ITNBR='''+@matcode+''' and  LRFLAG='''+@lr+''' and wtime between '''+convert(nvarchar,@stime,23)+''' and  '''+convert(nvarchar,@etime,23)+''''; 
	--print 'UPDATE tb_PP_CuringOutPut SET DOT='''+@dot+''' where   FAC='''+@fac+''' and BeginTime between '''+convert(nvarchar,@stime,23)+''' and  '''+convert(nvarchar,@etime,23)+''' and MaterialID='''+@matcode+''' and SulfEquipCode='''+@mchid+''' and LeftOrRight='''+@lr +''''
	--print 'UPDATE LTA0001 SET DOT='''+@dot+''' from LTA0001 WITH(INDEX(idx_Nonclustered_LTA0001_CUTIM)) where CUTIM  between '''+convert(nvarchar,@stime,23)+''' and  '''+convert(nvarchar,@etime,23)+'''  and ATTRIBUTE1='''+@fac+''' and LR='''+@lr+''' and CUMCH='''+@mchid+''' and CUITNBR='''+@matcode+'''';
	-- 取下一条记录
    FETCH NEXT FROM DOTCHANGE_yb INTO  @fac,@dot,@mchid,@lr,@stime,@etime,@matcode
end
 
 
close DOTCHANGE_yb --关闭游标

deallocate DOTCHANGE_yb --释放游标

end
GO


-- ----------------------------
-- procedure structure for proShrinkLog
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proShrinkLog]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proShrinkLog]
GO

CREATE PROCEDURE [dbo].[proShrinkLog]
(
	@dbName						NVARCHAR(1000)=NULL, --数据库名
	@logName					NVARCHAR(1000)='PLMES_log', --日志逻辑名
	@logBakPath					NVARCHAR(1000)='M:\log.trn' --日志备份物理文件路径文件名
)
AS
BEGIN	
	IF(ISNULL(@DBNAME,'')='')
	BEGIN
		SELECT @DBNAME=DB_NAME()
	END	
	DECLARE @sql						NVARCHAR(4000)
	SELECT @sql='BACKUP LOG '+@dbName+' TO DISK = N'''+@logBakPath+''' WITH NOFORMAT, INIT, '--先备份日志
			   +' NAME = N'''+@dbName+'-事务日志  备份'' ,SKIP, NOREWIND, NOUNLOAD,  STATS = 10 ;'
			   +' USE '+@dbName+'; '
			   +' DBCC SHRINKFILE (N'''+@logName+''' , 11, TRUNCATEONLY); ' 
			   +' DBCC SHRINKDATABASE (N'''+@DBNAME+'''); ' 
	EXECUTE sp_executesql @sql
END
GO


-- ----------------------------
-- procedure structure for proMiLianChanLiang
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proMiLianChanLiang]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proMiLianChanLiang]
GO

CREATE PROCEDURE [dbo].[proMiLianChanLiang]
AS
BEGIN
	DECLARE @tiQianMi													INT=0, -- dbo.gettiqianMi(),
					@wdate														DATETIME=GETDATE();
	select @wdate=DATEADD(day, -20, @wdate)				
	DECLARE @wTDate														datetime=DATEADD(mi, @tiQianMi, @wdate);
	DECLARE @shift														INT=dbo.GetBanCi(@wdate);
	DECLARE @beginHour												INT,
					@endHour													INT,
					@ShtName													nvarchar(1000);
	SELECT @beginHour=MIN(tbc.TimeHour),
					@endHour=MAX(tbc.TimeHour),
					@ShtName=tbc.ShtName
	  FROM vSystimeHour tBc with(nolock)
	 WHERE tbc.sht=@shift
	 GROUP BY tbc.ShtName;
	 SELECT @ShtName=ISNULL(@ShtName, '');
	
	DECLARE @JLJiHua																	DECIMAL(18,6), -- 终练计划
					@XLJiHua																	DECIMAL(18,6);  -- 小料计划
	SELECT @JLJiHua=SUM(CASE OUTTYPECOD
							WHEN 'JL' THEN 
									p.PLLOT -- 计划	
							END) ,
				@XLJiHua=SUM(CASE OUTTYPECOD
							WHEN 'XL' THEN 
									p.PLLOT -- 计划	
							END)					 					
		FROM PPB0103 p with(nolock)
		WHERE CONVERT(date,p.WDATE)=CONVERT(DATE,@wdate)
		and p.WSHT=@shift
		AND p.FAC = 'M0'
		AND p.OUTTYPECOD IN ('JL','XL');
		
	with mainData as (
			SELECT DATEADD(mi, @tiQianMi, tl.ProTime) as hbJTIM,
						DATEPART(HH, DATEADD(mi, @tiQianMi, tl.ProTime)) as hJTIM,
						tl.PlanId,
						p.OUTTYPECOD,
						tl.id
			from LTD0050 tl with(nolock)
			INNER JOIN PPB0103 p with(nolock)
			on tl.PlanId = p.ORDERNO			
		 WHERE tl.ProTime BETWEEN FORMAT(@wdate,'yyyy-MM-dd 00:00:00')
			and FORMAT(@wdate,'yyyy-MM-dd 23:59:59')
			and p.WSHT=@shift
			AND p.FAC = 'M0'
			AND p.OUTTYPECOD IN ('JL','XL')
	),
	mainGroupData as (
			SELECT t.OUTTYPECOD,
						tEDD0003.ITTYPENAM+@ShtName+N'产量' as timeType, 
						tEDD0003.ITTYPENAM+@ShtName+N'计划' as timeType1, 
						tsh.TimeHour,
						@JLJiHua/8 as HourJLJiHua, -- 终练计划量
						@XLJiHua/8 as HourXLJiHua,  -- 小料计划量
						COUNT(CASE OUTTYPECOD
									WHEN 'JL' THEN 
											 t.ID
									END) as countJLCl,
						COUNT(CASE OUTTYPECOD
									WHEN 'XL' THEN 
											 t.ID
									END) as countXLCl
			 from [dbo].vSystimeHour tsh with(nolock)
			LEFT JOIN	mainData t WITH(NOLOCK)
				left join EDD0003 tEDD0003 with(nolock) -- 编码字典表
				on t.OUTTYPECOD=tEDD0003.ITTYPECOD
			on tsh.TimeHour=t.hJTIM
			 and t.hbJTIM BETWEEN FORMAT(@wdate,'yyyy-MM-dd 00:00:00')
			 and FORMAT(@wdate,'yyyy-MM-dd 23:59:59')
			 and t.hJTIM BETWEEN @beginHour and @endHour
			 WHERE tsh.sht=@shift
			GROUP BY tsh.TimeHour,
								t.OUTTYPECOD,
								tEDD0003.ITTYPENAM
	)
	SELECT *
	into #tmainGroupData
	  from mainGroupData t;
						
	SELECT *
	  from #tmainGroupData
	 ORDER BY TimeHour, 
						timeType;
		
	SELECT SUM(CASE OUTTYPECOD
						 WHEN 'JL' THEN
								countJLCl
						 END) / NULLIF(@JLJiHua, 0) as JLJiHuaDaChengLv,
				 SUM(CASE OUTTYPECOD
						 WHEN 'XL' THEN
								countXLCl
						 END) / NULLIF(@XLJiHua, 0) as XLJiHuaDaChengLv
	  from #tmainGroupData t with(nolock)
	 WHERE DATEPART(HH, @wdate) >= TimeHour;
	 
	drop table #tmainGroupData;
END
GO


-- ----------------------------
-- procedure structure for proBanChengPinChanLiang
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proBanChengPinChanLiang]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proBanChengPinChanLiang]
GO

CREATE PROCEDURE [dbo].[proBanChengPinChanLiang]
AS
BEGIN
	DECLARE @tiQianMi													INT=0, -- dbo.gettiqianMi(),
					@wdate														DATETIME=GETDATE();
	DECLARE @wTDate														datetime=DATEADD(mi, @tiQianMi, @wdate);
	DECLARE @shift														INT=dbo.GetBanCi(@wdate);
	DECLARE @beginHour												INT,
					@endHour													INT,
					@ShtName													nvarchar(1000);
	SELECT @beginHour=MIN(tbc.TimeHour),
					@endHour=MAX(tbc.TimeHour),
					@ShtName=tbc.ShtName
	  FROM vSystimeHour tBc with(nolock)
	 WHERE tbc.sht=@shift
	 GROUP BY tbc.ShtName;
	 SELECT @ShtName=ISNULL(@ShtName, '');
	
	with mainData as (
		 SELECT DATEADD(mi, @tiQianMi, AUTIM) as hbJTIM,
						DATEPART(HH, DATEADD(mi, @tiQianMi, AUTIM)) as hJTIM,
						t.DIV,
						t.ID
			FROM LTC0001 t with(nolock)
			where t.DIV in ('JL','XL')
	),
  mainGroupData as (
	SELECT N'终练'+@ShtName+N'产量' as timType, -- CUTIM	硫化时间
				 tsh.TimeHour,
				COUNT(t.ID) as LTA0001Count
	 from [dbo].vSystimeHour tsh with(nolock)
	LEFT JOIN	mainData t WITH(NOLOCK)
	on tsh.TimeHour=t.hJTIM
	 and t.hbJTIM BETWEEN FORMAT(@wdate,'yyyy-MM-dd 00:00:00')
	 and FORMAT(@wdate,'yyyy-MM-dd 23:59:59')
	 and t.hJTIM BETWEEN @beginHour and @endHour
	 and t.DIV in ('JL') -- 终练
	 WHERE tsh.sht=@shift
	GROUP BY tsh.TimeHour
	UNION ALL
	SELECT N'小料'+@ShtName+N'产量' as timType, -- BUTIM	硫化时间
				tsh.TimeHour,
				COUNT(t.ID) as LTA0001Count
	 from [dbo].vSystimeHour tsh with(nolock)
	LEFT JOIN mainData t WITH(NOLOCK)
	on tsh.TimeHour=t.hJTIM
	and t.hbJTIM BETWEEN FORMAT(@wdate,'yyyy-MM-dd 00:00:00')
	 and FORMAT(@wdate,'yyyy-MM-dd 23:59:59')
	 and t.hJTIM BETWEEN @beginHour and @endHour
	 and t.DIV IN ('XL')
	 WHERE tsh.sht=@shift
	GROUP BY tsh.TimeHour
	)
	SELECT t.*
	  from mainGroupData t with(nolock)
	ORDER BY t.timType,
					 t.TimeHour;
END
GO

EXEC sp_addextendedproperty
'MS_Description', N'半成品当班产量',
'SCHEMA', N'dbo',
'PROCEDURE', N'proBanChengPinChanLiang'
GO


