	DROP PROCEDURE [dbo].[proMiLianDangBanTotal]
GO

CREATE PROCEDURE [dbo].[proMiLianDangBanTotal]
AS
BEGIN
	DECLARE @tiQianMi													INT=0, -- dbo.gettiqianMi(),
			@wdate														DATETIME=GETDATE();

	DECLARE @wTDate														datetime=DATEADD(mi, @tiQianMi, @wdate);
	DECLARE @shift														INT=dbo.GetBanCi(@wdate);
	DECLARE @beginHour													INT,
			@endHour													INT,
			@ShtName													nvarchar(1000);
	SELECT @beginHour=MIN(tbc.TimeHour),
			@endHour=MAX(tbc.TimeHour),
			@ShtName=tbc.ShtName
	  FROM vSystimeHour tBc with(nolock)
	 WHERE tbc.sht=@shift
	 GROUP BY tbc.ShtName;
	 SELECT @ShtName=ISNULL(@ShtName, '');
	
	DECLARE @JLJiHua																		DECIMAL(18,6), -- 终练计划
			@XLJiHua																		DECIMAL(18,6),  -- 小料计划
			@XLChanLiang																	DECIMAL(18,6);  -- 小料产量
	SELECT @JLJiHua=SUM(CASE OUTTYPECOD
							WHEN 'JL' THEN 
									p.PLLOT -- 计划	
							END) ,
			@XLJiHua=SUM(CASE OUTTYPECOD
						WHEN 'XL' THEN 
								p.PLLOT -- 计划	
						END),
			@XLChanLiang=SUM(CASE OUTTYPECOD
							WHEN 'XL' THEN 
									p.RELOT 
							END) -- 小料产量			 					
	FROM PPB0103 p with(nolock)
	WHERE CONVERT(DATE,p.WDATE)=CONVERT(DATE,@wdate)
	and p.WSHT=@shift
	AND p.FAC = 'M0'
	AND p.OUTTYPECOD IN ('JL','XL');	

	--DECLARE @JLChanLiang																	DECIMAL(18,6), -- 终练产量
	--		@XLChanLiang																	DECIMAL(18,6);  -- 小料产量
						
	--select @JLChanLiang=count(CASE p.OUTTYPECOD
	--						  WHEN 'JL' THEN 
	--								tl50.ID
	--							END) ,
	--		@XLChanLiang=count(CASE p.OUTTYPECOD
	--					WHEN 'XL' THEN 
	--							tl50.ID -- 计划	
	--					END)
	--		--			,
	--		--count(*) as RELOT  -- 终练产量
	--from LTD0050 tl50 with(nolock)
	--inner join PPB0103 p with(nolock)
	--on tl50.planid=p.ORDERNO
	--WHERE CONVERT(DATE,p.WDATE)=CONVERT(DATE,@wdate)
	--and p.WSHT=@shift
	--AND p.FAC = 'M0'
	--AND p.OUTTYPECOD IN ('JL','XL');
	--group by tl50.PlanId,
	--			p.OUTTYPECOD,
	--			p.PLLOT	

	--declare @beginDate														datetime,
	--		@endDate														datetime;
	--IF @wdate>=CONVERT(datetime,FORMAT(@wdate,'yyyy-MM-dd 07:45:00')) AND @wdate<CONVERT(datetime,FORMAT(GETDATE(),'yyyy-MM-dd 15:45:00'))
	--BEGIN
	--	select @beginDate=FORMAT(@wdate,'yyyy-MM-dd 07:45:00'),
	--			@endDate=FORMAT(@wdate,'yyyy-MM-dd 15:45:00');
	--END
	--ELSE IF @wdate>=CONVERT(datetime,FORMAT(@wdate,'yyyy-MM-dd 15:45:00')) AND @wdate<CONVERT(datetime,FORMAT(GETDATE(),'yyyy-MM-dd 23:45:00'))
	--BEGIN
	--	select @beginDate=FORMAT(@wdate,'yyyy-MM-dd 15:45:00'),
	--			@endDate=FORMAT(@wdate,'yyyy-MM-dd 23:45:00');
	--END
	--ELSE
	--BEGIN
	--	select @beginDate=FORMAT(@wdate,'23:45:00'),
	--			@endDate=FORMAT(@wdate,'07:45:00');
	--END;
	
	with mainData as (
			select p.OUTTYPECOD,
					tl50.PlanId,
					 p.PLLOT,
					 case OUTTYPECOD  -- IN ('JL',)
					 when 'XL' then --小料
						sum(p.RELOT)
					 when 'JL' then --终练胶
						count(*)
					 end as RELOT  -- 终练产量
			from LTD0050 tl50 with(nolock)
			left join PPB0103 p with(nolock)
			on tl50.planid=p.ORDERNO
			WHERE CONVERT(DATE,p.WDATE)=CONVERT(DATE,@wdate)
			and p.WSHT=@shift
			--and tl50.ProTime between @beginDate and @endDate
			AND p.FAC = 'M0'
			AND p.OUTTYPECOD IN ('JL','XL')
			group by tl50.PlanId,
					 p.OUTTYPECOD,
					 p.PLLOT

			-- 原来取产量的语句
			--SELECT p.OUTTYPECOD,
			--			p.id,
			--			p.PLLOT,
			--			p.RELOT  -- 终练产量
			--from PPB0103 p with(nolock)
		 --WHERE p.WSHT=@shift
			--AND p.FAC = 'M0'
			--AND p.OUTTYPECOD IN ('JL','XL')
	),
	mainGroupData as (
			SELECT @JLJiHua as jiHuaJLCl, -- 终练计划量
					@XLJiHua as jiHuaXLCl, -- 小料计划量
					--SUM(CASE OUTTYPECOD
					--	WHEN 'JL' THEN 
					--				t.PLLOT
					--	END) as jiHuaJLCl, -- 终练计划量
					--SUM(CASE OUTTYPECOD
					--	WHEN 'XL' THEN 
					--				t.PLLOT
					--	END) as jiHuaXLCl, -- 小料计划量
					SUM(CASE OUTTYPECOD
						WHEN 'JL' THEN 
							t.RELOT
						END) as chanLiangJLCl, -- 终练产量
					--SUM(CASE OUTTYPECOD
					--	WHEN 'XL' THEN 
					--		t.RELOT
					--	END) as chanLiangXLCl1, -- 小料产量
					@XLChanLiang as chanLiangXLCl -- 小料产量
			 from mainData t WITH(NOLOCK)
	)
	SELECT *
	into #tmainGroupData
	  from mainGroupData t;
	SELECT *, 
			chanLiangJLCl / NULLIF(jiHuaJLCl, 0) as jihuaDaChengLvJL, -- 终练计划达成率
			chanLiangXLCl / NULLIF(jiHuaXLCl, 0) as jihuaDaChengLvXL -- 小料计划达成率
	from #tmainGroupData
	

	drop table #tmainGroupData;
END
GO

EXEC sp_addextendedproperty
'MS_Description', N'密炼当班累计计划、产量',
'SCHEMA', N'dbo',
'PROCEDURE', N'proMiLianDangBanTotal'
GO


-- ----------------------------
-- procedure structure for proLiuHuaJiHuaDaChengLv
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proLiuHuaJiHuaDaChengLv]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proLiuHuaJiHuaDaChengLv]
GO

CREATE PROCEDURE [dbo].[proLiuHuaJiHuaDaChengLv]
(
		@FACList		nvarchar(50) -- 用工厂区分半钢、全钢
)
AS
BEGIN
	--   SET  NOCOUNT ON;
	--	 DECLARE @wdate		date=GETDATE()
	--	 DECLARE @chanLiang	DECIMAL(18,6)=(
	--	 SELECT COUNT(*)
	--	FROM dbo.tb_PP_CuringOutPut AS tpcop WITH ( NOLOCK )
	--	WHERE tpcop.FAC IN (SELECT [VALUE]
	--		from string_split(@FACList,','))
	--		AND CONVERT(date,tpcop.BeginTime) = @wdate),
	--	@jiHua	DECIMAL(18,6)=(SELECT SUM(p.PLLOT1+p.PLLOT2+p.PLLOT3)
	--	FROM PPB0201 AS p
	--	where CONVERT(date,p.WDATE) = @wdate
	--	and p.FAC IN (SELECT [VALUE]
	--	from string_split(@FACList,',')))
		
	--SELECT @chanLiang / NULLIF(@jiHua, 0) as jiHuaDaChengLv

	SET  NOCOUNT ON;
	DECLARE @wdate		date=GETDATE();

	DECLARE @chanLiang	DECIMAL(18,6)=(
	SELECT COUNT(*)
		FROM dbo.tb_PP_CuringOutPut AS tpcop WITH ( NOLOCK )
		WHERE tpcop.FAC IN (SELECT [VALUE]
			from string_split(@FACList,','))
			AND WDATE = CONVERT(date,@wdate));

	DECLARE @jiHua	DECIMAL(18,6)=(
	SELECT SUM(PLLOT)
		FROM PAD0201  AS p WITH ( NOLOCK )
		where WDATE = CONVERT(date,@wdate)
		and p.FAC IN (SELECT [VALUE]
		from string_split(@FACList,','))
		and ATTRIBUTE1 = 'FERT');
		
	SELECT @chanLiang / NULLIF(@jiHua, 0) as jiHuaDaChengLv

END
GO

