-- procedure structure for BARCODE_HASCHANGE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[BARCODE_HASCHANGE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[BARCODE_HASCHANGE]
