CREATE PROCEDURE [dbo].[BARCODE_HASCHANGE]
	@NEWBARCODE NVARCHAR(50),@OLDBARCODE NVARCHAR(50)
AS
BEGIN
	declare @nror int
    set @nror=0 
	begin tran
	UPDATE tb_PP_CuringOutPut SET GreenTyreNo='0000000000000' WHERE GreenTyreNo=@OLDBARCODE; 
	set @nror=@nror+@@error
	UPDATE tb_PP_CuringOutPut SET GreenTyreNo=@OLDBARCODE WHERE GreenTyreNo=@NEWBARCODE; 
	 set @nror=@nror+@@error
	UPDATE tb_PP_CuringOutPut SET GreenTyreNo=@NEWBARCODE WHERE GreenTyreNo='0000000000000'; 
	set @nror=@nror+@@error
	if @nror<>0
	begin 
		rollback transaction
    end
    else 
    begin 
        commit transaction
    end 

	 set @nror=0  
	begin tran
	UPDATE QMB0101 SET BARCODE='0000000000000' WHERE BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE QMB0101 SET BARCODE=@OLDBARCODE WHERE BARCODE=@NEWBARCODE;
	set @nror=@nror+@@error
	UPDATE QMB0101 SET BARCODE=@NEWBARCODE WHERE BARCODE='0000000000000';
	set @nror=@nror+@@error
		if @nror<>0
	begin 
		rollback transaction
    end
    else 
    begin 
        commit transaction
    end 

	 set @nror=0  
	begin tran
    UPDATE LTA0001	SET BARCODE='0000000000000' WHERE BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
    UPDATE LTA0001	SET BARCODE=@OLDBARCODE WHERE BARCODE=@NEWBARCODE;
	set @nror=@nror+@@error
    UPDATE LTA0001	SET BARCODE=@NEWBARCODE WHERE BARCODE='0000000000000';
	set @nror=@nror+@@error 
		if @nror<>0
	begin 
		rollback transaction
    end
    else 
    begin 
        commit transaction
    end 

	 set @nror=0  
	begin tran
	UPDATE wip0002 SET BARCODE='0000000000000' WHERE BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE wip0002 SET BARCODE=@OLDBARCODE WHERE BARCODE=@NEWBARCODE;
	set @nror=@nror+@@error
	UPDATE wip0002 SET BARCODE=@NEWBARCODE WHERE BARCODE='0000000000000';
	set @nror=@nror+@@error 
		if @nror<>0
	begin 
		rollback transaction
    end
    else 
    begin 
        commit transaction
    end 

	 set @nror=0  
	begin tran
	UPDATE wip0010 SET BARCODE='0000000000000' WHERE BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE wip0010 SET BARCODE=@OLDBARCODE WHERE BARCODE=@NEWBARCODE;
	set @nror=@nror+@@error
	UPDATE wip0010 SET BARCODE=@NEWBARCODE WHERE BARCODE='0000000000000';
	set @nror=@nror+@@error
	if @nror<>0
	begin 
		rollback transaction
    end
    else 
    begin 
        commit transaction
    end 

	 set @nror=0  
	begin transaction
	UPDATE QMB0012 SET BARCODE='0000000000000' WHERE BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE QMB0012 SET BARCODE=@OLDBARCODE WHERE BARCODE=@NEWBARCODE;
	set @nror=@nror+@@error
	UPDATE QMB0012 SET BARCODE=@NEWBARCODE WHERE BARCODE='0000000000000';
	set @nror=@nror+@@error
	if @nror<>0
	begin 
		rollback transaction
    end
    else 
    begin 
        commit transaction
    end 
	 
 
END
GO


-- ----------------------------
-- procedure structure for Report_BJXC_nodiv_pro
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Report_BJXC_nodiv_pro]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Report_BJXC_nodiv_pro]
GO

CREATE PROCEDURE [dbo].[Report_BJXC_nodiv_pro]
	 @FAC NVARCHAR(10),@DATE DATE
AS
BEGIN
	DECLARE @BDATE DATE
	SET @BDATE=DATEADD(day,-1,@DATE);
WITH RubberRequire--胶片BOM对应的终炼胶
AS (
 SELECT ParentMatType,ParentMatID,ParentMatEditionNo
     ,SubMatTypeName,SubMatID,EditionNo
     ,ParentMatType GTMatType
     ,ParentMatID GTMatID
     ,ParentMatEditionNo GTEditionNo
 FROM EDD0061 WHERE ParentMatType ='SK'
 UNION ALL
 SELECT A.ParentMatType,A.ParentMatID,A.ParentMatEditionNo
   ,A.SubMatTypeName,A.SubMatID,A.EditionNo
   ,B.GTMatType GTMatType
   ,B.GTMatID GTMatID
   ,B.GTEditionNo GTEditionNo
 FROM EDD0061 A
 INNER JOIN RubberRequire B ON A.ParentMatType=B.SubMatTypeName AND A.ParentMatID=B.SubMatID AND A.ParentMatEditionNo=B.EditionNo
 )   
 SELECT X.ITNBR,T1.ITTYPENAM DIV,[LOCATION],T1.ERPCODE,SAPBOM,
      WIDTH,Thickness,Density,
	   (CASE WHEN X.DIV IN('CCF') THEN PN*WIDTH/1000.0--[生产入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN PN*WIDTH*Thickness*Density/1000.0--[生产入库]计量单位转换为kg
	                ELSE PN END) RKQTY--[生产入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN STARQTY*WIDTH/1000.0--[期初]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN STARQTY*WIDTH*Thickness*Density/1000.0--[期初]计量单位转换为kg
	                ELSE STARQTY END),1) STARQTY--[期初]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN ENDQTY*WIDTH/1000.0--[期末]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN ENDQTY*WIDTH*Thickness*Density/1000.0--[期末]计量单位转换为kg
	                ELSE ENDQTY END),1) ENDQTY--[期末]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBIN*WIDTH/1000.0--[调拨入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBIN*WIDTH*Thickness*Density/1000.0--[调拨入库]计量单位转换为kg
	                ELSE DBIN END),1) DBIN--[调拨入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBOUT*WIDTH/1000.0--[调拨出库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBOUT*WIDTH*Thickness*Density/1000.0--[调拨出库]计量单位转换为kg
	                ELSE DBOUT END),1) DBOUT--[调拨出库]
	   ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN XN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE XN END),1) XHQTY--[消耗数量]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN FN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE FN END),1) FNQTY--[报废数量]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN CN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE CN END),1) CNQTY--[差值]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN BN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE BN END),1) BNQTY--[盘点数量]
	   ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN (ISNULL(STARQTY,0)+ISNULL(DBIN,0)+ISNULL(PN,0)-ISNULL(DBOUT,0)-ISNULL(XN,0)-ISNULL(ENDQTY,0))*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE ISNULL(STARQTY,0)+ISNULL(DBIN,0)+ISNULL(PN,0)-ISNULL(DBOUT,0)-ISNULL(XN,0)-ISNULL(ENDQTY,0) END),1) OTQTY--[消耗数量]
	   ,(CASE WHEN X.DIV IN('CCF') THEN '㎡'
	          WHEN X.DIV IN('BD','PTQ') THEN '对'  
	          WHEN X.DIV IN('TD','TR') THEN '条'
			  WHEN X.DIV IN('TC','SK') THEN 'kg'
			  ELSE 'm' END) UNIT FROM
( SELECT '半成品' [LOCATION],
			(CASE WHEN TBQM.ITNBR IS NOT NULL THEN TBQM.ITNBR WHEN TBRK.AITNBR IS NOT NULL THEN TBRK.AITNBR 
			WHEN TBQC.ITNBR IS NOT NULL THEN TBQC.ITNBR WHEN DB1.ITNBR IS NOT NULL THEN DB1.ITNBR WHEN DB2.ITNBR IS NOT NULL THEN DB2.ITNBR
			WHEN TBXH.ITNBR IS NOT NULL THEN TBXH.ITNBR WHEN TBBF.ITNBR IS NOT NULL THEN TBBF.ITNBR WHEN TBCZ.ITNBR IS NOT NULL THEN TBCZ.ITNBR
			WHEN TBPD.ITNBR IS NOT NULL THEN TBPD.ITNBR
			END) ITNBR ,
			(CASE WHEN TBQM.DIV IS NOT NULL THEN TBQM.DIV WHEN TBRK.DIV IS NOT NULL THEN TBRK.DIV WHEN TBQC.DIV IS NOT NULL THEN TBQC.DIV 
			WHEN DB1.DIV IS NOT NULL THEN DB1.DIV WHEN DB2.DIV IS NOT NULL THEN DB2.DIV  WHEN TBXH.DIV IS NOT NULL 
			THEN TBXH.DIV WHEN TBBF.DIV IS NOT NULL THEN TBBF.DIV WHEN TBCZ.DIV IS NOT NULL THEN TBCZ.DIV 
			WHEN TBPD.HALFDIV IS NOT NULL THEN TBPD.HALFDIV 
			END) DIV
		   ,STARQTY,PN,ENDQTY, DBIN, DBOUT,XN,FN,CN,BN
		   FROM
			(SELECT DIV,AITNBR,ROUND(SUM(QTY),2) PN 
			FROM LTC0001
			WHERE AUDAT=@DATE AND FAC =@FAC and isnull(IS_DELETE,0)=0 
			GROUP BY DIV,AITNBR) AS TBRK --0.产出
			full join 
			(SELECT  A1.DIV,A1.ITNBR, 1.0*SUM(CASE  WHEN DIV IN ('CCF','BDR','TR','TC','SK') THEN  SUMQTY  ELSE QTYA+QTYB END) STARQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@BDATE AND A1.FAC =@FAC AND WSHT='3'   AND A1.ITNBR IS NOT NULL   AND A1.ITNBR<>'' 
			GROUP BY  A1.DIV,A1.ITNBR)  
			AS TBQC ON TBRK.AITNBR=TBQC.ITNBR AND TBRK.DIV=TBQC.DIV   --1、半成品期初 
			full join
			(SELECT  A1.DIV,A1.ITNBR ,1.0*SUM(CASE  WHEN DIV IN ('CCF','BDR','TR','TC','SK') THEN  SUMQTY  ELSE QTYA+QTYB END) ENDQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD AND A1.ITNBR IS NOT NULL
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@DATE AND A1.FAC =@FAC AND WSHT='3'  AND A1.ITNBR IS NOT NULL    AND A1.ITNBR<>''
			GROUP BY A1.DIV,A1.ITNBR
			) AS  TBQM ON (TBRK.AITNBR=TBQM.ITNBR AND TBRK.DIV=TBQM.DIV) OR (TBQC.ITNBR=TBQM.ITNBR AND TBQC.DIV=TBQM.DIV) --2、半成品期期末
			FULL JOIN
			(  select DIV,SUM(QTY) DBIN,ITNBR from STB0014 where
		   CONVERT(NVARCHAR,CRTIM,23)=@DATE and YFAC=@FAC  and MOVETYPE in ('2','3')
		   group by DIV,ITNBR
			) DB1 ON (TBRK.AITNBR=DB1.ITNBR AND  TBRK.DIV=DB1.DIV) OR (TBQC.ITNBR=DB1.ITNBR AND  TBQC.DIV=DB1.DIV) 
			OR (TBQM.ITNBR=DB1.ITNBR AND  TBQM.DIV=DB1.DIV)  --3、半成品调拨入库
			FULL JOIN 
			(SELECT ITGRPCOD3 DIV,ITNBR,SUM(OUTQTY) DBOUT
				 FROM STB0004 
				WHERe OUTDAT=@DATE and FAC=@FAC  
				GROUP BY  ITGRPCOD3,ITNBR) DB2 ON (TBRK.AITNBR=DB2.ITNBR AND TBRK.DIV=DB2.DIV) OR (TBQC.ITNBR=DB2.ITNBR AND  TBQC.DIV=DB2.DIV) 
			OR (TBQM.ITNBR=DB2.ITNBR AND  TBQM.DIV=DB2.DIV) OR (DB1.ITNBR=DB2.ITNBR AND  DB1.DIV=DB2.DIV)  --4、半成品调拨出库
			 FULL JOIN 
			 (SELECT (CASE WHEN SubMatTypeName='BDW' THEN 'BDR' ELSE SubMatTypeName END) DIV--BOM消耗的为成品钢丝圈，系统中对成品钢丝圈不管理，消耗钢丝圈（规格代码一样）
			,SubMatID ITNBR
				,SUM(HA*(CASE WHEN SubMatTypeName IN('BDW','TR','SK') THEN CAST(SubMatNum AS numeric)--部件计量单位取条计算消耗量
			                  WHEN SubMatTypeName IN('CCF','TC') THEN CAST(ROUND(PCSCuttingWidth,0) AS int)*CAST(SubMatNum AS numeric)/1000.0--钢帘布/压延胶片BOM消耗取宽度计算平方米
							  ELSE CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0 END)) XN--部件计量单位根据单条长度计算消耗量
				,'' XC--无法计算消耗的lot数
			FROM
				(SELECT FAC,DIV,AUSHT,AITNBR,[VERSION],SUM(QTY) HA FROM LTC0001 WHERE ISNULL(IS_DELETE,0)='0' AND AUDAT=@DATE AND FAC=@FAC  
				GROUP BY FAC,DIV,AUSHT,AITNBR,[VERSION]) A1--半成品产量
			INNER JOIN 
				(SELECT ParentMatType,ParentMatID,ParentMatEditionNo,SubMatTypeName,SubMatID,SubMatNum,PCSCuttinglength,PCSCuttingWidth 
				  FROM EDD0061 WHERE SubMatTypeName IN('CCF','BDW','TR','TC','SK')) B1--半成品BOM（只取半成品内部耗用的物料类型）（消耗的物料在范围内）
			ON A1.DIV=B1.ParentMatType AND A1.AITNBR=B1.ParentMatID AND A1.[VERSION]=B1.ParentMatEditionNo
			GROUP BY SubMatTypeName,SubMatID
			 ) TBXH ON (TBRK.AITNBR=TBXH.ITNBR AND TBRK.DIV=TBXH.DIV) OR (TBQC.ITNBR=TBXH.ITNBR AND  TBQC.DIV=TBXH.DIV) 
			OR (TBQM.ITNBR=TBXH.ITNBR AND  TBQM.DIV=TBXH.DIV) OR (DB1.ITNBR=TBXH.ITNBR AND  DB1.DIV=TBXH.DIV) 
			 OR (DB2.ITNBR=TBXH.ITNBR AND  DB2.DIV=TBXH.DIV)----5.半成品内部消耗半成品
			 full join
			 (SELECT FAC,DIV,ITNBR,1.0*SUM(BQTY) FN,SUM(CASE WHEN REMARK=1 THEN 1 ELSE 0 END) FC FROM QMC0001  
			WHERE CDAT=@DATE  AND FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN ('10','11')
			GROUP BY FAC,DIV,ITNBR
			union all
			SELECT FAC,DIV,ITNBR,1.0*SUM(BQTY) FN,SUM(CASE WHEN REMARK=1 THEN 1 ELSE 0 END) FC FROM QMC0001  
			WHERE CDAT=@DATE  AND FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN ('12','13','15') and DIV  IN ('BDR','TR')
			GROUP BY FAC,DIV,ITNBR
			) TBBF ON (TBRK.AITNBR=TBBF.ITNBR AND TBRK.DIV=TBBF.DIV) OR (TBQC.ITNBR=TBBF.ITNBR AND  TBQC.DIV=TBBF.DIV) 
			OR (TBQM.ITNBR=TBBF.ITNBR AND  TBQM.DIV=TBBF.DIV) OR (DB1.ITNBR=TBBF.ITNBR AND  DB1.DIV=TBBF.DIV) 
			 OR (DB2.ITNBR=TBBF.ITNBR AND  DB2.DIV=TBBF.DIV) OR (TBXH.ITNBR=TBBF.ITNBR AND  TBXH.DIV=TBBF.DIV)---6.半成品报废半成品
			 full join
			 (select sum(CQTY) CN,ITNBR,ATTRIBUTE1 DIV FROM LOTCHANGELOG
			 WHERE CONVERT(NVARCHAR,ETIM,23)=@DATE AND FAC=@FAC and ATTRIBUTE1<>'' and [LOCATION] in('10','11')  GROUP BY ITNBR,ATTRIBUTE1) TBCZ
			  ON (TBRK.AITNBR=TBCZ.ITNBR AND TBRK.DIV=TBCZ.DIV) OR (TBQC.ITNBR=TBCZ.ITNBR AND  TBQC.DIV=TBCZ.DIV) 
			OR (TBQM.ITNBR=TBCZ.ITNBR AND  TBQM.DIV=TBCZ.DIV) OR (DB1.ITNBR=TBCZ.ITNBR AND  DB1.DIV=TBCZ.DIV) 
			 OR (DB2.ITNBR=TBCZ.ITNBR AND  DB2.DIV=TBCZ.DIV) OR (TBXH.ITNBR=TBCZ.ITNBR AND  TBXH.DIV=TBCZ.DIV)
			 OR (TBBF.ITNBR=TBCZ.ITNBR AND  TBBF.DIV=TBCZ.DIV)---7.差值
			 full join 
			 (	select b.HALFDIV,b.DIV,a.ITNBR, 
			sum(case when a.STA='1' then convert(float,isnull(qty,0)) when a.STA='2' then convert(float,isnull(qty,0))*-1.0 end) BN
			from STA0007 a left join STA0005 b on a.DOCCOD=b.DOCCOD where CONVERT(nvarchar(23),CONFIRMTIM,23)=@DATE
			and b.div=2 and a.sta in ('1','2')  AND b.FAC=@FAC
			group by b.HALFDIV,b.DIV,a.ITNBR ) TBPD on (TBRK.AITNBR=TBPD.ITNBR AND TBRK.DIV=TBPD.HALFDIV) OR (TBQC.ITNBR=TBPD.ITNBR AND  TBQC.DIV=TBPD.HALFDIV) 
			OR (TBQM.ITNBR=TBPD.ITNBR AND  TBQM.DIV=TBPD.HALFDIV) OR (DB1.ITNBR=TBPD.ITNBR AND  DB1.DIV=TBPD.HALFDIV) 
			 OR (DB2.ITNBR=TBPD.ITNBR AND  DB2.DIV=TBPD.HALFDIV) OR (TBXH.ITNBR=TBPD.ITNBR AND  TBXH.DIV=TBPD.HALFDIV)
			 OR (TBBF.ITNBR=TBPD.ITNBR AND  TBBF.DIV=TBPD.HALFDIV) OR (TBCZ.ITNBR=TBPD.ITNBR AND  TBCZ.DIV=TBPD.HALFDIV) --8.盘点数据
			 UNION 
			 SELECT '成型' [LOCATION],
			(CASE WHEN TBQM.ITNBR IS NOT NULL THEN TBQM.ITNBR  
			WHEN TBQC.ITNBR IS NOT NULL THEN TBQC.ITNBR WHEN DB1.ITNBR IS NOT NULL THEN DB1.ITNBR WHEN DB2.ITNBR IS NOT NULL THEN DB2.ITNBR
			WHEN TBXH.ITNBR IS NOT NULL THEN TBXH.ITNBR WHEN TBBF.ITNBR IS NOT NULL THEN TBBF.ITNBR WHEN TBCZ.ITNBR IS NOT NULL THEN TBCZ.ITNBR END) ITNBR ,
			(CASE WHEN TBQM.DIV IS NOT NULL THEN TBQM.DIV WHEN TBQC.DIV IS NOT NULL THEN TBQC.DIV 
			WHEN DB1.DIV IS NOT NULL THEN DB1.DIV WHEN DB2.DIV IS NOT NULL THEN DB2.DIV  WHEN TBXH.DIV IS NOT NULL 
			THEN TBXH.DIV WHEN TBBF.DIV IS NOT NULL THEN TBBF.DIV WHEN TBCZ.DIV IS NOT NULL THEN TBCZ.DIV   END) DIV
		   ,STARQTY,0 PN,ENDQTY,DBIN, DBOUT,XN,FN,CN,0 BN
		   FROM
			(SELECT  A1.DIV,A1.ITNBR,  1.0*SUM ( QTYD+QTYC ) STARQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@BDATE AND A1.FAC =@FAC AND WSHT='3'  
			AND A1.ITNBR IS NOT NULL  AND A1.ITNBR<>''   AND DIV NOT IN ('CCF','BDR','TR','TC','SK')  
			GROUP BY  A1.DIV,A1.ITNBR,A1.WSHT)  
			AS TBQC    --1、成型期初 
			full join
			(SELECT  A1.DIV,A1.ITNBR ,1.0*SUM(QTYC+QTYD ) ENDQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD AND A1.ITNBR IS NOT NULL
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@DATE AND A1.FAC =@FAC AND WSHT='3' 
			AND A1.ITNBR IS NOT NULL  AND A1.ITNBR<>''   AND DIV NOT IN ('CCF','BDR','TR','TC','SK')  
			GROUP BY A1.DIV,A1.ITNBR,A1.WSHT
			) AS  TBQM ON   (TBQC.ITNBR=TBQM.ITNBR AND TBQC.DIV=TBQM.DIV) --2、成型期期末
			FULL JOIN
			( select DIV,SUM(QTY) DBOUT,ITNBR from STB0014 where
		   CONVERT(NVARCHAR,CRTIM,23)=@DATE and YFAC=@FAC  and MOVETYPE in ('2','3')
		   	   and div NOT IN ('CCF','BDR','TR','TC','SK')  
		   group by DIV,ITNBR) DB2 ON  (TBQC.ITNBR=DB2.ITNBR AND  TBQC.DIV=DB2.DIV) 
			OR (TBQM.ITNBR=DB2.ITNBR AND  TBQM.DIV=DB2.DIV)  --3、成型调拨出库
			FULL JOIN 
			(SELECT ITGRPCOD3 DIV,ITNBR,SUM(OUTQTY) DBIN
				 FROM STB0004 
				WHERe OUTDAT=@DATE and FAC=@FAC   AND ITGRPCOD3 NOT IN ('CCF','BDR','TR','TC','SK')  
				GROUP BY  ITGRPCOD3,ITNBR) DB1 ON   (TBQC.ITNBR=DB1.ITNBR AND  TBQC.DIV=DB1.DIV) 
			OR (TBQM.ITNBR=DB1.ITNBR AND  TBQM.DIV=DB1.DIV) OR ( DB2.ITNBR=DB1.ITNBR AND   DB2.DIV=DB1.DIV)  --4、成型调拨出库
			 FULL JOIN 
			 (SELECT  SubMatTypeName DIV,SubMatID ITNBR
				,SUM(CX*(CASE WHEN SubMatTypeName IN('TD','PTD') THEN CAST(SubMatNum AS numeric) 
    						  WHEN SubMatTypeName IN('BD','PTQ','PD') THEN CAST(SubMatNum AS numeric)/2 --胎圈还要转换，BOM中单位为个，生产单位为对
							   WHEN SubMatTypeName IN('WG') THEN CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0/2 --肩垫卷产出就是两个
						  ELSE CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0 END)) XN--部件计量单位取条或米计算成型消耗量
				,'' XC--无法计算消耗的lot数
			FROM
				(SELECT FAC,BUSHT,BUITNBR,BUVERSION,COUNT(*) CX FROM LTA0001 WHERE ISNULL(IS_DELETE,0)='0' AND BUDAT=@DATE AND FAC =@FAC GROUP BY FAC,BUSHT,BUITNBR,BUVERSION) A1--成型产量
			LEFT JOIN 
				(SELECT ParentMatID,ParentMatEditionNo,SubMatTypeName,SubMatID,SubMatNum,PCSCuttinglength FROM EDD0061 WHERE ParentMatType='GT') B1--半成品BOM
			ON A1.BUITNBR=B1.ParentMatID AND A1.BUVERSION=B1.ParentMatEditionNo 
			GROUP BY SubMatTypeName,SubMatID) TBXH ON  (TBQC.ITNBR=TBXH.ITNBR AND  TBQC.DIV=TBXH.DIV) 
			OR (TBQM.ITNBR=TBXH.ITNBR AND  TBQM.DIV=TBXH.DIV) OR (DB1.ITNBR=TBXH.ITNBR AND  DB1.DIV=TBXH.DIV) 
			 OR (DB2.ITNBR=TBXH.ITNBR AND  DB2.DIV=TBXH.DIV) --成型产出消耗半成品
			 full join 
			  (SELECT Q.FAC,Q.DIV,L.AITNBR ITNBR,1.0*SUM(Q.BQTY) FN,SUM(CASE WHEN REMARK=1 THEN 1 ELSE 0 END) FC FROM QMC0001 Q LEFT JOIN LTC0001 L ON Q.LOTID=L.LOTID 
			WHERE CDAT=@DATE AND Q.FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN  ('12','13','15') and Q.DIV NOT IN ('BDR','TR')
			GROUP BY Q.FAC,Q.DIV,L.AITNBR) TBBF ON (TBQC.ITNBR=TBBF.ITNBR AND  TBQC.DIV=TBBF.DIV) 
			OR (TBQM.ITNBR=TBBF.ITNBR AND  TBQM.DIV=TBBF.DIV) OR (DB1.ITNBR=TBBF.ITNBR AND  DB1.DIV=TBBF.DIV) 
			 OR (DB2.ITNBR=TBBF.ITNBR AND  DB2.DIV=TBBF.DIV) OR (TBXH.ITNBR=TBBF.ITNBR AND  TBXH.DIV=TBBF.DIV)---6.半成品报废半成品
			 FULL JOIN 
			  (select sum(CQTY) CN,ITNBR,ATTRIBUTE1 DIV FROM LOTCHANGELOG
			 WHERE CONVERT(NVARCHAR,ETIM,23)=@DATE AND FAC=@FAC and ATTRIBUTE1<>'' and [LOCATION] in('12','13','15') AND ATTRIBUTE1 NOT IN ('TR','BDR','JL')  GROUP BY ITNBR,ATTRIBUTE1) TBCZ
			 ON (TBQC.ITNBR=TBCZ.ITNBR AND  TBQC.DIV=TBCZ.DIV) OR (TBBF.ITNBR=TBCZ.ITNBR AND  TBBF.DIV=TBCZ.DIV)
			OR (TBQM.ITNBR=TBCZ.ITNBR AND  TBQM.DIV=TBCZ.DIV) OR (DB1.ITNBR=TBCZ.ITNBR AND  DB1.DIV=TBCZ.DIV) 
			 OR (DB2.ITNBR=TBCZ.ITNBR AND  DB2.DIV=TBCZ.DIV) OR (TBXH.ITNBR=TBCZ.ITNBR AND  TBXH.DIV=TBCZ.DIV)---7.差值
			  ) X  
			 LEFT JOIN --下面是最外面一层的连接
			 (
			   SELECT ITTYPECOD,ITTYPENAM,ITNBR,VERSION,ERPCODE,SAPBOM
					  ,(CASE WHEN A2.ATTRVAL IS NULL THEN PCSCuttingWidth ELSE A2.ATTRVAL END) WIDTH--先从主数据找宽度，如果没有再从BOM中获取
					  ,A4.ATTRVAL Thickness
					  ,A5.ATTRVAL Density
			   FROM (SELECT ID,ITTYPECOD,ITTYPENAM,ITNBR,VERSION,ERPCODE,SAPBOM,ROW_NUMBER() OVER(PARTITION BY ITTYPECOD,ITNBR ORDER BY VERSION DESC) SE FROM EDD0001
					 WHERE ITGRPCOD='HALF' AND SHFLAG='Y') A1--已审核半成品物料主数据
			   LEFT JOIN EDD0002 A2 ON A1.ID=A2.ITEMID AND A2.ATTRCOD='M75'--从物料属性中获取宽度信息
			   LEFT JOIN
			   (
						  SELECT ParentMatType,ParentMatID,ParentMatEditionNo,PCSCuttingWidth
						  FROM
							(SELECT ParentMatType,ParentMatID,PCSCuttingWidth,ParentMatEditionNo
							       ,ROW_NUMBER() OVER(PARTITION BY ParentMatType,ParentMatID,ParentMatEditionNo ORDER BY ParentMatEditionNo DESC) SE 
						     FROM EDD0061
							 WHERE SubMatTypeName IN('CCF','PSC','PFC')) A1--从BOM中获取宽度信息,前提为BOM中宽度为产出物料的宽度
						  WHERE SE=1
			   ) A3 ON A1.ITTYPECOD=A3.ParentMatType AND A1.ITNBR=A3.ParentMatID AND A1.VERSION=A3.ParentMatEditionNo
			   LEFT JOIN EDD0002 A4 ON A1.ID=A4.ITEMID AND A4.ATTRCOD='M76'--从物料属性中获取厚度信息
			   LEFT JOIN
			   (
			             SELECT A51.*,A52.ATTRVAL FROM
						 (
			             SELECT DISTINCT GTMatType,GTMatID,GTEditionNo,SubMatID FROM RubberRequire WHERE SubMatTypeName='JL'--获取全钢胶片关联的终炼胶
						 UNION
						 SELECT DISTINCT ParentMatType,ParentMatID,ParentMatEditionNo,SubMatID FROM EDD0061 WHERE ParentMatType IN ('TC')--获取全钢压延胶片关联的终炼胶
						 ) A51
						 LEFT JOIN
						 (
						 SELECT SPEC,VERSION,ERPCODE,ROW_NUMBER() OVER(PARTITION BY ITTYPECOD,SPEC ORDER BY VERSION DESC) SE,ATTRVAL FROM EDD0001 A521
					     LEFT JOIN EDD0002 A522 ON A521.ID=A522.ITEMID
					     WHERE ITTYPECOD='JL' AND SHFLAG='Y' AND A522.ATTRCOD='M82'
						 ) A52 ON A51.SubMatID=A52.SPEC AND SE=1--获取每胶种的最新密度值
			   ) A5 ON A1.ITTYPECOD=A5.GTMatType AND A1.ITNBR=A5.GTMatID AND A1.VERSION=A5.GTEditionNo--获取全钢胶片及压延胶片关联的终炼胶密度
			   WHERE SE=1--取已审核主数据最新版本
		   ) T1  ON X.DIV=T1.ITTYPECOD AND X.ITNBR=T1.ITNBR--因报废及结算库存表中无物料规格版本，所以只能取最新版本关联，无版本关联
		   ORDER BY ITNBR
END
GO


-- ----------------------------
-- procedure structure for Report_BJXC_pro_time
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Report_BJXC_pro_time]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Report_BJXC_pro_time]
GO

CREATE PROCEDURE [dbo].[Report_BJXC_pro_time]
	@DIV NVARCHAR(10),@FAC NVARCHAR(10),@DATE DATE
AS
BEGIN

	DECLARE @QCDATE NVARCHAR(20);
	DECLARE @QMDATE NVARCHAR(20);
	
	SET @QCDATE=CONVERT(nvarchar(23),DATEADD(DAY,-1, @DATE),23)+' 23:44:59' ;
	SET @QMDATE=CONVERT(nvarchar(23),@DATE,23)+' 23:45:00' ;

	declare  @outtb table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBOUT float
)

	declare  @intb table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBIN float
)
	declare  @outtb2 table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBOUT2 float
)

	declare  @intb2 table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBIN2 float
)

if(@DIV<>'TR' AND @DIV<>'BDR')
BEGIN 
	insert into @outtb(div,ITNBR,DBOUT)
	SELECT ITGRPCOD3 DIV,ITNBR,SUM(OUTQTY) DBOUT
				 FROM STB0004 
				WHERe OUTDAT=@DATE and FAC=@FAC AND   ITGRPCOD3=@DIV
				GROUP BY  ITGRPCOD3,ITNBR;

				insert into @intb(div,ITNBR,DBIN)
				   select DIV,ITNBR ,SUM(QTY) DBIN from STB0014 where
		  CRTIM between @QCDATE and @QMDATE  and YFAC= @FAC AND DIV=@DIV and MOVETYPE in ('2','3')  AND YFAC=MFAC
		   group by DIV,ITNBR
END 
	insert into @outtb2(div,ITNBR,DBOUT2)
	select DIV,ITNBR ,SUM(QTY) DBOUT2 from STB0014 where
		   CRTIM between @QCDATE and @QMDATE and YFAC<>MFAC AND  YFAC=@FAC  AND DIV=@DIV and MOVETYPE in ('2','3')  
		   group by DIV,ITNBR

		   	insert into @intb2(div,ITNBR,DBIN2)
				  select DIV,ITNBR,SUM(QTY) DBIN2 from STB0014 where
		   CRTIM between @QCDATE and @QMDATE and YFAC<>MFAC AND  MFAC=@FAC AND DIV=@DIV and MOVETYPE in ('2','3')  
				GROUP BY  DIV,ITNBR; 

	DECLARE @BDATE DATE
	SET @BDATE=DATEADD(day,-1,@DATE);
WITH RubberRequire--胶片BOM对应的终炼胶
AS (
 SELECT ParentMatType,ParentMatID,ParentMatEditionNo
     ,SubMatTypeName,SubMatID,EditionNo
     ,ParentMatType GTMatType
     ,ParentMatID GTMatID
     ,ParentMatEditionNo GTEditionNo
 FROM EDD0061 WHERE ParentMatType ='SK'
 UNION ALL
 SELECT A.ParentMatType,A.ParentMatID,A.ParentMatEditionNo
   ,A.SubMatTypeName,A.SubMatID,A.EditionNo
   ,B.GTMatType GTMatType
   ,B.GTMatID GTMatID
   ,B.GTEditionNo GTEditionNo
 FROM EDD0061 A
 INNER JOIN RubberRequire B ON A.ParentMatType=B.SubMatTypeName AND A.ParentMatID=B.SubMatID AND A.ParentMatEditionNo=B.EditionNo
 )   
  SELECT X.ITNBR,T1.ITTYPENAM DIV,[LOCATION],T1.ERPCODE,SAPBOM,
      WIDTH,Thickness,Density,
	   (CASE WHEN X.DIV IN('CCF') THEN PN*WIDTH/1000.0--[生产入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN PN*WIDTH*Thickness*Density/1000.0--[生产入库]计量单位转换为kg
	                ELSE PN END) RKQTY--[生产入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN STARQTY*WIDTH/1000.0--[期初]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN STARQTY*WIDTH*Thickness*Density/1000.0--[期初]计量单位转换为kg
	                ELSE STARQTY END),1) STARQTY--[期初]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN ENDQTY*WIDTH/1000.0--[期末]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN ENDQTY*WIDTH*Thickness*Density/1000.0--[期末]计量单位转换为kg
	                ELSE ENDQTY END),1) ENDQTY--[期末]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBIN*WIDTH/1000.0--[调拨入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBIN*WIDTH*Thickness*Density/1000.0--[调拨入库]计量单位转换为kg
	                ELSE DBIN END),1) DBIN--[调拨入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBOUT*WIDTH/1000.0--[调拨出库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBOUT*WIDTH*Thickness*Density/1000.0--[调拨出库]计量单位转换为kg
	                ELSE DBOUT END),1) DBOUT--[调拨出库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBIN2*WIDTH/1000.0--[调拨入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBIN2*WIDTH*Thickness*Density/1000.0--[调拨入库]计量单位转换为kg
	                ELSE DBIN2 END),1) DBIN2--[工区外入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBOUT2*WIDTH/1000.0--[调拨出库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBOUT2*WIDTH*Thickness*Density/1000.0--[调拨出库]计量单位转换为kg
	                ELSE DBOUT2 END),1) DBOUT2--[工区外出库]
	   ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN XN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE XN END),1) XHQTY--[消耗数量]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN FN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE FN END),1) FNQTY--[报废数量]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN CN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE CN END),1) CNQTY--[差值]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN BN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE BN END),1) BNQTY--[盘点数量]
	   ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN (ISNULL(STARQTY,0)+ISNULL(DBIN,0)+ISNULL(PN,0)-ISNULL(DBOUT,0)-ISNULL(XN,0)-ISNULL(ENDQTY,0))*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE ISNULL(STARQTY,0)+ISNULL(DBIN,0)+ISNULL(PN,0)-ISNULL(DBOUT,0)-ISNULL(XN,0)-ISNULL(ENDQTY,0) END),1) OTQTY--[消耗数量]
	   ,(CASE WHEN X.DIV IN('CCF') THEN '㎡'
	          WHEN X.DIV IN('BD','PTQ','BDR') THEN '对'  
	          WHEN X.DIV IN('TD','TR') THEN '条'
			  WHEN X.DIV IN('TC','SK') THEN 'kg'
			  ELSE 'm' END) UNIT FROM
( SELECT '半成品' [LOCATION],
			(CASE WHEN TBQM.ITNBR IS NOT NULL THEN TBQM.ITNBR WHEN TBRK.AITNBR IS NOT NULL THEN TBRK.AITNBR 
			WHEN TBQC.ITNBR IS NOT NULL THEN TBQC.ITNBR WHEN DB1.ITNBR IS NOT NULL THEN DB1.ITNBR WHEN DB2.ITNBR IS NOT NULL THEN DB2.ITNBR
			WHEN TBXH.ITNBR IS NOT NULL THEN TBXH.ITNBR WHEN TBBF.ITNBR IS NOT NULL THEN TBBF.ITNBR WHEN TBCZ.ITNBR IS NOT NULL THEN TBCZ.ITNBR
			WHEN TBPD.ITNBR IS NOT NULL THEN TBPD.ITNBR END) ITNBR ,
			(CASE WHEN TBQM.DIV IS NOT NULL THEN TBQM.DIV WHEN TBRK.DIV IS NOT NULL THEN TBRK.DIV WHEN TBQC.DIV IS NOT NULL THEN TBQC.DIV 
			WHEN DB1.DIV IS NOT NULL THEN DB1.DIV WHEN DB2.DIV IS NOT NULL THEN DB2.DIV  WHEN TBXH.DIV IS NOT NULL 
			THEN TBXH.DIV WHEN TBBF.DIV IS NOT NULL THEN TBBF.DIV WHEN TBCZ.DIV IS NOT NULL THEN TBCZ.DIV  
			WHEN TBPD.DIV IS NOT NULL THEN TBPD.DIV END) DIV
		   ,STARQTY,PN,ENDQTY, DBIN, DBOUT,XN,FN,CN,BN,DBIN2,DBOUT2
		   FROM
			(SELECT DIV,AITNBR,ROUND(SUM(QTY),2) PN 
			FROM LTC0001
			WHERE AUTIM  between @QCDATE and @QMDATE AND FAC =@FAC and isnull(IS_DELETE,0)=0 and DIV=@DIV
			GROUP BY DIV,AITNBR) AS TBRK --0.产出
			full join 
			(SELECT  A1.DIV,A1.ITNBR, 1.0*SUM(CASE  WHEN DIV IN ('CCF','BDR','TR','TC','SK') THEN  SUMQTY  ELSE QTYA+QTYB END) STARQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@BDATE AND A1.FAC =@FAC AND WSHT='3'   AND A1.ITNBR IS NOT NULL AND A1.ITNBR<>''  AND A1.DIV=@DIV
			GROUP BY  A1.DIV,A1.ITNBR)  
			AS TBQC ON TBRK.AITNBR=TBQC.ITNBR AND TBRK.DIV=TBQC.DIV   --1、半成品期初 
			full join
			(SELECT  A1.DIV,A1.ITNBR ,1.0*SUM(CASE  WHEN DIV IN ('CCF','BDR','TR','TC','SK') THEN  SUMQTY  ELSE QTYA+QTYB END) ENDQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD AND A1.ITNBR IS NOT NULL
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@DATE AND A1.FAC =@FAC AND WSHT='3'  AND A1.ITNBR IS NOT NULL   AND A1.ITNBR<>'' AND A1.DIV=@DIV
			GROUP BY A1.DIV,A1.ITNBR
			) AS  TBQM ON (TBRK.AITNBR=TBQM.ITNBR AND TBRK.DIV=TBQM.DIV) OR (TBQC.ITNBR=TBQM.ITNBR AND TBQC.DIV=TBQM.DIV) --2、半成品期期末
			FULL JOIN
			(  select * from @intb 
			) DB1 ON (TBRK.AITNBR=DB1.ITNBR AND  TBRK.DIV=DB1.DIV) OR (TBQC.ITNBR=DB1.ITNBR AND  TBQC.DIV=DB1.DIV) 
			OR (TBQM.ITNBR=DB1.ITNBR AND  TBQM.DIV=DB1.DIV)  --3、半成品调拨入库
			FULL JOIN 
			(SELECT *   FROM @outtb  ) DB2 ON (TBRK.AITNBR=DB2.ITNBR AND TBRK.DIV=DB2.DIV) OR (TBQC.ITNBR=DB2.ITNBR AND  TBQC.DIV=DB2.DIV) 
			OR (TBQM.ITNBR=DB2.ITNBR AND  TBQM.DIV=DB2.DIV) OR (DB1.ITNBR=DB2.ITNBR AND  DB1.DIV=DB2.DIV)  --4、半成品调拨出库
			 FULL JOIN 
			 (SELECT * FROM (SELECT (CASE WHEN SubMatTypeName='BDW' THEN 'BDR' ELSE SubMatTypeName END) DIV--BOM消耗的为成品钢丝圈，系统中对成品钢丝圈不管理，消耗钢丝圈（规格代码一样）
			,SubMatID ITNBR
				,SUM(HA*(CASE WHEN SubMatTypeName IN('BDW','TR','SK') THEN CAST(SubMatNum AS numeric)--部件计量单位取条计算消耗量
			                  WHEN SubMatTypeName IN('CCF','TC') THEN CAST(ROUND(PCSCuttingWidth,0) AS int)*CAST(SubMatNum AS numeric)/1000.0--钢帘布/压延胶片BOM消耗取宽度计算平方米
							  ELSE CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0 END)) XN--部件计量单位根据单条长度计算消耗量
				,'' XC--无法计算消耗的lot数
			FROM
				(SELECT FAC,DIV,AUSHT,AITNBR,[VERSION],SUM(QTY) HA FROM LTC0001 WHERE ISNULL(IS_DELETE,0)='0' AND AUTIM between @QCDATE and @QMDATE AND FAC=@FAC 
				GROUP BY FAC,DIV,AUSHT,AITNBR,[VERSION]) A1--半成品产量
			INNER JOIN 
				(SELECT ParentMatType,ParentMatID,ParentMatEditionNo,SubMatTypeName,SubMatID,SubMatNum,PCSCuttinglength,PCSCuttingWidth 
				  FROM EDD0061 WHERE SubMatTypeName IN('CCF','BDW','TR','TC','SK')) B1--半成品BOM（只取半成品内部耗用的物料类型）（消耗的物料在范围内）
			ON A1.DIV=B1.ParentMatType AND A1.AITNBR=B1.ParentMatID AND A1.[VERSION]=B1.ParentMatEditionNo 
			GROUP BY SubMatTypeName,SubMatID
			 ) T WHERE DIV=@DIV) TBXH ON (TBRK.AITNBR=TBXH.ITNBR AND TBRK.DIV=TBXH.DIV) OR (TBQC.ITNBR=TBXH.ITNBR AND  TBQC.DIV=TBXH.DIV) 
			OR (TBQM.ITNBR=TBXH.ITNBR AND  TBQM.DIV=TBXH.DIV) OR (DB1.ITNBR=TBXH.ITNBR AND  DB1.DIV=TBXH.DIV) 
			 OR (DB2.ITNBR=TBXH.ITNBR AND  DB2.DIV=TBXH.DIV)----5.半成品内部消耗半成品
			 full join
			 (SELECT FAC,DIV,ITNBR,SUM(FN) FN,SUM(FC) FC FROM (SELECT FAC,DIV,ITNBR,1.0*SUM(BQTY) FN,SUM(CASE WHEN REMARK='1' THEN 1 ELSE 0 END) FC FROM QMC0001  
			WHERE CRTIM  between @QCDATE and @QMDATE AND DIV=@DIV AND FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN ('10','11')
			GROUP BY FAC,DIV,ITNBR
			union all
			SELECT FAC,DIV,ITNBR,1.0*SUM(BQTY) FN,SUM(CASE WHEN REMARK='1' THEN 1 ELSE 0 END) FC FROM QMC0001  
			WHERE CRTIM  between @QCDATE and @QMDATE AND DIV=@DIV AND FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN ('12','13','15') and DIV  IN ('BDR','TR')
			GROUP BY FAC,DIV,ITNBR) TT GROUP BY FAC,DIV,ITNBR
			) TBBF ON (TBRK.AITNBR=TBBF.ITNBR AND TBRK.DIV=TBBF.DIV) OR (TBQC.ITNBR=TBBF.ITNBR AND  TBQC.DIV=TBBF.DIV) 
			OR (TBQM.ITNBR=TBBF.ITNBR AND  TBQM.DIV=TBBF.DIV) OR (DB1.ITNBR=TBBF.ITNBR AND  DB1.DIV=TBBF.DIV) 
			 OR (DB2.ITNBR=TBBF.ITNBR AND  DB2.DIV=TBBF.DIV) OR (TBXH.ITNBR=TBBF.ITNBR AND  TBXH.DIV=TBBF.DIV)---6.半成品报废半成品
			 full join
			 (select sum(CQTY) CN,ITNBR,ATTRIBUTE1 DIV FROM LOTCHANGELOG
			 WHERE ETIM  between @QCDATE and @QMDATE AND FAC=@FAC and [LOCATION] in('10','11')  AND ATTRIBUTE1=@DIV AND ATTRIBUTE1 NOT IN ('TR','BDR','JL') GROUP BY ITNBR,ATTRIBUTE1) TBCZ
			  ON (TBRK.AITNBR=TBCZ.ITNBR and TBRK.DIV=TBCZ.DIV) OR (TBQC.ITNBR=TBCZ.ITNBR and TBQC.DIV=TBCZ.DIV ) 
			OR (TBQM.ITNBR=TBCZ.ITNBR and TBQM.DIV=TBCZ.DIV) OR (DB1.ITNBR=TBCZ.ITNBR and DB1.DIV=TBCZ.DIV) 
			 OR (DB2.ITNBR=TBCZ.ITNBR and DB2.DIV=TBCZ.DIV ) OR (TBXH.ITNBR=TBCZ.ITNBR and TBXH.DIV=TBCZ.DIV)
			 OR (TBBF.ITNBR=TBCZ.ITNBR and TBBF.DIV=TBCZ.DIV)---7.差值
			 full join 
			 (	select b.HALFDIV,b.DIV,a.ITNBR, 
			sum(case when a.STA='1' then convert(float,isnull(qty,0)) when a.STA='2' then convert(float,isnull(qty,0))*-1.0 end) BN
			from STA0007 a left join STA0005 b on a.DOCCOD=b.DOCCOD where CONFIRMTIM  between @QCDATE and @QMDATE
			and b.div=2 and a.sta in ('1','2') AND HALFDIV=@DIV AND b.FAC=@FAC
			group by b.HALFDIV,b.DIV,a.ITNBR ) TBPD on (TBRK.AITNBR=TBPD.ITNBR AND TBRK.DIV=TBPD.HALFDIV) OR (TBQC.ITNBR=TBPD.ITNBR AND  TBQC.DIV=TBPD.HALFDIV) 
			OR (TBQM.ITNBR=TBPD.ITNBR AND  TBQM.DIV=TBPD.HALFDIV) OR (DB1.ITNBR=TBPD.ITNBR AND  DB1.DIV=TBPD.HALFDIV) 
			 OR (DB2.ITNBR=TBPD.ITNBR AND  DB2.DIV=TBPD.HALFDIV) OR (TBXH.ITNBR=TBPD.ITNBR AND  TBXH.DIV=TBPD.HALFDIV)
			 OR (TBBF.ITNBR=TBPD.ITNBR AND  TBBF.DIV=TBPD.HALFDIV) OR (TBCZ.ITNBR=TBPD.ITNBR AND  TBCZ.DIV=TBPD.HALFDIV) --8.盘点数据
			 full join 
			 (  select * from @intb2 
			) FDB1 ON (TBRK.AITNBR=FDB1.ITNBR AND TBRK.DIV=FDB1.DIV) OR (TBQC.ITNBR=FDB1.ITNBR AND  TBQC.DIV=FDB1.DIV) 
			OR (TBQM.ITNBR=FDB1.ITNBR AND  TBQM.DIV=FDB1.DIV) OR (DB1.ITNBR=FDB1.ITNBR AND  DB1.DIV=FDB1.DIV) 
			 OR (DB2.ITNBR=FDB1.ITNBR AND  DB2.DIV=FDB1.DIV) OR (TBXH.ITNBR=FDB1.ITNBR AND  TBXH.DIV=FDB1.DIV)
			 OR (TBBF.ITNBR=FDB1.ITNBR AND  TBBF.DIV=FDB1.DIV) OR (TBCZ.ITNBR=FDB1.ITNBR AND  TBCZ.DIV=FDB1.DIV) 
			 OR (TBPD.ITNBR=FDB1.ITNBR AND  TBPD.HALFDIV=FDB1.DIV)  --9、工区外入库
			FULL JOIN 
			(SELECT *   FROM @outtb2  ) FDB2 ON (TBRK.AITNBR=FDB2.ITNBR AND TBRK.DIV=FDB2.DIV) OR (TBQC.ITNBR=FDB2.ITNBR AND  TBQC.DIV=FDB2.DIV) 
			OR (TBQM.ITNBR=FDB2.ITNBR AND  TBQM.DIV=FDB2.DIV) OR (DB1.ITNBR=FDB2.ITNBR AND  DB1.DIV=FDB2.DIV) 
			 OR (DB2.ITNBR=FDB2.ITNBR AND  DB2.DIV=FDB2.DIV) OR (TBXH.ITNBR=FDB2.ITNBR AND  TBXH.DIV=FDB2.DIV)
			 OR (TBBF.ITNBR=FDB2.ITNBR AND  TBBF.DIV=FDB2.DIV) OR (TBCZ.ITNBR=FDB2.ITNBR AND  TBCZ.DIV=FDB2.DIV) 
			 OR (TBPD.ITNBR=FDB2.ITNBR AND  TBPD.HALFDIV=FDB2.DIV)   OR (FDB1.ITNBR=FDB2.ITNBR AND  FDB1.DIV=FDB2.DIV)    --10、工区外出库
			 UNION 
			 SELECT '成型' [LOCATION],
			(CASE WHEN TBQM.ITNBR IS NOT NULL THEN TBQM.ITNBR  
			WHEN TBQC.ITNBR IS NOT NULL THEN TBQC.ITNBR WHEN DB1.ITNBR IS NOT NULL THEN DB1.ITNBR WHEN DB2.ITNBR IS NOT NULL THEN DB2.ITNBR
			WHEN TBXH.ITNBR IS NOT NULL THEN TBXH.ITNBR WHEN TBBF.ITNBR IS NOT NULL THEN TBBF.ITNBR WHEN TBCZ.ITNBR IS NOT NULL THEN TBCZ.ITNBR END) ITNBR ,
			(CASE WHEN TBQM.DIV IS NOT NULL THEN TBQM.DIV WHEN TBQC.DIV IS NOT NULL THEN TBQC.DIV 
			WHEN DB1.DIV IS NOT NULL THEN DB1.DIV WHEN DB2.DIV IS NOT NULL THEN DB2.DIV  WHEN TBXH.DIV IS NOT NULL 
			THEN TBXH.DIV WHEN TBBF.DIV IS NOT NULL THEN TBBF.DIV WHEN TBCZ.DIV IS NOT NULL THEN TBCZ.DIV   END) DIV
		   ,STARQTY,0 PN,ENDQTY,DBIN, DBOUT,XN,FN,CN,0 BN,0 DBIN2,0 DBOUT2
		   FROM
			(SELECT  A1.DIV,A1.ITNBR,  1.0*SUM ( QTYD+QTYC ) STARQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@BDATE AND A1.FAC =@FAC AND WSHT='3'  
			AND A1.ITNBR IS NOT NULL  AND A1.ITNBR<>''  AND A1.DIV=@DIV AND DIV NOT IN ('CCF','BDR','TR','TC','SK')  
			GROUP BY  A1.DIV,A1.ITNBR,A1.WSHT)  
			AS TBQC    --1、成型期初 
			full join
			(SELECT  A1.DIV,A1.ITNBR ,1.0*SUM(QTYC+QTYD ) ENDQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD AND A1.ITNBR IS NOT NULL
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@DATE AND A1.FAC =@FAC AND WSHT='3' 
			AND A1.ITNBR IS NOT NULL  AND A1.ITNBR<>''  AND A1.DIV=@DIV AND DIV NOT IN ('CCF','BDR','TR','TC','SK')  
			GROUP BY A1.DIV,A1.ITNBR,A1.WSHT
			) AS  TBQM ON   (TBQC.ITNBR=TBQM.ITNBR AND TBQC.DIV=TBQM.DIV) --2、成型期期末
			FULL JOIN
			( select DIV,SUM(QTY) DBOUT,ITNBR from STB0014 where
		   CRTIM  between @QCDATE and @QMDATE and YFAC=@FAC AND DIV=@DIV and MOVETYPE in ('2','3')
		   and div NOT IN ('CCF','BDR','TR','TC','SK')  and YFAC=MFAC
		   group by DIV,ITNBR) DB2 ON  (TBQC.ITNBR=DB2.ITNBR AND  TBQC.DIV=DB2.DIV) 
			OR (TBQM.ITNBR=DB2.ITNBR AND  TBQM.DIV=DB2.DIV)  --3、成型调拨出库
			FULL JOIN 
			(SELECT ITGRPCOD3 DIV,ITNBR,SUM(OUTQTY) DBIN
				 FROM STB0004 
				WHERe CRTIM  between @QCDATE and @QMDATE and FAC=@FAC AND   ITGRPCOD3=@DIV AND ITGRPCOD3 NOT IN ('CCF','BDR','TR','TC','SK')  
				GROUP BY  ITGRPCOD3,ITNBR) DB1 ON   (TBQC.ITNBR=DB1.ITNBR AND  TBQC.DIV=DB1.DIV) 
			OR (TBQM.ITNBR=DB1.ITNBR AND  TBQM.DIV=DB1.DIV) OR ( DB2.ITNBR=DB1.ITNBR AND   DB2.DIV=DB1.DIV)  --4、成型调拨出库
			 FULL JOIN 
			 (SELECT  SubMatTypeName DIV,SubMatID ITNBR
				,SUM(CX*(CASE WHEN SubMatTypeName IN('TD','PTD') THEN CAST(SubMatNum AS numeric) 
    						  WHEN SubMatTypeName IN('BD','PTQ','PD') THEN CAST(SubMatNum AS numeric)/2 --胎圈还要转换，BOM中单位为个，生产单位为对
    						  WHEN SubMatTypeName IN('WG') THEN CAST(ROUND(PCSCuttinglength,0) AS int)* CAST(SubMatNum AS numeric)/1000.0/2 --肩垫卷产出就是两个
						  ELSE CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0 END)) XN--部件计量单位取条或米计算成型消耗量
				,'' XC--无法计算消耗的lot数
			FROM
				(SELECT FAC,BUSHT,BUITNBR,BUVERSION,COUNT(*) CX FROM LTA0001 WHERE ISNULL(IS_DELETE,0)='0' AND BUTIM  between @QCDATE and @QMDATE AND FAC =@FAC GROUP BY FAC,BUSHT,BUITNBR,BUVERSION) A1--成型产量
			LEFT JOIN 
				(SELECT ParentMatID,ParentMatEditionNo,SubMatTypeName,SubMatID,SubMatNum,PCSCuttinglength FROM EDD0061 WHERE ParentMatType='GT') B1--半成品BOM
			ON A1.BUITNBR=B1.ParentMatID AND A1.BUVERSION=B1.ParentMatEditionNo
			WHERE SubMatTypeName=@DIV
			GROUP BY SubMatTypeName,SubMatID) TBXH ON  (TBQC.ITNBR=TBXH.ITNBR AND  TBQC.DIV=TBXH.DIV) 
			OR (TBQM.ITNBR=TBXH.ITNBR AND  TBQM.DIV=TBXH.DIV) OR (DB1.ITNBR=TBXH.ITNBR AND  DB1.DIV=TBXH.DIV) 
			 OR (DB2.ITNBR=TBXH.ITNBR AND  DB2.DIV=TBXH.DIV) --成型产出消耗半成品
			 full join 
			  (SELECT Q.FAC,Q.DIV,L.AITNBR ITNBR,1.0*SUM(Q.BQTY) FN,SUM(CASE WHEN REMARK=1 THEN 1 ELSE 0 END) FC FROM QMC0001 Q LEFT JOIN LTC0001 L ON Q.LOTID=L.LOTID 
			WHERE Q.crtim >=@QCDATE AND Q.CRTIM<@QMDATE AND Q.FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN  ('12','13','15') and Q.DIV NOT IN ('BDR','TR')
			GROUP BY Q.FAC,Q.DIV,L.AITNBR) TBBF ON (TBQC.ITNBR=TBBF.ITNBR AND  TBQC.DIV=TBBF.DIV) 
			OR (TBQM.ITNBR=TBBF.ITNBR AND  TBQM.DIV=TBBF.DIV) OR (DB1.ITNBR=TBBF.ITNBR AND  DB1.DIV=TBBF.DIV) 
			 OR (DB2.ITNBR=TBBF.ITNBR AND  DB2.DIV=TBBF.DIV) OR (TBXH.ITNBR=TBBF.ITNBR AND  TBXH.DIV=TBBF.DIV)---6.半成品报废半成品
			 FULL JOIN 
			  (select sum(CQTY) CN,ITNBR,ATTRIBUTE1 DIV FROM LOTCHANGELOG
			 WHERE ETIM  between @QCDATE and @QMDATE AND FAC=@FAC   and [LOCATION] in('12','13','15') AND ATTRIBUTE1=@DIV AND ATTRIBUTE1 NOT IN ('TR','BDR') GROUP BY ITNBR,ATTRIBUTE1) TBCZ
			 ON (TBQC.ITNBR=TBCZ.ITNBR and TBQC.DIV=TBCZ.DIV) OR (TBBF.ITNBR=TBCZ.ITNBR and TBBF.DIV=TBCZ.DIV)
			OR (TBQM.ITNBR=TBCZ.ITNBR and TBQM.DIV=TBCZ.DIV) OR (DB1.ITNBR=TBCZ.ITNBR and DB1.DIV=TBCZ.DIV) 
			 OR (DB2.ITNBR=TBCZ.ITNBR and DB2.DIV=TBCZ.DIV) OR (TBXH.ITNBR=TBCZ.ITNBR and TBXH.DIV=TBCZ.DIV)---7.差值
			  ) X  
			 LEFT JOIN --下面是最外面一层的连接
			 (
			   SELECT ITTYPECOD,ITTYPENAM,ITNBR,VERSION,ERPCODE,SAPBOM
					  ,(CASE WHEN A2.ATTRVAL IS NULL THEN PCSCuttingWidth ELSE A2.ATTRVAL END) WIDTH--先从主数据找宽度，如果没有再从BOM中获取
					  ,A4.ATTRVAL Thickness
					  ,A5.ATTRVAL Density
			   FROM (SELECT ID,ITTYPECOD,ITTYPENAM,ITNBR,VERSION,ERPCODE,SAPBOM,ROW_NUMBER() OVER(PARTITION BY ITTYPECOD,ITNBR ORDER BY VERSION DESC) SE FROM EDD0001
					 WHERE ITGRPCOD='HALF' AND SHFLAG='Y') A1--已审核半成品物料主数据
			   LEFT JOIN EDD0002 A2 ON A1.ID=A2.ITEMID AND A2.ATTRCOD='M75'--从物料属性中获取宽度信息
			   LEFT JOIN
			   (
						  SELECT ParentMatType,ParentMatID,ParentMatEditionNo,PCSCuttingWidth
						  FROM
							(SELECT ParentMatType,ParentMatID,PCSCuttingWidth,ParentMatEditionNo
							       ,ROW_NUMBER() OVER(PARTITION BY ParentMatType,ParentMatID,ParentMatEditionNo ORDER BY ParentMatEditionNo DESC) SE 
						     FROM EDD0061
							 WHERE SubMatTypeName IN('CCF','PSC','PFC')) A1--从BOM中获取宽度信息,前提为BOM中宽度为产出物料的宽度
						  WHERE SE=1
			   ) A3 ON A1.ITTYPECOD=A3.ParentMatType AND A1.ITNBR=A3.ParentMatID AND A1.VERSION=A3.ParentMatEditionNo
			   LEFT JOIN EDD0002 A4 ON A1.ID=A4.ITEMID AND A4.ATTRCOD='M76'--从物料属性中获取厚度信息
			   LEFT JOIN
			   (
			             SELECT A51.*,A52.ATTRVAL FROM
						 (
			             SELECT DISTINCT GTMatType,GTMatID,GTEditionNo,SubMatID FROM RubberRequire WHERE SubMatTypeName='JL'--获取全钢胶片关联的终炼胶
						 UNION
						 SELECT DISTINCT ParentMatType,ParentMatID,ParentMatEditionNo,SubMatID FROM EDD0061 WHERE ParentMatType IN ('TC')--获取全钢压延胶片关联的终炼胶
						 ) A51
						 LEFT JOIN
						 (
						 SELECT SPEC,VERSION,ERPCODE,ROW_NUMBER() OVER(PARTITION BY ITTYPECOD,SPEC ORDER BY VERSION DESC) SE,ATTRVAL FROM EDD0001 A521
					     LEFT JOIN EDD0002 A522 ON A521.ID=A522.ITEMID
					     WHERE ITTYPECOD='JL' AND SHFLAG='Y' AND A522.ATTRCOD='M82'
						 ) A52 ON A51.SubMatID=A52.SPEC AND SE=1--获取每胶种的最新密度值
			   ) A5 ON A1.ITTYPECOD=A5.GTMatType AND A1.ITNBR=A5.GTMatID AND A1.VERSION=A5.GTEditionNo--获取全钢胶片及压延胶片关联的终炼胶密度
			   WHERE SE=1--取已审核主数据最新版本
		   ) T1  ON X.DIV=T1.ITTYPECOD AND X.ITNBR=T1.ITNBR--因报废及结算库存表中无物料规格版本，所以只能取最新版本关联，无版本关联
		   ORDER BY ITNBR

END
GO


-- ----------------------------
-- procedure structure for proChengXingJiHuaChanLiangDangRi
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proChengXingJiHuaChanLiangDangRi]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proChengXingJiHuaChanLiangDangRi]
GO

CREATE PROCEDURE [dbo].[proChengXingJiHuaChanLiangDangRi]
(
		@FACList									NVARCHAR(50),
		@WDATE										DATETIME=NULL
)
AS
BEGIN
   
	SELECT @wdate = ISNULL(@wdate, GETDATE());
	
	DECLARE @DCL									DECIMAL(18,6),
			@QTYLOT									DECIMAL(18,6),
			@PLLOT									DECIMAL(18,6);
		
		begin
			SELECT @PLLOT=tPAD0201.PLLOT, --计划
			@QTYLOT=tLTA0001.QTYLOT, --产量
			@DCL = tLTA0001.QTYLOT / NULLIF(tPAD0201.PLLOT,0)  -- *
	  FROM (SELECT t.BUDAT, 
					COUNT(BARCODE) AS QTYLOT,
					COUNT(CASE BUSHT
						WHEN '1' THEN
							BARCODE
						END ) QTYLOT1,
					COUNT(CASE BUSHT
						WHEN '2' THEN
							BARCODE
						END ) QTYLOT2,
					COUNT(CASE BUSHT
						WHEN '3' THEN
							BARCODE
						END ) QTYLOT3 
			FROM LTA0001 t WITH (NOLOCK)
			WHERE FAC IN (SELECT [VALUE]
							FROM STRING_SPLIT(@FACList,','))
			AND CONVERT(DATE,BUDAT) = CONVERT(DATE,@WDATE)
			AND ISNULL(IS_DELETE, '0') = '0'
			GROUP BY t.BUDAT) tLTA0001
	RIGHT JOIN (SELECT WDATE, 
	                    CASE  WHEN @FACList ='02' THEN SUM(PLLOT)
						ELSE CEILING(SUM(PLLOT)/2) 
						END AS PLLOT,
						--CEILING(SUM(PLLOT)/2) AS PLLOT,
						SUM(CASE WSHT
							WHEN 1 THEN
								p.PLLOT
							END) AS PLLOT1,
						SUM(CASE WSHT
							WHEN 2 THEN
								p.PLLOT
							END) AS PLLOT2,
						SUM(CASE WSHT
							WHEN 3 THEN
								p.PLLOT
							END) AS PLLOT3
				FROM PAD0201 AS p WITH(NOLOCK)
				WHERE p.FAC IN (SELECT [VALUE]
								FROM STRING_SPLIT(@FACList,','))
				AND p.ATTRIBUTE1 = 'GT'
				AND MCHID NOT IN ('02B1-041','02B1-051','02B1-061','02B1-071','02B1-081','02DR0021','02R00011','02R00021','02R00031','02R00041','02R00051','02R00061','02TR0051','02TR0061') 
				AND CONVERT(DATE,WDATE) = CONVERT(DATE,@WDATE)
				GROUP BY WDATE) tPAD0201
	ON tPAD0201.WDATE=tLTA0001.BUDAT

	SELECT @PLLOT AS pllot,
			@QTYLOT AS qtylot,
			@DCL AS dcl
		end
	
END
GO


-- ----------------------------
-- function structure for GetCiFeiPinLv
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetCiFeiPinLv]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetCiFeiPinLv]
GO

CREATE FUNCTION [dbo].[GetCiFeiPinLv]
(	
	-- Add the parameters for the function here
	@DTP1												datetime,
	@DTP2												datetime
)
RETURNS @t TABLE
(
    打磨品													int,
	修理品													int,
	总次废品												int,
	外观次废品												int,
	[X光缺陷]												int,
	动平衡次废品											int,

    打磨品率												decimal(18,6),
	修理品率												decimal(18,6),
	总次废品率												decimal(18,6),
	外观次废品率											decimal(18,6),
	[X光缺陷率]												decimal(18,6),
	动平衡次废品率											decimal(18,6)
)
AS
BEGIN
	with qgQMA0001 as 
	(
		select *
		from QMA0001 tWGBAD WITH(NOLOCK)
		where tWGBAD.FAC IN ('01','03')
	), 
	tpQMB0101 as
	(
		SELECT COUNT(t.ID) as countTotal,
				nullif(COUNT(t.ID)*1.00,0) as countTotalNullIf,
				(select COUNT(*)
				   FROM [dbo].[QMB0101] t WITH(NOLOCK)
				  where t.QCSTATE in ('W3')
					and t.UPDTIM BETWEEN @DTP1 AND @DTP2) as countW3, --打磨
				--COUNT(case
				--when t.QCSTATE in ('W3') then	
				--	t.ID
				--end) AS countW3, --打磨
				(select COUNT(*)
				   FROM [dbo].[QMB0101] t WITH(NOLOCK)
				  where t.QCSTATE in ('W1','W2')
					and t.UPDTIM BETWEEN @DTP1 AND @DTP2) as countW12, --修理
				--COUNT(case
				--when t.QCSTATE in ('W1','W2') then	
				--	t.ID
				--end) AS countW12, -- 修理
				(select COUNT(*)
				   FROM [dbo].[QMB0101] t WITH(NOLOCK)
				  where t.QCSTATE in ('2','3')
					and t.UPDTIM BETWEEN @DTP1 AND @DTP2) as count23, -- 总次废品
				(select COUNT(*)
				   from [dbo].[QMB0101] t WITH(NOLOCK)
					inner JOIN qgQMA0001 tWGBAD WITH(NOLOCK)
					ON t.WGBAD = tWGBAD.BCOD
				  where tWGBAD.DIV IN (N'FT')
				   and tWGBAD.LTDIV in ('1','5','6','7')
					and t.UPDTIM BETWEEN @DTP1 AND @DTP2) as countWGBAD, -- 外观缺陷 
				(select COUNT(*)
				   from [dbo].[QMB0101] t WITH(NOLOCK)
					inner JOIN qgQMA0001 tXBAD WITH(NOLOCK)
					ON t.XBAD = tXBAD.BCOD
				  where tXBAD.DIV IN (N'FT')
				   and tXBAD.LTDIV in ('2')
					and t.UPDTIM BETWEEN @DTP1 AND @DTP2) as countXBAD, -- X光缺陷
				0 as countXBAD1 -- 动平衡缺陷
		FROM [dbo].[QMB0101] t WITH(NOLOCK)
	)
	insert into @t
	SELECT 	t2.countW3 as 打磨品,
			ISNULL(t2.countW12,0) as 修理品,
			t2.count23 as 总次废品,
			t2.countWGBAD as 外观次废品,
			t2.countXBAD as [X光缺陷],
			0 as 动平衡次废品											,
	
			t2.countW3/countTotalNullIf AS 打磨品率,
		   ISNULL(t2.countW12,0)/countTotalNullIf AS 修理品率,
		   ISNULL(t2.count23,0)/countTotalNullIf AS 总次废品率,
		   ISNULL(t2.countWGBAD,0)/countTotalNullIf AS 外观次废品率,
		   ISNULL(t2.countXBAD,0)/countTotalNullIf AS [X光缺陷率],
		   1 AS [动平衡次废品率]
		 --  ,
			--*
	FROM tpQMB0101 t2

    RETURN 
END;
GO


-- ----------------------------
-- procedure structure for Report_BJXC_nodiv_pro_time
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Report_BJXC_nodiv_pro_time]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Report_BJXC_nodiv_pro_time]
GO

CREATE PROCEDURE [dbo].[Report_BJXC_nodiv_pro_time]
 @FAC NVARCHAR(10),@day1 nvarchar(30)='',@day2 nvarchar(30)=''
AS
BEGIN

	DECLARE @QCDATE NVARCHAR(20);
	DECLARE @QMDATE NVARCHAR(20); 
	DECLARE @BDATE DATE;
	declare @DATE DATE;
	if(@day1='')
	begin
	SET @QCDATE=CONVERT(nvarchar(23),getdate()-1,23)+' 23:45:00' ;
	SET @QMDATE=CONVERT(nvarchar(23),getdate(),23)+' 23:45:00' ; 
	SET @DATE=CONVERT(nvarchar(23),getdate(),23);
	SET @BDATE=CONVERT(nvarchar(23),getdate()-1,23);
	end
	else
	begin 
	SET @QCDATE=@day1+' 23:45:00' ;
	SET @QMDATE=@day2+' 23:45:00' ; 
	SET @BDATE=@day1;
	SET @DATE=@day2;
	end 

	declare  @outtb table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBOUT float
)

	declare  @intb table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBIN float
)
	declare  @outtb2 table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBOUT2 float
)

	declare  @intb2 table   --声明表变量
(
DIV nvarchar(60),
ITNBR nvarchar(60),
DBIN2 float
)
 

 insert into @outtb(div,ITNBR,DBOUT)
	SELECT ITGRPCOD3 DIV,ITNBR,SUM(OUTQTY) DBOUT
				 FROM STB0004 
				WHERe CRTIM >= @QCDATE and CRTIM<@QMDATE and FAC=@FAC 
				GROUP BY  ITGRPCOD3,ITNBR;

				insert into @intb(div,ITNBR,DBIN)
				   select DIV,ITNBR ,SUM(QTY) DBIN from STB0014 where
		  CRTIM >= @QCDATE and CRTIM<@QMDATE and YFAC= @FAC and MOVETYPE in ('2','3')  AND YFAC=MFAC
		   group by DIV,ITNBR

	insert into @outtb2(div,ITNBR,DBOUT2)
	select DIV,ITNBR ,SUM(QTY) DBOUT2 from STB0014 where
		   CRTIM >= @QCDATE and CRTIM<@QMDATE and YFAC<>MFAC AND  YFAC=@FAC    and MOVETYPE in ('2','3')  
		   group by DIV,ITNBR

		   	insert into @intb2(div,ITNBR,DBIN2)
				  select DIV,ITNBR,SUM(QTY) DBIN2 from STB0014 where
		   CRTIM >= @QCDATE and CRTIM<@QMDATE and YFAC<>MFAC AND  MFAC=@FAC   and MOVETYPE in ('2','3')  
				GROUP BY  DIV,ITNBR; 

WITH RubberRequire--胶片BOM对应的终炼胶
AS (
 SELECT ParentMatType,ParentMatID,ParentMatEditionNo
     ,SubMatTypeName,SubMatID,EditionNo
     ,ParentMatType GTMatType
     ,ParentMatID GTMatID
     ,ParentMatEditionNo GTEditionNo
 FROM EDD0061 WHERE ParentMatType ='SK'
 UNION ALL
 SELECT A.ParentMatType,A.ParentMatID,A.ParentMatEditionNo
   ,A.SubMatTypeName,A.SubMatID,A.EditionNo
   ,B.GTMatType GTMatType
   ,B.GTMatID GTMatID
   ,B.GTEditionNo GTEditionNo
 FROM EDD0061 A
 INNER JOIN RubberRequire B ON A.ParentMatType=B.SubMatTypeName AND A.ParentMatID=B.SubMatID AND A.ParentMatEditionNo=B.EditionNo
 )   
  SELECT X.ITNBR,T1.ITTYPENAM DIV,[LOCATION],T1.ERPCODE,SAPBOM,T1.ITTYPECOD,@FAC [FAC],@DATE [WDATE],
      WIDTH,Thickness,Density,
	   (CASE WHEN X.DIV IN('CCF') THEN PN*WIDTH/1000.0--[生产入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN PN*WIDTH*Thickness*Density/1000.0--[生产入库]计量单位转换为kg
	                ELSE PN END) RKQTY--[生产入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN STARQTY*WIDTH/1000.0--[期初]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN STARQTY*WIDTH*Thickness*Density/1000.0--[期初]计量单位转换为kg
	                ELSE STARQTY END),1) STARQTY--[期初]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN ENDQTY*WIDTH/1000.0--[期末]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN ENDQTY*WIDTH*Thickness*Density/1000.0--[期末]计量单位转换为kg
	                ELSE ENDQTY END),1) ENDQTY--[期末]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBIN*WIDTH/1000.0--[调拨入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBIN*WIDTH*Thickness*Density/1000.0--[调拨入库]计量单位转换为kg
	                ELSE DBIN END),1) DBIN--[调拨入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBOUT*WIDTH/1000.0--[调拨出库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBOUT*WIDTH*Thickness*Density/1000.0--[调拨出库]计量单位转换为kg
	                ELSE DBOUT END),1) DBOUT--[调拨出库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBIN2*WIDTH/1000.0--[调拨入库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBIN2*WIDTH*Thickness*Density/1000.0--[调拨入库]计量单位转换为kg
	                ELSE DBIN2 END),1) DBIN2--[工区外入库]
	   ,ROUND((CASE WHEN X.DIV IN('CCF') THEN DBOUT2*WIDTH/1000.0--[调拨出库]计量单位转换为平方米
	                WHEN X.DIV IN('TC','SK') THEN DBOUT2*WIDTH*Thickness*Density/1000.0--[调拨出库]计量单位转换为kg
	                ELSE DBOUT2 END),1) DBOUT2--[工区外出库]
	   ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN XN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE XN END),1) XHQTY--[消耗数量]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN FN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE FN END),1) FNQTY--[报废数量]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN CN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE CN END),1) CNQTY--[差值]
       ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN BN*WIDTH*Thickness*Density/1000.0--[消耗数量]计量单位转换为kg
	                ELSE BN END),1) BNQTY--[盘点数量]
	   ,ROUND((CASE WHEN X.DIV IN('TC','SK') THEN otqty*WIDTH*Thickness*Density/1000.0 ELSE otqty END),1) OTQTY--[消耗数量]
	   ,(CASE WHEN X.DIV IN('CCF') THEN '㎡'
	          WHEN X.DIV IN('BD','PTQ','BDR') THEN '对'  
	          WHEN X.DIV IN('TD','TR') THEN '条'
			  WHEN X.DIV IN('TC','SK') THEN 'kg'
			  ELSE 'm' END) UNIT FROM
( SELECT '半成品' [LOCATION],
			(CASE WHEN TBQM.ITNBR IS NOT NULL THEN TBQM.ITNBR WHEN TBRK.AITNBR IS NOT NULL THEN TBRK.AITNBR 
			WHEN TBQC.ITNBR IS NOT NULL THEN TBQC.ITNBR WHEN DB1.ITNBR IS NOT NULL THEN DB1.ITNBR WHEN DB2.ITNBR IS NOT NULL THEN DB2.ITNBR
			WHEN TBXH.ITNBR IS NOT NULL THEN TBXH.ITNBR WHEN TBBF.ITNBR IS NOT NULL THEN TBBF.ITNBR WHEN TBCZ.ITNBR IS NOT NULL THEN TBCZ.ITNBR
			WHEN TBPD.ITNBR IS NOT NULL THEN TBPD.ITNBR END) ITNBR ,
			(CASE WHEN TBQM.DIV IS NOT NULL THEN TBQM.DIV WHEN TBRK.DIV IS NOT NULL THEN TBRK.DIV WHEN TBQC.DIV IS NOT NULL THEN TBQC.DIV 
			WHEN DB1.DIV IS NOT NULL THEN DB1.DIV WHEN DB2.DIV IS NOT NULL THEN DB2.DIV  WHEN TBXH.DIV IS NOT NULL 
			THEN TBXH.DIV WHEN TBBF.DIV IS NOT NULL THEN TBBF.DIV WHEN TBCZ.DIV IS NOT NULL THEN TBCZ.DIV  
			WHEN TBPD.HALFDIV IS NOT NULL THEN TBPD.HALFDIV END) DIV
		   ,STARQTY,PN,ENDQTY, DBIN, DBOUT,XN,FN,CN,BN,DBIN2,DBOUT2,0 otqty
		   FROM
			(SELECT DIV,AITNBR,ROUND(SUM(QTY),2) PN 
			FROM LTC0001
			WHERE AUTIM  >= @QCDATE and AUTIM  <@QMDATE AND FAC =@FAC and isnull(IS_DELETE,0)=0  
			GROUP BY DIV,AITNBR) AS TBRK --0.产出
			full join 
			(SELECT  A1.DIV,A1.ITNBR, 1.0*SUM(CASE  WHEN DIV IN ('CCF','BDR','TR','TC','SK') THEN  SUMQTY  ELSE QTYA+QTYB END) STARQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@BDATE AND A1.FAC =@FAC AND WSHT='3'   AND A1.ITNBR IS NOT NULL AND A1.ITNBR<>'' 
			GROUP BY  A1.DIV,A1.ITNBR)  
			AS TBQC ON TBRK.AITNBR=TBQC.ITNBR AND TBRK.DIV=TBQC.DIV   --1、半成品期初 
			full join
			(SELECT  A1.DIV,A1.ITNBR ,1.0*SUM(CASE  WHEN DIV IN ('CCF','BDR','TR','TC','SK') THEN  SUMQTY  ELSE QTYA+QTYB END) ENDQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD AND A1.ITNBR IS NOT NULL
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@DATE AND A1.FAC =@FAC AND WSHT='3'  AND A1.ITNBR IS NOT NULL   AND A1.ITNBR<>''  
			GROUP BY A1.DIV,A1.ITNBR
			) AS  TBQM ON (TBRK.AITNBR=TBQM.ITNBR AND TBRK.DIV=TBQM.DIV) OR (TBQC.ITNBR=TBQM.ITNBR AND TBQC.DIV=TBQM.DIV) --2、半成品期期末
			FULL JOIN
			(  select * from @intb 
			) DB1 ON (TBRK.AITNBR=DB1.ITNBR AND  TBRK.DIV=DB1.DIV) OR (TBQC.ITNBR=DB1.ITNBR AND  TBQC.DIV=DB1.DIV) 
			OR (TBQM.ITNBR=DB1.ITNBR AND  TBQM.DIV=DB1.DIV)  --3、半成品调拨入库
			FULL JOIN 
			(SELECT *   FROM @outtb  ) DB2 ON (TBRK.AITNBR=DB2.ITNBR AND TBRK.DIV=DB2.DIV) OR (TBQC.ITNBR=DB2.ITNBR AND  TBQC.DIV=DB2.DIV) 
			OR (TBQM.ITNBR=DB2.ITNBR AND  TBQM.DIV=DB2.DIV) OR (DB1.ITNBR=DB2.ITNBR AND  DB1.DIV=DB2.DIV)  --4、半成品调拨出库
			 FULL JOIN 
			 (SELECT * FROM (SELECT (CASE WHEN SubMatTypeName='BDW' THEN 'BDR' ELSE SubMatTypeName END) DIV--BOM消耗的为成品钢丝圈，系统中对成品钢丝圈不管理，消耗钢丝圈（规格代码一样）
			,SubMatID ITNBR
				,SUM(HA*(CASE WHEN SubMatTypeName IN('BDW','TR','SK') THEN CAST(SubMatNum AS numeric)--部件计量单位取条计算消耗量
			                  WHEN SubMatTypeName IN('CCF','TC') THEN CAST(ROUND(PCSCuttingWidth,0) AS int)*CAST(SubMatNum AS numeric)/1000.0--钢帘布/压延胶片BOM消耗取宽度计算平方米
							  ELSE CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0 END)) XN--部件计量单位根据单条长度计算消耗量
				,'' XC--无法计算消耗的lot数
			FROM
				(SELECT FAC,DIV,AUSHT,AITNBR,[VERSION],SUM(QTY) HA FROM LTC0001 WHERE ISNULL(IS_DELETE,0)='0' AND AUTIM >= @QCDATE and AUTIM  <@QMDATE AND FAC=@FAC 
				GROUP BY FAC,DIV,AUSHT,AITNBR,[VERSION]) A1--半成品产量
			INNER JOIN 
				(SELECT ParentMatType,ParentMatID,ParentMatEditionNo,SubMatTypeName,SubMatID,SubMatNum,PCSCuttinglength,PCSCuttingWidth 
				  FROM EDD0061 WHERE SubMatTypeName IN('CCF','BDW','TR','TC','SK')) B1--半成品BOM（只取半成品内部耗用的物料类型）（消耗的物料在范围内）
			ON A1.DIV=B1.ParentMatType AND A1.AITNBR=B1.ParentMatID AND A1.[VERSION]=B1.ParentMatEditionNo 
			GROUP BY SubMatTypeName,SubMatID
			 ) T  ) TBXH ON (TBRK.AITNBR=TBXH.ITNBR AND TBRK.DIV=TBXH.DIV) OR (TBQC.ITNBR=TBXH.ITNBR AND  TBQC.DIV=TBXH.DIV) 
			OR (TBQM.ITNBR=TBXH.ITNBR AND  TBQM.DIV=TBXH.DIV) OR (DB1.ITNBR=TBXH.ITNBR AND  DB1.DIV=TBXH.DIV) 
			 OR (DB2.ITNBR=TBXH.ITNBR AND  DB2.DIV=TBXH.DIV)----5.半成品内部消耗半成品
			 full join
			 (SELECT FAC,DIV,ITNBR,SUM(FN) FN,SUM(FC) FC FROM (SELECT FAC,DIV,ITNBR,1.0*SUM(BQTY) FN,SUM(CASE WHEN REMARK='1' THEN 1 ELSE 0 END) FC FROM QMC0001  
			WHERE CRTIM  >= @QCDATE and crtim<@QMDATE   AND FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN ('10','11')
			GROUP BY FAC,DIV,ITNBR
			union all
			SELECT FAC,DIV,ITNBR,1.0*SUM(BQTY) FN,SUM(CASE WHEN REMARK='1' THEN 1 ELSE 0 END) FC FROM QMC0001  
			WHERE CRTIM  >= @QCDATE and crtim<@QMDATE   AND FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN ('12','13','15') and DIV  IN ('BDR','TR')
			GROUP BY FAC,DIV,ITNBR) TT GROUP BY FAC,DIV,ITNBR
			) TBBF ON (TBRK.AITNBR=TBBF.ITNBR AND TBRK.DIV=TBBF.DIV) OR (TBQC.ITNBR=TBBF.ITNBR AND  TBQC.DIV=TBBF.DIV) 
			OR (TBQM.ITNBR=TBBF.ITNBR AND  TBQM.DIV=TBBF.DIV) OR (DB1.ITNBR=TBBF.ITNBR AND  DB1.DIV=TBBF.DIV) 
			 OR (DB2.ITNBR=TBBF.ITNBR AND  DB2.DIV=TBBF.DIV) OR (TBXH.ITNBR=TBBF.ITNBR AND  TBXH.DIV=TBBF.DIV)---6.半成品报废半成品
			 full join
			 (select sum(CQTY) CN,ITNBR,ATTRIBUTE1 DIV FROM LOTCHANGELOG
			 WHERE ETIM  >= @QCDATE and etim<@QMDATE AND FAC=@FAC and [LOCATION] in('10','11')    AND ATTRIBUTE1 NOT IN ('TR','BDR') GROUP BY ITNBR,ATTRIBUTE1) TBCZ
			  ON (TBRK.AITNBR=TBCZ.ITNBR and TBRK.DIV=TBCZ.DIV) OR (TBQC.ITNBR=TBCZ.ITNBR and TBQC.DIV=TBCZ.DIV ) 
			OR (TBQM.ITNBR=TBCZ.ITNBR and TBQM.DIV=TBCZ.DIV) OR (DB1.ITNBR=TBCZ.ITNBR and DB1.DIV=TBCZ.DIV) 
			 OR (DB2.ITNBR=TBCZ.ITNBR and DB2.DIV=TBCZ.DIV ) OR (TBXH.ITNBR=TBCZ.ITNBR and TBXH.DIV=TBCZ.DIV)
			 OR (TBBF.ITNBR=TBCZ.ITNBR and TBBF.DIV=TBCZ.DIV)---7.差值
			 full join 
			 (	select b.HALFDIV,a.ITNBR, 
			sum(case when a.STA='1' then convert(float,isnull(qty,0)) when a.STA='2' then convert(float,isnull(qty,0))*-1.0 end) BN
			from STA0007 a left join STA0005 b on a.DOCCOD=b.DOCCOD where CONFIRMTIM  >= @QCDATE and CONFIRMTIM  <@QMDATE
			and b.div=2 and a.sta in ('1','2')   AND b.FAC=@FAC
			group by b.HALFDIV,b.DIV,a.ITNBR ) TBPD on (TBRK.AITNBR=TBPD.ITNBR AND TBRK.DIV=TBPD.HALFDIV) OR (TBQC.ITNBR=TBPD.ITNBR AND  TBQC.DIV=TBPD.HALFDIV) 
			OR (TBQM.ITNBR=TBPD.ITNBR AND  TBQM.DIV=TBPD.HALFDIV) OR (DB1.ITNBR=TBPD.ITNBR AND  DB1.DIV=TBPD.HALFDIV) 
			 OR (DB2.ITNBR=TBPD.ITNBR AND  DB2.DIV=TBPD.HALFDIV) OR (TBXH.ITNBR=TBPD.ITNBR AND  TBXH.DIV=TBPD.HALFDIV)
			 OR (TBBF.ITNBR=TBPD.ITNBR AND  TBBF.DIV=TBPD.HALFDIV) OR (TBCZ.ITNBR=TBPD.ITNBR AND  TBCZ.DIV=TBPD.HALFDIV) --8.盘点数据
			 full join 
			 (  select * from @intb2 
			) FDB1 ON (TBRK.AITNBR=FDB1.ITNBR AND TBRK.DIV=FDB1.DIV) OR (TBQC.ITNBR=FDB1.ITNBR AND  TBQC.DIV=FDB1.DIV) 
			OR (TBQM.ITNBR=FDB1.ITNBR AND  TBQM.DIV=FDB1.DIV) OR (DB1.ITNBR=FDB1.ITNBR AND  DB1.DIV=FDB1.DIV) 
			 OR (DB2.ITNBR=FDB1.ITNBR AND  DB2.DIV=FDB1.DIV) OR (TBXH.ITNBR=FDB1.ITNBR AND  TBXH.DIV=FDB1.DIV)
			 OR (TBBF.ITNBR=FDB1.ITNBR AND  TBBF.DIV=FDB1.DIV) OR (TBCZ.ITNBR=FDB1.ITNBR AND  TBCZ.DIV=FDB1.DIV) 
			 OR (TBPD.ITNBR=FDB1.ITNBR AND  TBPD.HALFDIV=FDB1.DIV)  --9、工区外入库
			FULL JOIN 
			(SELECT *   FROM @outtb2  ) FDB2 ON (TBRK.AITNBR=FDB2.ITNBR AND TBRK.DIV=FDB2.DIV) OR (TBQC.ITNBR=FDB2.ITNBR AND  TBQC.DIV=FDB2.DIV) 
			OR (TBQM.ITNBR=FDB2.ITNBR AND  TBQM.DIV=FDB2.DIV) OR (DB1.ITNBR=FDB2.ITNBR AND  DB1.DIV=FDB2.DIV) 
			 OR (DB2.ITNBR=FDB2.ITNBR AND  DB2.DIV=FDB2.DIV) OR (TBXH.ITNBR=FDB2.ITNBR AND  TBXH.DIV=FDB2.DIV)
			 OR (TBBF.ITNBR=FDB2.ITNBR AND  TBBF.DIV=FDB2.DIV) OR (TBCZ.ITNBR=FDB2.ITNBR AND  TBCZ.DIV=FDB2.DIV) 
			 OR (TBPD.ITNBR=FDB2.ITNBR AND  TBPD.HALFDIV=FDB2.DIV)   OR (FDB1.ITNBR=FDB2.ITNBR AND  FDB1.DIV=FDB2.DIV)    --10、工区外出库
			 UNION 
			 SELECT '成型' [LOCATION],
			(CASE WHEN TBQM.ITNBR IS NOT NULL THEN TBQM.ITNBR  
			WHEN TBQC.ITNBR IS NOT NULL THEN TBQC.ITNBR WHEN DB1.ITNBR IS NOT NULL THEN DB1.ITNBR WHEN DB2.ITNBR IS NOT NULL THEN DB2.ITNBR
			WHEN TBXH.ITNBR IS NOT NULL THEN TBXH.ITNBR WHEN TBBF.ITNBR IS NOT NULL THEN TBBF.ITNBR WHEN TBCZ.ITNBR IS NOT NULL THEN TBCZ.ITNBR
		    WHEN TBCXLOG.ITNBR IS NOT NULL THEN TBCXLOG.ITNBR  END) ITNBR ,
			(CASE WHEN TBQM.DIV IS NOT NULL THEN TBQM.DIV WHEN TBQC.DIV IS NOT NULL THEN TBQC.DIV 
			WHEN DB1.DIV IS NOT NULL THEN DB1.DIV WHEN DB2.DIV IS NOT NULL THEN DB2.DIV  WHEN TBXH.DIV IS NOT NULL 
			THEN TBXH.DIV WHEN TBBF.DIV IS NOT NULL THEN TBBF.DIV WHEN TBCZ.DIV IS NOT NULL THEN TBCZ.DIV  
		    WHEN TBCXLOG.DIV IS NOT NULL THEN TBCXLOG.DIV  END) DIV
		   ,STARQTY,0 PN,ENDQTY,DBIN, DBOUT,XN,FN,CN,0 BN,0 DBIN2,0 DBOUT2,CXLOGXN OTQTY
		   FROM
			(SELECT  A1.DIV,A1.ITNBR,  1.0*SUM ( QTYD+QTYC ) STARQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@BDATE AND A1.FAC =@FAC AND WSHT='3'  
			AND A1.ITNBR IS NOT NULL  AND A1.ITNBR<>''   AND DIV NOT IN ('CCF','BDR','TR','TC','SK')  
			GROUP BY  A1.DIV,A1.ITNBR,A1.WSHT)  
			AS TBQC    --1、成型期初 
			full join
			(SELECT  A1.DIV,A1.ITNBR ,1.0*SUM(QTYC+QTYD ) ENDQTY
			FROM RE0001 A1
			LEFT JOIN EDD0003 A2 ON A1.DIV=A2.ITTYPECOD AND A1.ITNBR IS NOT NULL
			WHERE A2.ITGRPCOD='HALF' AND A1.WDATE=@DATE AND A1.FAC =@FAC AND WSHT='3' 
			AND A1.ITNBR IS NOT NULL  AND A1.ITNBR<>''   AND DIV NOT IN ('CCF','BDR','TR','TC','SK')  
			GROUP BY A1.DIV,A1.ITNBR,A1.WSHT
			) AS  TBQM ON   (TBQC.ITNBR=TBQM.ITNBR AND TBQC.DIV=TBQM.DIV) --2、成型期期末
			FULL JOIN
			( select DIV,SUM(QTY) DBOUT,ITNBR from STB0014 where
		   CRTIM  >= @QCDATE and crtim<@QMDATE and YFAC=@FAC   and MOVETYPE in ('2','3')
		   and div NOT IN ('CCF','BDR','TR','TC','SK')  and YFAC=MFAC
		   group by DIV,ITNBR) DB2 ON  (TBQC.ITNBR=DB2.ITNBR AND  TBQC.DIV=DB2.DIV) 
			OR (TBQM.ITNBR=DB2.ITNBR AND  TBQM.DIV=DB2.DIV)  --3、成型调拨出库
			FULL JOIN 
			(SELECT ITGRPCOD3 DIV,ITNBR,SUM(OUTQTY) DBIN
				 FROM STB0004 
				WHERe CRTIM  >= @QCDATE and crtim<@QMDATE and FAC=@FAC   AND ITGRPCOD3 NOT IN ('CCF','BDR','TR','TC','SK')  
				GROUP BY  ITGRPCOD3,ITNBR) DB1 ON   (TBQC.ITNBR=DB1.ITNBR AND  TBQC.DIV=DB1.DIV) 
			OR (TBQM.ITNBR=DB1.ITNBR AND  TBQM.DIV=DB1.DIV) OR ( DB2.ITNBR=DB1.ITNBR AND   DB2.DIV=DB1.DIV)  --4、成型调拨出库
			 FULL JOIN 
			 (SELECT  SubMatTypeName DIV,SubMatID ITNBR
				,SUM(CX*(CASE WHEN SubMatTypeName IN('TD','PTD') THEN CAST(SubMatNum AS numeric) 
    						  WHEN SubMatTypeName IN('BD','PTQ','PD') THEN CAST(SubMatNum AS numeric)/2 --胎圈还要转换，BOM中单位为个，生产单位为对
    						  WHEN SubMatTypeName IN('WG') THEN CAST(ROUND(PCSCuttinglength,0) AS int)* CAST(SubMatNum AS numeric)/1000.0/2 --肩垫卷产出就是两个
						  ELSE CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0 END)) XN--部件计量单位取条或米计算成型消耗量
				,'' XC--无法计算消耗的lot数
			FROM
				(SELECT FAC,BUSHT,BUITNBR,BUVERSION,COUNT(*) CX FROM LTA0001 WHERE ISNULL(IS_DELETE,0)='0' AND BUTIM  >= @QCDATE and butim<@QMDATE AND FAC =@FAC GROUP BY FAC,BUSHT,BUITNBR,BUVERSION) A1--成型产量
			LEFT JOIN 
				(SELECT ParentMatID,ParentMatEditionNo,SubMatTypeName,SubMatID,SubMatNum,PCSCuttinglength FROM EDD0061 WHERE ParentMatType='GT') B1--半成品BOM
			ON A1.BUITNBR=B1.ParentMatID AND A1.BUVERSION=B1.ParentMatEditionNo 
			GROUP BY SubMatTypeName,SubMatID) TBXH ON  (TBQC.ITNBR=TBXH.ITNBR AND  TBQC.DIV=TBXH.DIV) 
			OR (TBQM.ITNBR=TBXH.ITNBR AND  TBQM.DIV=TBXH.DIV) OR (DB1.ITNBR=TBXH.ITNBR AND  DB1.DIV=TBXH.DIV) 
			 OR (DB2.ITNBR=TBXH.ITNBR AND  DB2.DIV=TBXH.DIV) --成型产出消耗半成品
			 full join 
			  (SELECT Q.FAC,Q.DIV,L.AITNBR ITNBR,1.0*SUM(Q.BQTY) FN,SUM(CASE WHEN REMARK=1 THEN 1 ELSE 0 END) FC FROM QMC0001 Q LEFT JOIN LTC0001 L ON Q.LOTID=L.LOTID 
			WHERE Q.crtim >=@QCDATE AND Q.CRTIM<@QMDATE AND Q.FAC=@FAC AND AYN='Y' AND isnull(STKSTS,'12') IN  ('12','13','15') and Q.DIV NOT IN ('BDR','TR')
			GROUP BY Q.FAC,Q.DIV,L.AITNBR) TBBF ON (TBQC.ITNBR=TBBF.ITNBR AND  TBQC.DIV=TBBF.DIV) 
			OR (TBQM.ITNBR=TBBF.ITNBR AND  TBQM.DIV=TBBF.DIV) OR (DB1.ITNBR=TBBF.ITNBR AND  DB1.DIV=TBBF.DIV) 
			 OR (DB2.ITNBR=TBBF.ITNBR AND  DB2.DIV=TBBF.DIV) OR (TBXH.ITNBR=TBBF.ITNBR AND  TBXH.DIV=TBBF.DIV)---6.半成品报废半成品
			 FULL JOIN 
			  (select sum(CQTY) CN,ITNBR,ATTRIBUTE1 DIV FROM LOTCHANGELOG
			 WHERE ETIM  >= @QCDATE and etim<@QMDATE AND FAC=@FAC   and [LOCATION] in('12','13','15')  AND ATTRIBUTE1 NOT IN ('TR','BDR','JL') GROUP BY ITNBR,ATTRIBUTE1) TBCZ
			 ON (TBQC.ITNBR=TBCZ.ITNBR and TBQC.DIV=TBCZ.DIV) OR (TBBF.ITNBR=TBCZ.ITNBR and TBBF.DIV=TBCZ.DIV)
			OR (TBQM.ITNBR=TBCZ.ITNBR and TBQM.DIV=TBCZ.DIV) OR (DB1.ITNBR=TBCZ.ITNBR and DB1.DIV=TBCZ.DIV) 
			 OR (DB2.ITNBR=TBCZ.ITNBR and DB2.DIV=TBCZ.DIV) OR (TBXH.ITNBR=TBCZ.ITNBR and TBXH.DIV=TBCZ.DIV)---7.差值
			  FULL JOIN 
			  (SELECT  SubMatTypeName DIV,SubMatID ITNBR
				,SUM(CXLOG*(CASE WHEN SubMatTypeName IN('TD','PTD') THEN CAST(SubMatNum AS numeric) 
    						  WHEN SubMatTypeName IN('BD','PTQ','PD') THEN CAST(SubMatNum AS numeric)/2 --胎圈还要转换，BOM中单位为个，生产单位为对
    						  WHEN SubMatTypeName IN('WG') THEN CAST(ROUND(PCSCuttinglength,0) AS int)* CAST(SubMatNum AS numeric)/1000.0/2 --肩垫卷产出就是两个
						  ELSE CAST(ROUND(PCSCuttinglength,0) AS int)*CAST(SubMatNum AS numeric)/1000.0 END)) CXLOGXN--部件计量单位取条或米计算成型消耗量
				,'' XC--无法计算消耗的lot数
			FROM
				(SELECT FAC,ITNBR,SUM(DIV) CXLOG FROM GTEDIT_opday WHERE CRTIM  >= @QCDATE and CRTIM<@QMDATE AND FAC =@FAC GROUP BY FAC,ITNBR) A1--成型产量
			LEFT JOIN 
					(select * from 
(SELECT ParentMatID,ROW_NUMBER() over (partition by ParentMatID,SubMatTypeName order by ParentMatEditionNo desc) rw, ParentMatEditionNo,SubMatTypeName,SubMatID,SubMatNum,PCSCuttinglength FROM EDD0061 WHERE ParentMatType='GT' 
				 ) tt where rw=1 ) B1--半成品BOM
			ON A1.ITNBR=B1.ParentMatID  
			GROUP BY SubMatTypeName,SubMatID) TBCXLOG
			 ON (TBQC.ITNBR=TBCXLOG.ITNBR and TBQC.DIV=TBCXLOG.DIV) OR (TBBF.ITNBR=TBCXLOG.ITNBR and TBBF.DIV=TBCXLOG.DIV)
			OR (TBQM.ITNBR=TBCXLOG.ITNBR and TBQM.DIV=TBCXLOG.DIV) OR (DB1.ITNBR=TBCXLOG.ITNBR and DB1.DIV=TBCXLOG.DIV) 
			 OR (DB2.ITNBR=TBCXLOG.ITNBR and DB2.DIV=TBCXLOG.DIV) OR (TBXH.ITNBR=TBCXLOG.ITNBR and TBXH.DIV=TBCXLOG.DIV)
			 OR (TBCZ.ITNBR=TBCXLOG.ITNBR and TBCZ.DIV=TBCXLOG.DIV) ---8.成型当日修改记录
			  ) X  
			 LEFT JOIN --下面是最外面一层的连接
			 (
			   SELECT ITTYPECOD,ITTYPENAM,ITNBR,VERSION,ERPCODE,SAPBOM
					  ,(CASE WHEN A2.ATTRVAL IS NULL THEN PCSCuttingWidth ELSE A2.ATTRVAL END) WIDTH--先从主数据找宽度，如果没有再从BOM中获取
					  ,A4.ATTRVAL Thickness
					  ,A5.ATTRVAL Density
			   FROM (SELECT ID,ITTYPECOD,ITTYPENAM,ITNBR,VERSION,ERPCODE,SAPBOM,ROW_NUMBER() OVER(PARTITION BY ITTYPECOD,ITNBR ORDER BY VERSION DESC) SE FROM EDD0001
					 WHERE ITGRPCOD='HALF' AND SHFLAG='Y') A1--已审核半成品物料主数据
			   LEFT JOIN EDD0002 A2 ON A1.ID=A2.ITEMID AND A2.ATTRCOD='M75'--从物料属性中获取宽度信息
			   LEFT JOIN
			   (
						  SELECT ParentMatType,ParentMatID,ParentMatEditionNo,PCSCuttingWidth
						  FROM
							(SELECT ParentMatType,ParentMatID,PCSCuttingWidth,ParentMatEditionNo
							       ,ROW_NUMBER() OVER(PARTITION BY ParentMatType,ParentMatID,ParentMatEditionNo ORDER BY ParentMatEditionNo DESC) SE 
						     FROM EDD0061
							 WHERE SubMatTypeName IN('CCF','PSC','PFC')) A1--从BOM中获取宽度信息,前提为BOM中宽度为产出物料的宽度
						  WHERE SE=1
			   ) A3 ON A1.ITTYPECOD=A3.ParentMatType AND A1.ITNBR=A3.ParentMatID AND A1.VERSION=A3.ParentMatEditionNo
			   LEFT JOIN EDD0002 A4 ON A1.ID=A4.ITEMID AND A4.ATTRCOD='M76'--从物料属性中获取厚度信息
			   LEFT JOIN
			   (
			             SELECT A51.*,A52.ATTRVAL FROM
						 (
			             SELECT DISTINCT GTMatType,GTMatID,GTEditionNo,SubMatID FROM RubberRequire WHERE SubMatTypeName='JL'--获取全钢胶片关联的终炼胶
						 UNION
						 SELECT DISTINCT ParentMatType,ParentMatID,ParentMatEditionNo,SubMatID FROM EDD0061 WHERE ParentMatType IN ('TC')--获取全钢压延胶片关联的终炼胶
						 ) A51
						 LEFT JOIN
						 (
						 SELECT SPEC,VERSION,ERPCODE,ROW_NUMBER() OVER(PARTITION BY ITTYPECOD,SPEC ORDER BY VERSION DESC) SE,ATTRVAL FROM EDD0001 A521
					     LEFT JOIN EDD0002 A522 ON A521.ID=A522.ITEMID
					     WHERE ITTYPECOD='JL' AND SHFLAG='Y' AND A522.ATTRCOD='M82'
						 ) A52 ON A51.SubMatID=A52.SPEC AND SE=1--获取每胶种的最新密度值
			   ) A5 ON A1.ITTYPECOD=A5.GTMatType AND A1.ITNBR=A5.GTMatID AND A1.VERSION=A5.GTEditionNo--获取全钢胶片及压延胶片关联的终炼胶密度
			   WHERE SE=1--取已审核主数据最新版本
		   ) T1  ON X.DIV=T1.ITTYPECOD AND X.ITNBR=T1.ITNBR--因报废及结算库存表中无物料规格版本，所以只能取最新版本关联，无版本关联
		   ORDER BY ITNBR

END
GO


-- ----------------------------
-- procedure structure for Barcode_Collection
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Barcode_Collection]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Barcode_Collection]
GO

CREATE PROCEDURE [dbo].[Barcode_Collection]
(
	@FAC   NVARCHAR(5),			--工厂
	@MCHID NVARCHAR(30),		--机台号
	@BARCODE NVARCHAR(30),		--条码
	@BUITNBR NVARCHAR(50),		--成型规格代码
	@BUITDSC NVARCHAR(100),		--成型规格名称
	@BUVERSION NVARCHAR(5),		--成型版本号
	@BUSHT NVARCHAR(5),			--成型班次
	@BUBAN NVARCHAR(5),			--成型班组
	@STATE NVARCHAR(10),		--状态
	@BUDAT NVARCHAR(10),		--成型日期
	@BUTIM DATETIME,			--成型时间
	@BUNAM NVARCHAR(10),		--成型操作人
	@BUNAMCOD NVARCHAR(30),		--成型操作人工号
	@BUCOTCOD NVARCHAR(50),		--施工表编号\8
	@SPEC NVARCHAR(20),			--SPEC号
	@BUPLANCOD NVARCHAR(50),	--成型工单号
	@DIV NVARCHAR(2),			--在库位置
	@OPDIV NVARCHAR(10),		--操作类型
	@NAM NVARCHAR(10),			--当前登录人
	@LOGINNAME NVARCHAR(20),	--当前登录人工号
	@MSG NVARCHAR(500),			--操作内容
	@REMARK NVARCHAR(100)			--补录原因
)
AS 
BEGIN

	declare @boi nvarchar(2);
	set @boi='';
	SELECT @boi=ATTRVAL FROM  EDC0011 WHERE ITEMID IN (SELECT ID FROM EDC0001 WHERE MCHID=@MCHID) and ATTRCOD='L12'
	--成型生产追溯LTA0001
	INSERT INTO LTA0001(FAC,BARCODE,BUMCH,BUITNBR,BUITDSC,BUVERSION,BUSHT,BUBAN,STATE,BUDAT,BUTIM,BUNAM,
	BUNAMCOD,BUCOTCOD,SPEC,BUPLANCOD,CRTIM,IS_DELETE,NORMALSTA,TYRENO,BOI)
    VALUES	(@FAC,@BARCODE,@MCHID,@BUITNBR,@BUITDSC,@BUVERSION,@BUSHT,@BUBAN, @STATE,@BUDAT,@BUTIM,@BUNAM,
    @BUNAMCOD,@BUCOTCOD,@SPEC,@BUPLANCOD,GETDATE(),'0','N',@BARCODE,@boi);
    
    --胎坯库存WIP0002
	IF NOT EXISTS(select top 1 * from WIP0002 where BARCODE=@BARCODE)
	BEGIN
		INSERT INTO WIP0002 (FAC,MCHID,WSHT,WBAN,BARCODE,ITNBR,ITDSC,ENAM, LOGINNAM,WDATE,WTIME,STIME,ETIME,
	DIV,VERSION,CRTIM,SPEC) 
	VALUES(@FAC,@MCHID,@BUSHT,@BUBAN,@BARCODE,@BUITNBR,@BUITDSC,@BUNAM,@BUNAMCOD,@BUDAT,@BUTIM,@BUTIM,@BUTIM,
	@DIV,@BUVERSION,GETDATE(),@SPEC);
	END
	
	--生产调整履历LT_OPERATE
	INSERT INTO LT_OPERATE (FAC,BARCODE,OPDIV,ENAM,LOGINNAM,CRTIM,MSG,BEFORITNBR,TYRENO,NORMALSTA,REMARK) 
	VALUES (@FAC,@BARCODE,@OPDIV,@NAM,@LOGINNAME,GETDATE(),@MSG,'','','M',@REMARK);
	
	--成型实绩信息IF_WMS_GT_02
	--INSERT INTO ifdb.[PLMESINTERFACE].dbo.IF_WMS_GT_02(
	--ID,BARCODE,MCHID,SPEC,ITNBR,ITDSC,WDATE,WTIME,WSHT,WBAN,USERID,PRIOOUTYN,GTSTATUS,RCV_FLAG,
	--ENT_USER_ID,ENT_DT,EDITYN)
	--VALUES(NEWID(),@BARCODE,@MCHID,@SPEC,@BUITNBR,@BUITDSC,@BUDAT,@BUTIM,@BUSHT,@BUBAN,@LOGINNAME,'N','N','N',
	--@NAM,GETDATE(),'N');
END
GO


-- ----------------------------
-- procedure structure for InsPlan_LH_GC
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[InsPlan_LH_GC]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[InsPlan_LH_GC]
GO

CREATE PROCEDURE [dbo].[InsPlan_LH_GC]
--计划导入
(

	@MCHID NVARCHAR(30),		--机台号

	@WDATE DATETIME,			--计划日期

	@ITNBR NVARCHAR(50),		--规格代码

	@ITDSC NVARCHAR(80),		--规格名称

	@LR NVARCHAR(1),			--左右机台

	@PLQTYA INT,				--早班计划量

	@PLQTYB INT,				--中班计划量

	@PLQTYC INT,				--晚班计划量

	@ENAM NVARCHAR(20),			--修改人

	@STQTY1 INT,				--定额1

	@STQTY2 INT,				--定额2

	@STQTY3 INT,				 --定额3

    @SEQ INT					 --计划顺序

)

AS 

BEGIN

	DECLARE @FAC NVARCHAR(10),						--工厂代码 

			@ORDERNO NVARCHAR(20),					--工单号,

