			@COLORLINE2 NVARCHAR(50),				--色线2

			@SPEC NVARCHAR(20),						--胎胚SPEC号

			@GreenTyreMaterialID NVARCHAR(50),		--轮胎胎胚规格代码

			@SubMatEditionNo NVARCHAR(10),			--胎胚规格版本

