		WHERE ITNBR=@ITNBR AND ITGRPCOD='FERT'  AND VERSION=@VERSION



	--获取色线 

		SELECT TOP 1 @BUITDSC=ITDSC,@GreenTyreMaterialID=ITNBR,@SubMatEditionNo=VERSION FROM  EDD0001  

		WHERE SPEC=@BUITNBR AND CLASSDIV='工程胎'  AND ITGRPCOD='GT' ORDER BY CONVERT(INT,VERSION) DESC

		

