-- ----------------------------
-- procedure structure for pro_SettleWip_half
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pro_SettleWip_half]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pro_SettleWip_half]
GO

CREATE PROCEDURE [dbo].[pro_SettleWip_half]
AS
BEGIN
	declare @nowtime datetime
	declare @wdate date
	declare @wsht nvarchar(3)
	 
	SELECT @nowtime=dateadd(hh,-1,getdate())
	declare @shifttb table(WDATE DATE,SHT nvarchar(20),NSHT nvarchar(20),BAN nvarchar(20),STIME DATETIME,ETIME DATETIME,SHTNAM nvarchar(20),NSHTNAM nvarchar(20))

	insert into @shifttb 
	EXEC  GetShiftByTime @nowtime
	--取得上个班的班次和日期
	select @wsht=sht,@wdate=WDATE from @shifttb
	--先删除结算
	delete RE0001 WHERE WDATE=@wdate  and WSHT=@wsht AND DIV<>'GT'
	-- WIP0001半成品库存结算
	declare @fac nvarchar(3) declare @div nvarchar(10) declare @itnbr nvarchar(50) declare @itdsc nvarchar(100) declare @lotcnt nvarchar(20) declare @CARTYPE nvarchar(20)     
	declare @sumqty  nvarchar(20) declare @lota nvarchar(20) declare @lotb nvarchar(20) declare @lotc nvarchar(20) declare @lotd nvarchar(20)
	declare @lot1 nvarchar(20) declare @lot2 nvarchar(20) declare @lot3 nvarchar(20) declare @lot4 nvarchar(20)  declare @lot5 nvarchar(20) 
	declare @qty1 nvarchar(20) declare @qty2 nvarchar(20) declare @qty3 nvarchar(20) declare @qty4 nvarchar(20)  declare @qty5 nvarchar(20) 
	declare @qtya nvarchar(20) declare @qtyb nvarchar(20) declare @qtyc nvarchar(20) declare @qtyd nvarchar(20) ,@qtye nvarchar(20) ,@qtyf nvarchar(20) ,@spec nvarchar(20),@lote nvarchar(20),@lotf nvarchar(20),@qtyg nvarchar(20),@lotg nvarchar(20)
	declare wip01_cursor cursor for  SELECT w.FAC,w.DIV,w.ITNBR,w.ITDSC, COUNT(w.LOTID) LOTCNT,SUM(w.QTY) SUMQTY ,
                          COUNT(CASE WHEN l.ASTATE= '1' THEN 1 END)AS LOT1, 
                          COUNT(CASE WHEN l.ASTATE= '2' THEN 1 END)AS LOT2, 
                          COUNT(CASE WHEN l.ASTATE ='3' THEN 1 END)AS LOT3, 
                          COUNT(CASE WHEN l.ASTATE= '4' THEN 1 END)AS LOT4, 
                          COUNT(CASE WHEN l.ASTATE= '5' THEN 1 END)AS LOT5,  
                          ISNULL(SUM(CASE WHEN l.ASTATE= '1' THEN w.QTY END),0) AS QTY1, 
                          ISNULL(SUM(CASE WHEN l.ASTATE= '2' THEN w.QTY END),0) AS QTY2 ,
                          ISNULL(SUM(CASE WHEN l.ASTATE='3' THEN w.QTY END),0) AS QTY3,
                          ISNULL(SUM(CASE WHEN l.ASTATE= '4' THEN w.QTY END ),0) AS QTY4 ,
                          ISNULL(SUM(CASE WHEN l.ASTATE= '5' THEN w.QTY END),0) AS QTY5, 
                          COUNT(CASE WHEN w.STKSTS= '10' THEN 1 END)AS LOTA, 
                          COUNT(CASE WHEN w.STKSTS= '11' THEN 1 END)AS LOTB, 
                          COUNT(CASE WHEN w.STKSTS in ('12','13') THEN 1 END)AS LOTC, 
                          COUNT(CASE WHEN w.STKSTS= '15' THEN 1 END)AS LOTD, 
                          COUNT(CASE WHEN w.STA in ('1','6') THEN 1 END)AS LOTE, 
                          COUNT(CASE WHEN w.STA not in ('1','6','4') THEN 1 END)AS LOTF, 
                          COUNT(CASE WHEN w.STA='4' THEN 1 END)AS LOTG, 
                          ISNULL(SUM(CASE WHEN w.STKSTS= '10' THEN w.QTY END),0) AS QTYA, 
                          ISNULL(SUM(CASE WHEN w.STKSTS= '11' THEN w.QTY END),0) AS QTYB,
                          ISNULL(SUM(CASE WHEN w.STKSTS in ('12','13') THEN w.QTY END),0) AS QTYC,
                          ISNULL(SUM(CASE WHEN w.STKSTS= '15' THEN w.QTY END ),0) AS QTYD ,
                          ISNULL(SUM(CASE WHEN w.STA   in ('1','6') THEN w.QTY END),0) AS QTYE,
                          ISNULL(SUM(CASE WHEN w.STA not in ('1','6','4') THEN w.QTY END ),0) AS QTYF ,
                          ISNULL(SUM(CASE WHEN w.STA='4' THEN w.QTY END ),0) AS QTYG ,
						  case when isnull(CARTYPE,'')='' then 0 else CARTYPE  end CARTYPE
						  --CARTYPE
						  FROM WIP0001 w inner join LTC0001 l on w.LOTID=l.LOTID WHERE  ISNULL(w.IS_DELETE,0)=0 and ITNBR<>'' and w.QTY>0 GROUP BY w.FAC,w.DIV,w.ITNBR,w.ITDSC 
						  ,case when isnull(CARTYPE,'')='' then 0 else CARTYPE  end
						  --,CARTYPE
	  --打开游标--
    open wip01_cursor
    --开始循环游标变量--
    fetch next from wip01_cursor into @fac,@div,@itnbr,@itdsc,@lotcnt, @sumqty,@qty1,@qty2,@qty3,@qty4,@qty5,@lot1,@lot2,@lot3,@lot4,@lot5,@lota,@lotb,@lotc,@lotd,@lote,@lotf,@lotg,@qtya,@qtyb,@qtyc,@qtyd,@qtye,@qtyf,@qtyg,@CARTYPE
    while @@FETCH_STATUS = 0    --返回被 FETCH语句执行的最后游标的状态--
        begin            
             insert into RE0001(WDATE,WSHT,SUMQTY,ITNBR,ITDSC,QTY,FAC,DIV,LOTA,LOTB,LOTC,LOTD,LOTE,LOTF,LOTG,QTYA,QTYB,QTYC,QTYD,QTYE,QTYF,QTYG,QTY1,QTY2,QTY3,QTY4,QTY5,LOT1,LOT2,LOT3,LOT4,LOT5,CARTYPE)
			 VALUES
			 (@wdate,@wsht,@sumqty,@itnbr,@itdsc,@lotcnt,@fac,@div,@lota,@lotb,@lotc,@lotd,@lote,@lotf,@lotg,@qtya,@qtyb,@qtyc,@qtyd,@qtye,@qtyf,@qtyg,@qty1,@qty2,@qty3,@qty4,@qty5,@lot1,@lot2,@lot3,@lot4,@lot5,@CARTYPE)
             fetch next from wip01_cursor into @fac,@div,@itnbr,@itdsc,@lotcnt, @sumqty,@qty1,@qty2,@qty3,@qty4,@qty5,@lot1,@lot2,@lot3,@lot4,@lot5,@lota,@lotb,@lotc,@lotd,@lote,@lotf,@lotg,@qtya,@qtyb,@qtyc,@qtyd,@qtye,@qtyf,@qtyg,@CARTYPE --转到下一个游标，没有会死循环
        end   
    close wip01_cursor  --关闭游标
    deallocate wip01_cursor   --释放游标
 
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	 
END
GO


-- ----------------------------
-- procedure structure for proMiLianKuCunDanBan
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proMiLianKuCunDanBan]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proMiLianKuCunDanBan]
GO

CREATE PROCEDURE [dbo].[proMiLianKuCunDanBan]
(
		@ITTYPECOD									NVARCHAR(50),--'XL'，小料.'JL',终练
		@WDATE										DATETIME=NULL
)
AS
BEGIN
	SELECT @wdate = ISNULL(@wdate, GETDATE());
	DECLARE @tiQianMi													INT=0; -- dbo.gettiqianMi(),
	DECLARE @wTDate														datetime=DATEADD(mi, @tiQianMi, @wdate);
	DECLARE @WSHT														INT=dbo.GetBanCi(@wdate);
	
	SELECT --SUM(A.CHECODE) as sumCHECODE,
			sum(A.WT) as sumWT
		--'N' XZ,
		--A.* ,
		--B.JGRDREMARK	,
		--B.USEINGWAY,
		--ISNULL( C.EXPTIM, 0 ) - DATEDIFF( HOUR, A.WTIME, GETDATE( ) ) TimCount 
	FROM WIP0003 A with(nolock)
	LEFT JOIN LTD0001 B with(nolock)
	ON A.lotid  = B.lotid
	LEFT JOIN (SELECT ITNBR,
					CYCLTIM,
					EXPTIM,
					ITTYPECOD,
					ROW_NUMBER ( ) OVER ( partition BY ITNBR ORDER BY version DESC ) rw 
				FROM EDD0001 
				WHERE ITGRPCOD = 'MX' 
	) C 
	ON A.ITNBR= C.ITNBR 
	AND C.rw= 1 
	WHERE ISNULL( A.IS_DELETE, 0 ) = 0 
	AND a.WSHT=@WSHT
	AND A.LOC = '02' 
	AND C.ITTYPECOD = @ITTYPECOD	
	--AND A.ITNBR LIKE '%#%'
END
GO


-- ----------------------------
-- procedure structure for proBanChengPinJiHuaDaChengLv1
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proBanChengPinJiHuaDaChengLv1]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proBanChengPinJiHuaDaChengLv1]
GO

CREATE PROCEDURE [dbo].[proBanChengPinJiHuaDaChengLv1]
(
		@FACList																nvarchar(50),
		@OUTTYPECODList															nvarchar(1000), -- 胎面、胎侧、胎体、内衬层、带束层、胎圈
		@WDATE																	DATETIME=NULL
)
AS
BEGIN
	SELECT @wdate = ISNULL(@wdate, GETDATE());
	DECLARE @tiQianMi													INT=0; -- dbo.gettiqianMi(),
	DECLARE @wTDate														datetime=DATEADD(mi, @tiQianMi, @wdate);
	DECLARE @WSHT														INT=dbo.GetBanCi(@wdate);
	
	select t.OUTTYPECOD, 
			tedd0003.ITTYPENAM,
			isnull(SUM(LTC.qty),0) as SUM_MESQTY, -- 产量
		   SUM(LTC.qty)/nullif(SUM(t.PLQTY),0) as jiHuaDaChengLv, --计划达成率
		   case 
		   when t.OUTTYPECOD in ('BD','PTQ') then
				N'对'
		   when t.OUTTYPECOD in ('TD') then
				N'条'
		   else
				N'米'
			end as danwei --单位
	from LTC0001 LTC with(nolock)
    left join PAD0201_HALF t with(nolock) on LTC.ORDERNO = t.PLANCOD
	left join EDD0003 tedd0003 with(nolock)
	on t.OUTTYPECOD=tedd0003.ITTYPECOD
	where LTC.FAC in (SELECT [VALUE]
					from string_split(@FACList,','))
	AND convert(date,LTC.AUTIM) = convert(date,@wdate)
	AND LTC.AUSHT =@WSHT
	AND t.OUTTYPECOD in (SELECT [VALUE]
						   from string_split(@OUTTYPECODList,','))
	group by t.OUTTYPECOD,
			tedd0003.ITTYPENAM
END
GO


-- ----------------------------
-- function structure for IsNum
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[IsNum]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[IsNum]
GO

CREATE FUNCTION [dbo].[IsNum]
(
	@valStr										NVARCHAR(100) --要对其判断的字符串
)
RETURNS INT
WITH SCHEMABINDING
AS 
BEGIN 
	DECLARE @isNUM								INT=ISNUMERIC(@valStr)
	IF(@isNUM=0)
	BEGIN
		RETURN @isNUM
	END
	-- PATINDEX('%[^0-9|.|-|+]%','2.2') == 0 ，从 https://www.cnblogs.com/2296bbs/p/12551423.html 抄的
	IF(PATINDEX('%[^0-9|.|-|+]%',@valStr)<>0)
	BEGIN
		SELECT @isNUM=0
	END
	RETURN  @isNUM
END
GO


-- ----------------------------
-- function structure for ConvertToDecimal
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ConvertToDecimal]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ConvertToDecimal]
GO

CREATE FUNCTION [dbo].[ConvertToDecimal]
(
	@valStr										NVARCHAR(100) --要对其判断的字符串
)
RETURNS DECIMAL(18,6)
WITH SCHEMABINDING
AS 
BEGIN 
	DECLARE @decVal								DECIMAL(18,6)
	IF([dbo].IsNum(@valStr)=1)
	BEGIN
		SELECT @decVal = CONVERT(DECIMAL(18,6),@valStr)
	END

	RETURN  @decVal
END
GO


-- ----------------------------
-- procedure structure for proSyncQMA1001
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proSyncQMA1001]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proSyncQMA1001]
GO

CREATE PROCEDURE [dbo].[proSyncQMA1001]
(
		@ITEM												NVARCHAR(50)=N'内周长',
		@FAC												NVARCHAR(100) = N'02'
  --      @DATE2												DATETIME = '2022/11/29 0:00:00',
  --      @DATE1												DATETIME='2000/2/17 0:00:00',
  --      @DIV												NVARCHAR(100)='%0209%',
		--@MchId												NVARCHAR(100)='',
		--@ITNBR												NVARCHAR(100)='',
		--@xiangMu											NVARCHAR(100)='',
)
AS
BEGIN
	DECLARE	@TableName											NVARCHAR(50)='QMA1001',
			@DbName												NVARCHAR(50)= 'PLMES',
		--@computerStartDate									DATETIME='2000-1-1',
		--@computerEndDate									DATETIME='2999-1-1';--,
		--@minGroupItemCount									INT=5;
			@PLCTAG												NVARCHAR(50)=N'内周长';
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	WITH mainData as (
	SELECT t.[FAC]
		  ,t.[MCHID]
		  ,t.[ITNBR]
		  ,t.[ITDSC]
		  ,t.[WTIME]
		  ,t.[WDATE]
		  ,t.[WSHT]
		  ,t.[WBAN]
		  ,t.[QMA1001Id]
		  ,t.[EDA0004Id]
		  ,t.[QMA1002Id]
		  ,t.[QMA1000Id]
		  ,t.ITEMCODE
		  ,t.DIV
		  ,t.ATTRIBUTE2
		  ,ct.SYS_CHANGE_VERSION
		  ,ct.SYS_CHANGE_CREATION_VERSION
		  ,ct.SYS_CHANGE_OPERATION
		  ,ct.SYS_CHANGE_COLUMNS
		  ,ct.SYS_CHANGE_CONTEXT
	FROM VQMA1001 t WITH(NOLOCK)
	INNER JOIN CHANGETABLE(CHANGES dbo.QMA1001,0) ct
	ON t.QMA1001Id = ct.ID
	UNION ALL
	SELECT t.[FAC]
		  ,t.[MCHID]
		  ,t.[ITNBR]
		  ,t.[ITDSC]
		  ,t.[WTIME]
		  ,t.[WDATE]
		  ,t.[WSHT]
		  ,t.[WBAN]
		  ,t.[QMA1001Id]
		  ,t.[EDA0004Id]
		  ,t.[QMA1002Id]
		  ,t.[QMA1000Id]
		  ,t.ITEMCODE
		  ,t.DIV
		  ,t.ATTRIBUTE2
		  ,ct.SYS_CHANGE_VERSION
		  ,ct.SYS_CHANGE_CREATION_VERSION
		  ,ct.SYS_CHANGE_OPERATION
		  ,ct.SYS_CHANGE_COLUMNS
		  ,ct.SYS_CHANGE_CONTEXT
	FROM VQMA1001 t WITH(NOLOCK)
	INNER JOIN CHANGETABLE(CHANGES dbo.EDA0004,0) ct
	ON t.EDA0004Id=ct.ID
	UNION ALL
	SELECT t.[FAC]
		  ,t.[MCHID]
		  ,t.[ITNBR]
		  ,t.[ITDSC]
		  ,t.[WTIME]
		  ,t.[WDATE]
		  ,t.[WSHT]
		  ,t.[WBAN]
		  ,t.[QMA1001Id]
		  ,t.[EDA0004Id]
		  ,t.[QMA1002Id]
		  ,t.[QMA1000Id]
		  ,t.ITEMCODE
		  ,t.DIV
		  ,t.ATTRIBUTE2
		  ,ct.SYS_CHANGE_VERSION
		  ,ct.SYS_CHANGE_CREATION_VERSION
		  ,ct.SYS_CHANGE_OPERATION
		  ,ct.SYS_CHANGE_COLUMNS
		  ,ct.SYS_CHANGE_CONTEXT
	FROM VQMA1001 t WITH(NOLOCK)
	INNER JOIN CHANGETABLE(CHANGES dbo.QMA1002,0) ct
	ON t.QMA1002Id = ct.ID
	UNION ALL
	SELECT t.[FAC]
		  ,t.[MCHID]
		  ,t.[ITNBR]
		  ,t.[ITDSC]
		  ,t.[WTIME]
		  ,t.[WDATE]
		  ,t.[WSHT]
		  ,t.[WBAN]
		  ,t.[QMA1001Id]
		  ,t.[EDA0004Id]
		  ,t.[QMA1002Id]
		  ,t.[QMA1000Id]
		  ,t.ITEMCODE
		  ,t.DIV
		  ,t.ATTRIBUTE2
		  ,ct.SYS_CHANGE_VERSION
		  ,ct.SYS_CHANGE_CREATION_VERSION
		  ,ct.SYS_CHANGE_OPERATION
		  ,ct.SYS_CHANGE_COLUMNS
		  ,ct.SYS_CHANGE_CONTEXT
	FROM VQMA1001 t WITH(NOLOCK)
	INNER JOIN CHANGETABLE(CHANGES dbo.QMA1000,0) ct
	ON  t.QMA1000Id = ct.ID) 
	select t.* 
	INTO #mainData
	FROM mainData t 
	CROSS APPLY (SELECT TOP 1 *
				   FROM RCBDB003.PrinxQualityBigDataNew.dbo.T_Basic_chanxian2zhibiao tz WITH(NOLOCK)
				  WHERE tz.Code=@ITEM) tzb
	WHERE t.ITEMCODE = tzb.ITEMCODE
	AND t.DIV = 'ProcessQuality'
	AND t.ATTRIBUTE2 = 'HALF'
	AND t.FAC = @FAC;

	DELETE FROM RCBDB003.PrinxQualityBigDataNew.dbo.Source_GYMAIN
	WHERE [TableName] =@TableName
	  and [DbName] = @DbName
	  AND ID in (SELECT CONVERT(NVARCHAR(100),td.QMA1001Id)
					FROM #mainData td
				   WHERE td.SYS_CHANGE_OPERATION in ('D','I','U'))
	DELETE FROM RCBDB003.PrinxQualityBigDataNew.dbo.Source_GYITEM
	WHERE [TableName] = @TableName
	  and [DbName] = @DbName
		and MID in (SELECT CONVERT(NVARCHAR(100),td.QMA1001Id)
					 FROM #mainData td
				    WHERE td.SYS_CHANGE_OPERATION in ('D','I','U'))

	INsert into RCBDB003.PrinxQualityBigDataNew.dbo.Source_GYITEM
	(
			[MID]
			 ,[ITEM]
			 ,[PLCTAG]
			 ,[VAL]
			 ,[TableName]
			 ,[DbName]
			 ,[Year]
	)
	SELECT [QMA1001Id],
			@ITEM as ITEM,
			@PLCTAG as PLCTAG,
			VAL,
		  @TableName as TableName,
		  @DbName as DbName,
		  2022 AS [Year]
	  FROM #mainData t with(nolock)
	WHERE t.SYS_CHANGE_OPERATION in ('I')
	
	 INSERT into RCBDB003.PrinxQualityBigDataNew.dbo.Source_GYMAIN
			   ([ID]
			   ,[FAC]
			   ,[MCHID]
			   ,[ITNBR]
			   ,[ITDSC]
			   ,[WTIME]
			   ,[WDATE]
			   ,[WSHT]
			   ,[WBAN]
			   ,[TableName]
			   ,[DbName]
			   ,[Year])		   
	SELECT [QMA1001Id]
				,[FAC]
		  ,[MCHID]
		  ,[ITNBR]
		  ,[ITDSC]
		  ,[WTIME]
		  ,[WDATE]
		  ,[WSHT]
		  ,[WBAN]
		  ,@TableName as TableName
		  ,@DbName as DbName
		  ,2022
	FROM #mainData t with(nolock)
	WHERE t.SYS_CHANGE_OPERATION in ('I')

	DROP TABLE #mainData
END
GO


-- ----------------------------
-- procedure structure for sp_upgraddiagrams
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_upgraddiagrams]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_upgraddiagrams]
GO

CREATE PROCEDURE [dbo].[sp_upgraddiagrams]
	AS
	BEGIN
		IF OBJECT_ID(N'dbo.sysdiagrams') IS NOT NULL
			return 0;
	
		CREATE TABLE dbo.sysdiagrams
		(
			name sysname NOT NULL,
			principal_id int NOT NULL,	-- we may change it to varbinary(85)
			diagram_id int PRIMARY KEY IDENTITY,
			version int,
	
			definition varbinary(max)
			CONSTRAINT UK_principal_name UNIQUE
			(
				principal_id,
				name
			)
		);


		/* Add this if we need to have some form of extended properties for diagrams */
		/*
		IF OBJECT_ID(N'dbo.sysdiagram_properties') IS NULL
		BEGIN
			CREATE TABLE dbo.sysdiagram_properties
			(
				diagram_id int,
				name sysname,
				value varbinary(max) NOT NULL
			)
		END
		*/

		IF OBJECT_ID(N'dbo.dtproperties') IS NOT NULL
		begin
			insert into dbo.sysdiagrams
			(
				[name],
				[principal_id],
				[version],
				[definition]
			)
			select	 
				convert(sysname, dgnm.[uvalue]),
				DATABASE_PRINCIPAL_ID(N'dbo'),			-- will change to the sid of sa
				0,							-- zero for old format, dgdef.[version],
				dgdef.[lvalue]
			from dbo.[dtproperties] dgnm
				inner join dbo.[dtproperties] dggd on dggd.[property] = 'DtgSchemaGUID' and dggd.[objectid] = dgnm.[objectid]	
				inner join dbo.[dtproperties] dgdef on dgdef.[property] = 'DtgSchemaDATA' and dgdef.[objectid] = dgnm.[objectid]
				
			where dgnm.[property] = 'DtgSchemaNAME' and dggd.[uvalue] like N'_EA3E6268-D998-11CE-9454-00AA00A3F36E_' 
			return 2;
		end
		return 1;
	END
GO


-- ----------------------------
-- procedure structure for sp_qc_alarm_scraprepair
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_qc_alarm_scraprepair]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_qc_alarm_scraprepair]
GO

CREATE PROCEDURE [dbo].[sp_qc_alarm_scraprepair]
@FAC nvarchar(10), @BCOD nvarchar(20), @BNAM nvarchar(50), @RESULT nvarchar(10), @BARCODE nvarchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间
   DECLARE @ITNBR   NVARCHAR (50)                                     --规格代码
   DECLARE @ITDSC   NVARCHAR (100)                                    --规格名称
   DECLARE @DEPNAM   NVARCHAR (20)                                      --缺陷部门
   DECLARE @CUMCHID NVARCHAR (10)                                        --设备号
   DECLARE @LR nvarchar(1)                                              --左右
   DECLARE @RULECODE nvarchar(10)                                         --预警规则代码
   DECLARE @RULENAME nvarchar(100)                                         --预警规则描述
   DECLARE @BUMCHID NVARCHAR (10)                                        --设备号
   --DECLARE @LEVLCODE nvarchar(50)                                         --预警等级代码
   
   --获取当前时间的班次开始时间和班次结束时间
   --声明一个表用于获取班次信息
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;
   --若不良代码为空，则返回
   IF (@BCOD = '' or @BCOD is null)
     RETURN
   --基于不良代码获取其预警规则
   SELECT @RULECODE = ATTRIBUTE2 FROM QMA0006_DD WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','));
   --若规则代码为空，则返回
   IF (@RULECODE = '' or @RULECODE is null)
     RETURN
     
   DECLARE @BADCNT   INT
   DECLARE @ALMCNT   INT
   DECLARE @BARCODE_S NVARCHAR(MAX)
   
   IF @RULECODE = 'LH'--若规则是：同一硫化规格
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.SCRAPREPAIR, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB
                        LEFT JOIN LTA0001 LTA ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W1','W2')) BADCNT
                  LEFT JOIN (SELECT SCRAPREPAIR
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
        END
   IF @RULECODE = 'LHMJ'--若规则是：同一硫化规格，同一模具（机台）
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.SCRAPREPAIR, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB
                        LEFT JOIN LTA0001 LTA ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W1','W2')) BADCNT
                  LEFT JOIN (SELECT SCRAPREPAIR
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CX'
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一成型规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.SCRAPREPAIR, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB
                        LEFT JOIN LTA0001 LTA ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W1','W2')) BADCNT
                  LEFT JOIN (SELECT SCRAPREPAIR
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.SCRAPREPAIR, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB
                        LEFT JOIN LTA0001 LTA ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W1','W2')) BADCNT
                  LEFT JOIN (SELECT SCRAPREPAIR
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXGGJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH,@ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型规格+机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.SCRAPREPAIR, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB
                        LEFT JOIN LTA0001 LTA ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W1','W2')) BADCNT
                  LEFT JOIN (SELECT SCRAPREPAIR
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'MJ'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.SCRAPREPAIR, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB
                        LEFT JOIN LTA0001 LTA ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W1','W2')) BADCNT
                  LEFT JOIN (SELECT SCRAPREPAIR
                             FROM QMA0006_DD
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   --若报警标准数量为0或空，则返回
   IF @ALMCNT = 0
     RETURN
   --获取预警规则描述
   SELECT @RULENAME=DNAM FROM  EDA0004 WHERE DIV = 'ALARM_RULE_PCR' AND DCOD =@RULECODE
   --获取缺陷部门
   SELECT @DEPNAM = DEPNAM FROM QMB0012 WHERE BARCODE = @BARCODE
   --若缺陷数超过了报警标准数量，则继续
   IF @BADCNT >= @ALMCNT AND @DEPNAM!='' AND @DEPNAM!='无责任部门' AND @DEPNAM IS NOT NULL
      BEGIN
               --各字段不能是null，转换为空
               IF @DEPNAM IS NULL
                BEGIN
                  SET @DEPNAM =''
                END
               IF @CUMCHID IS NULL
                BEGIN
                  SET @CUMCHID =''
                END
               IF @LR IS NULL
                BEGIN
                  SET @LR =''
                END    
               IF @ITNBR IS NULL
                BEGIN
                  SET @ITNBR =''
                END    
               IF @ITDSC IS NULL
                BEGIN
                  SET @ITDSC =''
                END      
               IF @BUMCHID IS NULL
                BEGIN
                  SET @BUMCHID =''
                END     
				
				IF @BARCODE_S IS NULL
                BEGIN
                  SET @BARCODE_S =''
                END    

				IF @BARCODE IS NULL
                BEGIN
                  SET @BARCODE =''
                END    

               INSERT INTO SJC0003_PCR (FAC,
                                        CHKDIV,
                                        DIV,
                                        MCHID,
                                        LR,
                                        WDATE,
                                        WSHT,
                                        ITNBR,
                                        ITDSC,
                                        BCOD,
                                        BNAM,
                                        CONTENT,
                                        TXNTIME,
                                        HDFLAG,
                                        HDTIM,
                                        BUMCH,
                                        BARCODES,
                                        NOW_BARCODE)
               VALUES (@FAC,
                       'VI',
                       @DEPNAM,
                       @CUMCHID,
                       @LR,
                       @WDATE,
                       @SHT,
                       @ITNBR,
                       @ITDSC,
                       @BCOD,
                       @BNAM,
                       '['+@RULENAME+']废次品和修理品达到了' + CONVERT(NVARCHAR(10),@BADCNT) + '条',
                       GETDATE (),
                       'N',
                       NULL,
                       @BUMCHID,
                       @BARCODE_S,
                       @BARCODE);
      END
END
GO


-- ----------------------------
-- procedure structure for Proc_WIP0032_BK
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Proc_WIP0032_BK]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Proc_WIP0032_BK]
GO

CREATE PROCEDURE [dbo].[Proc_WIP0032_BK]
(
@ID NVARCHAR(80), --待操作Id
@userid NVARCHAR(80),
@username NVARCHAR(80)
)
AS
BEGIN  
    BEGIN TRANSACTION;
	BEGIN TRY	
		if not exists(select top 10 * from wip0032 w  inner join WIP0030 w1 on w1.ORGID = w.OLDID where w.ID =@ID)
		begin
		   select '原卷已不在投料队列，禁止回退'
		   return 0
		end
		--修改队列wip0030数据
		update w1 set w1.REMQTY=w1.REMQTY +w2.CJQTY from WIP0030 w1
		inner join WIP0032 w2 on w1.ORGID= w2.OLDID and w2.ID=@ID
		--修改wip0001数据
			--原卷
			update w1 set w1.QTY=w1.QTY +w2.CJQTY from WIP0001 w1
			inner join WIP0032 w2 on w1.ID= w2.OLDID and w2.ID=@ID;
			--新卷
			update w1 set w1.QTY=w1.QTY -w2.CJQTY from WIP0001 w1
			inner join WIP0032 w2 on w1.ID= w2.NEWJID and w2.ID=@ID;
			--若数量为零，删除新卷数据
			if exists(select 1 from WIP0001 w1 inner join WIP0032 w2 on w1.ID= w2.NEWJID and w2.ID=@ID where (w1.QTY -w2.CJQTY)=0 )
			begin
				delete from  WIP0001 where id=(select NEWJID from WIP0032 w2 where w2.ID=@ID  )
			end

		--修改wip0032数据
		update WIP0032 set  IS_BCAK=1,BKNAME=@username,BKLOGNAME=@userid,BKTIME=GETDATE() where ID=@ID		
		-- 提交事务
		COMMIT TRANSACTION;
		select  '1';
	END TRY
	BEGIN CATCH
	  
		-- 回滚事务
		IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;
		SELECT  ERROR_MESSAGE();
	    SELECT  ERROR_SEVERITY();
	    SELECT  ERROR_STATE();    
        select  '0';		
	END CATCH;

END
GO


-- ----------------------------
-- procedure structure for sp_qc_alarm_scrappolished
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_qc_alarm_scrappolished]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_qc_alarm_scrappolished]
GO

CREATE PROCEDURE [dbo].[sp_qc_alarm_scrappolished]
@FAC nvarchar(10), @BCOD nvarchar(20), @BNAM nvarchar(50), @RESULT nvarchar(10), @BARCODE nvarchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间
   DECLARE @ITNBR   NVARCHAR (50)                                     --规格代码
   DECLARE @ITDSC   NVARCHAR (100)                                    --规格名称
   DECLARE @DEPNAM   NVARCHAR (20)                                      --缺陷部门
   DECLARE @CUMCHID NVARCHAR (10)                                        --设备号
   DECLARE @LR nvarchar(1)                                              --左右
   DECLARE @RULECODE nvarchar(10)                                         --预警规则代码
   DECLARE @RULENAME nvarchar(100)                                         --预警规则描述
   DECLARE @BUMCHID NVARCHAR (10)                                        --设备号
   --DECLARE @LEVLCODE nvarchar(50)                                         --预警等级代码
   
   --获取当前时间的班次开始时间和班次结束时间
   --声明一个表用于获取班次信息
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;
   --若不良代码为空，则返回
   IF (@BCOD = '' or @BCOD is null)
     RETURN
   --基于不良代码获取其预警规则
   SELECT @RULECODE = ATTRIBUTE2 FROM QMA0006_DD WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','));
   --若规则代码为空，则返回
   IF (@RULECODE = '' or @RULECODE is null)
     RETURN
     
   DECLARE @BADCNT   INT
   DECLARE @ALMCNT   INT
   DECLARE @BARCODE_S NVARCHAR(MAX)
   
   IF @RULECODE = 'LH'--若规则是：同一硫化规格
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.SCRAPPOLISHED, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W3')) BADCNT
                  LEFT JOIN (SELECT SCRAPPOLISHED
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
        END
   IF @RULECODE = 'LHMJ'--若规则是：同一硫化规格，同一模具（机台）
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.SCRAPPOLISHED, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W3')) BADCNT
                  LEFT JOIN (SELECT SCRAPPOLISHED
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CX'
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一成型规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.SCRAPPOLISHED, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W3')) BADCNT
                  LEFT JOIN (SELECT SCRAPPOLISHED
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.SCRAPPOLISHED, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W3')) BADCNT
                  LEFT JOIN (SELECT SCRAPPOLISHED
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXGGJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH,@ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型规格+机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.SCRAPPOLISHED, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W3')) BADCNT
                  LEFT JOIN (SELECT SCRAPPOLISHED
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'MJ'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.SCRAPPOLISHED, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3','W3')) BADCNT
                  LEFT JOIN (SELECT SCRAPPOLISHED
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   --若报警标准数量为0或空，则返回
   IF @ALMCNT = 0
     RETURN
   --获取预警规则描述
   SELECT @RULENAME=DNAM FROM  EDA0004 WHERE DIV = 'ALARM_RULE_PCR' AND DCOD =@RULECODE
   --获取缺陷部门
   SELECT @DEPNAM = DEPNAM FROM QMB0012 WHERE BARCODE = @BARCODE
   --若缺陷数超过了报警标准数量，则继续
   IF @BADCNT >= @ALMCNT AND @DEPNAM!='' AND @DEPNAM!='无责任部门' AND @DEPNAM IS NOT NULL
      BEGIN
               --各字段不能是null，转换为空
               IF @DEPNAM IS NULL
                BEGIN
                  SET @DEPNAM =''
                END
               IF @CUMCHID IS NULL
                BEGIN
                  SET @CUMCHID =''
                END
               IF @LR IS NULL
                BEGIN
                  SET @LR =''
                END    
               IF @ITNBR IS NULL
                BEGIN
                  SET @ITNBR =''
                END    
               IF @ITDSC IS NULL
                BEGIN
                  SET @ITDSC =''
                END      
               IF @BUMCHID IS NULL
                BEGIN
                  SET @BUMCHID =''
                END     
				
				IF @BARCODE_S IS NULL
                BEGIN
                  SET @BARCODE_S =''
                END    

				IF @BARCODE IS NULL
                BEGIN
                  SET @BARCODE =''
                END    

               INSERT INTO SJC0003_PCR (FAC,
                                        CHKDIV,
                                        DIV,
                                        MCHID,
                                        LR,
                                        WDATE,
                                        WSHT,
                                        ITNBR,
                                        ITDSC,
                                        BCOD,
                                        BNAM,
                                        CONTENT,
                                        TXNTIME,
                                        HDFLAG,
                                        HDTIM,
                                        BUMCH,
                                        BARCODES,
                                        NOW_BARCODE)
               VALUES (@FAC,
                       'VI',
                       @DEPNAM,
                       @CUMCHID,
                       @LR,
                       @WDATE,
                       @SHT,
                       @ITNBR,
                       @ITDSC,
                       @BCOD,
                       @BNAM,
                       '['+@RULENAME+']废次品和打磨品达到了' + CONVERT(NVARCHAR(10),@BADCNT) + '条',
                       GETDATE (),
                       'N',
                       NULL,
                       @BUMCHID,
                       @BARCODE_S,
                       @BARCODE);
      END
END
GO


-- ----------------------------
-- procedure structure for sp_helpdiagrams
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_helpdiagrams]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_helpdiagrams]
GO

CREATE PROCEDURE [dbo].[sp_helpdiagrams]
	(
		@diagramname sysname = NULL,
		@owner_id int = NULL
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		DECLARE @user sysname
		DECLARE @dboLogin bit
		EXECUTE AS CALLER;
			SET @user = USER_NAME();
			SET @dboLogin = CONVERT(bit,IS_MEMBER('db_owner'));
		REVERT;
		SELECT
			[Database] = DB_NAME(),
			[Name] = name,
			[ID] = diagram_id,
			[Owner] = USER_NAME(principal_id),
			[OwnerID] = principal_id
		FROM
			sysdiagrams
		WHERE
			(@dboLogin = 1 OR USER_NAME(principal_id) = @user) AND
			(@diagramname IS NULL OR name = @diagramname) AND
			(@owner_id IS NULL OR principal_id = @owner_id)
		ORDER BY
			4, 5, 1
	END
GO


-- ----------------------------
-- procedure structure for GetShift
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetShift]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetShift]
GO

CREATE PROCEDURE [dbo].[GetShift] 


as
declare @dTime datetime;
declare @STime datetime;
declare @ETime datetime;
declare @DateN datetime;
set @dTime=getdate();
set @DateN=getdate();
set @STime=getdate();
set @ETime=getdate();
declare @sht varchar(10);
declare @nsht varchar(10);
declare @ban varchar(10);
DECLARE @starb NVARCHAR(3);
SELECT @starb=e.WTIMSTART
FROM
	EDB0001 AS e
SET @sht='1';
SET @ban='A';
DECLARE @WDATE DATETIME, @SHT1 CHAR(1),@SHT2 CHAR(1),@SHT3 CHAR(1),@DT1 DATETIME,@DT2 DATETIME,@DT3 DATETIME  
declare cursor_edb03 CURSOR SCROLL FOR SELECT WDATE,SHT1,SHT2,SHT3,TIM1,TIM2,TIM3 FROM EDB0003 WHERE WDATE BETWEEN @dTime-1 and @dTime+1 and fac='03' ORDER BY WDATE 
open cursor_edb03   
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
WHILE(@@FETCH_STATUS=0)
BEGIN 
		if(@dTime >= @DT1 and @dTime < @DT2)
		begin 
		   set @sht = '1' ;
		   set @nsht = '2' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT1;
		   set @STime = @DT1;
		   SET @ETime = DATEADD(Second,-1,@DT2);
		END 
		if(@dTime >= @DT2 and @dTime < @DT3 )
		begin 
		   set @sht = '2' ;
		   set @nsht = '3' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT2;
		   set @STime = @DT2;  
		   SET @ETime = DATEADD(Second,-1,@DT3);
		END  
		if(@dTime >= @DT3  )
		begin 
		   set @sht = '3' ;
		   set @nsht = '1' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT3;
		   set @STime = @DT3;
		   SET @ETime = DATEADD(Second,-1,@DT1);
		end    
		IF(@sht=3 AND @stime<@DT1 AND @ETime<@STime)
		BEGIN 
		   SET @ETime = DATEADD(Second,-1,@DT1);
		END      
  
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
END


CLOSE cursor_edb03
deallocate cursor_edb03  

SELECT @DateN WDATE,@sht SHT,@nsht NSHT,@ban BAN,@STime STIME,@ETime ETIME,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac='03' AND dcod=@sht) SHTNAM,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac='03' AND dcod=@Nsht) NSHTNAM
GO


-- ----------------------------
-- procedure structure for sp_qc_alarm_polishedrepair
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_qc_alarm_polishedrepair]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_qc_alarm_polishedrepair]
GO

CREATE PROCEDURE [dbo].[sp_qc_alarm_polishedrepair]
@FAC nvarchar(10), @BCOD nvarchar(20), @BNAM nvarchar(50), @RESULT nvarchar(10), @BARCODE nvarchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间
   DECLARE @ITNBR   NVARCHAR (50)                                     --规格代码
   DECLARE @ITDSC   NVARCHAR (100)                                    --规格名称
   DECLARE @DEPNAM   NVARCHAR (20)                                      --缺陷部门
   DECLARE @CUMCHID NVARCHAR (10)                                        --设备号
   DECLARE @LR nvarchar(1)                                              --左右
   DECLARE @RULECODE nvarchar(10)                                         --预警规则代码
   DECLARE @RULENAME nvarchar(100)                                         --预警规则描述
   DECLARE @BUMCHID NVARCHAR (10)                                        --设备号
   --DECLARE @LEVLCODE nvarchar(50)                                         --预警等级代码
   
   --获取当前时间的班次开始时间和班次结束时间
   --声明一个表用于获取班次信息
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;
   --若不良代码为空，则返回
   IF (@BCOD = '' or @BCOD is null)
     RETURN
   --基于不良代码获取其预警规则
   SELECT @RULECODE = ATTRIBUTE2 FROM QMA0006_DD with(nolock) WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','));
   --若规则代码为空，则返回
   IF (@RULECODE = '' or @RULECODE is null)
     RETURN
     
   DECLARE @BADCNT   INT
   DECLARE @ALMCNT   INT
   DECLARE @BARCODE_S NVARCHAR(MAX)
   
   IF @RULECODE = 'LH'--若规则是：同一硫化规格
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.POLISHEDREPAIR, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2','W3')) BADCNT
                  LEFT JOIN (SELECT POLISHEDREPAIR
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
        END
   IF @RULECODE = 'LHMJ'--若规则是：同一硫化规格，同一模具（机台）
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.POLISHEDREPAIR, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2','W3')) BADCNT
                  LEFT JOIN (SELECT POLISHEDREPAIR
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CX'
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一成型规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.POLISHEDREPAIR, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2','W3')) BADCNT
                  LEFT JOIN (SELECT POLISHEDREPAIR
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.POLISHEDREPAIR, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2','W3')) BADCNT
                  LEFT JOIN (SELECT POLISHEDREPAIR
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXGGJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH,@ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型规格+机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.POLISHEDREPAIR, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2','W3')) BADCNT
                  LEFT JOIN (SELECT POLISHEDREPAIR
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'MJ'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.POLISHEDREPAIR, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('W1','W2','W3')) BADCNT
                  LEFT JOIN (SELECT POLISHEDREPAIR
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   --若报警标准数量为0或空，则返回
   IF @ALMCNT = 0
     RETURN
   --获取预警规则描述
   SELECT @RULENAME=DNAM FROM  EDA0004 WHERE DIV = 'ALARM_RULE_PCR' AND DCOD =@RULECODE
   --获取缺陷部门
   SELECT @DEPNAM = DEPNAM FROM QMB0012 WHERE BARCODE = @BARCODE
   --若缺陷数超过了报警标准数量，则继续
   IF @BADCNT >= @ALMCNT AND @DEPNAM!='' AND @DEPNAM!='无责任部门' AND @DEPNAM IS NOT NULL
      BEGIN
               --各字段不能是null，转换为空
               IF @DEPNAM IS NULL
                BEGIN
                  SET @DEPNAM =''
                END
               IF @CUMCHID IS NULL
                BEGIN
                  SET @CUMCHID =''
                END
               IF @LR IS NULL
                BEGIN
                  SET @LR =''
                END    
               IF @ITNBR IS NULL
                BEGIN
                  SET @ITNBR =''
                END    
               IF @ITDSC IS NULL
                BEGIN
                  SET @ITDSC =''
                END      
               IF @BUMCHID IS NULL
                BEGIN
                  SET @BUMCHID =''
                END     
				
				IF @BARCODE_S IS NULL
                BEGIN
                  SET @BARCODE_S =''
                END    

				IF @BARCODE IS NULL
                BEGIN
                  SET @BARCODE =''
                END    

               INSERT INTO SJC0003_PCR (FAC,
                                        CHKDIV,
                                        DIV,
                                        MCHID,
                                        LR,
                                        WDATE,
                                        WSHT,
                                        ITNBR,
                                        ITDSC,
                                        BCOD,
                                        BNAM,
                                        CONTENT,
                                        TXNTIME,
                                        HDFLAG,
                                        HDTIM,
                                        BUMCH,
                                        BARCODES,
                                        NOW_BARCODE)
               VALUES (@FAC,
                       'VI',
                       @DEPNAM,
                       @CUMCHID,
                       @LR,
                       @WDATE,
                       @SHT,
                       @ITNBR,
                       @ITDSC,
                       @BCOD,
                       @BNAM,
                       '['+@RULENAME+']打磨品和修理品达到了' + CONVERT(NVARCHAR(10),@BADCNT) + '条',
                       GETDATE (),
                       'N',
                       NULL,
                       @BUMCHID,
                       @BARCODE_S,
                       @BARCODE);
      END
END
GO


-- ----------------------------
-- function structure for SplitString
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SplitString]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SplitString]
GO

CREATE FUNCTION [dbo].[SplitString]
(
    @Input NVARCHAR(MAX),
    @Delimiter CHAR(1)
)
RETURNS @OutputTable TABLE (Item NVARCHAR(MAX))
AS
BEGIN
    DECLARE @Start INT, @End INT
    SET @Start = 1
    SET @End = CHARINDEX(@Delimiter, @Input)

    WHILE @Start < LEN(@Input) + 1 BEGIN
        IF @End = 0  
            SET @End = LEN(@Input) + 1

        INSERT INTO @OutputTable (Item)  
        VALUES(SUBSTRING(@Input, @Start, @End - @Start))

        SET @Start = @End + 1
        SET @End = CHARINDEX(@Delimiter, @Input, @Start)
    END
    RETURN
END
GO


-- ----------------------------
-- procedure structure for SETQCWIP0003
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SETQCWIP0003]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SETQCWIP0003]
GO

CREATE PROCEDURE [dbo].[SETQCWIP0003] 
AS
BEGIN
--	 merge into WIP0003 W
--USING(

----SELECT A.ITNBR,A.LOTID,DATEDIFF(HOUR,A.WTIME,GETDATE()) NOWTIM,A.WTIME,
----CASE WHEN DATEDIFF(HOUR,A.WTIME,GETDATE())>EXPTIM then 2
----when DATEDIFF(HOUR,A.WTIME,GETDATE()) < CYCLTIM then 4
----when DATEDIFF(HOUR,A.WTIME,GETDATE()) >= CYCLTIM and DATEDIFF(HOUR,A.WTIME,GETDATE()) <= exptim then 1 end STATUS
----FROM WIP0003 A LEFT JOIN (select ITNBR,CYCLTIM,EXPTIM ,ROW_NUMBER() over (partition by ITNBR order by right ('0000000000'+[VERSION],10) desc) rw from EDD0001 where ITTYPECOD='JL' AND SHFLAG='Y'  ) B --AND ISNULL(CYCLTIM,0)<>0 AND ISNULL(EXPTIM,0)<>0
----ON A.ITNBR=B.ITNBR AND B.rw=1
----WHERE ISNULL(A.IS_DELETE,0)=0 AND A.DIV='JL' and isnull(A.status,0)<>6

----2023-02-17 加入母炼胶判定
--SELECT A.ITNBR,A.LOTID,DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60 NOWTIM,A.WTIME,
--CASE WHEN DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60>EXPTIM then 2
--when DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60 < CYCLTIM then 4
--when DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60 >= CYCLTIM and DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60 <= exptim then 1 end STATUS
--FROM WIP0003 A LEFT JOIN (select ITNBR,CYCLTIM,EXPTIM,ITTYPECOD ,ROW_NUMBER() over (partition by ITNBR,ITTYPECOD order by right ('0000000000'+[VERSION],10) desc)
--rw from EDD0001 where ITTYPECOD in ('JL','ML','SL','XL') AND SHFLAG='Y'  ) B --AND ISNULL(CYCLTIM,0)<>0 AND ISNULL(EXPTIM,0)<>0
--ON A.ITNBR=B.ITNBR AND A.DIV=B.ITTYPECOD AND B.rw=1
--WHERE ISNULL(A.IS_DELETE,'0')='0' AND A.DIV IN ('JL','ML','SL','XL') and isnull(A.status,'0') in ('1','2','4','0')
--) T1
--ON W.LOTID=T1.LOTID AND   ISNULL(W.STATUS,0)<>ISNULL(T1.STATUS,0)
--WHEN MATCHED THEN 
--UPDATE SET  STATUS=T1.STATUS ;


SET NOCOUNT ON;

-- 开启循环更新
WHILE 1 = 1
BEGIN
    -- 每次只更新 2000 条，减少锁持有时间
    ;WITH UpdateData AS (
        SELECT TOP (2000) W.LOTID, T1.STATUS
        FROM WIP0003 W
        INNER JOIN (
            SELECT A.ITNBR, A.LOTID, 
                   DATEDIFF(MINUTE, A.WTIME, GETDATE()) * 1.0 / 60 AS NOWTIM, 
                   A.WTIME,
                   CASE 
                       WHEN DATEDIFF(MINUTE, A.WTIME, GETDATE()) * 1.0 / 60 > EXPTIM THEN 2
                       WHEN DATEDIFF(MINUTE, A.WTIME, GETDATE()) * 1.0 / 60 < CYCLTIM THEN 4
                       WHEN DATEDIFF(MINUTE, A.WTIME, GETDATE()) * 1.0 / 60 >= CYCLTIM AND DATEDIFF(MINUTE, A.WTIME, GETDATE()) * 1.0 / 60 <= EXPTIM THEN 1 
                   END AS STATUS
            FROM WIP0003 A 
            LEFT JOIN (
                SELECT ITNBR, CYCLTIM, EXPTIM, ITTYPECOD, 
                       ROW_NUMBER() OVER (PARTITION BY ITNBR, ITTYPECOD ORDER BY RIGHT('0000000000' + [VERSION], 10) DESC) AS rw 
                FROM EDD0001 
                WHERE ITTYPECOD IN ('JL','ML','SL','XL') AND SHFLAG = 'Y'
            ) B ON A.ITNBR = B.ITNBR AND A.DIV = B.ITTYPECOD AND B.rw = 1
            WHERE ISNULL(A.IS_DELETE, '0') = '0' 
              AND A.DIV IN ('JL','ML','SL','XL') 
              AND ISNULL(A.STATUS, '0') IN ('1','2','4','0')
        ) T1 ON W.LOTID = T1.LOTID
        WHERE ISNULL(W.STATUS, 0) <> ISNULL(T1.STATUS, 0)
    )
    UPDATE W
    SET W.STATUS = UpdateData.STATUS
    FROM WIP0003 W
    INNER JOIN UpdateData ON W.LOTID = UpdateData.LOTID;

    -- 如果没有更新任何行，退出循环
    IF @@ROWCOUNT = 0 BREAK;

    -- 稍微等待一下，释放资源给其他线程
    WAITFOR DELAY '00:00:01'; 
END

END
GO


-- ----------------------------
-- procedure structure for sp_helpdiagramdefinition
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_helpdiagramdefinition]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_helpdiagramdefinition]
GO

CREATE PROCEDURE [dbo].[sp_helpdiagramdefinition]
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname;
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId ))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end

		select version, definition FROM dbo.sysdiagrams where diagram_id = @DiagId ; 
		return 0
	END
GO


-- ----------------------------
-- procedure structure for sp_creatediagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_creatediagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_creatediagram]
GO

CREATE PROCEDURE [dbo].[sp_creatediagram]
	(
		@diagramname 	sysname,
		@owner_id		int	= null, 	
		@version 		int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId int
		declare @retval int
		declare @IsDbo	int
		declare @userName sysname
		if(@version is null or @diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID(); 
		select @IsDbo = IS_MEMBER(N'db_owner');
		revert; 
		
		if @owner_id is null
		begin
			select @owner_id = @theId;
		end
		else
		begin
			if @theId <> @owner_id
			begin
				if @IsDbo = 0
				begin
					RAISERROR (N'E_INVALIDARG', 16, 1);
					return -1
				end
				select @theId = @owner_id
			end
		end
		-- next 2 line only for test, will be removed after define name unique
		if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end
	
		insert into dbo.sysdiagrams(name, principal_id , version, definition)
				VALUES(@diagramname, @theId, @version, @definition) ;
		
		select @retval = @@IDENTITY 
		return @retval
	END
GO


-- ----------------------------
-- procedure structure for pr_gettire_sort_PCR_KJ
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pr_gettire_sort_PCR_KJ]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pr_gettire_sort_PCR_KJ]
GO

CREATE PROCEDURE [dbo].[pr_gettire_sort_PCR_KJ]
@barcode varchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   --设置事务为读
   SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

   DECLARE
      @itnbr       VARCHAR (50),
      @itdsc       VARCHAR (80),
      @is_hold     CHAR (1),
      @is_trial    CHAR (1),
      @is_xray     CHAR (1),
      @is_sds      CHAR (1),
      @is_recheck  CHAR (1),
      @is_freeinsp CHAR (1),
      @ub_mchine   VARCHAR (255),
      @prior_mch   VARCHAR (255),
      @cnt         INT,
      @cnt_prior   INT,
      @ufyn        CHAR (1),
      @dbyn        CHAR (1),
      @mchid       VARCHAR (20),
      @mchid_p     VARCHAR (20),
      
      @recheck_rule VARCHAR(2),
      @recheck_rule_val INT,
      @recheck_no  VARCHAR(30),
      @xray_rule   VARCHAR(2),
	  --@xray_rule_val INT,
      @xray_rule_val FLOAT,
      @sds_rule   VARCHAR(2),
      @sds_rule_val INT

   SET @itnbr = ''
   SET @itdsc = ''
   SET @is_hold = ''
   SET @is_trial = ''
   SET @is_xray = 'N'--默认不X光
   SET @is_sds = 'N'--默认不SDS
   SET @is_recheck = 'N'--默认不复检
   SET @is_freeinsp = 'N'--默认非免检
   SET @ub_mchine = ''
   SET @prior_mch = ''

   SET @cnt = 0
   SET @cnt_prior = 0
   SET @mchid = ''
   SET @ufyn = ''
   SET @dbyn = ''
   SET @mchid_p = ''
   SET @recheck_no = ''

   --获取条码信息
   SELECT TOP 1
          @itnbr = TB.MATERIALID,
          @itdsc = TB.MATERIALNAME,
          @is_trial =
             CASE WHEN (ISNULL (LT.CUSTATE, '') = '2' OR ISNULL (LT.ATTRIBUTE2, '') = 'Y')
                        THEN 'Y' ELSE 'N' END,
          @is_hold = ISNULL (WIP.LOCKYN, N'N')
   FROM tb_PP_CuringOutPut AS TB
        LEFT OUTER JOIN LTA0001 AS LT ON TB.TYRENO = LT.TYRENO
        LEFT OUTER JOIN WIP0010 AS WIP ON TB.TYRENO = WIP.TYRENO
   WHERE TB.TYRENO = @barcode

   --判断能去哪个UB机
   SELECT A.MCHID,
          A.LNUM,
          B.RIMNO,
          A.UFYN,
          A.DBYN
   INTO #TEMP_T1
   FROM CKA0003 A, QMB0203 B
   WHERE     A.MCHID = B.MCHID
         AND A.LNUM = B.RIMNO
         AND B.MCHID NOT IN ('02DJ001',
                             '02DJ002',
                             '02DJ003',
                             '02DJ004')                        --老区动均设备不参与自动分拣
         AND A.ITNBR = @itnbr


   SELECT @cnt = count (1) FROM #TEMP_T1

   IF @cnt > 0
      BEGIN
         DECLARE
            cur_temp1 CURSOR FOR SELECT MCHID, UFYN, DBYN FROM #TEMP_T1

         OPEN cur_temp1
         FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn

         WHILE @@FETCH_STATUS = 0
         BEGIN
            --若均匀性和动平衡为N,则为免检
            IF (@ufyn = 'N' AND @dbyn = 'N')
               BEGIN
                  SET @ub_mchine = ''
                  SET @is_freeinsp = 'Y'
                  BREAK
               END
            ELSE
               BEGIN
                  SET @ub_mchine = @ub_mchine + @mchid + ','
               END

            FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn        --下一个
         END

         IF @ub_mchine ! = ''
            BEGIN
               SET @ub_mchine = LEFT (@ub_mchine, LEN (@ub_mchine) - 1)
            END

         CLOSE cur_temp1
         DEALLOCATE cur_temp1
      END

   --设备优先.
   IF (@ub_mchine ! = '' AND @ub_mchine ! = 'NONE')
      BEGIN
         --SELECT DISTINCT MCHID
         --INTO #TEMP_T2
         --FROM CKA0004
         --WHERE itnbr = @itnbr AND ONEYN = 'Y'
         
        SELECT DISTINCT C1.MCHID INTO #TEMP_T2 FROM CKA0003 C1 LEFT JOIN CKA0004 C2
        ON C1.MCHID=C2.MCHID AND C1.TCOD=C2.TCOD AND C1.ITNBR=C2.ITNBR 
        WHERE C1.ITNBR=@itnbr AND C2.ONEYN = 'Y'

        SELECT @cnt_prior = count (1) FROM #TEMP_T2

         IF @cnt_prior > 0
            BEGIN
               DECLARE
                  cur_temp2 CURSOR FOR SELECT MCHID FROM #TEMP_T2

               OPEN cur_temp2
               FETCH NEXT FROM cur_temp2   INTO @mchid_p

               WHILE @@FETCH_STATUS = 0
               BEGIN
                  SET @prior_mch = @prior_mch + @mchid_p + ','
                  FETCH NEXT FROM cur_temp2   INTO @mchid_p              --下一个
               END

               IF @prior_mch ! = ''
                  BEGIN
                     SET @prior_mch = LEFT (@prior_mch, LEN (@prior_mch) - 1)
                  END

               CLOSE cur_temp2
               DEALLOCATE cur_temp2
            END
        DROP TABLE #TEMP_T2
      END

   --删除临时表
   DROP TABLE #TEMP_T1
   
   --判断是否复检,X光,SDS
   IF (@itnbr!='' and @itnbr is not null)
     BEGIN
      DECLARE @rchk_cnt_per INT,
              @rchk_sum_cnt INT,
              @xray_cnt_per INT,
              @xray_sum_cnt INT,
              @sds_cnt_per INT,
              @sds_sum_cnt INT
      --根据规格获取分拣策略
      SELECT @recheck_rule=RECHECK_RULE,
             @recheck_rule_val=RECHECK_RULE_VAL,
             @recheck_no=RECHECK_NO,
             @xray_rule = XRAY_RULE,
             @xray_rule_val = XRAY_RULE_VAL,
             @sds_rule = SDS_RULE,
             @sds_rule_val = SDS_RULE_VAL
             FROM CKA0006
             WHERE  ITNBR = @itnbr
             
      --判断复检口
      IF @recheck_rule = '0'--若规则是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
            SET @is_recheck = 'Y'
        END
      IF @recheck_rule = '2'--若规则是不检
        BEGIN
          SET @is_recheck = 'N'
          SET @recheck_no = ''
        END
      IF @recheck_rule = '1' --若规则是抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,1,0,0)
          ELSE
            UPDATE CKA0060 SET RECHECKSUMQTY = RECHECKSUMQTY+1 WHERE ITNBR = @itnbr
          SET @rchk_cnt_per = round(100/cast(@recheck_rule_val as float),0)--获取每多少个检测一个（复检）
          SELECT @rchk_sum_cnt = RECHECKSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
                SET @is_recheck = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_recheck = 'N'
              SET @recheck_no = ''
            END
        END
        
      --判断X光
      IF @xray_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
            SET @is_xray = 'Y'
        END
      IF @xray_rule = '2'--若不检
        BEGIN
          SET @is_xray = 'N'
        END
      IF @xray_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,1,0)
          ELSE
            UPDATE CKA0060 SET XRAYSUMQTY = XRAYSUMQTY+1 WHERE ITNBR = @itnbr
          SET @xray_cnt_per = round(100/cast(@xray_rule_val as float),0)--获取每多少个检测一个（X光）
          SELECT @xray_sum_cnt = XRAYSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@xray_sum_cnt % @xray_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
                SET @is_xray = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_xray = 'N'
            END
          --若物流调用记录中已存在<不冻结>并且<分X光>，则代表物流线由于某些原因（主要是X光道口满）上次没分X光，则之后不再分往X光。2021-10-01 质检车间要求
          IF EXISTS(SELECT BARCODE FROM CKA0009 WHERE BARCODE = @barcode AND IS_HOLD = 'N' AND IS_XRAY = 'Y')
            BEGIN
              SET @is_xray = 'N'
            END
        END
        
      --判断SDS
      IF @sds_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
            SET @is_sds = 'Y'
        END
      IF @sds_rule = '2'--若不检
        BEGIN
          SET @is_sds = 'N'
        END
      IF @sds_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,0,1)
          ELSE
            UPDATE CKA0060 SET SDSSUMQTY = SDSSUMQTY+1 WHERE ITNBR = @itnbr
          SET @sds_cnt_per = round(100/cast(@sds_rule_val as float),0)--获取每多少个检测一个（SDS）
          SELECT @sds_sum_cnt = SDSSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@sds_sum_cnt % @sds_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
                SET @is_sds = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_sds = 'N'
            END
        END
     END
   --记录物流线调用履历(先只记录需检X光的)
   IF(@is_xray = 'Y')
      BEGIN
        INSERT INTO CKA0009
       (FAC, BARCODE, ITNBR, ITDSC, IS_HOLD, IS_TRIAL, IS_XRAY, IS_RECHECK, IS_FREEINSP, UB_MCHINE, PRIOR_MCH, RECHECK_NO, IS_SDS, CALLTIM) 
       VALUES ('02', @barcode, @itnbr, @itdsc, @is_hold, @is_trial, @is_xray, @is_recheck, @is_freeinsp, @ub_mchine, @prior_mch, @recheck_no, @is_sds, getdate())
      END
   --若规格为空则返回空行.MODIFYED By GCZhang 20240613 DC胎改为从无信息下胎口下胎
   --IF @itnbr='' or @itnbr is null
   IF @itnbr='' or @itnbr is null or @is_trial = 'Y'
     BEGIN
         SELECT '' barcode,
                '' itnbr,
                '' itdsc,
                '' is_hold,
                '' is_trial,
                '' is_xray,
                '' is_recheck,
                '' is_freeinsp,
                '' ub_mchine,
                '' prior_mch,
                '' recheck_no,
                '' is_sds
                WHERE 0 = 1
     END
   ELSE
     BEGIN
         --返回测试代号.
         SELECT @barcode barcode,
                @itnbr itnbr,
                @itdsc itdsc,
                @is_hold is_hold,
                @is_trial is_trial,
                @is_xray is_xray,
                @is_recheck is_recheck,
                @is_freeinsp is_freeinsp,
                @ub_mchine ub_mchine,
                @prior_mch prior_mch,
                @recheck_no recheck_no,
                @is_sds is_sds
     END
END
GO


-- ----------------------------
-- procedure structure for sp_renamediagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_renamediagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_renamediagram]
GO

CREATE PROCEDURE [dbo].[sp_renamediagram]
	(
		@diagramname 		sysname,
		@owner_id		int	= null,
		@new_diagramname	sysname
	
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @DiagIdTarg		int
		declare @u_name			sysname
		if((@diagramname is null) or (@new_diagramname is null))
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		end
	
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT;
	
		select @u_name = USER_NAME(@owner_id)
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		end
	
		-- if((@u_name is not null) and (@new_diagramname = @diagramname))	-- nothing will change
		--	return 0;
	
		if(@u_name is null)
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @new_diagramname
		else
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @owner_id and name = @new_diagramname
	
		if((@DiagIdTarg is not null) and  @DiagId <> @DiagIdTarg)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end		
	
		if(@u_name is null)
			update dbo.sysdiagrams set [name] = @new_diagramname, principal_id = @theId where diagram_id = @DiagId
		else
			update dbo.sysdiagrams set [name] = @new_diagramname where diagram_id = @DiagId
		return 0
	END
GO


-- ----------------------------
-- procedure structure for pr_gettire_sort_PCR_1617
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pr_gettire_sort_PCR_1617]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pr_gettire_sort_PCR_1617]
GO

CREATE PROCEDURE [dbo].[pr_gettire_sort_PCR_1617]
@barcode varchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   --设置事务为读
   SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

   DECLARE
      @itnbr       VARCHAR (50),
      @itdsc       VARCHAR (80),
      @is_hold     CHAR (1),
      @is_trial    CHAR (1),
      @is_xray     CHAR (1),
      @is_sds      CHAR (1),
      @is_recheck  CHAR (1),
      @is_freeinsp CHAR (1),
      @ub_mchine   VARCHAR (255),
      @prior_mch   VARCHAR (255),
      @cnt         INT,
      @cnt_prior   INT,
      @ufyn        CHAR (1),
      @dbyn        CHAR (1),
      @mchid       VARCHAR (20),
      @mchid_p     VARCHAR (20),
	  @mchid_16    VARCHAR (20),
      @mchid_17    VARCHAR (20),

      
      @recheck_rule VARCHAR(2),
      @recheck_rule_val INT,
      @recheck_no  VARCHAR(30),
      @xray_rule   VARCHAR(2),
	  --@xray_rule_val INT,
      @xray_rule_val FLOAT,
      @sds_rule   VARCHAR(2),
      @sds_rule_val INT

   SET @itnbr = ''
   SET @itdsc = ''
   SET @is_hold = ''
   SET @is_trial = ''
   SET @is_xray = 'N'--默认不X光
   SET @is_sds = 'N'--默认不SDS
   SET @is_recheck = 'N'--默认不复检
   SET @is_freeinsp = 'N'--默认非免检
   SET @ub_mchine = ''
   SET @prior_mch = ''
   SET @mchid_16 = '02DJ016'
   SET @mchid_17 = '02DJ017'



   SET @cnt = 0
   SET @cnt_prior = 0
   SET @mchid = ''
   SET @ufyn = ''
   SET @dbyn = ''
   SET @mchid_p = ''
   SET @recheck_no = ''

   --获取条码信息
   SELECT TOP 1
          @itnbr = TB.MATERIALID,
          @itdsc = TB.MATERIALNAME,
          @is_trial =
             CASE WHEN (ISNULL (LT.CUSTATE, '') = '2' OR ISNULL (LT.ATTRIBUTE2, '') = 'Y')
                        THEN 'Y' ELSE 'N' END,
          @is_hold = ISNULL (WIP.LOCKYN, N'N')
   FROM tb_PP_CuringOutPut AS TB
        LEFT OUTER JOIN LTA0001 AS LT ON TB.TYRENO = LT.TYRENO
        LEFT OUTER JOIN WIP0010 AS WIP ON TB.TYRENO = WIP.TYRENO
   WHERE TB.TYRENO = @barcode

   --判断能去哪个UB机
   SELECT A.MCHID,
          A.LNUM,
          B.RIMNO,
          A.UFYN,
          A.DBYN
   INTO #TEMP_T1
   FROM CKA0003 A, QMB0203 B
   WHERE     A.MCHID = B.MCHID
         AND A.LNUM = B.RIMNO
         AND B.MCHID NOT IN ('02DJ001',
                             '02DJ002',
                             '02DJ003',
                             '02DJ004')                        --老区动均设备不参与自动分拣
         AND A.ITNBR = @itnbr


   SELECT @cnt = count (1) FROM #TEMP_T1

   IF @cnt > 0
      BEGIN
         DECLARE
            cur_temp1 CURSOR FOR SELECT MCHID, UFYN, DBYN FROM #TEMP_T1

         OPEN cur_temp1
         FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn

         WHILE @@FETCH_STATUS = 0
         BEGIN
            --若均匀性和动平衡为N,则为免检
            IF (@ufyn = 'N' AND @dbyn = 'N')
               BEGIN
                  SET @ub_mchine = ''
                  SET @is_freeinsp = 'Y'
                  BREAK
               END
            ELSE
               BEGIN
                  SET @ub_mchine = @ub_mchine + @mchid + ','
               END

            FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn        --下一个
         END

         IF @ub_mchine ! = ''
            BEGIN
               SET @ub_mchine = LEFT (@ub_mchine, LEN (@ub_mchine) - 1)
            END

         CLOSE cur_temp1
         DEALLOCATE cur_temp1
      END

   --设备优先.
   IF (@ub_mchine ! = '' AND @ub_mchine ! = 'NONE')
      BEGIN
         --SELECT DISTINCT MCHID
         --INTO #TEMP_T2
         --FROM CKA0004
         --WHERE itnbr = @itnbr AND ONEYN = 'Y'
         
        SELECT DISTINCT C1.MCHID INTO #TEMP_T2 FROM CKA0003 C1 LEFT JOIN CKA0004 C2
        ON C1.MCHID=C2.MCHID AND C1.TCOD=C2.TCOD AND C1.ITNBR=C2.ITNBR 
        WHERE C1.ITNBR=@itnbr AND C2.ONEYN = 'Y'

        SELECT @cnt_prior = count (1) FROM #TEMP_T2

         IF @cnt_prior > 0
            BEGIN
               DECLARE
                  cur_temp2 CURSOR FOR SELECT MCHID FROM #TEMP_T2

               OPEN cur_temp2
               FETCH NEXT FROM cur_temp2   INTO @mchid_p

               WHILE @@FETCH_STATUS = 0
               BEGIN
                  SET @prior_mch = @prior_mch + @mchid_p + ','
                  FETCH NEXT FROM cur_temp2   INTO @mchid_p              --下一个
               END

               IF @prior_mch ! = ''
                  BEGIN
                     SET @prior_mch = LEFT (@prior_mch, LEN (@prior_mch) - 1)
                  END

               CLOSE cur_temp2
               DEALLOCATE cur_temp2
--Add By GCZhang 20250310 
--对于同一规格有多检测机检测的情况，虽优先级已设为16,17动均机，但由于原分拣上位机不识别16,17动均机，仍会将胎分拨到其它机台。
--为解决上述问题，系统增加处理逻辑，若优先机台包含16,17动均机的，首次扫描则认为是冻结，以便继续向南运输，使其分拣到16,17机台，第二次时则恢复正常逻辑
			   IF (@mchid_16 IN (SELECT MCHID FROM #TEMP_T2) OR @mchid_17 IN (SELECT MCHID FROM #TEMP_T2) ) 
                  BEGIN
--若物流调用记录中已存在<冻结>并且<分科捷>，则代表物流线由于某些原因（主要是道口满）上次没分科捷，则之后不再分往科捷。
					  IF NOT EXISTS (select ID from CKA0009 where Barcode = @barcode AND IS_HOLD = 'Y' AND is_freeinsp = 'K') 
						  BEGIN
						  SET @is_hold = 'Y'
						  SET @is_freeinsp = 'K'	
						  END
					  ELSE
						  BEGIN
                          SET @is_hold = @is_hold
						  SET @is_freeinsp = @is_freeinsp		
						  END
                  END
--END By GCZhang 20250310 

            END
        DROP TABLE #TEMP_T2
      END

   --删除临时表
   DROP TABLE #TEMP_T1
   
   --判断是否复检,X光,SDS
   IF (@itnbr!='' and @itnbr is not null)
     BEGIN
      DECLARE @rchk_cnt_per INT,
              @rchk_sum_cnt INT,
              @xray_cnt_per INT,
              @xray_sum_cnt INT,
              @sds_cnt_per INT,
              @sds_sum_cnt INT
      --根据规格获取分拣策略
      SELECT @recheck_rule=RECHECK_RULE,
             @recheck_rule_val=RECHECK_RULE_VAL,
             @recheck_no=RECHECK_NO,
             @xray_rule = XRAY_RULE,
             @xray_rule_val = XRAY_RULE_VAL,
             @sds_rule = SDS_RULE,
             @sds_rule_val = SDS_RULE_VAL
             FROM CKA0006
             WHERE  ITNBR = @itnbr
             
      --判断复检口
      IF @recheck_rule = '0'--若规则是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
            SET @is_recheck = 'Y'
        END
      IF @recheck_rule = '2'--若规则是不检
        BEGIN
          SET @is_recheck = 'N'
          SET @recheck_no = ''
        END
      IF @recheck_rule = '1' --若规则是抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,1,0,0)
          ELSE
            UPDATE CKA0060 SET RECHECKSUMQTY = RECHECKSUMQTY+1 WHERE ITNBR = @itnbr
          SET @rchk_cnt_per = round(100/cast(@recheck_rule_val as float),0)--获取每多少个检测一个（复检）
          SELECT @rchk_sum_cnt = RECHECKSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
                SET @is_recheck = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_recheck = 'N'
              SET @recheck_no = ''
            END
        END
        
      --判断X光
      IF @xray_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
            SET @is_xray = 'Y'
        END
      IF @xray_rule = '2'--若不检
        BEGIN
          SET @is_xray = 'N'
        END
      IF @xray_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,1,0)
          ELSE
            UPDATE CKA0060 SET XRAYSUMQTY = XRAYSUMQTY+1 WHERE ITNBR = @itnbr
          SET @xray_cnt_per = round(100/cast(@xray_rule_val as float),0)--获取每多少个检测一个（X光）
          SELECT @xray_sum_cnt = XRAYSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@xray_sum_cnt % @xray_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
                SET @is_xray = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_xray = 'N'
            END
          --若物流调用记录中已存在<不冻结>并且<分X光>，则代表物流线由于某些原因（主要是X光道口满）上次没分X光，则之后不再分往X光。2021-10-01 质检车间要求
          IF EXISTS(SELECT BARCODE FROM CKA0009 WHERE BARCODE = @barcode AND IS_HOLD = 'N' AND IS_XRAY = 'Y')
            BEGIN
              SET @is_xray = 'N'
            END
        END
        
      --判断SDS
      IF @sds_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
            SET @is_sds = 'Y'
        END
      IF @sds_rule = '2'--若不检
        BEGIN
          SET @is_sds = 'N'
        END
      IF @sds_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,0,1)
          ELSE
            UPDATE CKA0060 SET SDSSUMQTY = SDSSUMQTY+1 WHERE ITNBR = @itnbr
          SET @sds_cnt_per = round(100/cast(@sds_rule_val as float),0)--获取每多少个检测一个（SDS）
          SELECT @sds_sum_cnt = SDSSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@sds_sum_cnt % @sds_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
                SET @is_sds = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_sds = 'N'
            END
        END
     END
   --记录物流线调用履历(先只记录需检X光的) MODIFYED By GCZhang 20250310 增加优先级含16、17动均机的分拣履历
   --IF(@is_xray = 'Y')
   IF(@is_xray = 'Y' OR @is_freeinsp = 'K') 
      BEGIN
        INSERT INTO CKA0009
       (FAC, BARCODE, ITNBR, ITDSC, IS_HOLD, IS_TRIAL, IS_XRAY, IS_RECHECK, IS_FREEINSP, UB_MCHINE, PRIOR_MCH, RECHECK_NO, IS_SDS, CALLTIM) 
       VALUES ('02', @barcode, @itnbr, @itdsc, @is_hold, @is_trial, @is_xray, @is_recheck, @is_freeinsp, @ub_mchine, @prior_mch, @recheck_no, @is_sds, getdate())
      END
   --若规格为空则返回空行.MODIFYED By GCZhang 20240613 DC胎改为从无信息下胎口下胎
   --IF @itnbr='' or @itnbr is null
   IF @itnbr='' or @itnbr is null or @is_trial = 'Y'
     BEGIN
         SELECT '' barcode,
                '' itnbr,
                '' itdsc,
                '' is_hold,
                '' is_trial,
                '' is_xray,
                '' is_recheck,
                '' is_freeinsp,
                '' ub_mchine,
                '' prior_mch,
                '' recheck_no,
                '' is_sds
                WHERE 0 = 1
     END
   ELSE
     BEGIN
         --返回测试代号.
         SELECT @barcode barcode,
                @itnbr itnbr,
                @itdsc itdsc,
                @is_hold is_hold,
                @is_trial is_trial,
                @is_xray is_xray,
                @is_recheck is_recheck,
                @is_freeinsp is_freeinsp,
                @ub_mchine ub_mchine,
                @prior_mch prior_mch,
                @recheck_no recheck_no,
                @is_sds is_sds
     END
END
GO


-- ----------------------------
-- procedure structure for sp_alterdiagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_alterdiagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_alterdiagram]
GO

CREATE PROCEDURE [dbo].[sp_alterdiagram]
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END
GO


-- ----------------------------
-- procedure structure for sp_dropdiagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_dropdiagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_dropdiagram]
GO

CREATE PROCEDURE [dbo].[sp_dropdiagram]
	(
		@diagramname 	sysname,
		@owner_id	int	= null
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		end
	
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT; 
		
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		end
	
		delete from dbo.sysdiagrams where diagram_id = @DiagId;
	
		return 0;
	END
GO


-- ----------------------------
-- procedure structure for sp_qc_alarm_allquality
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_qc_alarm_allquality]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_qc_alarm_allquality]
GO

CREATE PROCEDURE [dbo].[sp_qc_alarm_allquality]
@FAC nvarchar(10), @BCOD nvarchar(20), @BNAM nvarchar(50), @RESULT nvarchar(10), @BARCODE nvarchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间
   DECLARE @ITNBR   NVARCHAR (50)                                     --规格代码
   DECLARE @ITDSC   NVARCHAR (100)                                    --规格名称
   DECLARE @DEPNAM   NVARCHAR (20)                                      --缺陷部门
   DECLARE @CUMCHID NVARCHAR (10)                                        --设备号
   DECLARE @LR nvarchar(1)                                              --左右
   DECLARE @RULECODE nvarchar(10)                                         --预警规则代码
   DECLARE @RULENAME nvarchar(100)                                         --预警规则描述
   DECLARE @BUMCHID NVARCHAR (10)                                        --设备号
   --DECLARE @LEVLCODE nvarchar(50)                                         --预警等级代码
   
   --获取当前时间的班次开始时间和班次结束时间
   --声明一个表用于获取班次信息
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;
   --若不良代码为空，则返回
   IF (@BCOD = '' or @BCOD is null)
     RETURN
   --基于不良代码获取其预警规则
   SELECT @RULECODE = ATTRIBUTE2 FROM QMA0006_DD WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','));
   --若规则代码为空，则返回
   IF (@RULECODE = '' or @RULECODE is null)
     RETURN
     
   DECLARE @BADCNT   INT
   DECLARE @ALMCNT   INT
   DECLARE @BARCODE_S NVARCHAR(MAX)
   
   IF @RULECODE = 'LH'--若规则是：同一硫化规格
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ALLQUALITY, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ALLQUALITY
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
        END
   IF @RULECODE = 'LHMJ'--若规则是：同一硫化规格，同一模具（机台）
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = CUITNBR,@ITDSC = CUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一硫化规格，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ALLQUALITY, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUITNBR = @ITNBR
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ALLQUALITY
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CX'
      BEGIN
             --获取条码生产信息
             SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH, @ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
             --查询当班，同一成型规格，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
                    @ALMCNT = ISNULL (ALMCNT.ALLQUALITY, 0),
                    @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ALLQUALITY
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ALLQUALITY, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ALLQUALITY
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'CXGGJT'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH,@ITNBR = BUITNBR,@ITDSC = BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一成型规格+机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ALLQUALITY, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.BUITNBR = @ITNBR
                         AND LTA.BUMCH = @BUMCHID
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ALLQUALITY
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   IF @RULECODE = 'MJ'
      BEGIN
         --获取条码生产信息
         SELECT @CUMCHID = CUMCH,@LR = LR,@BUMCHID = BUMCH FROM LTA0001 WHERE BARCODE = @BARCODE;
         --查询当班，同一硫化机台，同一缺陷
             SELECT @BADCNT = BADCNT.BADCNT,
               @ALMCNT = ISNULL (ALMCNT.ALLQUALITY, 0),
               @BARCODE_S = BARCODES
             FROM (SELECT COUNT (*) BADCNT,STRING_AGG(ISNULL(QMB.BARCODE,''), ',') BARCODES
                   FROM QMB0012 QMB with(nolock)
                        LEFT JOIN LTA0001 LTA with(nolock) ON QMB.BARCODE = LTA.BARCODE
                   WHERE     QMB.CRTIM BETWEEN @CRTIM1 AND @CRTIM2
                         AND QMB.FAC IN (select col from SplitIn(@FAC,','))
                         AND LTA.CUMCH = @CUMCHID
                         AND LTA.LR = @LR
                         AND QMB.BCOD = @BCOD
                         AND QMB.RESULT IN ('2','3')) BADCNT
                  LEFT JOIN (SELECT ALLQUALITY
                             FROM QMA0006_DD with(nolock)
                             WHERE ECODE = @BCOD AND FAC IN (select col from SplitIn(@FAC,','))) ALMCNT
                     ON 1 = 1
      END
   --若报警标准数量为0或空，则返回
   IF @ALMCNT = 0
     RETURN
   --获取预警规则描述
   SELECT @RULENAME=DNAM FROM  EDA0004 WHERE DIV = 'ALARM_RULE_PCR' AND DCOD =@RULECODE
   --获取缺陷部门
   SELECT @DEPNAM = DEPNAM FROM QMB0012 WHERE BARCODE = @BARCODE
   --若缺陷数超过了报警标准数量，则继续
   IF @BADCNT >= @ALMCNT AND @DEPNAM!='' AND @DEPNAM!='无责任部门' AND @DEPNAM IS NOT NULL
      BEGIN
               --各字段不能是null，转换为空
               IF @DEPNAM IS NULL
                BEGIN
                  SET @DEPNAM =''
                END
               IF @CUMCHID IS NULL
                BEGIN
                  SET @CUMCHID =''
                END
               IF @LR IS NULL
                BEGIN
                  SET @LR =''
                END    
               IF @ITNBR IS NULL
                BEGIN
                  SET @ITNBR =''
                END    
               IF @ITDSC IS NULL
                BEGIN
                  SET @ITDSC =''
                END      
               IF @BUMCHID IS NULL
                BEGIN
                  SET @BUMCHID =''
                END     
				
				IF @BARCODE_S IS NULL
                BEGIN
                  SET @BARCODE_S =''
                END    

				IF @BARCODE IS NULL
                BEGIN
                  SET @BARCODE =''
                END    

               INSERT INTO SJC0003_PCR (FAC,
                                        CHKDIV,
                                        DIV,
                                        MCHID,
                                        LR,
                                        WDATE,
                                        WSHT,
                                        ITNBR,
                                        ITDSC,
                                        BCOD,
                                        BNAM,
                                        CONTENT,
                                        TXNTIME,
                                        HDFLAG,
                                        HDTIM,
                                        BUMCH,
                                        BARCODES,
                                        NOW_BARCODE)
               VALUES (@FAC,
                       'VI',
                       @DEPNAM,
                       @CUMCHID,
                       @LR,
                       @WDATE,
                       @SHT,
                       @ITNBR,
                       @ITDSC,
                       @BCOD,
                       @BNAM,
                       '['+@RULENAME+']废次品和修理品和打磨品达到了' + CONVERT(NVARCHAR(10),@BADCNT) + '条',
                       GETDATE (),
                       'N',
                       NULL,
                       @BUMCHID,
                       @BARCODE_S,
                       @BARCODE);
      END
END
GO


-- ----------------------------
-- procedure structure for GetShiftByTime
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetShiftByTime]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetShiftByTime]
GO

CREATE PROCEDURE [dbo].[GetShiftByTime]  
	@dTime datetime,	 
	@fac NVARCHAR(10)='03'
as 
declare @STime datetime;
declare @ETime datetime;
declare @DateN datetime; 
set @DateN=getdate();
set @STime=getdate();
set @ETime=getdate();
declare @sht varchar(10);
declare @nsht varchar(10);
declare @ban varchar(10);
DECLARE @starb NVARCHAR(3);
SELECT @starb=e.WTIMSTART
FROM
	EDB0001 AS e
SET @sht='1';
SET @ban='A';
DECLARE @WDATE DATETIME, @SHT1 CHAR(1),@SHT2 CHAR(1),@SHT3 CHAR(1),@DT1 DATETIME,@DT2 DATETIME,@DT3 DATETIME  
declare cursor_edb03 CURSOR SCROLL FOR SELECT WDATE,SHT1,SHT2,SHT3,TIM1,TIM2,TIM3 FROM EDB0003 WHERE WDATE BETWEEN @dTime-1 and @dTime+1 and fac=@fac ORDER BY WDATE 
open cursor_edb03   
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
WHILE(@@FETCH_STATUS=0)
BEGIN 
		if(@dTime >= @DT1 and @dTime < @DT2)
		begin 
		   set @sht = '1' ;
		   set @nsht = '2' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT1;
		   set @STime = @DT1;
		   SET @ETime = DATEADD(Second,-1,@DT2);
		END 
		if(@dTime >= @DT2 and @dTime < @DT3 )
		begin 
		   set @sht = '2' ;
		   set @nsht = '3' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT2;
		   set @STime = @DT2;  
		   SET @ETime = DATEADD(Second,-1,@DT3);
		END  
		if(@dTime >= @DT3  )
		begin 
		   set @sht = '3' ;
		   set @nsht = '1' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT3;
		   set @STime = @DT3;
		   SET @ETime = DATEADD(Second,-1,@DT1);
		end    
		IF(@sht=3 AND @stime<@DT1 AND @ETime<@STime)
		BEGIN 
		   SET @ETime = DATEADD(Second,-1,@DT1);
		END      
  
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
END


CLOSE cursor_edb03
deallocate cursor_edb03  

SELECT @DateN WDATE,@sht SHT,@nsht NSHT,@ban BAN,@STime STIME,@ETime ETIME,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac='03' AND dcod=@sht) SHTNAM,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac='03' AND dcod=@Nsht) NSHTNAM
GO


-- ----------------------------
-- function structure for fn_diagramobjects
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[fn_diagramobjects]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[fn_diagramobjects]
GO

CREATE FUNCTION [dbo].[fn_diagramobjects]() 
	RETURNS int
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		declare @id_upgraddiagrams		int
		declare @id_sysdiagrams			int
		declare @id_helpdiagrams		int
		declare @id_helpdiagramdefinition	int
		declare @id_creatediagram	int
		declare @id_renamediagram	int
		declare @id_alterdiagram 	int 
		declare @id_dropdiagram		int
		declare @InstalledObjects	int

		select @InstalledObjects = 0

		select 	@id_upgraddiagrams = object_id(N'dbo.sp_upgraddiagrams'),
			@id_sysdiagrams = object_id(N'dbo.sysdiagrams'),
			@id_helpdiagrams = object_id(N'dbo.sp_helpdiagrams'),
			@id_helpdiagramdefinition = object_id(N'dbo.sp_helpdiagramdefinition'),
			@id_creatediagram = object_id(N'dbo.sp_creatediagram'),
			@id_renamediagram = object_id(N'dbo.sp_renamediagram'),
			@id_alterdiagram = object_id(N'dbo.sp_alterdiagram'), 
			@id_dropdiagram = object_id(N'dbo.sp_dropdiagram')

		if @id_upgraddiagrams is not null
			select @InstalledObjects = @InstalledObjects + 1
		if @id_sysdiagrams is not null
			select @InstalledObjects = @InstalledObjects + 2
		if @id_helpdiagrams is not null
			select @InstalledObjects = @InstalledObjects + 4
		if @id_helpdiagramdefinition is not null
			select @InstalledObjects = @InstalledObjects + 8
		if @id_creatediagram is not null
			select @InstalledObjects = @InstalledObjects + 16
		if @id_renamediagram is not null
			select @InstalledObjects = @InstalledObjects + 32
		if @id_alterdiagram  is not null
			select @InstalledObjects = @InstalledObjects + 64
		if @id_dropdiagram is not null
			select @InstalledObjects = @InstalledObjects + 128
		
		return @InstalledObjects 
	END
GO


-- ----------------------------
-- function structure for CheckBARCODE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CheckBARCODE]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[CheckBARCODE]
GO

CREATE FUNCTION [dbo].[CheckBARCODE]
(
    @Barcode NVARCHAR(50)
)
RETURNS BIT -- 返回类型改为 BIT，0表示不唯一，1表示唯一
AS
BEGIN
    DECLARE @IsUnique BIT;

    -- 逻辑：如果主表存在 OR 历史表存在，则不唯一
    IF EXISTS (SELECT 1 FROM dbo.LTA0001 nolock WHERE Barcode = @Barcode)
       OR EXISTS (SELECT 1 FROM dbo.TB_BARCODE WHERE Barcode = @Barcode)
    BEGIN
        SET @IsUnique = 0; -- 找到了，不唯一
    END
    ELSE
    BEGIN
        SET @IsUnique = 1; -- 都没找到，唯一
    END

    RETURN @IsUnique;
END
GO


-- ----------------------------
-- function structure for CheckTYRENO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CheckTYRENO]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[CheckTYRENO]
GO

CREATE FUNCTION [dbo].[CheckTYRENO]
(
    @Barcode NVARCHAR(50)
)
RETURNS BIT -- 返回类型改为 BIT，0表示不唯一，1表示唯一
AS
BEGIN
    DECLARE @IsUnique BIT;

    -- 逻辑：如果主表存在 OR 历史表存在，则不唯一
    IF EXISTS (SELECT 1 FROM dbo.tb_PP_CuringOutPut nolock WHERE TyreNo = @Barcode)
       OR EXISTS (SELECT 1 FROM dbo.TB_TYRENO WHERE TyreNo = @Barcode)
    BEGIN
        SET @IsUnique = 0; -- 找到了，不唯一
    END
    ELSE
    BEGIN
        SET @IsUnique = 1; -- 都没找到，唯一
    END

    RETURN @IsUnique;
END
GO


-- ----------------------------
-- procedure structure for pro_SettleWip
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pro_SettleWip]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pro_SettleWip]
GO

CREATE PROCEDURE [dbo].[pro_SettleWip]
AS
BEGIN
	declare @nowtime datetime
	declare @wdate date
	declare @wsht nvarchar(3)
	 
	SELECT @nowtime=dateadd(hh,-1,getdate())
	declare @shifttb table(WDATE DATE,SHT nvarchar(20),NSHT nvarchar(20),BAN nvarchar(20),STIME DATETIME,ETIME DATETIME,SHTNAM nvarchar(20),NSHTNAM nvarchar(20))

	insert into @shifttb 
	EXEC  GetShiftByTime @nowtime
	--取得上个班的班次和日期
	select @wsht=sht,@wdate=WDATE from @shifttb
	--先删除结算
	delete RE0001 WHERE WDATE=@wdate  and WSHT=@wsht  AND DIV='GT'
	-- WIP0001半成品库存结算
	declare @fac nvarchar(3) declare @div nvarchar(10) declare @itnbr nvarchar(50) declare @itdsc nvarchar(100) declare @lotcnt nvarchar(20) declare @CARTYPE nvarchar(20)     
	declare @sumqty  nvarchar(20) declare @lota nvarchar(20) declare @lotb nvarchar(20) declare @lotc nvarchar(20) declare @lotd nvarchar(20)
	declare @lot1 nvarchar(20) declare @lot2 nvarchar(20) declare @lot3 nvarchar(20) declare @lot4 nvarchar(20)  declare @lot5 nvarchar(20) 
	declare @qty1 nvarchar(20) declare @qty2 nvarchar(20) declare @qty3 nvarchar(20) declare @qty4 nvarchar(20)  declare @qty5 nvarchar(20) 
	declare @qtya nvarchar(20) declare @qtyb nvarchar(20) declare @qtyc nvarchar(20) declare @qtyd nvarchar(20) ,@qtye nvarchar(20) ,@qtyf nvarchar(20) ,@spec nvarchar(20),@lote nvarchar(20),@lotf nvarchar(20),@qtyg nvarchar(20),@lotg nvarchar(20)
	 

	--结算库存表，2在库状态的
    declare wip02_cursor cursor for  select tt.FAC,tt.DIV,tt.SPEC,t.ITDSC,tt.LOTCNT,LOT1,LOT2,LOT3,LOT4,LOT5,LOTA,LOTB,LOTC,LOTD,LOTE,QTYA,QTYB,QTYC,QTYD,SUMQTY from (
						   SELECT w.FAC,'GT' DIV,w.SPEC,COUNT(w.ID) LOTCNT,  
						   sum(CASE WHEN l.STATE= '1' THEN 1 else 0  END)AS LOT1, 
                          sum(CASE WHEN l.STATE= '2' THEN 1 else 0  END)AS LOT2, 
                          sum(CASE WHEN l.STATE ='3' THEN 1 else 0  END)AS LOT3, 
                          sum(CASE WHEN l.STATE= '4' THEN 1 else 0  END)AS LOT4, 
                          sum(CASE WHEN l.STATE= '5' THEN 1 else 0  END)AS LOT5,  
						   sum(CASE WHEN w.DIV= '1' THEN 1 else 0  END)AS LOTA, 
                          sum(CASE WHEN w.DIV= '2' THEN 1 else 0  END)AS LOTB, 
                          sum(CASE WHEN w.DIV= '3' THEN 1 else 0  END)AS LOTC, 
                          sum(CASE WHEN w.DIV= '4' THEN 1 else 0  END)AS LOTD, 
                          sum(CASE WHEN w.DIV= '5' THEN 1 else 0  END)AS LOTE,
                          sum(CASE WHEN w.STA  in ('1','6')  THEN 1 else 0  END)AS QTYA, 
                          sum(CASE WHEN w.STA not in ('1','2','6') THEN 1 else 0  END)AS QTYB,  
                          sum(CASE WHEN w.STA  in ('2') THEN 1 else 0  END)AS QTYC,  
                          sum(CASE WHEN w.IS_LOCK='Y' THEN 1 else 0  END)AS QTYD,  
                          0 SUMQTY FROM WIP0002 w LEFT join LTA0001 l on w.BARCODE=l.BARCODE  WHERE ISNULL(w.IS_DELETE,0)=0 and isnull(GTDIV,2)=2 GROUP BY w.SPEC,w.FAC
						  )tt left join  
						 ( SELECT distinct  SPEC,ITDSC,CLASSDIV,row_number() over (partition by spec,CLASSDIV order by RIGHT('0000000000'+REPLACE(e.[VERSION], ' ', ''),10) desc) ROWNUM 
 FROM EDD0001 AS e 
		WHERE   ITGRPCOD='GT' AND IS_USE=0 AND SHFLAG='Y') t on tt.SPEC=t.SPEC and t.ROWNUM=1   and    case when FAC in ('01','03','11') then '全钢' else '半钢' end=CLASSDIV
	open wip02_cursor
	fetch next from wip02_cursor into @fac,@div,@spec,@itdsc,@lotcnt,@lot1,@lot2,@lot3,@lot4,@lot5,@lota,@lotb,@lotc,@lotd,@lote,@qtya,@qtyb,@qtyc,@qtyd,@sumqty
	while @@FETCH_STATUS =0
		begin
			  insert into RE0001(WDATE,WSHT,SUMQTY,ITNBR,ITDSC,QTY,FAC,DIV,LOTA,LOTB,LOTC,LOTD,LOTE,QTYA,QTYB,QTYC,QTYD,LOT1,LOT2,LOT3,LOT4,LOT5)
			 VALUES
			 (@wdate,@wsht,@sumqty,@spec,@itdsc,@lotcnt,@fac,@div,@lota,@lotb,@lotc,@lotd,@lote,@qtya,@qtyb,@qtyc,@qtyd,@lot1,@lot2,@lot3,@lot4,@lot5)
			fetch next from wip02_cursor into @fac,@div,@spec,@itdsc,@lotcnt,@lot1,@lot2,@lot3,@lot4,@lot5,@lota,@lotb,@lotc,@lotd,@lote,@qtya,@qtyb,@qtyc,@qtyd,@sumqty
		end
    close wip02_cursor  --关闭游标
    deallocate wip02_cursor   --释放游标

	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	 
END
GO


