SELECT @_LNOCOUNT=COUNT(*) FROM STC0017 (NOLOCK) WHERE ShelfNumber =@LNO AND GOODSSTATE <> '5'  AND GOODSSTATE <> '3'
IF @_LNOCOUNT>0 BEGIN
INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('1',@TYRENO,'货架已在MES中使用！',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
  SELECT '货架['+@_LNO+']已在MES中使用！';
  RETURN;
END
SELECT TOP 1 @_QCSTATE=CAST(replace(CASE A.QCSTATE
WHEN '' THEN '9.0'
WHEN NULL THEN '9.0'
ELSE A.QCSTATE END,'W','1') AS decimal(18,2)) ,@_WGRESNM=(SELECT TOP 1 DNAM FROM EDA0004 (NOLOCK)
                    WHERE DIV = 'QC_RESULT' AND DCOD = A.QCSTATE ),@_DC=ISNULL(A.ATTRIBUTE1,'0') FROM QMB0101 (NOLOCK) AS A WHERE A.TYRENO = @TYRENO


					 IF(@_DC='2')
      BEGIN
      INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('1',@TYRENO,'试制(DC)禁止入库',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']试制(DC)禁止入库！';
	RETURN;
      END 
	  					 IF(@_DC='4')
      BEGIN
      INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('1',@TYRENO,'项目样胎禁止入库',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']项目样胎,禁止入库！';
	RETURN;
      END 


IF (@FAC != '02')
    BEGIN




	IF(@_QCSTATE = 0.0)
      BEGIN
      INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('1',@TYRENO,'综合质量无数据信息,不能上架',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']综合质量无数据信息,不能上架！';
	RETURN;
      END 

	




IF(@_QCSTATE !=9.0 )
BEGIN
IF(@_QCSTATE !=1.3)
BEGIN
	IF(@_QCSTATE > 1.3)
	BEGIN
	INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('1',@TYRENO,'综合质量处于[ '+@_WGRESNM+' ]的状态,不能上架',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']综合质量处于[ '+@_WGRESNM+' ]的状态,不能上架！';
	RETURN;
	END
END
END
ELSE
BEGIN
	INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('1',@TYRENO,'综合质量处于[ 未检 ]的状态,不能上架',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']综合质量处于[ 未检 ]的状态,不能上架！';
	RETURN;
END


SELECT TOP 1 @_ITNBR2=ITNBR FROM STC0009 (NOLOCK) WHERE LNO = @LNO AND EQUIPID = @EqID
IF(@_ITNBR2!='') BEGIN
IF(@_ITNBR1 != @_ITNBR2) BEGIN
SELECT '同一个货笼不能装两种规格的轮胎!';
RETURN;
END
END

END


SELECT @_barCodeCount=COUNT(*) FROM STC0009 (NOLOCK) WHERE TYRENO = @TYRENO
IF(@_barCodeCount>0)BEGIN
SELECT @_LNO=LNO FROM STC0009 (NOLOCK) WHERE TYRENO = @TYRENO
SELECT '成品胎已经在[ '+@_LNO+' ]货架上！';
RETURN;
END

SELECT @_ShelfCount=COUNT(LNO) FROM STC0009 (NOLOCK) WHERE LNO = @LNO AND ITNBR = @_ITNBR1 AND EQUIPID = @EqID AND [LEVEL] = '1' 
SELECT @_CargoCageQuantity=ISNULL(SUM(LQTY),0) FROM STC0004 (NOLOCK) WHERE ITNBR = @_ITNBR1
IF (@_CargoCageQuantity != 0)
BEGIN
    IF (@_ShelfCount > @_CargoCageQuantity)
    BEGIN
        SELECT '该货笼已经达到最大装胎数量，无法在装笼操作！';
        RETURN;
    END
END
ELSE
BEGIN
SELECT @_CargoCageQuantity =100;
IF (@FAC = '03' OR @FAC = '01')
    BEGIN
      SELECT @_CargoCageQuantity = 9;
   END
IF @_ShelfCount > @_CargoCageQuantity
   BEGIN
        SELECT '该货笼已经达到最大装胎数量，无法在装笼操作！';
        RETURN;
   END
END
SELECT '';
RETURN;
END
GO


-- ----------------------------
-- procedure structure for OUTSTD
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[OUTSTD]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[OUTSTD]
GO

CREATE PROCEDURE [dbo].[OUTSTD]
AS
BEGIN
	

declare @sorderno nvarchar(50), @itnbr nvarchar(50), @charg nvarchar(50), @recqty int, @qclot nvarchar(50), @it nvarchar(50), @qty int, @lorderno nvarchar(50)

declare cursor_s1 CURSOR SCROLL FOR 
SELECT  orderno,ITNBR,CHARG,sum(RECEPTQTY) qty FROM STD1002 WHERE ISNULL(OUTSTA,'')<>'OK' AND ETIM BETWEEN  GETDATE()-2 and GETDATE()  group by orderno,ITNBR,CHARG
open cursor_s1
FETCH NEXT from cursor_s1 into @sorderno,@itnbr,@charg,@recqty
WHILE(@@FETCH_STATUS=0)
begin 
		declare cursor_s2 cursor scroll for
		SELECT QCLOT,ITNBR, COUNT(*) qty,LORDERNO FROM STD0002 where  OUTTIME between GETDATE()-2 and GETDATE() and LORDERNO=@sorderno  group by QCLOT,ITNBR,LORDERNO
		open cursor_s2
		FETCH NEXT FROM cursor_s2 INTO @qclot,@it,@qty,@lorderno
		while(@@FETCH_STATUS=0)
		begin  
			--print @qclot+';'+@charg+';'+@it+';'+@itnbr+';'+@qty+';'+@recqty+';'+@sorderno
			if(@qclot=@charg and @it=@itnbr )
			begin
				if( @qty>=@recqty )--or @qty=@recqty
				begin
				  --print 'update STD1002 set OUTSTA=OK WHERE lorderno='+@lorderno+' and CHARG='+@qclot+' and ITNBR='+@it 
				  update STD1002 set OUTSTA='OK' WHERE orderno=@lorderno and CHARG=@qclot and ITNBR=@it
				end
			end
			FETCH NEXT from cursor_s2 into @qclot,@it,@qty,@lorderno
		end
		CLOSE cursor_s2
		deallocate cursor_s2  
FETCH NEXT from cursor_s1 into @sorderno,@itnbr,@charg,@recqty
end
CLOSE cursor_s1
deallocate cursor_s1  

END
GO


-- ----------------------------
-- procedure structure for drp_lhnew
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[drp_lhnew]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[drp_lhnew]
GO

CREATE PROCEDURE [dbo].[drp_lhnew] @day1 nvarchar(30)='',@day2 nvarchar(30)=''
AS
BEGIN
	

	DECLARE @SDATE NVARCHAR(20);
	DECLARE @EDATE NVARCHAR(20);
	DECLARE @QCDATE NVARCHAR(20);
	DECLARE @QMDATE NVARCHAR(20);
	if(@day1='')
	begin
	SET @SDATE=CONVERT(nvarchar(23),getdate()-2,23)+' 23:59:01' ;
	SET @EDATE=CONVERT(nvarchar(23),getdate()-1,23)+' 23:59:00' ;
	SET @QCDATE=CONVERT(nvarchar(23),getdate()-2,23) ;
	SET @QMDATE=CONVERT(nvarchar(23),getdate()-1,23); 
	end
	else
	begin 
	SET @SDATE=@day1+' 23:59:01' ;
	SET @EDATE=@day2+' 23:59:00' ;
	SET @QCDATE=@day1 ;
	SET @QMDATE=@day2;
	end

	delete re0066 where wdate=@QMDATE and fac='全钢';

insert into re0066 (ITNBR,STARQTY,ENDQTY,OUTQTY,INQTY,INQTY2,BNQTY,OUTBD,OUTFC,INOUTQTY,LCOUT,BLQTY,WDATE,FAC)
select t.*,@QMDATE as [wdate] ,'全钢' fac  from
(SELECT (CASE WHEN A.ITNBR IS NOT NULL THEN A.ITNBR WHEN B.ITNBR IS NOT NULL THEN B.ITNBR WHEN C.ITNBR IS NOT NULL THEN C.ITNBR WHEN D.ITNBR IS NOT NULL THEN D.ITNBR WHEN E.ITNBR IS NOT NULL THEN E.ITNBR WHEN F.ITNBR IS NOT NULL THEN F.ITNBR WHEN G.ITNBR IS NOT NULL THEN G.ITNBR WHEN H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS IS NOT NULL THEN H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS  WHEN L.ITNBR IS NOT NULL THEN L.ITNBR   WHEN I.ITNBR IS NOT NULL THEN I.ITNBR  END) ITNBR , 
ISNULL(A.STARQTY,0) STARQTY, ISNULL(B.ENDQTY,0) ENDQTY,
ISNULL(C.OUTQTY,0) OUTQTY 
,ISNULL(D.INQTY,0) INQTY,ISNULL(E.INQTY,0) INQTY2,ISNULL(F.BN,0) BNQTY,ISNULL(H.OUTBD,0) OUTBD,ISNULL(G.OUTFC,0) OUTFC,ISNULL(I.INOUTQTY,0) INOUTQTY 
,ISNULL(L.LCOUT,0) LCOUT ,ISNULL(BL.BLQTY,0) BLQTY  FROM
(SELECT sum(ENDQTY) as[STARQTY],  ITNBR from re0066 where wdate=@QCDATE and fac='全钢' group by itnbr )A --期初数据
FULL JOIN
(SELECT 0 ENDQTY ,ITNBR from re0066 where wdate=@QMDATE and  fac='全钢' ) B--期末数据
ON A.ITNBR=B.ITNBR
FULL JOIN
( SELECT count(*) OUTQTY,ITNBR FROM STC0019 a left join STC0018 b on a.Warehousereceipt=b.Warehousereceipt  WHERE CONVERT(NVARCHAR, AffirmTim,120) BETWEEN  @SDATE and @EDATE and workshop in ('01','03') group by itnbr) C --出库数据
on A.ITNBR=C.ITNBR OR B.ITNBR=C.ITNBR
FULL JOIN
(select MaterialID ITNBR ,count(TyreNo) INQTY from tb_PP_CuringOutPut where wdate=@QMDATE  and FAC in('01','03') GROUP BY MaterialID) D  --入库数据
on A.ITNBR=D.ITNBR OR B.ITNBR=D.ITNBR OR C.ITNBR=D.ITNBR
FULL JOIN
(select MaterialID ITNBR ,count(TyreNo) INQTY from tb_PP_CuringOutPut where BEGINTIME BETWEEN @SDATE and @EDATE  and FAC in('01','03') GROUP BY MaterialID) E  --入库数据2
on A.ITNBR=E.ITNBR OR B.ITNBR=E.ITNBR OR C.ITNBR=E.ITNBR OR D.ITNBR=E.ITNBR
full join
(select  b.DIV,a.ITNBR, 
			sum(case when a.STA='1' then 1 when a.STA='2' then -1 end) BN
			from STA0007 a left join STA0005 b on a.DOCCOD=b.DOCCOD where  b.div=5 and a.sta in ('1','2') 
			and  CONFIRMTIM   between @SDATE and @EDATE AND  B.FAC IN('01','03')
			group by  b.DIV,a.ITNBR ) F
ON A.ITNBR=F.ITNBR OR B.ITNBR=F.ITNBR OR C.ITNBR=F.ITNBR OR D.ITNBR=F.ITNBR OR E.ITNBR=F.ITNBR
full join
(select  COUNT(*) OUTFC,ITNBR from STC0053
			WHERE  COLLECTTIM   between @SDATE and @EDATE AND  FAC IN('01','03')
			group by  ITNBR ) G
ON A.ITNBR=G.ITNBR OR B.ITNBR=G.ITNBR OR C.ITNBR=G.ITNBR OR D.ITNBR=G.ITNBR OR F.ITNBR=G.ITNBR OR E.ITNBR=G.ITNBR
full join
( select itnbr,count(*) OUTBD from ifdb.[PLMESINTERFACE].[dbo].[WIP0010_WMS] where crtim  between @SDATE and @EDATE AND  FAC IN('01','03')
 group by itnbr ) H
ON A.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR B.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR C.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS
OR D.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR F.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR G.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR E.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS
FULL JOIN
(select itnbr,count(*) INOUTQTY from STC0021 A LEFT JOIN STC0020 B ON  A.Returnnumber = B.Returnnumber WHERE B.UPDTIM BETWEEN @SDATE and @EDATE group by itnbr ) I ON A.ITNBR=I.ITNBR OR B.ITNBR=I.ITNBR OR
C.ITNBR=I.ITNBR OR D.ITNBR=I.ITNBR OR E.ITNBR=I.ITNBR OR F.ITNBR=I.ITNBR OR G.ITNBR=I.ITNBR OR H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS=I.ITNBR
FULL JOIN
(select itnbr,count(distinct tyreno) LCOUT from QLC0011  WHERE OutTime BETWEEN @SDATE and @EDATE　AND  FAC IN('01','03') group by itnbr ) L ON A.ITNBR=L.ITNBR OR B.ITNBR=L.ITNBR OR C.ITNBR=L.ITNBR OR D.ITNBR=L.ITNBR OR F.ITNBR=L.ITNBR
OR E.ITNBR=L.ITNBR OR F.ITNBR=L.ITNBR OR G.ITNBR=L.ITNBR OR H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS=L.ITNBR OR I.ITNBR=L.ITNBR
FULL JOIN
(  SELECT SUM(DIV) BLQTY,ITNBR FROM FTREEDIT
 where crtim BETWEEN @SDATE and @EDATE   and FAC IN('01','03') 
 GROUP BY ITNBR) BL ON A.ITNBR=BL.ITNBR OR B.ITNBR=BL.ITNBR OR C.ITNBR=BL.ITNBR OR D.ITNBR=BL.ITNBR OR F.ITNBR=BL.ITNBR
OR E.ITNBR=BL.ITNBR OR F.ITNBR=BL.ITNBR OR G.ITNBR=BL.ITNBR OR H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS=BL.ITNBR OR I.ITNBR=BL.ITNBR OR L.ITNBR=BL.ITNBR
) t
inner JOIN 
(SELECT * FROM
(SELECT ITNBR,row_number() over (PARTITION by ITNBR ORDER BY VERSION DESC) rid,version,SAPBOM FROM EDD0001 WHERE  ITGRPCOD='FERT'   AND SHFLAG='Y' and FAC in ('01','03'))
t where rid=1)  t2
on t.ITNBR=t2.ITNBR  
WHERE STARQTY<>0 OR ENDQTY<>0 OR OUTQTY<>0 OR INQTY<>0 OR INQTY2<>0 OR BNQTY<>0 OR OUTBD<>0 OR OUTFC<>0 OR INOUTQTY<>0 OR LCOUT<>0 OR BLQTY<>0 ;

  UPDATE RE0066 SET ENDQTY=STARQTY+INOUTQTY+INQTY2+BLQTY+BNQTY-OUTQTY-OUTBD-OUTFC-LCOUT WHERE FAc='全钢' and wdate=@QMDATE;
  UPDATE RE0066 SET ENDQTY=0 WHERE FAc='全钢' and wdate=@QMDATE and ENDQTY<0;

--  INSERT INTO RE0066(ENDQTY,ITNBR,WDATE,FAC) 
--select sum(ENDQTY) ENDQTY,ITNBR,@QMDATE as [wdate] ,'半钢' fac
--from
--(
--select ITNBR,COUNT(*) ENDQTY from WIP0010 where fac='02' and isnull(IS_DELETE,'0')='0'  GROUP BY ITNBR
--union all
--SELECT  ITNBR,count(*) ENDQTY FROM STC0017  with ( nolock) WHERE GOODSSTATE IN ('1','2','4')  and workshop='02'
--and Transfercardnumber not  IN (SELECT Transfercardnumber FROM STC0019  a 
--inner join STC0018 b on a.Warehousereceipt=b.Warehousereceipt and b.STATE='3')   group by ITNBR) t group by ITNBR ;

 
	delete re0066 where wdate=@QMDATE and fac='半钢';

insert into re0066 (ITNBR,STARQTY,ENDQTY,OUTQTY,INQTY,INQTY2,BNQTY,OUTBD,OUTFC,INOUTQTY,LCOUT,BLQTY,WDATE,FAC)	 
select t.*,@QMDATE as [wdate] ,'半钢' fac  from
(SELECT (CASE WHEN A.ITNBR IS NOT NULL THEN A.ITNBR WHEN B.ITNBR IS NOT NULL THEN B.ITNBR WHEN C.ITNBR IS NOT NULL THEN C.ITNBR WHEN D.ITNBR IS NOT NULL THEN D.ITNBR WHEN E.ITNBR IS NOT NULL THEN E.ITNBR WHEN F.ITNBR IS NOT NULL THEN F.ITNBR WHEN G.ITNBR IS NOT NULL THEN G.ITNBR WHEN H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS IS NOT NULL THEN H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS  WHEN L.ITNBR IS NOT NULL THEN L.ITNBR   WHEN I.ITNBR IS NOT NULL THEN I.ITNBR  END) ITNBR , 
ISNULL(A.STARQTY,0) STARQTY, ISNULL(B.ENDQTY,0) ENDQTY,
ISNULL(C.OUTQTY,0) OUTQTY 
,ISNULL(D.INQTY,0) INQTY,ISNULL(E.INQTY,0) INQTY2,ISNULL(F.BN,0) BNQTY,ISNULL(H.OUTBD,0) OUTBD,ISNULL(G.OUTFC,0) OUTFC,ISNULL(I.INOUTQTY,0) INOUTQTY 
,ISNULL(L.LCOUT,0) LCOUT ,ISNULL(BL.BLQTY,0) BLQTY  FROM
(SELECT sum(ENDQTY) as[STARQTY],  ITNBR from re0066 where wdate=@QCDATE and fac='半钢' group by itnbr )A --期初数据
FULL JOIN
(SELECT 0 ENDQTY ,ITNBR from re0066 where wdate=@QMDATE and  fac='半钢' ) B--期末数据
ON A.ITNBR=B.ITNBR
FULL JOIN
( SELECT count(*) OUTQTY,ITNBR FROM STC0019 a left join STC0018 b on a.Warehousereceipt=b.Warehousereceipt  WHERE CONVERT(NVARCHAR, AffirmTim,120) BETWEEN  @SDATE and @EDATE and workshop in ('02') group by itnbr) C --出库数据
on A.ITNBR=C.ITNBR OR B.ITNBR=C.ITNBR
FULL JOIN
(select MaterialID ITNBR ,count(TyreNo) INQTY from tb_PP_CuringOutPut where wdate=@QMDATE  and FAC in('02') GROUP BY MaterialID) D  --入库数据
on A.ITNBR=D.ITNBR OR B.ITNBR=D.ITNBR OR C.ITNBR=D.ITNBR
FULL JOIN
(select MaterialID ITNBR ,count(TyreNo) INQTY from tb_PP_CuringOutPut where BEGINTIME BETWEEN @SDATE and @EDATE  and FAC in('02') GROUP BY MaterialID) E  --入库数据2
on A.ITNBR=E.ITNBR OR B.ITNBR=E.ITNBR OR C.ITNBR=E.ITNBR OR D.ITNBR=E.ITNBR
full join
(select  b.DIV,a.ITNBR, 
			sum(case when a.STA='1' then 1 when a.STA='2' then -1 end) BN
			from STA0007 a left join STA0005 b on a.DOCCOD=b.DOCCOD where  b.div=5 and a.sta in ('1','2') 
			and  CONFIRMTIM   between @SDATE and @EDATE AND  B.FAC IN('02')
			group by  b.DIV,a.ITNBR ) F
ON A.ITNBR=F.ITNBR OR B.ITNBR=F.ITNBR OR C.ITNBR=F.ITNBR OR D.ITNBR=F.ITNBR OR E.ITNBR=F.ITNBR
full join
(select  COUNT(*) OUTFC,ITNBR from STC0053
			WHERE  COLLECTTIM   between @SDATE and @EDATE AND  FAC IN('02')
			group by  ITNBR ) G
ON A.ITNBR=G.ITNBR OR B.ITNBR=G.ITNBR OR C.ITNBR=G.ITNBR OR D.ITNBR=G.ITNBR OR F.ITNBR=G.ITNBR OR E.ITNBR=G.ITNBR
full join
( select itnbr,count(*) OUTBD from ifdb.[PLMESINTERFACE].[dbo].[WIP0010_WMS] where crtim  between @SDATE and @EDATE AND  FAC IN('02')
 group by itnbr ) H
ON A.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR B.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR C.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS
OR D.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR F.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR G.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS OR E.ITNBR=H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS
FULL JOIN
(select itnbr,count(*) INOUTQTY from STC0021 A LEFT JOIN STC0020 B ON  A.Returnnumber = B.Returnnumber WHERE B.UPDTIM BETWEEN @SDATE and @EDATE group by itnbr ) I ON A.ITNBR=I.ITNBR OR B.ITNBR=I.ITNBR OR
C.ITNBR=I.ITNBR OR D.ITNBR=I.ITNBR OR E.ITNBR=I.ITNBR OR F.ITNBR=I.ITNBR OR G.ITNBR=I.ITNBR OR H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS=I.ITNBR
FULL JOIN
(select itnbr,count(distinct tyreno) LCOUT from QLC0011  WHERE OutTime BETWEEN @SDATE and @EDATE　AND  FAC IN('02') group by itnbr ) L ON A.ITNBR=L.ITNBR OR B.ITNBR=L.ITNBR OR C.ITNBR=L.ITNBR OR D.ITNBR=L.ITNBR OR F.ITNBR=L.ITNBR
OR E.ITNBR=L.ITNBR OR F.ITNBR=L.ITNBR OR G.ITNBR=L.ITNBR OR H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS=L.ITNBR OR I.ITNBR=L.ITNBR
FULL JOIN
(  SELECT SUM(DIV) BLQTY,ITNBR FROM FTREEDIT
 where crtim BETWEEN @SDATE and @EDATE   and FAC IN('02') 
 GROUP BY ITNBR) BL ON A.ITNBR=BL.ITNBR OR B.ITNBR=BL.ITNBR OR C.ITNBR=BL.ITNBR OR D.ITNBR=BL.ITNBR OR F.ITNBR=BL.ITNBR
OR E.ITNBR=BL.ITNBR OR F.ITNBR=BL.ITNBR OR G.ITNBR=BL.ITNBR OR H.ITNBR COLLATE Chinese_PRC_90_CI_AI_WS=BL.ITNBR OR I.ITNBR=BL.ITNBR OR L.ITNBR=BL.ITNBR
) t
inner JOIN 
(SELECT * FROM
(SELECT ITNBR,row_number() over (PARTITION by ITNBR ORDER BY VERSION DESC) rid,version,SAPBOM FROM EDD0001 WHERE  ITGRPCOD='FERT'   AND SHFLAG='Y' and FAC in ('02'))
t where rid=1)  t2
on t.ITNBR=t2.ITNBR  
WHERE STARQTY<>0 OR ENDQTY<>0 OR OUTQTY<>0 OR INQTY<>0 OR INQTY2<>0 OR BNQTY<>0 OR OUTBD<>0 OR OUTFC<>0 OR INOUTQTY<>0 OR LCOUT<>0 OR BLQTY<>0 ;
   UPDATE RE0066 SET ENDQTY=STARQTY+INOUTQTY+INQTY2+BLQTY+BNQTY-OUTQTY-OUTBD-OUTFC-LCOUT WHERE FAc='半钢' and wdate=@QMDATE;
  UPDATE RE0066 SET ENDQTY=0 WHERE FAc='半钢' and wdate=@QMDATE and ENDQTY<0;

END
GO


-- ----------------------------
-- procedure structure for tyreno_CHANGE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[tyreno_CHANGE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[tyreno_CHANGE]
GO

CREATE PROCEDURE [dbo].[tyreno_CHANGE]
	@NEWBARCODE NVARCHAR(50),@OLDBARCODE NVARCHAR(50)
AS
BEGIN 
	BEGIN transaction
    declare @nror int
    set @nror=0 
	UPDATE QMB0101 SET TYRENO=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
    UPDATE LTA0001	SET TYRENO=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE tb_PP_CuringOutPut SET TYRENO=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE wip0010 SET TYRENO=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
	if @nror<>0
		begin 
			rollback transaction
        end
        else 
        begin 
            commit transaction
        end
END
GO


-- ----------------------------
-- procedure structure for SET_LTC0002_HALFPRO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SET_LTC0002_HALFPRO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SET_LTC0002_HALFPRO]
GO

CREATE PROCEDURE [dbo].[SET_LTC0002_HALFPRO] 
	 @PLANCOD NVARCHAR(50)
AS
BEGIN
	DECLARE @MCHID NVARCHAR(10);
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
declare @tbname nvarchar(20);
declare @outwidth float;
declare @inwidth float;
declare @cmd nvarchar(max);
DECLARE @AB NVARCHAR(20);
  
  

SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD,@AB=LRFLAG FROM PAD0201_HALF WHERE PLANCOD=@PLANCOD;

IF @MCHID LIKE '11CR%'
BEGIN
	SET @outtypecod='BDR'
END;

SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR AND ITTYPECOD=@outtypecod AND SHFLAG='Y' AND IS_USE=0; -- 2022-08-22 更改，审核过的最高版本，之前没有加审核
--2025-07-03 更改计划版本
update PAD0201_HALF set VERSION=@VERSION where PLANCOD=@PLANCOD and VERSION<>@VERSION;

with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight)
as
(
--初始查询
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
union all
--递归条件
select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth,a.PCSBOMWeight
from EDD0061 a 
inner join
temp b
on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
and b.EditionNo=a.ParentMatEditionNo)
)
select distinct * INTO #T2  from temp 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
--2024-12-03 针对Up-Fit-Cushion 不去递归更新 全钢加强层的上贴合胶片的使用位置变更，最新使用位置是：Up-Fit-Cushion  原使用位置：F-Cushion
MERGE INTO #T2 a
USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
 on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  and a.Usage<>'Up-Fit-Cushion'
when matched then
update set SubMatID=b.SubMatID;



--2024-11-29 新增  半钢纤维帘布换算,和全钢大卷一样

if(@outtypecod ='PFC')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSWidth from PFC_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 钢丝已经是换算过的，所以这里需要沟通更改
		update #t2 set PCSBOMWeight=@outwidth/1000 * PCSBOMWeight 
	END
END

if(@outtypecod ='PSB')
BEGIN 
set @outwidth=0; 
set @cmd=N'select top 1 @outwidth= PCSBeltWidth from PSB_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PSC')
		BEGIN
			select TOP 1 @inwidth= PCSRouteWidth from PSC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PSC') order by CONVERT(int, PCSSheetVersion) desc

			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000
				update #t2 set PCSCuttinglength=(@outwidth/@inwidth)*1000 where SubMatTypeName='PSC'
			end
		end 　
	END
END

if(@outtypecod ='PCC')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSWidth from PCC_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin 
	    --找纤维帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PFC')
		BEGIN
			select TOP 1 @inwidth= PCSWidth from PFC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PFC') order by CONVERT(int, PCSSheetVersion) desc

			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000
				update #t2 set PCSCuttinglength=(@outwidth/@inwidth)*1000 where SubMatTypeName='PFC'
			end
		end 
	END
END

if(@outtypecod ='PKT')
BEGIN 
	set @outwidth=0;    
	--找纤维帘布的宽度
	if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PFC')
	BEGIN
		select TOP 1 @inwidth= PCSWidth from PFC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PFC') order by CONVERT(int, PCSSheetVersion) desc

		if(@inwidth>0)
