	--找中卷的宽度
	if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PKT')
	BEGIN
		select TOP 1 @inwidth= PartWidth from PKT_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PKT') order by CONVERT(int, PCSSheetVersion) desc

		if(@inwidth>0)
		begin
			update #t2 set PCSCuttinglength=1000
			update #t2 set PCSCuttinglength=(PCSCuttingWidth/@inwidth)*1000 where SubMatTypeName='PKT'
		end
	end  
	--找纤维帘布的宽度
	if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PFC')
	BEGIN
		select TOP 1 @inwidth= PCSWidth from PFC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PFC') order by CONVERT(int, PCSSheetVersion) desc

		if(@inwidth>0)
		begin
			update #t2 set PCSCuttinglength=1000
			update #t2 set PCSCuttinglength=(PCSCuttingWidth/@inwidth)*1000 where SubMatTypeName='PFC'
		end
	end  
END

