if(@outtypecod ='CCF')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD=''M75'' WHERE ITNBR='''+@ITNBR+'''  and VERSION='''+@VERSION+'''  '
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 钢丝已经是换算过的，所以这里需要沟通更改
		update #t2 set PCSBOMWeight=@outwidth/1000 * PCSBOMWeight 
		update #t2 set PCSCuttinglength= PCSBOMWeight*1000.000  WHERE SubMatTypeName<>'JL'
	END
END

if(@outtypecod ='ZB')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD=''M75'' WHERE ITNBR='''+@ITNBR+'''  and VERSION='''+@VERSION+'''  '
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 2024-10-30，冠带扣减逻辑修改
	--2025-02-19 全钢冠带扣减逻辑修改，产出载具上都是一起卷两根，宽度是一根得宽度,在原来基础上需要乘以2
		update #t2 set PCSBOMWeight=(@outwidth/1000)*2 * PCSBOMWeight 
		update #t2 set PCSCuttinglength= PCSBOMWeight*1000.000  WHERE SubMatTypeName<>'JL'
	END
END


if(@outtypecod ='SWR')
