 update #t2 set PCSBOMWeight=PCSBOMWeight* CONVERT(float,2) ,PCSCuttinglength=PCSBOMWeight* CONVERT(float,2)*1000
END
if(@outtypecod ='PTQ')
BEGIN 
set @outwidth=1;  
set @cmd=N'select top 1 @outwidth= isnull(PCSApexCuttinglength,1) from PTQ_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
