		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='CCF')
		BEGIN 
			SELECT TOP 1 @inwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD='M75' WHERE ITNBR=(select top 1  SubMatID from #T2 where SubMatTypeName='CCF') and SHFLAG='Y' order by CONVERT(int, A.VERSION) desc
			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000  
				update #t2 set PCSCuttinglength=(PCSCuttingWidth/@inwidth)*1000 where SubMatTypeName='CCF'
			end
		end 　 
END

if(@outtypecod ='CC')
BEGIN 
set @outwidth=0;    
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='CCF')
		BEGIN 
			SELECT TOP 1 @inwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD='M75' WHERE ITNBR=(select top 1  SubMatID from #T2 where SubMatTypeName='CCF') and SHFLAG='Y' order by CONVERT(int, A.VERSION) desc
			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000  *CONVERT(float,SubMatNum)
				update #t2 set PCSCuttinglength=(PCSCuttingWidth/@inwidth)*1000 where SubMatTypeName='CCF'
			end
		end 　 
END

