	SET @AB='L|R';
END
IF(@AB='')--2024.08.07 增加左右标准带出
BEGIN
	UPDATE LTC0002 SET NBRST='',DSCST='',XQTY=1 WHERE MCHID=@MCHID
	UPDATE LTC0002 WITH(UPDLOCK)
					  SET SDIV=C.TYPECOD,
						  NBRST=C.SubMatID,
						  DSCST=C.SubMatID,
						  XQTY=  C.XQTY,
						  JLXQTY=C.PCSBOMWeight,
						  PLANCOD=@PLANCOD
					  FROM LTC0002 D 
						  INNER JOIN ( SELECT q.TCOD,q.TYPECOD,t.SubMatID,t.PCSBOMWeight,CASE WHEN  t.PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty FROM VIEW_QMA0014_USAGE q 
						inner join #T2 t on q.TYPECOD=t.subMatTypeName and q.USAGE = t.Usage  WHERE MCHID=@MCHID    ) C ON D.LDIV = C.TCOD
					  WHERE D.MCHID=@MCHID 


				  
	update LTC0002 SET DIV=6
	FROM LTC0002 A LEFT JOIN EDD0663 B ON A.NBRST=B.MatID WHERE 
	(NBRRE<>NBRST AND ISNULL(B.SubMatID,'')<>A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID

	update LTC0002 SET DIV=1
	FROM LTC0002 A LEFT JOIN EDD0663 B ON A.NBRST=B.MatID WHERE 
	(NBRST=NBRRE OR ISNULL(B.SubMatID,'')=A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID

END
ELSE
BEGIN
	UPDATE LTC0002 SET NBRST='',DSCST='',XQTY=1 WHERE MCHID=@MCHID and LDIV in (select tcod from VIEW_QMA0014_USAGE where MCHID=@MCHID and  ISNULL(LRFLAG,'') in 
					(SELECT value FROM STRING_SPLIT(@AB, '|')UNION all SELECT '' value)   )
	UPDATE LTC0002 WITH(UPDLOCK)
					  SET SDIV=C.TYPECOD,
						  NBRST=C.SubMatID,
						  DSCST=C.SubMatID,
						  XQTY=  C.XQTY,
						  JLXQTY=C.PCSBOMWeight,
						  PLANCOD=@PLANCOD
					  FROM LTC0002 D 
						  INNER JOIN ( SELECT q.TCOD,q.TYPECOD,t.SubMatID,t.PCSBOMWeight,CASE WHEN  t.PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty FROM VIEW_QMA0014_USAGE q 
						inner join #T2 t on q.TYPECOD=t.subMatTypeName and q.USAGE = t.Usage  WHERE MCHID=@MCHID and  ISNULL(q.LRFLAG,'') in 
						(SELECT value FROM STRING_SPLIT(@AB, '|')UNION all SELECT '' value)    ) C ON D.LDIV = C.TCOD
					  WHERE D.MCHID=@MCHID 


				  
	update LTC0002 SET DIV=6
	FROM LTC0002 A LEFT JOIN EDD0663 B ON A.NBRST=B.MatID WHERE 
	(NBRRE<>NBRST AND ISNULL(B.SubMatID,'')<>A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID and LDIV in (select tcod from VIEW_QMA0014_USAGE where  MCHID=@MCHID and ISNULL(LRFLAG,'') in 
						(SELECT value FROM STRING_SPLIT(@AB, '|')UNION all SELECT '' value)   )

	update LTC0002 SET DIV=1
	FROM LTC0002 A LEFT JOIN EDD0663 B ON A.NBRST=B.MatID WHERE 
	(NBRST=NBRRE OR ISNULL(B.SubMatID,'')=A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID and LDIV in (select tcod from VIEW_QMA0014_USAGE where MCHID=@MCHID and  ISNULL(LRFLAG,'') in 
						(SELECT value FROM STRING_SPLIT(@AB, '|')UNION all SELECT '' value)   )

END

	drop table #T2
END
GO


-- ----------------------------
-- procedure structure for alllc_pro
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[alllc_pro]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[alllc_pro]
GO

CREATE PROCEDURE [dbo].[alllc_pro] @itnbrdd nvarchar(50),@newspecdd nvarchar(30)
AS
BEGIN
	SELECT itnbr,MAX(OutDate) wdate,DATEDIFF(day,MAX(OutDate),getdate()) sday,0 qty into #l_t1  FROM QLC0010 where [State]>3 AND FAC in ('01','03','11') AND planno not like 'FJ%'   group by ITNBR; 
MERGE INTO #l_t1 a
	using(SELECT COUNT(*) QTY,ITNBR,B.OUTDATE FROM TB_PP_CURINGOUTPUT A 
inner JOIN (SELECT itnbr,MAX(OUTDATE) OUTDATE   FROM QLC0010 where [State]>3  AND FAC in ('01','03','11') AND planno not like 'FJ%'  group by ITNBR) B ON A.MaterialID=B.ITNBR AND A.BeginTime>B.OUTDATE AND A.CUSTATE  IN ('1','')
GROUP BY ITNBR,OUTDATE) b
on a.itnbr=b.itnbr AND a.wdate=b.OUTDATE 
when MATCHED THEN
UPDATE set a.qty=b.qty;
	--declare @itnbr nvarchar(20),@date datetime
	--declare cursor_s1 CURSOR SCROLL FOR 
	--SELECT itnbr,wdate FROM #l_t1     
	--open cursor_s1
	--fetch  next from cursor_s1 into @itnbr,@date
	--while(@@FETCH_STATUS=0)
	--begin
	--	update #l_t1 set qty=(select count(*) from tb_PP_CuringOutPut where MaterialID=@itnbr and BeginTime>@date) where ITNBR=@itnbr
	--	fetch  next from cursor_s1 into @itnbr,@date
	--end
	--CLOSE cursor_s1
	--deallocate cursor_s1;

	with
	t_t1 AS
	(SELECT * FROM (select distinct ATTRVAL SPEC ,a.ITNBR,a.ITDSC, 
	ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId  
	from EDD0001 a left join EDD0002 b on a.ID=b.ITEMID and b.ATTRCOD='GreenTyreSPEC'
	where a.ITTYPECOD='FT' AND a.FAC in ('01','03','11') ) A WHERE A.RowId=1 and SPEC<>'null' and SPEC<>'' and ITNBR like  '%'+@itnbrdd+'%' ), t_t2 as
	(SELECT MaterialID,isnull(convert(nvarchar(10), DATEDIFF(day,MAX(WDATE),getdate())),999999) StopDay 
	FROM tb_PP_CuringOutPut where MaterialID<>'' AND isnull(CUSTATE,'')  IN ('1','')   GROUP BY MaterialID ) ,
	t_t3 as (SELECT distinct A.ProductNum,a.DayNum,b.SPEC,b.NewSPEC FROM QLC0002 A LEFT JOIN QLC0003 B ON A.RuleCode=B.NewSPEC  where A.FAC in ('01','03','11') and NewSPEC  like '%'+@newspecdd+'%')
	select t_t1.spec,t_t3.NewSPEC,t_t1.ITNBR,t_t1.ITDSC,isnull(t_t2.StopDay,999999) StopDay,isnull(#l_t1.qty,0) qty,
	isnull(#l_t1.sday,999) sday,isnull(t_t3.DayNum,'-') DayNum,isnull(t_t3.ProductNum,'-') ProductNum 
	 ,isnull(t_t3.DayNum,0)-isnull(#l_t1.sday,0) cday,'' ATTRIBUTE3
	from t_t1  
	left join t_t2  on t_t1.ITNBR=t_t2. MaterialID  
	left join #l_t1 on t_t1.ITNBR=#l_t1.ITNBR  
	left join t_t3 on t_t1.SPEC=t_t3.SPEC  
	--where isnull(t_t1.ITNBR,'') like '%'+@itnbrdd+'%' and isnull(t_t3.NewSPEC,'') like '%'+@newspecdd+'%'
	order by SPEC
	drop table #l_t1
END
GO


