IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[f_GetPANum]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[f_GetPANum]
GO

CREATE FUNCTION [dbo].[f_GetPANum]()
returns varchar(20)
as
begin
declare @PANum varchar(20)
declare @time varchar(8)
set @time=RIGHT('00'+CONVERT(varchar,YEAR(getdate())),2)+RIGHT('00'+CONVERT(varchar,month(getdate())),2)+CONVERT(varchar,DAY(GETDATE()))--取到当前年月日
select @PANum='PA'+@time+RIGHT(100000+ISNULL(RIGHT(MAX(ORDERNOA),5),0)+1,5)--获取当前表最大值并加1
from PPB0201 where WDATE=CONVERT(varchar(30), GETDATE(), 23)
return @PANum
end
GO


