-- procedure structure for SET_LTC0002_PRO_IN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SET_LTC0002_PRO_IN]') AND type IN ('P', 'PC', 'RF', 'X'))
