GO

CREATE PROCEDURE [dbo].[SET_LTC0002_PRO_IN] 
	 @PLANCOD NVARCHAR(50),
	 @SECTION NVARCHAR(1)='0'
AS
BEGIN
	DECLARE @MCHID NVARCHAR(10);
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10); 

SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_GT WHERE PLANCOD=@PLANCOD;
 
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,PCSBOMWeight,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth INTO #T2 
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod

if(exists(select * from #T2))
	begin
		if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='PD'))
begin 
	 UPDATE QMA0014 SET TYPECOD='PD' WHERE MCHID=@MCHID  AND  TCOD='4-1'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='WG' WHERE MCHID=@MCHID  AND  TCOD='4-1'
END 
		if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB'))
begin 
--2023-09-21 修改 
--UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='SB' AND Usage='Belt #4'))
	BEGIN
		UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
	ELSE
	BEGIN
	 UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
END
		if(exists( select * from #T2 where ParentMatType=@outtypecod and SubMatTypeName='DE'  and Usage<>'Standard'))
begin 
	 UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage ASC)  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage DESC)  WHERE MCHID=@MCHID  AND  TCOD='9-2'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-2'
END 

	--声明表变量
	 declare @qma14tb table
	 (tcod nvarchar(50),TYPECOD nvarchar(50),COMPLOCATION nvarchar(150),LRFLAG nvarchar(150))
	 insert into @qma14tb (TCOD,COMPLOCATION,TYPECOD,LRFLAG  )
	 select TCOD,COMPLOCATION,TYPECOD,LRFLAG  from QMA0014 t with(nolock)  where MCHID=@MCHID

	update #T2 set PCSCuttinglength='' WHERE ParentMatType=@outtypecod AND   SubMatTypeName IN ('TD','PD')
	UPDATE LTC0002 SET NBRST='',DSCST='',XQTY=1,PLANCOD=@PLANCOD WHERE MCHID=@MCHID AND SECTION=@SECTION
	MERGE INTO LTC0002 A
	USING( SELECT q.TCOD,q.TYPECOD,t.SubMatID,CASE  WHEN q.TYPECOD ='JL' THEN convert(decimal(9,3), t.PCSBOMWeight) WHEN q.TYPECOD IN ('PTQ','BD') THEN 1.000 WHEN t.PCSCuttinglength='' THEN 1.000  ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty,EditionNo FROM QMA0014 q 
				inner join #T2 t on q.TYPECOD=t.subMatTypeName and q.COMPLOCATION=t.Usage  
				WHERE MCHID=@MCHID ) B ON A.LDIV=B.TCOD AND A.MCHID=@MCHID AND A.SECTION=@SECTION
	WHEN MATCHED THEN
	UPDATE SET SDIV=B.TYPECOD,NBRST=B.SubMatID,DSCST=B.SubMatID, XQTY=  B.XQTY,TVERSION=B.EditionNo;
	 


	drop table #T2
	end
else
	begin
		SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR AND SHFLAG='Y';
		select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,PCSBOMWeight,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth INTO #TT3 
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
if(exists( select * from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='PD'))
begin 
	 UPDATE QMA0014 SET TYPECOD='PD' WHERE MCHID=@MCHID  AND  TCOD='4-1'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='WG' WHERE MCHID=@MCHID  AND  TCOD='4-1'
END
		if(exists( select * from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='ZB'))
begin 
	 --2023-09-21修改
	--UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	if(exists( select * from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='SB' AND Usage='Belt #4'))
	BEGIN
		UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
	ELSE
	BEGIN
	 UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
END
		if(exists( select * from #TT3 where ParentMatType=@outtypecod and SubMatTypeName='DE'  and Usage<>'Standard'))
begin 
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage ASC)  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #TT3 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage DESC)  WHERE MCHID=@MCHID  AND  TCOD='9-2'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-2'
END 


	update #TT3 set PCSCuttinglength='' WHERE ParentMatType=@outtypecod AND   SubMatTypeName IN ('TD','PD')
	UPDATE LTC0002 SET NBRST='',DSCST='',XQTY=1,PLANCOD=@PLANCOD WHERE MCHID=@MCHID AND SECTION=@SECTION
	MERGE INTO LTC0002 A
	USING( SELECT q.TCOD,q.TYPECOD,t.SubMatID,CASE WHEN q.TYPECOD ='JL' THEN convert(decimal(9,3), t.PCSBOMWeight) WHEN q.TYPECOD IN ('PTQ','BD') THEN 1.000 WHEN t.PCSCuttinglength='' THEN 1.000   ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty,EditionNo FROM QMA0014 q 
				inner join #TT3 t on q.TYPECOD=t.subMatTypeName and q.COMPLOCATION=t.Usage  
				WHERE MCHID=@MCHID ) B ON A.LDIV=B.TCOD AND A.MCHID=@MCHID AND A.SECTION=@SECTION
	WHEN MATCHED THEN
	UPDATE SET SDIV=B.TYPECOD,NBRST=B.SubMatID,DSCST=B.SubMatID, XQTY=  B.XQTY,TVERSION=B.EditionNo;

		drop table #TT3

	end


END
GO


