-- ----------------------------
-- procedure structure for p_killspid
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[p_killspid]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[p_killspid]
GO

CREATE PROCEDURE [dbo].[p_killspid]
(
	@dbname   varchar(200)    --要关闭进程的数据库名
)
as
begin
    declare @sql     	nvarchar(500),
       		@spid   	nvarchar(20)
    declare   #tb   cursor   for
    select spid=cast(spid as Nvarchar(20))
      from master..sysprocesses
     where dbid=db_id(@dbname)
    open  #tb
    fetch  next from #tb into @spid
    while (@@fetch_status=0)
    begin
    	exec('kill '+@spid)
    	fetch next from #tb into @spid
    end
    close #tb
    deallocate #tb
END
GO


-- ----------------------------
-- function structure for GetMenuLevel
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetMenuLevel]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetMenuLevel]
GO

CREATE FUNCTION [dbo].[GetMenuLevel]
(
	-- Add the parameters for the function here
	@LSFW_MENUId							INT					
)
RETURNS INT
AS
BEGIN
	-- Declare the return variable here
	DECLARE @level											INT=0,
			@LSFW_MENUIdCopy								INT=@LSFW_MENUId

	WHILE(ISNULL(@level,0)=0 or ISNULL(@LSFW_MENUIdCopy,-1)<>-1)
	BEGIN
		SELECT @LSFW_MENUIdCopy=tmn.ROOTID
		FROM LSFW_MENU tmn
		WHERE tmn.ID=@LSFW_MENUIdCopy;

		SELECT @level=@level+1;
	END

	RETURN @level;
END
GO


-- ----------------------------
-- procedure structure for GetRoleAction
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRoleAction]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetRoleAction]
GO

CREATE PROCEDURE [dbo].[GetRoleAction]
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	--为后续各种关联 基础权限项 操作准备的表
	SELECT -1000 AS ORD,
			1 AS orderNum,
			'查看' AS ACTNAM
	INTO #tempNomACT
	UNION ALL 	
	SELECT -990 AS ORD,
			2,
		   '修改权' AS ACTNAM
	UNION ALL 	
	SELECT -980 AS ORD,
			3,
		   '删除权' AS ACTNAM

	--将所有权限项（一般+特殊）都 into 入#tempLSFW_MENUACT
	--先按照 LSFW_MENUACT （特殊权限项）表结构插入 特殊权限项
	SELECT CONVERT(NVARCHAR(70),ID) AS id,
			MENUID,
			ORD,
			ACTNAM,
			ACTTYP,
			BTNNAM,
			ENAM,
			ETIM
	INTO #tempLSFW_MENUACT
	FROM dbo.LSFW_MENUACT t
	--再把每个菜单项的一般权限项插入 #tempLSFW_MENUACT	
	INSERT INTO #tempLSFW_MENUACT
	(
		ID,
		MENUID,
		ORD,
		ACTNAM
	)
	SELECT NEWID() AS id,
			tm.ID AS MENUId,
			tna.ORD,
			tna.ACTNAM
	 FROM dbo.LSFW_MENU tm,#tempNomACT tna
	ORDER BY tm.ID,
			  tna.ORD
	--按照 菜单项 分组，#tempLSFW_MENUACT.ORD 排序，最终 ordNumber 输出列行号 = LSFW_ROLEACTION.ACTIONSTRING 字段对应位数
	SELECT t.*,
			tmn.MENUNAME, 
			tmn.ROOTID,
			--按照 菜单项 分组，#tempLSFW_MENUACT.ORD 排序（因为，我自己插入的一般权限项用的 -负数，所以，一般权限项会排在前面）
			ROW_NUMBER() OVER(PARTITION BY t.MENUID ORDER BY t.ORD) as ordNumber 
	INTO #tLSFW_MENUACTordNumber
	FROM #tempLSFW_MENUACT t
	LEFT JOIN dbo.LSFW_MENU tmn
	ON(t.MENUID=tmn.ID)
	--WHERE dbo.GetMenuLevel(t.MENUID)=3

	--将竖向的哪个 菜单项、哪些操作权限、哪个角色有（这个菜单项的这项权限）into 进 #tLSFW_ROLEACTIONUnPivot
	SELECT t.[ID],
			t.[ROLEID],
			t.[MENUID],
			t.[ACTIONSTRING],

			ta.MENUNAME,
			ta.ACTNAM,
			tr.ROLENAME,
			ta.ordNumber,
			ta.ROOTID,
			tr.ROLENAME+'('+tr.FAC+')' AS fullRolename --这是可以直接显示在Excel横向列上的列名
			--,
			--SUBSTRING(t.ACTIONSTRING,ta.ordNumber,1) 
	INTO #tLSFW_ROLEACTIONUnPivot --竖向的赋权记录
	 FROM dbo.LSFW_ROLEACTION t --赋权记录表
	LEFT join #tLSFW_MENUACTordNumber ta --权限项基础表竖过来
	ON(t.MENUID=ta.MENUID
	--整好用 ta.ordNumber 对 LSFW_ROLEACTION.ACTIONSTRING 的每一位
	AND SUBSTRING(t.ACTIONSTRING,ta.ordNumber,1)='1') -- LSFW_ROLEACTION.ACTIONSTRING 是比如，'100100' 这样的，前3位肯定有，分别表示 查询、修改、删除 权限
	LEFT JOIN dbo.LSFW_ROLE tr
	ON(t.ROLEID=tr.ID)

	
	DECLARE @roleIdListStr							NVARCHAR(max),
			@roleNameListStr						NVARCHAR(max)
	SELECT @roleIdListStr=ISNULL(@roleIdListStr,'') + ISNULL('['+CONVERT(NVARCHAR(100),tr.ID)+'],',''),
			@roleNameListStr=ISNULL(@roleNameListStr,'') + ISNULL('['+tr.ROLENAME+'('+tr.FAC+')'+'],','')
	FROM LSFW_ROLE tr WITH(NOLOCK)
	--GROUP BY tr.FAC,
	--		 tr.ROLENAME

	SELECT @roleIdListStr=SUBSTRING(@roleIdListStr,1,LEN(@roleIdListStr)-1),
			@roleNameListStr=SUBSTRING(@roleNameListStr,1,LEN(@roleNameListStr)-1)
			
	DECLARE @sql									NVARCHAR(max)
	SELECT @sql='SELECT traPivot.MENUID, --Excel中不用的列靠边
						tmn.[ORDER], --Excel中不用的列靠边
						tmn.MENUNAME as 主模块名称, -- 主模块名称（对应2级菜单项）
						traPivot.MENUNAME as 子模块名称, -- （对应3级菜单项）
						traPivot.ACTNAM as [事务代码描述/功能/菜单], -- （对应3级菜单项下的小操作项，相当于 LSFW_ROLEACTION.ACTNAM ）
						'''' as [事务代码], --Excel表有这列，但数据库中没有
						'''' as [重要性等级], --Excel表有这列，但数据库中没有
						'+@roleNameListStr+'
					FROM (select DISTINCT t.MENUID,
								 t.MENUNAME, 
								 t.ACTNAM, 
								 t.fullRolename,
								 t.RootId
							from #tLSFW_ROLEACTIONUnPivot t) traUp -- DISTINCT 写里面出来的数据条数是对的，写外面就会多出一个级别的条数数据
					PIVOT (
						COUNT(traUp.fullRolename) for fullRolename IN 
						('+@roleNameListStr+' ) '
					+ ' ) AS traPivot
					left join LSFW_MENU tmn
					on(traPivot.RootId=tmn.Id)
					--left join LSFW_ROLE tr
					--on(traPivot.RootId=tr.Id)
					where dbo.GetMenuLevel(traPivot.MENUID)=3 --只取第3级的记录，对应的第2级的父项名称显示在左面
					order by tmn.[ORDER],
							 traPivot.MENUNAME,
							 traPivot.ACTNAM ;'

	EXECUTE dbo.sp_executesql @sql 

	DROP TABLE #tLSFW_ROLEACTIONUnPivot
	DROP TABLE #tLSFW_MENUACTordNumber
	DROP TABLE #tempLSFW_MENUACT
	DROP TABLE #tempNomACT
END
GO


