-- ----------------------------
-- procedure structure for GetUserRole
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetUserRole]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetUserRole]
GO

CREATE PROCEDURE [dbo].[GetUserRole]
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	-- 最后横向显示 角色名，纵向显示 LSFW_EMPLOYEE 用户信息
	SELECT DISTINCT ISNULL(tr.ROLENAME +'(' + tr.FAC +')','') AS FullRolename, -- 角色名(工厂编号)
			tur.USERID -- LSFW_EMPLOYEE.Id
	INTO #tUserrole
	FROM LSFW_ROLE tr	
	LEFT JOIN LSFW_USERROLE tur
	ON(tur.ROLEID=tr.ID)
	
	DECLARE @roleNameListStr							NVARCHAR(4000)=''
	-- 构建下文 @sql 中横向 角色名(工厂编号) 部分
	SELECT @roleNameListStr=ISNULL(@roleNameListStr,'') + ISNULL('[' + tr.ROLENAME +'(' + tr.FAC +')],' ,'')
	FROM LSFW_ROLE tr	
	INNER JOIN LSFW_USERROLE tur
	ON(tr.ID=tur.ROLEID)
	GROUP BY tr.FAC,
			 tr.ROLENAME						
	ORDER BY tr.FAC,
			 tr.ROLENAME
	--去掉最后一个 ','
	SELECT @roleNameListStr=SUBSTRING(@roleNameListStr,1,LEN(@roleNameListStr)-1)
	--构建 pivot 语法语句
	DECLARE @sql						NVARCHAR(MAX)
	
	SELECT @sql='SELECT ''浦林成山（山东）轮胎有限公司'' as company, 
							tu.DEPNAM,
							tu.LOGINNAME,
							tu.NAME,
							tPvUr.* '
				+' FROM #tUserrole t
				pivot
				(
					COUNT(t.FullRolename)
					for t.FullROLENAME in ('+@roleNameListStr+')
				)  AS tPvUr '
				+' inner JOIN dbo.LSFW_EMPLOYEE tu '
				+' ON(tu.ID=tPvUr.USERID) '
				+' order by tu.DEPNAM; '

	EXECUTE dbo.sp_executesql @sql 


	DROP TABLE #tUserrole


END
GO


-- ----------------------------
-- function structure for f_GetPCNum
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[f_GetPCNum]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[f_GetPCNum]
GO

CREATE FUNCTION [dbo].[f_GetPCNum]()
returns varchar(20)
as
begin
declare @PANum varchar(20)
declare @time varchar(8)
set @time=RIGHT('00'+CONVERT(varchar,YEAR(getdate())),2)+RIGHT('00'+CONVERT(varchar,month(getdate())),2)+CONVERT(varchar,DAY(GETDATE()))--取到当前年月日
select @PANum='PC'+@time+RIGHT(100000+ISNULL(RIGHT(MAX(ORDERNOC),5),0)+1,5)--获取当前表最大值并加1
from PPB0201 where WDATE=CONVERT(varchar(30), GETDATE(), 23)
return @PANum
end
GO


-- ----------------------------
-- procedure structure for GET_PPB0202_HALFPRO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GET_PPB0202_HALFPRO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GET_PPB0202_HALFPRO]
GO

CREATE PROCEDURE [dbo].[GET_PPB0202_HALFPRO] 
	 @MCHID NVARCHAR(30)
AS
BEGIN
	 
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
declare @tbname nvarchar(20);
declare @outwidth float;
declare @inwidth float;
declare @cmd nvarchar(max); 
  
SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='5');
if(@outtypecod='SK')
BEGIN 
	if (exists(SELECT TOP 1 ITNBR FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='4')))
begin
	 SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='4');
end;
END 
ELSE
BEGIN
	if (exists(SELECT TOP 1 ITNBR FROM PAD0201_HALF WHERE MCHID=@MCHID AND   STA='4'))
begin
	 SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE MCHID=@MCHID AND   STA='4';
end;
END 



SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR AND SHFLAG='Y'; -- 2022-08-22 更改，审核过的最高版本，之前没有加审核 ;
 

with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight)
as
(
--初始查询
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
union all
--递归条件
select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth,a.PCSBOMWeight
from EDD0061 a 
inner join
temp b
on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
and b.EditionNo=a.ParentMatEditionNo)
)
select distinct * INTO #T2  from temp 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
MERGE INTO #T2 a
USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
 on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  
when matched then
update set SubMatID=b.SubMatID;

if(@outtypecod ='PSB')
BEGIN 
set @outwidth=0; 
--set @cmd=N'select top 1 @outwidth= PCSBeltWidth from PSB_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
 -- EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
 
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PSC')
		BEGIN
			select TOP 1 @inwidth= PCSRouteWidth from PSC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PSC') order by CONVERT(int, PCSSheetVersion) desc

