select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,CASE WHEN  PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1]  from #T2 temp INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 ON temp.SubMatTypeName=T1.TYPECOD AND T1.COMPLOCATION like  '%'+temp.Usage+'%' ; 
