-- ----------------------------
-- procedure structure for Transform_CureData_From_Old_MES
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Transform_CureData_From_Old_MES]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Transform_CureData_From_Old_MES]
GO

CREATE PROCEDURE [dbo].[Transform_CureData_From_Old_MES]
@BARCODE nvarchar(50), @ITNBR nvarchar(50), @ITDSC nvarchar(100), @MCHID_MAYBE_NOT_RIGHT nvarchar(10), @LRFLAG nvarchar(1), @MOLDNO nvarchar(50), @BLADNO nvarchar(50), @DOT nvarchar(4), @USERNO nvarchar(20), @USERNAM nvarchar(20), @CUTIM datetime, @custate nvarchar(3), @wdate date, @wsht nvarchar(1), @wban nvarchar(3)
WITH EXEC AS CALLER
AS
BEGIN
   SET  NOCOUNT ON;
   DECLARE @error   INT
   SET @error = 0
   DECLARE @MCHID   NVARCHAR (10)                                        --机台号
   --声明一个表用于获取班次信息（已经没用了）
   DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20),
                       FAC        NVARCHAR (20)
                    )

   --用新MES规格名称，如果没有再用旧MES
   DECLARE @tempITDSC   NVARCHAR (100)
   SET @tempITDSC = ''
   SELECT TOP 1
          @tempITDSC = ITDSC
   FROM EDD0001
   WHERE ITNBR = @ITNBR
   ORDER BY VERSION DESC

   IF @tempITDSC ! = ''
      SET @ITDSC = @tempITDSC

   --可能传过来的机台号位数不对，需补充
   IF LEN (@MCHID_MAYBE_NOT_RIGHT) < 5
      BEGIN
         SET @MCHID = '02LH' + @MCHID_MAYBE_NOT_RIGHT
      END
   ELSE
      BEGIN
         SET @MCHID = @MCHID_MAYBE_NOT_RIGHT
      END
   --处理工厂日期，中班的工厂日期需减去一天
   IF (@wsht = '2')
     BEGIN
       SET @wdate = dateadd(day,-1,@wdate)
     END
   --处理班次
   IF(@wsht = '1')
    BEGIN
      SET @wsht = '2'
    END
   ELSE IF(@wsht = '2')
    BEGIN
      SET @wsht = '3'
    END
   ELSE
    BEGIN
      SET @wsht = '1'
    END
   --处理班组
   IF(@wban = '61')
     BEGIN
       SET @wban = 'A'
     END
   ELSE IF(@wban = '62')
    BEGIN
      SET @wban = 'B'
    END
   ELSE
    BEGIN
      SET @wban = 'C'
    END
    
   --获取班次信息(已经没用了)
   INSERT INTO @shifttb
   EXEC LHGetShiftByTime @MCHID, @CUTIM
     
   --生产类型
   IF (@custate = '' or @custate is null)
     BEGIN
       SET @custate = '1'
     END
   ELSE
     BEGIN
       IF @custate = 'N'
         SET @custate = '1'
       ELSE
         SET @custate = '2'
     END
   --开始执行事务
   BEGIN TRANSACTION

   --LTA0001有则更新，无则插入
   IF NOT EXISTS
         (SELECT ID
          FROM LTA0001
          WHERE BARCODE = @BARCODE)
      INSERT INTO LTA0001 (ID,
                           FAC,
                           BARCODE,
                           CUDAT,
                           CUTIM,
                           CUSTIM,
                           CUETIM,
                           CUSHT,
                           CUBAN,
                           CUMCH,
                           LR,
                           CUITNBR,
                           CUITDSC,
                           MODCOD,
                           CUNAM,
                           CUNAMCOD,
                           CUSTATE,
                           TYRENO,
                           DOT,
                           ATTRIBUTE1)
      VALUES (newid (),
              '02',
              @BARCODE,
              @wdate,
              @CUTIM,
              @CUTIM,
              @CUTIM,
              @wsht,
              @wban,
              @MCHID,
              @LRFLAG,
              @ITNBR,
              @ITDSC,
              @MOLDNO,
              @USERNAM,
              @USERNO,
              @custate,
              @BARCODE,
              @DOT,
              '02')
   ELSE
      UPDATE LTA0001
      SET CUDAT = @wdate,
          CUTIM = @CUTIM,
          CUSTIM = @CUTIM,
          CUETIM = @CUTIM,
          CUSHT = @wsht,
          CUBAN = @wban,
          CUMCH = @MCHID,
          LR = @LRFLAG,
          CUITNBR = @ITNBR,
          CUITDSC = @ITDSC,
          MODCOD = @MOLDNO,
          CUNAM = @USERNAM,
          CUNAMCOD = @USERNO,
          CUSTATE = @custate,
          DOT = @DOT,
          ATTRIBUTE1 = '02'
      WHERE BARCODE = @BARCODE;

   SET @error = @error + @@ERROR

   --有则更新，无则插入
   IF NOT EXISTS
         (SELECT TyreNo
          FROM tb_PP_CuringOutPut
          WHERE TyreNo = @BARCODE)
      INSERT INTO tb_PP_CuringOutPut (TyreNo,
                                      ShiftNo,
                                      GreenTyreNo,
                                      MaterialID,
                                      PlanID,
                                      PlanDetailID,
                                      BeginTime,
                                      EndTime,
                                      QualityLevel,
                                      MouldID,
                                      BladderCount,
                                      MouldAmt,
                                      LeftOrRight,
                                      ArtID,
                                      DelayTime,
                                      Remark,
                                      RecorderID,
                                      RecordTime,
                                      CuringState,
                                      RealEndTime,
                                      IsFirstTyre,
                                      SulfEquipCode,
                                      SulfShift,
                                      SulfTeam,
                                      EmpName,
                                      EmpID,
                                      AllTime,
                                      DelayOpenMouldTime,
                                      JDEUPDATEFLAG,
                                      AssistTempState,
                                      GreenTyreTemp,
                                      EnvironmentTemp,
                                      TechChangeTime,
                                      StopTime,
                                      DingXing1,
                                      DingXing2,
                                      N2Value,
                                      S1,
                                      S2,
                                      S3,
                                      S4,
                                      FAC,
                                      DOT,
                                      MaterialName,
                                      WDATE,
                                      NORMALSTA,
                                      CUSTATE,
                                      BladderID)
      VALUES (@BARCODE,
              '',
              @BARCODE,
              @ITNBR,
              '',
              '',
              @CUTIM,
              @CUTIM,
              '',
              @MOLDNO,
              '0',
              '0',
              @LRFLAG,
              '',
              '0',
              '',
              '',
              @CUTIM,
              '正常',
              '0',
              '0',
              @MCHID,
              @wsht,
              @wban,
              @USERNAM,
              @USERNO,
              '0',
              '0',
              '0',
              '',
              '0.00',
              '0.00',
              '0.00',
              '0',
              '',
              'OLD',
              '',
              '',
              '',
              '',
              '',
              '02',
              @DOT,
              @ITDSC,
              @wdate,
              'Y',
              @custate,
              @BLADNO)
   ELSE
      UPDATE tb_PP_CuringOutPut
      SET WDATE = @wdate,
          RecordTime = @CUTIM,
          BeginTime = @CUTIM,
          EndTime = @CUTIM,
          MouldID = @MOLDNO,
          SulfShift = @wsht,
          SulfTeam = @wban,
          SulfEquipCode = @MCHID,
          LeftOrRight = @LRFLAG,
          MaterialID = @ITNBR,
          MaterialName = @ITDSC,
          EmpName = @USERNAM,
          EmpID = @USERNO,
          DOT = @DOT,
          CUSTATE = @custate,
          BladderID = @BLADNO,
          DingXing2 = 'OLD'
      WHERE TyreNo = @BARCODE;

   SET @error = @error + @@ERROR
   
   --有则更新，无则插入
  IF NOT EXISTS
         (SELECT TYRENO
          FROM QMB0101
          WHERE TYRENO = @BARCODE)
   INSERT INTO QMB0101 (FAC,
                        BARCODE,
                        TYRENO,
                        ITNBR,
                        ITDSC,
                        MCHID,
                        QCSTATE,
                        ATTRIBUTE1)
   VALUES ('02',
           @BARCODE,
           @BARCODE,
           @ITNBR,
           @ITDSC,
           @MCHID,
           '1',
           @custate)
  ELSE
    UPDATE QMB0101 SET ITNBR = @ITNBR,ITDSC = @ITDSC,MCHID = @MCHID, ATTRIBUTE1 = @custate
    WHERE TYRENO = @BARCODE;

   SET @error = @error + @@ERROR

   --有则更新，无则插入
   IF NOT EXISTS
         (SELECT TYRENO
          FROM WIP0010
          WHERE TYRENO = @BARCODE)
      INSERT INTO WIP0010 (FAC,
                           BARCODE,
                           MCHID,
                           LRFLAG,
                           WSHT,
                           WBAN,
                           ITNBR,
                           ITDSC,
                           STA,
                           WDATE,
                           WTIME,
                           STKSTS,
                           CRTIM,
                           UPDTIM,
                           STOAREA,
                           INLOC,
                           TYRENO,
                           STODIV,
                           LOCKYN,
                           REMARK,
                           TYRESTA,
                           DOT)
      VALUES ('02',
              @BARCODE,
              @MCHID,
              @LRFLAG,
              @wsht,
              @wban,
              @ITNBR,
              @ITDSC,
              '1',
              @wdate,
              @CUTIM,
              '11',
              @CUTIM,
              NULL,
              NULL,
              NULL,
              @BARCODE,
              NULL,
              'N',
              NULL,
              NULL,
              @DOT)
   ELSE
      UPDATE WIP0010
      SET WDATE = @wdate,
          WTIME = @CUTIM,
          CRTIM = @CUTIM,
          WSHT = @wsht,
          WBAN = @wban,
          MCHID = @MCHID,
          LRFLAG = @LRFLAG,
          ITNBR = @ITNBR,
          ITDSC = @ITDSC
      WHERE TYRENO = @BARCODE;

   SET @error = @error + @@ERROR

   --删除胎胚库存
   DELETE FROM WIP0002
   WHERE BARCODE = @BARCODE;

   SET @error = @error + @@ERROR

   --更新LTA0022的规格，供曲线采集
   IF @LRFLAG = 'L'
      BEGIN
         UPDATE LTA0022
         SET LITNBR = @ITNBR, LITDSC = @ITDSC, ETIM = getdate ()
         WHERE MCHID = @MCHID;
      END
   ELSE
      BEGIN
         UPDATE LTA0022
         SET RITNBR = @ITNBR, RITDSC = @ITDSC, ETIM = getdate ()
         WHERE MCHID = @MCHID;
      END

   SET @error = @error + @@ERROR

   IF @error <> 0
      BEGIN
         ROLLBACK TRANSACTION
      END
   ELSE
      BEGIN
         COMMIT TRANSACTION
      END
END
GO


-- ----------------------------
-- procedure structure for proSyncData
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[proSyncData]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[proSyncData]
GO

CREATE PROCEDURE [dbo].[proSyncData]
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @DBName									NVARCHAR(100)=DB_NAME()
	SELECT N'SYS_CHANGE_VERSION' AS CHANGETABLECol
	INTO #CHANGETABLECol
	UNION ALL
	SELECT N'SYS_CHANGE_CREATION_VERSION'
	UNION ALL
	SELECT N'SYS_CHANGE_OPERATION'
	UNION ALL
	SELECT N'SYS_CHANGE_COLUMNS'
	UNION ALL
	SELECT N'SYS_CHANGE_CONTEXT'
	
	--创建一个游标
	--目标库表名= 'Source_'+DB_NAME()+'_'+源库表名
	DECLARE my_cursor CURSOR FOR 
	SELECT DISTINCT t.name
	FROM sys.change_tracking_tables ctt WITH(NOLOCK)
	INNER JOIN sys.tables t WITH(NOLOCK)
	ON t.object_id = ctt.object_id
	INNER JOIN RCBDB003.PrinxQualityBigDataNew.sys.sysobjects tOr WITH(NOLOCK)
	ON(t.type = 'U'
	AND tOr.xtype='U'
	AND (t.name=tOr.name
	 OR tOr.name='Source_'+@DBName+'_'+t.name))

	--打开游标
	OPEN my_cursor;
	DECLARE @tableName								NVARCHAR(100)
	--循环游标
	FETCH NEXT FROM my_cursor
	INTO @tableName; --获取my_cursor的下一条数据
	WHILE @@FETCH_STATUS=0 
	BEGIN		
		CREATE TABLE #CHANGETABLE
		(
			[SYS_CHANGE_VERSION]					[BIGINT] NULL,
			[SYS_CHANGE_CREATION_VERSION]			[BIGINT] NULL,
			[SYS_CHANGE_OPERATION]					[NVARCHAR](100) NULL,
			[SYS_CHANGE_COLUMNS]					[VARBINARY](MAX) NULL,
			[SYS_CHANGE_CONTEXT]					[VARBINARY](MAX) NULL
		)		
		SELECT COLUMN_NAME
		INTO #KeyColumnName
		FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE t WITH(NOLOCK)
		where TABLE_NAME = @tableName

		DECLARE @alterCHANGETABLEsql										NVARCHAR(MAX)
		SELECT @alterCHANGETABLEsql=''
		SELECT @alterCHANGETABLEsql = ISNULL(@alterCHANGETABLEsql,'') + N'ALTER TABLE #CHANGETABLE ADD ['+tKey.COLUMN_NAME+'] nvarchar(100); '
		  FROM #KeyColumnName tKey
		EXECUTE SP_EXECUTESQL @alterCHANGETABLEsql

		DECLARE @insertCHANGETABLESql								NVARCHAR(MAX)
		SELECT @insertCHANGETABLESql='INSERT INTO #CHANGETABLE
									  SELECT *
									    FROM CHANGETABLE(CHANGES dbo.['+@tableName+'],0) as ct '

		EXECUTE SP_EXECUTESQL @insertCHANGETABLESql

		DECLARE @IdFieldSqlPart												NVARCHAR(MAX),
				@TableIdSqlPart												NVARCHAR(MAX),
				@TableIdFieldNameSqlPart									NVARCHAR(MAX),
				@IdFieldNameSqlPart											NVARCHAR(MAX),
				@index														INT=0,
				@tOldWhereSqlPart											NVARCHAR(MAX)

		SELECT @IdFieldSqlPart='',
				@TableIdSqlPart='',
				@IdFieldNameSqlPart='',
				@TableIdFieldNameSqlPart='',
				@index=1,
				@tOldWhereSqlPart=''

		SELECT @IdFieldSqlPart=ISNULL(@IdFieldSqlPart,'')+ISNULL(t.name+',',','),
				@TableIdSqlPart=ISNULL(@TableIdSqlPart,'')+ISNULL('TableId'+CONVERT(NVARCHAR(100),@index)+',',','),
				@IdFieldNameSqlPart=ISNULL(@IdFieldNameSqlPart,'')+ISNULL('''' + t.name+''',',','),
				@TableIdFieldNameSqlPart=ISNULL(@TableIdFieldNameSqlPart,'')+ISNULL('TableId'+CONVERT(NVARCHAR(100),@index)+'FieldName,',','),
				@tOldWhereSqlPart=ISNULL(@tOldWhereSqlPart,'')+ISNULL(' and t.[' + t.name+'] = tOld.['+ 'TableId'+CONVERT(NVARCHAR(100),@index) +'] COLLATE DATABASE_DEFAULT  ',','),
				@index=@index+1
		  FROM tempdb.sys.columns t WITH(NOLOCK)
		  WHERE object_id = object_id('tempdb..#CHANGETABLE') 
		  AND ISNULL(t.name,'') COLLATE DATABASE_DEFAULT NOT IN (SELECT tcol.CHANGETABLECol
																   FROM #CHANGETABLECol tcol)

		DECLARE @sql									NVARCHAR(max)
		SELECT @sql='insert into RCBDB003.PrinxQualityBigDataNew.dbo.SysCtGenZong '
					+' (
							SYS_CHANGE_VERSION,
							SYS_CHANGE_CREATION_VERSION,
							SYS_CHANGE_OPERATION,
							SYS_CHANGE_COLUMNS,
							SYS_CHANGE_CONTEXT,
							'+@TableIdSqlPart
							+@TableIdFieldNameSqlPart+'
							TableName,
							DbName,
							AddDate
						) 
						select SYS_CHANGE_VERSION,
								SYS_CHANGE_CREATION_VERSION,
								SYS_CHANGE_OPERATION,
								SYS_CHANGE_COLUMNS,
								SYS_CHANGE_CONTEXT,'
								+@IdFieldSqlPart
								+@IdFieldNameSqlPart
								+' @tableName, '
								+' @DBName, '	
								+' getdate() '						
						+' from #CHANGETABLE t '
						+' where not exists (select *
											   from RCBDB003.PrinxQualityBigDataNew.dbo.SysCtGenZong tOld with(nolock)
											  where tOld.tableName = @tableName  
												and tOld.DbName = @DBName '
											  + @tOldWhereSqlPart
											  +' ); '

					+' update tOld '
					+' set tOld.SYS_CHANGE_VERSION=t.SYS_CHANGE_VERSION,
							tOld.SYS_CHANGE_CREATION_VERSION=t.SYS_CHANGE_CREATION_VERSION,
							tOld.SYS_CHANGE_OPERATION=t.SYS_CHANGE_OPERATION,
							tOld.SYS_CHANGE_COLUMNS=t.SYS_CHANGE_COLUMNS,
							tOld.SYS_CHANGE_CONTEXT=t.SYS_CHANGE_CONTEXT,
							tOld.UpdateDate=getdate() '
					+' from #CHANGETABLE t, RCBDB003.PrinxQualityBigDataNew.dbo.SysCtGenZong tOld '
					+' where tOld.tableName=@tableName 
						 and tOld.DbName=@DBName
						 and (isnull(tOld.SYS_CHANGE_VERSION,0)<isnull(t.SYS_CHANGE_VERSION,0)
						  or isnull(tOld.SYS_CHANGE_CREATION_VERSION,0)<isnull(t.SYS_CHANGE_CREATION_VERSION,0)) '
					+@tOldWhereSqlPart

			EXECUTE SP_EXECUTESQL @sql,N'@tableName nvarchar(100),@DBName nvarchar(100)',@tableName=@tableName,@DBName=@DBName

			DROP TABLE #CHANGETABLE
			DROP TABLE #KeyColumnName	
			
			FETCH NEXT FROM my_cursor
			INTO @tableName;  --获取下一条数据并赋值给变量
	END; --关闭释放游标
	CLOSE my_cursor;
	DEALLOCATE my_cursor;

	DROP TABLE #CHANGETABLECol
END
GO


-- ----------------------------
-- procedure structure for GET_PPB0202_HALFPRO_BYPLANCOD
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GET_PPB0202_HALFPRO_BYPLANCOD]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GET_PPB0202_HALFPRO_BYPLANCOD]
GO

CREATE PROCEDURE [dbo].[GET_PPB0202_HALFPRO_BYPLANCOD] 
	 @PLANCOD NVARCHAR(50)
AS
BEGIN

DECLARE @MCHID NVARCHAR(20)	 
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
declare @tbname nvarchar(20);
declare @outwidth float;
declare @inwidth float;
declare @cmd nvarchar(max);
  
SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE PLANCOD=@PLANCOD;
--if (exists(SELECT TOP 1 ITNBR FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='4')))
--begin
--	 SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='4');
--end;

SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR  AND SHFLAG='Y';
 

with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight)
as
(
--初始查询
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
union all
--递归条件
select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth,a.PCSBOMWeight
from EDD0061 a 
inner join
temp b
on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
and b.EditionNo=a.ParentMatEditionNo)
)
select distinct * INTO #T2  from temp 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
MERGE INTO #T2 a
USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
 on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  
when matched then
update set SubMatID=b.SubMatID;

if(@outtypecod ='PSB')
BEGIN 
set @outwidth=0; 
--set @cmd=N'select top 1 @outwidth= PCSBeltWidth from PSB_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
 -- EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
 
	--找钢丝帘布的宽度
	if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PSC')
	BEGIN
		select TOP 1 @inwidth= PCSRouteWidth from PSC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PSC') order by CONVERT(int, PCSSheetVersion) desc

		if(@inwidth>0)
		begin
			update #t2 set PCSCuttinglength=1000
			update #t2 set PCSCuttinglength=(PCSCuttingWidth/@inwidth)*1000 where SubMatTypeName='PSC'
		end
	end 　 
END

if(@outtypecod ='PCC')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSWidth from PCC_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin 
	    --找纤维帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PFC')
		BEGIN
			select TOP 1 @inwidth= PCSRouteWidth from PSC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PFC') order by CONVERT(int, PCSSheetVersion) desc

			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000
				update #t2 set PCSCuttinglength=(@outwidth/@inwidth)*1000 where SubMatTypeName='PFC'
			end
		end 
	END
END

if(@outtypecod ='TD')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSMouldedlength from TD_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 规格长度*bom 重量，就是一条的重量
		update #t2 set PCSBOMWeight=(@outwidth * PCSBOMWeight)/1000 where SubMatTypeName='JL'
	END
END

if(@outtypecod ='PD')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSPartMouldedlength from PD_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 规格长度*bom 重量，就是一条的重量
		update #t2 set PCSBOMWeight=(@outwidth * PCSBOMWeight)/1000 where SubMatTypeName='JL'
	END
END

if(@outtypecod ='TR')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSPartMouldedlength from TR_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 规格长度*bom 重量，就是一条的重量
		update #t2 set PCSCuttinglength='' where SubMatTypeName<>'JL'
		update #t2 set PCSBOMWeight=(@outwidth * PCSBOMWeight)/1000 where SubMatTypeName='JL'
	END
END

if(@outtypecod ='CCF')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD=''M75'' WHERE ITNBR='''+@ITNBR+'''  and VERSION='''+@VERSION+'''  '
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 钢丝已经是换算过的，所以这里需要沟通更改
		update #t2 set PCSBOMWeight=@outwidth * PCSBOMWeight 
	END
END

if(@outtypecod ='SWR')
BEGIN 
 update #t2 set PCSCuttinglength='' WHERE SubMatTypeName<>'JL'
END

if(@outtypecod ='SB')
BEGIN 
set @outwidth=0;    
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='CCF')
		BEGIN 
			SELECT TOP 1 @inwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD='M75' WHERE ITNBR=(select top 1  SubMatID from #T2 where SubMatTypeName='CCF') order by CONVERT(int, A.VERSION) desc
			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000  
				update #t2 set PCSCuttinglength=(PCSCuttingWidth/@inwidth)*1000 where SubMatTypeName='CCF'
			end
		end 　 
END

if(@outtypecod ='CC')
BEGIN 
set @outwidth=0;    
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='CCF')
		BEGIN 
			SELECT TOP 1 @inwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD='M75' WHERE ITNBR=(select top 1  SubMatID from #T2 where SubMatTypeName='CCF') order by CONVERT(int, A.VERSION) desc
			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000  
				update #t2 set PCSCuttinglength=(PCSCuttingWidth/@inwidth)*1000 where SubMatTypeName='CCF'
			end
		end 　 
END

if(@outtypecod ='SK')
BEGIN 
set @outwidth=0; 
set @cmd=N'select top 1 @outwidth= ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD=''M75'' WHERE ITNBR='''+@ITNBR+'''  and VERSION='''+@VERSION+'''  '
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='TC')
		BEGIN
			SELECT TOP 1 @inwidth=ATTRVAL FROM EDD0001 A LEFT JOIN EDD0002 B ON A.ID=B.ITEMID AND B.ATTRCOD='M75' WHERE ITNBR=(select top 1  SubMatID from #T2 where SubMatTypeName='TC') order by CONVERT(int, A.VERSION) desc
			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000
				update #t2 set PCSCuttinglength=(@outwidth/@inwidth)*1000 where SubMatTypeName='TC'
			end
		end 　
	END
END

--select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,CASE WHEN  PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1]  from #T2 temp INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 ON temp.SubMatTypeName=T1.TYPECOD AND temp.Usage=T1.COMPLOCATION;
 
select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,CASE WHEN  PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1]  from #T2 temp INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 ON temp.SubMatTypeName=T1.TYPECOD AND T1.COMPLOCATION like  '%'+temp.Usage+'%' ;
drop table #T2
END
GO


