-- ----------------------------
-- procedure structure for InsPlan_LH_BG
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[InsPlan_LH_BG]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[InsPlan_LH_BG]
GO

CREATE PROCEDURE [dbo].[InsPlan_LH_BG]
(
	@MCHID NVARCHAR(30),		--机台号
	@WDATE DATETIME,			--计划日期
	@ITNBR NVARCHAR(50),		--规格代码
	@ITDSC NVARCHAR(80),		--规格名称
	@LR NVARCHAR(1),			--左右机台
	@PLQTYA INT,				--早班计划量
	@PLQTYB INT,				--中班计划量
	@PLQTYC INT,				--晚班计划量
	@ENAM NVARCHAR(20),			--修改人
	@STQTY1 INT,				--定额1
	@STQTY2 INT,				--定额2
	@STQTY3 INT,				 --定额3
    @SEQ INT					 --计划顺序
)
AS 
BEGIN
	DECLARE @FAC NVARCHAR(10),						--工厂代码 
			@ORDERNO NVARCHAR(20),					--工单号,
			@VERSION NVARCHAR(10),					--版本号,
			@MCHTYPECOD NVARCHAR(10),				--设备类型代码
			@OUTTYPECOD NVARCHAR(10),				--产出物料类型
			@BUITNBR NVARCHAR(50),					--胎胚规格代码
			@BUITDSC NVARCHAR(50),					--胎胚规格名称
			@COLORLINE NVARCHAR(50),				--色线
			@COLORLINE2 NVARCHAR(50),				--色线2
			@SPEC NVARCHAR(20),						--胎胚SPEC号
			@GreenTyreMaterialID NVARCHAR(50),		--轮胎胎胚规格代码
			@SubMatEditionNo NVARCHAR(10),			--胎胚规格版本
			@CUITDSC NVARCHAR(100)			--硫化规格代码
	--初始化变量 
	SET @FAC='';
	SET @ORDERNO='';
	SET @MCHTYPECOD='';
	SET @OUTTYPECOD='';
	SET @BUITNBR='';
	SET @BUITDSC='';
	SET @COLORLINE='';
	SET @COLORLINE2='';
	SET @SPEC='';
	SET @GreenTyreMaterialID='';
	SET @SubMatEditionNo='';
	SET @CUITDSC='';
	
	--获取设备类型代码,工厂代码                                                
		SELECT @MCHTYPECOD=TYPECOD,@FAC=e.FAC FROM EDC0001 AS e WHERE e.MCHID=@MCHID  
		
	--获取版本号，胎胚SPEC号，产出物料类型
		SELECT top 1 @VERSION=[VERSION],@SPEC=e.SPEC,@OUTTYPECOD=e.ITTYPECOD FROM EDD0001 AS e 
		WHERE e.ITNBR=@ITNBR AND ITGRPCOD='FERT' AND SHFLAG='Y'  and IS_USE=0 --e.FAC=@FAC AND
		order by [VERSION] desc
		
		SELECT @CUITDSC=ITDSC,@BUITNBR=E2.ATTRVAL FROM EDD0001 
		LEFT JOIN EDD0002  E2 ON EDD0001.ID=E2.ITEMID AND E2.ATTRCOD='GreenTyreSPEC'
		WHERE ITNBR=@ITNBR AND ITGRPCOD='FERT'  AND VERSION=@VERSION

	--获取色线 
		SELECT TOP 1 @BUITDSC=ITDSC,@GreenTyreMaterialID=ITNBR,@SubMatEditionNo=VERSION FROM  EDD0001  
		WHERE SPEC=@BUITNBR AND CLASSDIV='半钢'  AND ITGRPCOD='GT' ORDER BY CONVERT(INT,VERSION) DESC
		
		--SELECT TOP 1 @GreenTyreMaterialID=GreenTyreMaterialID,@SubMatEditionNo=T2.VERSION 
		--FROM edd0006 T1 
		--LEFT JOIN EDD0001 T2 ON T1.GreenTyreMaterialID=T2.ITNBR 
		--WHERE TyreMaterialID=@ITNBR AND T1.EditionNo=@VERSION ORDER BY T2.VERSION desc
		--if @GreenTyreMaterialID=''
		--begin
		--	SELECT TOP 1 @GreenTyreMaterialID=GreenTyreMaterialID,@SubMatEditionNo=SubMatEditionNo 
		--	FROM edd0006 T1  
		--	WHERE TyreMaterialID=@ITNBR    
		--end
 
		SELECT @COLORLINE=ATTRVAL  FROM EDD0002 WHERE ITEMID=
(SELECT TOP 1 ID FROM EDD0001 WHERE  ITNBR  =
( SELECT top 1 SubMatID  FROM EDD0061 AS e WHERE
 e.ParentMatID=@GreenTyreMaterialID AND SubmatTypeName='PTD' ORDER BY CONVERT(INT,ParentMatEditionNo) DESC)  ORDER BY CONVERT(INT,VERSION) DESC) AND ATTRCOD='M96'
 
		SELECT @COLORLINE2=ATTRVAL  FROM EDD0002 WHERE ITEMID=
(SELECT TOP 1 ID  FROM EDD0001 WHERE   ITNBR  =
( SELECT top 1 SubMatID  FROM EDD0061 AS e WHERE
 e.ParentMatID=@GreenTyreMaterialID AND SubmatTypeName='PTD' ORDER BY CONVERT(INT,ParentMatEditionNo) DESC)  ORDER BY CONVERT(INT,VERSION) DESC) AND ATTRCOD='M12'
		set @COLORLINE=@COLORLINE+'('+@COLORLINE2+')';
	--获取计划顺序,当前机台当前左右的最大的顺序+1  
		--SELECT @SEQ=CASE WHEN MAX(p.SEQA) IS NULL THEN 1 ELSE MAX(p.SEQA)+1 END FROM PLA0009 p 
		--WHERE p.MCHID=@MCHID AND p.WDATE=@WDATE AND p.ATTRIBUTE1='FERT' AND LR=@LR --p.FAC=@FAC AND 
		
	--获取胎胚规格信息
		--SELECT TOP 1 @BUITDSC=ITDSC FROM  EDD0001  
		--WHERE SPEC=@BUITNBR 

	IF @CUITDSC<>''
	BEGIN
		SET @ITDSC=@CUITDSC
	END

    IF @ITNBR is null
	BEGIN
		SET @ITNBR=''
	END
	IF @ITDSC is null
	BEGIN
		SET @ITDSC=''
	END
	IF @LR='A'--左右机台
	BEGIN
		--获取工单号
		--SELECT @ORDERNO=dbo.GetPLANNO_LH(@WDATE,'L',@MCHID,@SEQ);
		--左机台
		INSERT INTO PLB0009
		(
			ID,
			FAC,
			DIV,
			MCHTYPECOD,
			OUTTYPECOD,
			WDATE,
			MCHID,
			LR,
			ITNBR,
			ITDSC,
			PLQTY1,
			PLQTY2,
			PLQTY3,
			PLQTY,
			PLLOT1,
			PLLOT2,
			PLLOT3,
			PLLOT,
			[STATE],
			ENDCK,
			ENAM,
			ETIM,
			SEQA,
			SEQB,
			SEQC,
			VERSION,
			BOMVER,
			ORDERNOA,
			ORDERNOB,
			ORDERNOC,
			BUITNBR,
			BUITDSC,
			ATTRIBUTE1,
			ATTRIBUTE2,
			COLORLINE,
			SPEC,
			STQTY1,
			STQTY2,
			STQTY3,
			STQTY
		)
		VALUES
		(
			NEWID(),
			@FAC,
			'1',
			@MCHTYPECOD,
			@OUTTYPECOD,
			@WDATE,
			@MCHID,
			'L',
			@ITNBR,
			@ITDSC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			'1',
			'N',
			@ENAM,
			GETDATE(),
			@SEQ,
			@SEQ,
			@SEQ,
			@VERSION,
			@SubMatEditionNo,
			'',
			'',
			'',
