-- ----------------------------
-- procedure structure for SETQCWIP0002
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SETQCWIP0002]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SETQCWIP0002]
GO

CREATE PROCEDURE [dbo].[SETQCWIP0002] 
AS
BEGIN
	 SET LOCK_TIMEOUT 5000
	 DECLARE @Now DATETIME = GETDATE();
	 merge into WIP0002 W
USING( 
--SELECT A.BARCODE,
--CASE WHEN DATEDIFF(HOUR,A.WTIME,GETDATE())>EXPTIM then 2
--when DATEDIFF(HOUR,A.WTIME,GETDATE()) < CYCLTIM then 4
--when DATEDIFF(HOUR,A.WTIME,GETDATE()) >= CYCLTIM and DATEDIFF(HOUR,A.WTIME,GETDATE()) <= exptim then 1 end STA
--FROM WIP0002 A LEFT JOIN EDD0001 B 
--ON A.ITNBR=B.ITNBR AND B.ITGRPCOD='GT' AND A.VERSION=B.VERSION 
--WHERE ISNULL(A.IS_DELETE,0)=0 and A.STA<>6  and a.fac<>'02'
SELECT A.BARCODE,
CASE WHEN DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60>isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 2
when DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60 < isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) then 4
when DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60 >=  isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) and DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60 <= isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 1 end STA
FROM WIP0002 A LEFT JOIN EDD1001 E1 ON A.ITNBR=E1.ITNBR AND E1.DIV='GT' AND  E1.ATTRCOD='EXPTIM' 
 LEFT JOIN EDD1001 C1 ON A.ITNBR=C1.ITNBR AND C1.DIV='GT' AND  C1.ATTRCOD='CYCLTIM' 
 LEFT JOIN EDD0003 D ON D.ITTYPECOD='GT'   
WHERE ISNULL(A.IS_DELETE,0)=0 and A.STA in ('1','2','4')  and a.fac<>'02'
) T1
ON W.BARCODE=T1.BARCODE AND  W.STA<>T1.STA
WHEN MATCHED THEN 
UPDATE SET  STA=T1.STA 
OPTION (MAXDOP 1);  -- 👈 关键：禁用并行
END
GO


