-- procedure structure for SET_LTC0002_HALFPRO_OUT
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SET_LTC0002_HALFPRO_OUT]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SET_LTC0002_HALFPRO_OUT]
GO

CREATE PROCEDURE [dbo].[SET_LTC0002_HALFPRO_OUT] 
	 @PLANCOD NVARCHAR(50)
AS
BEGIN
	DECLARE @MCHID NVARCHAR(10);
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
declare @tbname nvarchar(20);
declare @outwidth float;
declare @inwidth float;
declare @cmd nvarchar(max);
  
  

SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE PLANCOD=@PLANCOD;
SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR AND ITTYPECOD=@outtypecod AND SHFLAG='Y'; -- 2022-08-22 更改，审核过的最高版本，之前没有加审核
 --2025-07-03 更改计划版本
update PAD0201_HALF set VERSION=@VERSION where PLANCOD=@PLANCOD and VERSION<>@VERSION;
with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight)
as
(
--初始查询
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
union all
--递归条件
select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth,a.PCSBOMWeight
from EDD0061 a 
inner join
temp b
on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
and b.EditionNo=a.ParentMatEditionNo)
)
select distinct * INTO #T2  from temp 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
MERGE INTO #T2 a
USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
 on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  
when matched then
update set SubMatID=b.SubMatID;

--2026-07-08 新增，产出逻辑*2
if(@outtypecod ='NDE')
BEGIN 
 update #t2 set PCSCuttinglength=PCSCuttinglength*2 where SubMatTypeName='PDE'
END

--2024-11-29 新增  半钢纤维帘布换算,和全钢大卷一样

if(@outtypecod ='PFC')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSWidth from PFC_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 钢丝已经是换算过的，所以这里需要沟通更改
		update #t2 set PCSBOMWeight=@outwidth/1000 * PCSBOMWeight 
	END
END

if(@outtypecod ='PSB')
BEGIN 
set @outwidth=0; 
set @cmd=N'select top 1 @outwidth= PCSBeltWidth from PSB_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PSC')
		BEGIN
			select TOP 1 @inwidth= PCSRouteWidth from PSC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PSC') order by CONVERT(int, PCSSheetVersion) desc

			if(@inwidth>0)
			begin
				update #t2 set PCSCuttinglength=1000
				update #t2 set PCSCuttinglength=(@outwidth/@inwidth)*1000 where SubMatTypeName='PSC'
			end
		end 　
	END
END

