-- ----------------------------
-- procedure structure for SETQCWIP0001
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SETQCWIP0001]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SETQCWIP0001]
GO

CREATE PROCEDURE [dbo].[SETQCWIP0001] 
AS
BEGIN
	 merge into WIP0001 W
USING( 
--SELECT A.LOTID,
--CASE WHEN DATEDIFF(HOUR,A.WTIME,GETDATE())>EXPTIM then 2
--when DATEDIFF(HOUR,A.WTIME,GETDATE())< CYCLTIM then 4
--when DATEDIFF(HOUR,A.WTIME,GETDATE()) >= CYCLTIM and DATEDIFF(HOUR,A.WTIME,GETDATE()) <= exptim then 1 end STA
--FROM WIP0001 A LEFT JOIN (select case when a.EXPTIM=0 then b.EXPTIM else a.EXPTIM end exptim,
-- case when a.CYCLTIM=0 then b.CYCLTIM else a.CYCLTIM end CYCLTIM,a.ITNBR,a.ITTYPECOD,
-- row_number() over ( partition by a.itnbr,a.ittypecod  order by cast([version] as int )  desc) rw
-- from EDD0001 a left join EDD0003 b on a.ittypecod=b.ittypecod where B.ITGRPCOD='HALF') as B  
--ON A.DIV=B.ITTYPECOD AND B.RW=1 AND A.ITNBR=B.ITNBR
--WHERE ISNULL(A.IS_DELETE,0)=0 and A.STA<>6 and a.fac<>'02'
SELECT A.LOTID, 
CASE WHEN DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60 >isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 2
when DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60  < isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) then 4
when DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60  >=  isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) and DATEDIFF(MINUTE,A.WTIME,GETDATE())* 1.0 / 60  <= isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 1 end STA
FROM WIP0001 A LEFT JOIN EDD1001 E1 ON A.ITNBR=E1.ITNBR AND E1.DIV=a.DIV AND  E1.ATTRCOD='EXPTIM' 
 LEFT JOIN EDD1001 C1 ON A.ITNBR=C1.ITNBR AND C1.DIV=a.DIV AND  C1.ATTRCOD='CYCLTIM' 
 LEFT JOIN EDD0003 D ON D.ITTYPECOD=a.DIV  
WHERE ISNULL(A.IS_DELETE,0)=0 and A.STA in (1,2,4) and a.fac<>'02'
) T1
ON W.LOTID=T1.LOTID AND  W.STA<>T1.STA
WHEN MATCHED THEN 
UPDATE SET  STA=T1.STA ;

END
GO


-- ----------------------------
-- procedure structure for PROC_LH_PERSON1
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[PROC_LH_PERSON1]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[PROC_LH_PERSON1]
GO

CREATE PROCEDURE [dbo].[PROC_LH_PERSON1]
@FAC NVARCHAR(10),@WDATE1 NVARCHAR(10),@WDATE2 NVARCHAR(10) ,@WHERESTR NVARCHAR(500)
AS
BEGIN

--DECLARE @EDDTB TABLE
--(
--	spec nvarchar(10),
--	itnbr nvarchar(50),
--	ITDSC nvarchar(200),
--	ITTYPECOD nvarchar(50),
--	VERSION nvarchar(50),
--	ERPCODE nvarchar(50)
--)
 
--insert into @EDDTB(spec,itnbr,ITDSC,ITTYPECOD, VERSION,  ERPCODE)
SELECT MAX(ATTRVAL) spec, ITNBR, ITDSC,ITTYPECOD, VERSION,  ERPCODE INTO #TB_SPEC FROM EDD0001 e1 LEFT JOIN EDD0002 e2 on e1.ID=e2.ITEMID and e2.ATTRCOD='GreenTyreSPEC'    WHERE e1.ID IN
  (select id from ( SELECT ID,row_number() over (partition by itnbr,ITTYPECOD order by RIGHT('0000000000'+REPLACE(e.[VERSION], ' ', ''),10) desc) ROWNUM 
 FROM EDD0001 AS e 
  WHERE  ITGRPCOD='FERT' AND IS_USE=0 AND SHFLAG='Y' ) T
  where T.ROWNUM=1)  GROUP BY ITNBR, ITDSC,ITTYPECOD, VERSION,  ERPCODE
   

	exec ( N'SELECT T1.*,ISNULL(T2.PLLOT,0) PLLOT FROM (
			 SELECT  WDATE,EmpID,EmpName,SulfEquipCode,SulfShift,COUNT(*) TOPUT,GTSPEC   FROM 
			 (  SELECT FORMAT (WDATE,''yyyy-MM-dd'') WDATE,EmpID,EmpName,SulfEquipCode,SulfShift,MaterialID,b.spec GTSPEC FROM tb_PP_CuringOutPut a
			  left join #TB_SPEC b on a.MaterialID=b.ITNBR
             WHERE    WDATE BETWEEN '''+@WDATE1+''' AND '''+@WDATE2+''' AND FAC='''+@FAC+''' AND ISNUMERIC(TyreNo)=1'+@WHERESTR+' ) AA  
			 GROUP BY WDATE,EmpID,EmpName,SulfEquipCode,SulfShift,GTSPEC ) T1
			 	 LEFT JOIN (  SELECT ITNBR,WSHT,SUM(PLLOT) PLLOT,MCHID,WDATE FROM
						(
						SELECT BUITNBRL ITNBR, WSHT,SUM(PLLOT)/2 PLLOT,MCHID,WDATE FROM PAD0201 WITH(NOLOCK) 
						  WHERE  FAC='''+@FAC+''' AND ATTRIBUTE1=''FERT'' AND WDATE BETWEEN '''+@WDATE1+''' AND '''+@WDATE2+'''  
						  GROUP BY BUITNBRL,WSHT,MCHID,WDATE--左规格计划量
						UNION ALL
						SELECT BUITNBRR ITNBR, WSHT,SUM(PLLOT)/2 PLLOT,MCHID,WDATE FROM PAD0201 WITH(NOLOCK) 
						  WHERE  FAC='''+@FAC+''' AND ATTRIBUTE1=''FERT'' AND WDATE BETWEEN '''+@WDATE1+''' AND '''+@WDATE2+'''   
						  GROUP BY BUITNBRR,WSHT,MCHID,WDATE--右规格计划量
						) T 
			GROUP BY ITNBR,WSHT,MCHID,WDATE ) T2 ON T1.GTSPEC=T2.ITNBR AND T1.SulfEquipCode=T2.MCHID AND T1.SulfShift=T2.WSHT  and T1.WDATE=t2.WDATE
          ORDER BY WDATE,SulfShift,SulfEquipCode');

		  drop table #TB_SPEC
END
GO


-- ----------------------------
-- procedure structure for SET_LTC0002_HALFPRO_IN
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SET_LTC0002_HALFPRO_IN]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SET_LTC0002_HALFPRO_IN]
GO

CREATE PROCEDURE [dbo].[SET_LTC0002_HALFPRO_IN] 
	 @PLANCOD NVARCHAR(50)
AS
BEGIN
	DECLARE @MCHID NVARCHAR(10);
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
declare @tbname nvarchar(20);
declare @outwidth float;
declare @inwidth float;
declare @cmd nvarchar(max);
  
  

SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE PLANCOD=@PLANCOD;
SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR AND ITTYPECOD=@outtypecod AND SHFLAG='Y'; -- 2022-08-22 更改，审核过的最高版本，之前没有加审核
 --2025-07-03 更改计划版本
update PAD0201_HALF set VERSION=@VERSION where PLANCOD=@PLANCOD and VERSION<>@VERSION;
with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight)
as
(
--初始查询
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
union all
--递归条件
select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth,a.PCSBOMWeight
from EDD0061 a 
inner join
temp b
on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
and b.EditionNo=a.ParentMatEditionNo)
)
select distinct * INTO #T2  from temp 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
MERGE INTO #T2 a
USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
 on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  
when matched then
update set SubMatID=b.SubMatID;


--2026-07-08 新增，产出逻辑*2
if(@outtypecod ='NDE')
BEGIN 
 update #t2 set PCSCuttinglength=PCSCuttinglength*2 where SubMatTypeName='PDE'
END

--2024-11-29 新增  半钢纤维帘布换算,和全钢大卷一样

if(@outtypecod ='PFC')
BEGIN 
set @outwidth=0;  
set @cmd=N'select top 1 @outwidth= PCSWidth from PFC_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
	-- 钢丝已经是换算过的，所以这里需要沟通更改
		update #t2 set PCSBOMWeight=@outwidth/1000 * PCSBOMWeight 
	END
END

if(@outtypecod ='PSB')
BEGIN 
set @outwidth=0; 
set @cmd=N'select top 1 @outwidth= PCSBeltWidth from PSB_EDD02 where PLM_CODE='''+@ITNBR+'''  and PCSMachineId='''+@mchid+''' order by CONVERT(int, PCSSheetVersion) desc'
  EXEC  sp_executesql  @cmd, N'@outwidth float output',@outwidth output;
	if(@outwidth>0)
	begin
		--找钢丝帘布的宽度
		if exists(SELECT TOP 1 * FROM QMA0014 WHERE MCHID=@MCHID AND TYPECOD='PSC')
		BEGIN
			select TOP 1 @inwidth= PCSRouteWidth from PSC_EDD02 where PLM_CODE=(select top 1  SubMatID from #T2 where SubMatTypeName='PSC') order by CONVERT(int, PCSSheetVersion) desc

			if(@inwidth>0)
