--2023-03-02 更改，特殊多个投入口位置号，逻辑更改，轮询去取得判断，注释的是原有逻辑
--UPDATE LTC0002 WITH(UPDLOCK)
--                  SET SDIV=C.TYPECOD,
--                      NBRST=C.SubMatID,
--                      DSCST=C.SubMatID,
--                      XQTY=  C.XQTY,
--					  JLXQTY=C.PCSBOMWeight,
--					  PLANCOD=@PLANCOD
--                  FROM LTC0002 D 
--                      INNER JOIN ( SELECT q.TCOD,q.TYPECOD,t.SubMatID,t.PCSBOMWeight,CASE WHEN  t.PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty FROM QMA0014 q 
--					inner join #T2 t on q.TYPECOD=t.subMatTypeName and q.COMPLOCATION LIKE '%'+t.Usage+'%' 
--					WHERE MCHID=@MCHID  ) C ON D.LDIV = C.TCOD
--                  WHERE D.MCHID=@MCHID 

--声明表变量
 declare @qma14tb table
 (tcod nvarchar(50),TYPECOD nvarchar(50),COMPLOCATION nvarchar(150))
 insert into @qma14tb (TCOD,COMPLOCATION,TYPECOD  )
 select TCOD,COMPLOCATION,TYPECOD  from QMA0014 t with(nolock)  where MCHID=@MCHID

DECLARE @COMPLOCATION NVARCHAR(150),@TYPECOD nvarchar(50),@TCOD	 nvarchar(50);
declare cur_sor cursor--第一个游标循环。轮询所有特殊投入口
for
(select TCOD,COMPLOCATION,TYPECOD  from @qma14tb t   where COMPLOCATION LIKE '%,%')--多项目投入口 找出来
open cur_sor
fetch next from cur_sor into @tcod,@COMPLOCATION,@TYPECOD
while @@FETCH_STATUS=0
begin
	declare @compla nvarchar(50);
	if exists(select top 1 * from #T2 where   subMatTypeName=@TYPECOD )
	begin
		declare nbyb cursor
		for
		(SELECT VALUE FROM STRING_SPLIT(@COMPLOCATION,','))-- 
		open nbyb
		fetch next from nbyb into @compla
		while @@FETCH_STATUS=0
		begin
		if exists(select top 1 * from #T2 where   subMatTypeName=@TYPECOD and Usage=@compla )
		begin 
		 update @qma14tb set COMPLOCATION=@compla where tcod=@TCOD
		 break;
		end
		fetch next from nbyb into @compla
		end
		close nbyb
		deallocate nbyb
	end
	else
	begin
		declare nbyb cursor
		for
		(SELECT VALUE FROM STRING_SPLIT(@COMPLOCATION,','))-- 
		open nbyb
		fetch next from nbyb into @compla
		while @@FETCH_STATUS=0
		begin
		if exists(select top 1 * from #T2 where   Usage=@compla )--轮询看看BOM里面有没有投入口的规格，如果有就不继续，并且更新表变量的位置号,2024-3-18 更改，存在类型不是配置得类型得情况
		begin 
		 update @qma14tb set COMPLOCATION=@compla,TYPECOD=(select top 1 subMatTypeName from #T2 where    Usage=@compla) where tcod=@TCOD
		 break;
		end
		fetch next from nbyb into @compla
		end
		close nbyb
		deallocate nbyb
	end
	fetch next from cur_sor into @tcod,@COMPLOCATION,@TYPECOD
end
close cur_sor
deallocate cur_sor

UPDATE LTC0002 SET NBRST='',DSCST='' WHERE MCHID=@MCHID
UPDATE LTC0002 WITH(UPDLOCK)
                  SET SDIV=C.TYPECOD,
                      NBRST=C.SubMatID,
                      DSCST=C.SubMatID, 
					  PLANCOD=@PLANCOD
                  FROM LTC0002 D 
                      INNER JOIN ( SELECT q.TCOD,q.TYPECOD,t.SubMatID,t.PCSBOMWeight,CASE WHEN  t.PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), t.PCSCuttinglength)/1000 end xqty FROM VIEW_QMA0014_USAGE q 
					inner join #T2 t on q.TYPECOD=t.subMatTypeName and q.USAGE = t.Usage  WHERE MCHID=@MCHID   ) C ON D.LDIV = C.TCOD
                  WHERE D.MCHID=@MCHID 


				  
update LTC0002 SET DIV=6
FROM LTC0002 A LEFT JOIN EDD0663 B ON A.NBRST=B.MatID WHERE 
(NBRRE<>NBRST AND ISNULL(B.SubMatID,'')<>A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID

update LTC0002 SET DIV=1
FROM LTC0002 A LEFT JOIN EDD0663 B ON A.NBRST=B.MatID WHERE 
(NBRST=NBRRE OR ISNULL(B.SubMatID,'')=A.NBRRE) AND LOTID<>'' AND MCHID=@MCHID

drop table #T2
END
GO


-- ----------------------------
-- procedure structure for alllc_pro_cta
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[alllc_pro_cta]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[alllc_pro_cta]
GO

CREATE PROCEDURE [dbo].[alllc_pro_cta] @itnbrdd nvarchar(50),@newspecdd nvarchar(30)
AS
BEGIN 
	

SELECT itnbr,MAX(OutDate) wdate,DATEDIFF(day,MAX(OutDate),getdate()) sday,0 qty into #l_t2 
FROM QLC0010 where [State]>3 AND FAC in  ('01','03','11')
--AND planno not like 'FJ%'   --赵群超 抓取CTA的要一起抓取手动的 2025.09.12
group by ITNBR; 
--查询上一次例查计划后已生产条数更新
MERGE INTO #l_t2 a
	using(
	SELECT COUNT(*) QTY,ITNBR,B.OUTDATE FROM TB_PP_CURINGOUTPUT A 
	   inner JOIN 
	   (       
		  SELECT itnbr,MAX(OUTDATE) OUTDATE   FROM QLC0010 where [State]>3  AND FAC in  ('01','03','11')
		 -- AND  planno not like 'FJ%' 
		   group by ITNBR
	   ) B ON A.MaterialID=B.ITNBR AND A.BeginTime>B.OUTDATE AND A.CUSTATE  IN ('1','')
	   GROUP BY ITNBR,OUTDATE   
   ) b
on a.itnbr=b.itnbr AND a.wdate=b.OUTDATE 
when MATCHED THEN
UPDATE set a.qty=b.qty;



	with
	t_t1 AS --查询产品表找到SPEC对应规格
	(
	 
		SELECT * FROM 
		(
			select distinct ATTRVAL SPEC ,a.ITNBR,a.ITDSC, 	ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY right ('0000000000'+[VERSION],10) DESC) RowId  
			from EDD0001 a 
			left join EDD0002 b on a.ID=b.ITEMID and b.ATTRCOD='GreenTyreSPEC'
			where a.ITTYPECOD='FT' AND a.FAC in  ('01','03','11')
		) A 
		WHERE A.RowId=1 and SPEC<>'null' and SPEC<>''  and ITNBR like '%'+@itnbrdd+'%'
	),
	t_t2 as --停产时长
	(
		
		SELECT MaterialID,isnull(convert(nvarchar(10), DATEDIFF(day,MAX(WDATE),getdate())),999999) StopDay 
		FROM tb_PP_CuringOutPut 
		where BeginTime>( DATEADD(DAY,-300,GETDATE()) ) and FAC in ('01','03','11') and  MaterialID<>''
		 AND isnull(CUSTATE,'')  IN ('1','')  GROUP BY MaterialID 
	),
	t_t3 as --查例查基础规则获取自然天
	(
	  SELECT distinct A.ProductNum,a.DayNum,b.SPEC,b.NewSPEC 
	  FROM QLC0002 A 
	  LEFT  JOIN QLC0003 B ON A.RuleCode=B.NewSPEC  
	  where A.FAC in ('01','03','11') and NewSPEC like '%'+@newspecdd+'%'
	),
	t2 as  --查询已做例查计划中存在CTA项的数据
	(
		SELECT itnbr,MAX(OutDate) wdate,DATEDIFF(day,MAX(OutDate),getdate()) sday,90-DATEDIFF(day,MAX(OutDate),getdate())  cday
		FROM QLC0010 q10
		inner join QLC0010_1 q101 on q10.PlanNo=q101.PlanNo
		where [State]>3 AND q10.FAC in ('01','03','11')
		--AND q10.planno not like 'FJ%' 
		and q101.ItemCode='1433273876393152'  
		group by ITNBR
	),
	t3 as --SPEC下只要有一个规格小于120天，整个SPEC下的所有规格都不推送，即max(cday)>0 获取需要生成例查的SPEC
	(	
	select  SPEC,   max(cday) cdayMAX, case when min(cday) is null then  -999 else min(cday) end cdayMIN   from  t_t1
	left join t2 on t_t1.ITNBR = t2.ITNBR
	group by SPEC having max(cday)<0 or max(cday) is null	
	),
	t4 as  --取一个差额天数最大的推送一个，过滤掉已停产规格
	(
		select tt.*,t3.cdayMIN cday from
		(
			select  t_t1.*,	ROW_NUMBER() OVER (PARTITION BY SPEC ORDER BY wdate asc,t_t1.itnbr) SPECId ,t2.sday   
			from  t_t1
			inner join t_t2 on  t_t1.ITNBR = t_t2.MaterialID
			left join t2 on t_t1.ITNBR = t2.ITNBR	
			where   t_t2.StopDay=0					
		)tt 
		inner  join t3 on t3.SPEC=tt.SPEC
		where  SPECId=1		
	) 

	
		
		select 
		t4.spec,t_t3.NewSPEC,t4.ITNBR,t4.ITDSC,isnull(t_t2.StopDay,999999) StopDay,isnull(#l_t2.qty,0) qty,
		isnull(t4.sday,999)	sday,'120' DayNum,isnull(t_t3.ProductNum,'-') ProductNum 
			 ,t4.cday,'CTA检测' ATTRIBUTE3 
		from  t4
		left join t_t2  on t4.ITNBR=t_t2. MaterialID
		left join #l_t2 on t4.ITNBR=#l_t2.ITNBR 
		left join t_t3  on t4.SPEC = t_t3.SPEC  
		where StopDay=0
	    order by SPEC

	
	drop table #l_t2


END
GO


