-- procedure structure for pro_GTWeight
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pro_GTWeight]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pro_GTWeight]
GO

CREATE PROCEDURE [dbo].[pro_GTWeight]
AS
BEGIN
	declare @wdate date
declare @wsht nvarchar(3)
declare @stime datetime
declare @etime datetime
declare @shifttb table(WDATE DATE,SHT nvarchar(20),NSHT nvarchar(20),BAN nvarchar(20),STIME DATETIME,ETIME DATETIME,SHTNAM nvarchar(20),NSHTNAM nvarchar(20))

	insert into @shifttb 
	EXEC  getshift  
	--取得上个班的班次和日期
	select @wsht=sht,@wdate=WDATE,@stime=STIME,@etime=ETIME from @shifttb 
	 
INSERT INTO GTWeight(fac,itnbr,wt,qty,crtim,wdate,wsht)
select  fac,ITNBR,avg(WT) wt,count(*) qty ,getdate() CRTIM,@wdate,@wsht from(
select   fac,ITNBR,WT,ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY crtim DESC) AS RowNum from QMC0013 where CRTIM>DATEADD(HOUR,-1,@stime) and CRTIM<=DATEADD(HOUR,-1,@etime)   ) t
where RowNum<=100
group by fac,ITNBR
	 
END
GO


-- ----------------------------
-- procedure structure for SETNEWCARNO_BG
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SETNEWCARNO_BG]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SETNEWCARNO_BG]
GO

CREATE PROCEDURE [dbo].[SETNEWCARNO_BG] 
AS
BEGIN
	declare @Transfercardnumber nvarchar(30);
	declare @ShelfNumber nvarchar(30);
	declare @newTransfercardnumber nvarchar(30);
	declare @Serialnumber nvarchar(30);

	if exists( select top 1 t1.Transfercardnumber from 
	(
	SELECT  Transfercardnumber, COUNT(ID) num FROM STC0017 WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop ='02'   GROUP BY Transfercardnumber 
	) t1
	inner join
	(SELECT Transfercardnumber,COUNT(id) num FROM STC0017  WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop ='02'  GROUP BY Transfercardnumber,ShelfNumber
	) t2 on t1.Transfercardnumber=t2.Transfercardnumber and t1.num>t2.num)
	begin
			select top 1 @Transfercardnumber=t1.Transfercardnumber from 
		(
		SELECT  Transfercardnumber, COUNT(ID) num FROM STC0017 WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop ='02'    GROUP BY Transfercardnumber 
		) t1
		inner join
		(SELECT Transfercardnumber,COUNT(id) num FROM STC0017  WHERE CRTIM>DATEADd(MI,-10,getdate()) AND workshop ='02'   GROUP BY Transfercardnumber,ShelfNumber
		) t2 on t1.Transfercardnumber=t2.Transfercardnumber and t1.num>t2.num
			select top 1 @ShelfNumber=ShelfNumber from STC0017 where Transfercardnumber=@Transfercardnumber

			SELECT  @Serialnumber=right('0000'+cast(MAX(NM)+1  as varchar),5)   FROM (
		SELECT SUBSTRING(Transfercardnumber,11,5) AS NM FROM STC0017 WHERE Transfercardnumber LIKE CONVERT(VARCHAR(100),GETDATE(),112)+'02%' 
		) AS TBB 
		SELECT @newTransfercardnumber=CONVERT(varchar(8),GETDATE(),112)+'02'+@Serialnumber

		UPDATE STC0017 SET Transfercardnumber=@newTransfercardnumber ,Serialnumber=@Serialnumber,UPDTIM=GETDATE() WHERE Transfercardnumber=@Transfercardnumber AND ShelfNumber=@ShelfNumber AND workshop ='02'
		UPDATE STC0019 SET Transfercardnumber=@newTransfercardnumber,UPDTIM=GETDATE()  WHERE Transfercardnumber=@Transfercardnumber AND ShelfNumber=@ShelfNumber AND workshop ='02'
	end 
END
GO


-- ----------------------------
-- procedure structure for SP_LogisticsCirculationCardNumber
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_LogisticsCirculationCardNumber]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SP_LogisticsCirculationCardNumber]
GO

CREATE PROCEDURE [dbo].[SP_LogisticsCirculationCardNumber]

@FAC varchar(50)

AS
BEGIN
DECLARE @_Transfercardnumber varchar(100) 
DECLARE @_FAC varchar(10)

SET @_Transfercardnumber =''
SET @_FAC='02'

IF (@FAC != '02')
    BEGIN
   SET @_FAC='01'
    END

 SELECT @_Transfercardnumber=CONVERT(VARCHAR(8), GETDATE(), 112)+@_FAC
       +RIGHT(REPLICATE('0', 4)
             +CAST(ISNULL(MAX(CAST(RIGHT(Transfercardnumber, 5) AS INT)) + 1, 1) AS VARCHAR(5)), 5)
  FROM STC0050(NOLOCK)
WHERE LEFT(Transfercardnumber,10)=CONVERT(VARCHAR(8),GETDATE(),112)+@_FAC

INSERT INTO STC0050(Transfercardnumber,TNTYPE,CRTIM)VALUES(@_Transfercardnumber,'1',GETDATE());

SELECT @_Transfercardnumber  AS TransNum

RETURN;
END
GO


