CREATE PROCEDURE [dbo].[StatisticsMCHIDField]
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	CREATE TABLE #t ( 
		tablename VARCHAR(64), 
		columnname VARCHAR(64) 
	)

	--1、声明游标
	declare num_cursor cursor
	for
		select t.MCHID
		from EDC0001 t with(nolock)
		for read only
	--2、打开游标
	open num_cursor
	--声明变量
	declare @MCHID		nvarchar(100)
	--3、读取游标中的数据
	fetch next from num_cursor
	into @MCHID
	while @@FETCH_STATUS = 0
	begin
		insert into #t EXEC SP_FindValueInDB @MCHID
		fetch next from num_cursor
		into @MCHID
	end

	--4、关闭游标
	close num_cursor
	--5、释放游标
	deallocate num_cursor

	select *
	  from #t

	drop table #t
END
GO


-- ----------------------------
-- procedure structure for bg_cx_jxc_rep
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[bg_cx_jxc_rep]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[bg_cx_jxc_rep]
GO

CREATE PROCEDURE [dbo].[bg_cx_jxc_rep]
  @day1 nvarchar ( 30 ) = '',@day2 nvarchar ( 30 ) = '' 
AS
BEGIN
DECLARE
		@SDATE NVARCHAR ( 30 );
	DECLARE
		@EDATE NVARCHAR ( 30 );
	DECLARE
		@QCDATE NVARCHAR ( 30 );
	DECLARE
		@QMDATE NVARCHAR ( 30 );
IF
		( @day1 = '' ) 
		
		BEGIN
			
			SET @SDATE = CONVERT ( nvarchar ( 23 ), getdate( ) - 2, 23 ) + ' 23:45:00';
		
		SET @EDATE = CONVERT ( nvarchar ( 23 ), getdate( ) - 1, 23 ) + ' 23:45:00';
		
		SET @QCDATE = CONVERT ( nvarchar ( 23 ), getdate( ) - 2, 23 );
		
		SET @QMDATE = CONVERT ( nvarchar ( 23 ), getdate( ) - 1, 23 );
		
		END 
ELSE 
 BEGIN
			
		SET @SDATE =@day1 + ' 23:45:00';
		
		SET @EDATE =@day2 + ' 23:45:00';
		
		SET @QCDATE =@day1;
		
		SET @QMDATE =@day2;
		----------------------
	END 
	DELETE re0068 WHERE wdate =@QMDATE AND fac = '半钢';
		
		INSERT INTO re0068 (
		ITNBR,
		STARQTY,
		ENDQTY,
		OUTQTY,
		INQTY,
		BNQTY,
		BLQTY,
		CXQTY,
		WDATE,
		ERPCODE,
		FAC 
	)
	SELECT t.*, @QMDATE AS WDATE,t2.ERPCODE,'半钢' fac FROM
		(
SELECT (CASE WHEN A.ITNBR IS NOT NULL THEN A.ITNBR WHEN B.ITNBR IS NOT NULL THEN B.ITNBR
WHEN C.ITNBR IS NOT NULL THEN C.ITNBR WHEN D.ITNBR IS NOT NULL THEN D.ITNBR WHEN F.ITNBR IS NOT NULL THEN F.ITNBR 
WHEN E.ITNBR IS NOT NULL THEN E.ITNBR WHEN Q.ITNBR IS NOT NULL THEN Q.ITNBR END) ITNBR , 

ISNULL(A.STARQTY,0) STARQTY,ISNULL(B.ENDQTY,0) ENDQTY,ISNULL(C.OUTQTY,0) OUTQTY 
,ISNULL(D.INQTY,0) INQTY,ISNULL(F.BN,0) BNQTY,ISNULL(E.XGQTY,0) BLQTY,ISNULL(Q.CXQTY,0) CXQTY FROM

( SELECT SUM ( ENDQTY ) AS [STARQTY], ITNBR FROM re0068 WHERE wdate =@QCDATE AND fac = '半钢' GROUP BY itnbr )A --期初数据
FULL JOIN
( SELECT 0 ENDQTY, ITNBR FROM re0068 WHERE wdate =@QMDATE AND fac = '半钢' ) B --期末数据
ON A.ITNBR=B.ITNBR

FULL JOIN
( SELECT
	b.ATTRVAL ITNBR,
	COUNT ( TyreNo ) OUTQTY 
FROM
	tb_PP_CuringOutPut a
	LEFT JOIN (
	SELECT
		* 
	FROM
		(
		SELECT
			ITNBR,
			row_number ( ) OVER ( PARTITION BY ITNBR ORDER BY VERSION DESC ) rid,
			version,
			ATTRVAL 
		FROM
			EDD0001 a
			LEFT JOIN edd0002 b ON a.id= b.itemid 
			AND ATTRCOD = 'GreenTyreSPEC' 
		WHERE
			A.ITGRPCOD= 'FERT' 
			AND ATTRVAL <> 'null' 
		) AS tb_ft 
	WHERE
		rid = 1 
	) b ON a.MaterialID= b.ITNBR 
WHERE
	BeginTime >= @SDATE
	AND BeginTime < @EDATE
	AND FAC IN ( '02' ) 
GROUP BY
	b.ATTRVAL) C --出库数据
on A.ITNBR=C.ITNBR OR B.ITNBR=C.ITNBR
FULL JOIN
(select SPEC itnbr,COUNT(*)INQTY from LTA0001 where BUTIM >=  @SDATE and BUTIM < @EDATE and fac in ('02') and ISNULL(IS_DELETE,'0')='0' group by SPEC) D  --入库数据
on A.ITNBR=D.ITNBR OR B.ITNBR=D.ITNBR OR C.ITNBR=D.ITNBR
full join
(select c.SPEC itnbr,
			sum(case when a.STA='1' then 1 when a.STA='2' then -1 end) BN
			from STA0007 a left join STA0005 b on a.DOCCOD=b.DOCCOD
			left join (SELECT DISTINCT ITNBR,SPEC FROM EDD0001 WHERE ITGRPCOD='GT' AND SPEC<>'' AND ERPCODE<>'') c
			on a.ITNBR=c.ITNBR
			where  CONFIRMTIM>= @SDATE and  CONFIRMTIM < @EDATE
			and b.div=3 and a.sta in ('1','2')  and b.FAC in ('02')
			group by c.SPEC  ) F--盘点数据
ON A.ITNBR=F.ITNBR OR B.ITNBR=F.ITNBR OR C.ITNBR=F.ITNBR OR D.ITNBR=F.ITNBR
full join 
(select b.SPEC ITNBR ,sum(div) XGQTY from gtedit a
left join (SELECT DISTINCT ITNBR,SPEC FROM EDD0001 WHERE ITGRPCOD='GT' AND SPEC<>'' AND ERPCODE<>'') b
on a.ITNBR=b.ITNBR 
where CRTIM >= @SDATE and CRTIM< @EDATE and a.fac in ('02') group by b.SPEC) E --修改数
ON A.ITNBR=E.ITNBR OR B.ITNBR=E.ITNBR OR C.ITNBR=E.ITNBR OR D.ITNBR=E.ITNBR OR F.itnbr=E.ITNBR
full join  
(select b.SPEC ITNBR ,count(*) CXQTY from GTProFailure a INNER JOIN LTA0001 l on a.BARCODE=l.BARCODE
left join (SELECT DISTINCT ITNBR,SPEC FROM EDD0001 WHERE ITGRPCOD='GT' AND SPEC<>'' AND ERPCODE<>'') b
on a.ITNBR=b.ITNBR 
where a.CRTIM >= @SDATE and a.CRTIM<@EDATE and a.fac in ('02') group by b.SPEC) Q --修改数
ON A.ITNBR=Q.ITNBR OR B.ITNBR=Q.ITNBR OR C.ITNBR=Q.ITNBR OR D.ITNBR=Q.ITNBR OR F.itnbr=Q.ITNBR OR E.itnbr=Q.ITNBR
) t
LEFT JOIN 
(SELECT * FROM
(SELECT SPEC,row_number() over (PARTITION by spec ORDER BY VERSION DESC) rid,version,ERPCODE FROM EDD0001 WHERE  ITGRPCOD='GT' AND SPEC<>'' AND ERPCODE<>'' AND fac in ('02'))
t where rid=1)  t2
on t.ITNBR=t2.SPEC;

UPDATE RE0068 
	--SET ENDQTY = STARQTY + INOUTQTY + BLQTY + BNQTY - OUTQTY - OUTBD - OUTFC - LCOUT 
	SET ENDQTY = STARQTY + INQTY + BLQTY - OUTQTY
	WHERE
		FAc = '半钢' 
		AND wdate =@QMDATE;
	UPDATE RE0068 
	SET ENDQTY = 0 
	WHERE
		FAc = '半钢' 
		AND wdate =@QMDATE 
		AND ENDQTY < 0;
END
GO


-- ----------------------------
-- procedure structure for SP_FindValueInDB
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_FindValueInDB]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SP_FindValueInDB]
GO

CREATE PROCEDURE [dbo].[SP_FindValueInDB]

(

    @value VARCHAR(1024)

)        

AS

BEGIN

    -- SET NOCOUNT ON added to prevent extra result sets from

    -- interfering with SELECT statements.

SET NOCOUNT ON;

DECLARE @sql VARCHAR(1024) 

DECLARE @table VARCHAR(64) 

DECLARE @column VARCHAR(64) 

 

CREATE TABLE #t ( 

    tablename VARCHAR(64), 

    columnname VARCHAR(64) 

) 

 

DECLARE TABLES CURSOR 

FOR 

 

    SELECT o.name, c.name 

    FROM syscolumns c 

    INNER JOIN sysobjects o ON c.id = o.id 

    WHERE o.type = 'U' 
	AND c.xtype IN (167, 175, 231, 239) 

    ORDER BY o.name, c.name 

 

OPEN TABLES 

 

FETCH NEXT FROM TABLES 

INTO @table, @column 

 

WHILE @@FETCH_STATUS = 0 

BEGIN 

    SET @sql = 'IF EXISTS(SELECT NULL FROM [' + @table + '] with(nolock) ' 

    SET @sql = @sql + 'WHERE [' + @column + '] LIKE ''' + @value +''' ) ' 

    SET @sql = @sql + 'INSERT INTO #t VALUES (''' + @table + ''', ''' 

    SET @sql = @sql + @column + ''')' 

    EXEC(@sql) 

 

    FETCH NEXT FROM TABLES 

    INTO @table, @column 

END 

 

CLOSE TABLES 

DEALLOCATE TABLES 

 

SELECT * 

FROM #t 

 

DROP TABLE #t 

 

End
GO


-- ----------------------------
-- procedure structure for ReportForm_QMB0201
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ReportForm_QMB0201]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ReportForm_QMB0201]
GO

CREATE PROCEDURE [dbo].[ReportForm_QMB0201]
(
	--Author:林元征
	--Date:2019.12.03
	--修改之后请写上修改人员、内容、时间和原因
	@FAC NVARCHAR(10),		--工厂
	@DB1 NVARCHAR(50),		--列名1
	@DB2 NVARCHAR(50),		--列名2
	@ITDSC NVARCHAR(200),	--规格名称
	@DATE1 NVARCHAR(200),	--日期1
	@DATE2 NVARCHAR(200)	--日期2
)
AS 
BEGIN
	DECLARE @MCHID NVARCHAR(2000),@MCHIDAVG1 NVARCHAR(2000),@MCHIDAVG2 NVARCHAR(2000),@Sql NVARCHAR(4000)
	SELECT @MCHID= STUFF((SELECT ','+'['+BUMCH+']' FROM (SELECT l.BUMCH FROM QMB0201 AS q INNER JOIN LTA0001 AS l ON q.BARCODE=l.BARCODE AND q.FAC=l.FAC WHERE q.FAC=@FAC GROUP BY l.BUMCH) T  FOR XML PATH('')) ,1,1,'') -- 获取PIVOT机台
	SELECT @MCHIDAVG1= STUFF((SELECT ','+'CONVERT(DECIMAL(10,2),ROUND(AVG(['+BUMCH+']),2))'+' [A_'+BUMCH+']' FROM (SELECT l.BUMCH FROM QMB0201 AS q INNER JOIN LTA0001 AS l ON q.BARCODE=l.BARCODE AND q.FAC=l.FAC WHERE q.FAC=@FAC GROUP BY l.BUMCH) T  FOR XML PATH('')),1,1,'')
	SELECT @MCHIDAVG2= STUFF((SELECT ','+'CONVERT(DECIMAL(10,2),ROUND(AVG(['+BUMCH+']),2))'+' [B_'+BUMCH+']' FROM (SELECT l.BUMCH FROM QMB0201 AS q INNER JOIN LTA0001 AS l ON q.BARCODE=l.BARCODE AND q.FAC=l.FAC WHERE q.FAC=@FAC GROUP BY l.BUMCH) T  FOR XML PATH('')),1,1,'')
	
	--DECLARE @SqlPIVOT1 NVARCHAR(1000)='SELECT * FROM(SELECT A.WDATE,'+@MCHIDAVG1+' FROM(SELECT * FROM(SELECT q.*,l.BUMCH FROM QMB0201 AS q INNER JOIN LTA0001 AS l ON q.BARCODE=l.BARCODE AND q.FAC=l.FAC) A PIVOT(MAX('+@DB1+') FOR BUMCH IN('+@MCHID+')) T WHERE T.ITDSC='''+@ITDSC+''')A GROUP BY A.WDATE) AA' -- 拼接PIVOT
	DECLARE @SqlPIVOT1 NVARCHAR(MAX)='SELECT * FROM(SELECT C.WDATE,'+@MCHIDAVG1+'
									  FROM(SELECT * FROM(SELECT q.*,l.BUMCH FROM QMB0201 AS q INNER JOIN LTA0001 AS l ON q.BARCODE=l.BARCODE AND q.FAC=l.FAC AND q.FAC='''+@FAC+''') A 
									  PIVOT(MAX('+@DB1+') FOR BUMCH IN('+@MCHID+'))B
									  WHERE B.ITDSC='''+@ITDSC+''')C GROUP BY C.WDATE)AA' -- 拼接PIVOT
	--DECLARE @SqlPIVOT2 NVARCHAR(1000)='(SELECT B.WDATE WDATE2,'+@MCHIDAVG2+' FROM(SELECT * FROM(SELECT q.*,l.BUMCH FROM QMB0201 AS q INNER JOIN LTA0001 AS l ON q.BARCODE=l.BARCODE AND q.FAC=l.FAC) B PIVOT(MAX('+@DB2+') FOR BUMCH IN('+@MCHID+')) T WHERE T.ITDSC='''+@ITDSC+''')B GROUP BY B.WDATE) BB' -- 拼接PIVOT
	DECLARE @SqlPIVOT2 NVARCHAR(MAX)='(SELECT F.WDATE WDATE2,'+@MCHIDAVG2+'
									   FROM(SELECT * FROM(SELECT q.*,l.BUMCH FROM QMB0201 AS q INNER JOIN LTA0001 AS l ON q.BARCODE=l.BARCODE AND q.FAC=l.FAC AND q.FAC='''+@FAC+''') D
									   PIVOT(MAX('+@DB2+') FOR BUMCH IN('+@MCHID+')) E
									   WHERE E.ITDSC='''+@ITDSC+''') F  GROUP BY F.WDATE) BB' -- 拼接PIVOT
	SET @Sql= @SqlPIVOT1+' LEFT JOIN '+@SqlPIVOT2+' ON AA.WDATE=BB.WDATE2 WHERE AA.WDATE BETWEEN '''+@DATE1+''' AND '''+@DATE2+''' ORDER BY AA.WDATE';
	PRINT @Sql
	EXEC (@Sql)

END
GO


