-- ----------------------------
-- procedure structure for alllc_pro_xj
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[alllc_pro_xj]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[alllc_pro_xj]
GO

CREATE PROCEDURE [dbo].[alllc_pro_xj] @itnbrdd nvarchar(50),@newspecdd nvarchar(30)
AS
BEGIN
	
	SELECT itnbr,MAX(OutDate) wdate,DATEDIFF(day,MAX(OutDate),getdate()) sday,0 qty into #l_t1  FROM QLC0007 where [State]>3    group by ITNBR; 
MERGE INTO #l_t1 a
	using(SELECT SUM( ERFMG) QTY,ITNBR,B.OUTDATE FROM PAD0009 A 
inner JOIN (SELECT itnbr,MAX(OUTDATE) OUTDATE   FROM QLC0007 where [State]>3    group by ITNBR) B ON A.MATNR=B.ITNBR AND A.WDATE>B.OUTDATE
GROUP BY ITNBR,OUTDATE) b
on a.itnbr=b.itnbr AND a.wdate=b.OUTDATE 
when MATCHED THEN
UPDATE set a.qty=b.qty;
	--declare @itnbr nvarchar(20),@date datetime
	--declare cursor_s1 CURSOR SCROLL FOR 
	--SELECT itnbr,wdate FROM #l_t1     
	--open cursor_s1
	--fetch  next from cursor_s1 into @itnbr,@date
	--while(@@FETCH_STATUS=0)
	--begin
	--	update #l_t1 set qty=(select count(*) from tb_PP_CuringOutPut where MaterialID=@itnbr and BeginTime>@date) where ITNBR=@itnbr
	--	fetch  next from cursor_s1 into @itnbr,@date
	--end
	--CLOSE cursor_s1
	--deallocate cursor_s1;

		with  t_t2 as
	(SELECT MATNR,isnull(convert(nvarchar(10), DATEDIFF(day,MAX( WDATE),getdate()-1)),999999) StopDay 
	FROM PAD0009 where MATNR<>''   GROUP BY MATNR ) ,
	t_t3 as (SELECT distinct A.ProductNum,a.DayNum,b.SPEC,b.NewSPEC FROM QLC0005 A LEFT JOIN QLC0006 B ON A.RuleCode=B.NewSPEC )
	select t_t1.spec,t_t3.NewSPEC,t_t1.ITNBR,t_t1.ITDSC,isnull(t_t2.StopDay,999999) StopDay,isnull(#l_t1.qty,0) qty,
	isnull(#l_t1.sday,0) sday,isnull(t_t3.DayNum,'-') DayNum,isnull(t_t3.ProductNum,'-') ProductNum 
	 ,isnull(t_t3.DayNum,0)-isnull(#l_t1.sday,0) cday
	from QLC0008 t_t1  
	left join t_t2  on t_t1.ITNBR=t_t2. MATNR  
	left join #l_t1 on t_t1.ITNBR=#l_t1.ITNBR  
	left join t_t3 on t_t1.SPEC=t_t3.SPEC   
	where t_t1.ITNBR like '%'+@itnbrdd+'%' and t_t3.NewSPEC like '%'+@newspecdd+'%'
	order by SPEC
END
GO


-- ----------------------------
-- procedure structure for TEST_PR
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[TEST_PR]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[TEST_PR]
GO

CREATE PROCEDURE [dbo].[TEST_PR]
WITH EXEC AS CALLER
AS
BEGIN
  DECLARE @rchk_cnt_per int,
          @recheck_rule_val int,
          @rchk_sum_cnt int
  SET @recheck_rule_val = 30
  SET @rchk_sum_cnt = 27
  SET @rchk_cnt_per = round(100/cast(@recheck_rule_val as float),0)
  print @rchk_cnt_per
  IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
    BEGIN
      print '达到条件'
    END
  ELSE
    BEGIN
      print '未达条件'
    END
END
GO


