-- ----------------------------
-- procedure structure for MXOEE_PRO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[MXOEE_PRO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[MXOEE_PRO]
GO

CREATE PROCEDURE [dbo].[MXOEE_PRO]
	-- Add the parameters for the stored procedure here
@stime datetime,@etime datetime
AS
BEGIN

--机台合格率统计
with hgltb as (
 SELECT t.JMCH,isnull((AQTY-ng)*1.00/AQTY,1.00) hgl FROM 
(select JMCH,SUM(CNUM2-CNUM1+1) AS AQTY from LTD0001 where   DIV IN ('JL','ML','SL') AND JTIM>=@stime and JTIM<=@etime
group by JMCH ) T
LEFT JOIN
( select a.JMCH,count(*) ng from LTD0001 A  LEFT JOIN QMD0009 B ON A.LOTID = B.barcode where DIV IN ('JL','ML','SL') AND JTIM>=@stime and JTIM<=@etime
 AND isnull(FinalCheck_result,'') not  in ('1','2','')
 group by JMCH ) T2 ON T.JMCH=T2.JMCH ) ,
 --表1 负荷扣减时间 负荷需要扣减停机的时间，计划停机，饭食停机N003，计划检修N004，
 tb1 as (
 SELECT e.MCHID,   CONVERT(DECIMAL(8,2),SUM(ISNULL(e.STOPTIM,0))/60) STOPTIM 
                 FROM EQA0008 AS e left join EDC0006 edc on e.TYPECOD=edc.NOSTRTCOD
            LEFT JOIN EDC0001 AS e2 ON e2.MCHID = e.MCHID 
                WHERE e2.FAA='ML' AND  edc.SUBTCOD in ('N003','N004','N007','N008') AND
				E.IS_STP=1 AND e.STIM>=@stime and e.STIM<=@etime 
             GROUP BY e.MCHID
UNION 
SELECT e4.MCHID,SUM(STPTIM) STPTIM FROM EQA0009 AS e4  LEFT JOIN EDC0001 AS e2 ON e4.MCHID = e2.MCHID 
 WHERE e2.FAA='ML' and WDATE>=@stime and WDATE<=@etime  GROUP BY  e4.MCHID ) ,
 -- 表2 净开机扣减时间 减完上面的复合停机之后 剪掉 下面 的生产 准备时间，主要由EAM 给的 维修时间，和 后面 可能 需要加上，点检类别，和 换规格类别
--20240920 王浩说不用 EAM 维修时间
tb2 as(SELECT MCHID,SUM(STOPTIM) STOPTIM FROM ( SELECT e.MCHID,   CONVERT(DECIMAL(8,2),SUM(ISNULL(e.STOPTIM,0))/60) STOPTIM 
                 FROM EQA0008 AS e left join EDC0006 edc on e.TYPECOD=edc.NOSTRTCOD
            inner JOIN EDC0001 AS e2 ON e2.MCHID = e.MCHID 
                WHERE e2.FAA='ML' AND  edc.SUBTCOD in ('N001','N005') AND
				E.IS_STP=1 AND e.STIM>=@stime and e.STIM<=@etime 
             GROUP BY e.MCHID
			 --union 
			 --SELECT e2.MCHID,sum(DATEDIFF (MINUTE, HAPPEN_DATE, REPAIR_END_TIME)) STOPTIM
    --             FROM IF_EAM_MACHINE_REPAIR e inner JOIN EDC0001 AS e2 ON e.MCHID collate Chinese_PRC_90_CI_AI_WS = e2.MCHID 
    --            WHERE e2.FAA='ML' and  HAPPEN_DATE>=@stime and HAPPEN_DATE<=@etime 
				--and REPAIR_END_TIME>HAPPEN_DATE and HAPPEN_DATE is not null
				--group by e2.MCHID
				) T GROUP BY MCHID) ,
--可用率 就是480 - 第一个表的时间-第二个表扣减时间 /  480 - 第一个表的时间
--  表3单独计算 待料时间
tb3 as ( SELECT e.MCHID,   CONVERT(DECIMAL(8,2),SUM(ISNULL(e.STOPTIM,0))/60) STOPTIM 
                 FROM EQA0008 AS e left join EDC0006 edc on e.TYPECOD=edc.NOSTRTCOD
            inner JOIN EDC0001 AS e2 ON e2.MCHID = e.MCHID 
                WHERE e2.FAA='ML' AND  edc.SUBTCOD in ('N001') AND
				E.IS_STP=1 AND e.STIM>=@stime and e.STIM<=@etime 
             GROUP BY e.MCHID),
--tb4 生产耗时
tb4 as
(SELECT A.MCHID,ISNULL(SUM(B.AQTY*A.MCHEFFIC)/60,0) CT ,SUM(B.AQTY) AS SUM_AOTY,SUM(A.MCHEFFIC) AS SUM_MCHEFFIC FROM EDE0013 A LEFT JOIN
(select JMCH,SUM(CNUM2-CNUM1+1) AS AQTY,ITNBR from LTD0001 where   DIV IN ('JL','ML','SL') AND JTIM>=@stime and JTIM<=@etime
group by JMCH,ITNBR) B ON A.MCHID=B.JMCH AND A.ITNBR=B.ITNBR
GROUP BY A.MCHID),
-- 所有机台
--2024-09-13 这里原来标准是480 改成区间的分钟
mtb as (SELECT MCHID,DATEDIFF(MINUTE,@stime,@etime) BZ FROM EDC0001 mtb left join hgltb h1 on mtb.MCHID=h1.JMCH WHERE TYPECOD IN ('GK270','GK400','GE580','GE420/800T'))

--净开动率就是，可用率 就是480 - 第一个表的时间-第二个表扣减时间-表3 的扣减时间/可用率 就是480 - 第一个表的时间-第二个表扣减时间
--速度开动率 产出产量* 每公斤耗时(未知，是否和机台规格关联)/  480 - 第一个表的时间-第二个表扣减时间-表3 的扣减时间

--OEE :净开动率*速度开动率*合格率*可用率

--第一步，先查出来所有得密炼机台

SELECT mtb.MCHID,BZ,isnull(tb1.STOPTIM,0) [FHT],isnull(tb2.STOPTIM,0) [KJT],isnull(tb3.STOPTIM,0) [YWT]
,isnull(tb4.SUM_AOTY ,0) [SUM_AOTY],isnull(tb4.SUM_MCHEFFIC ,0) [SUM_MCHEFFIC]
,isnull(tb4.CT ,0) [CT],ISNULL(h1.hgl,0)*100 [HGL],(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0))*1.0/(BZ-isnull(tb1.STOPTIM,0))*100[KYL],
(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0)-isnull(tb3.STOPTIM,0))*1.0/(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0))*100 [KDL],
case when  isnull(tb4.CT,0)=0 then 100 else  tb4.CT*1.0/(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0)-isnull(tb3.STOPTIM,0))*100 end [SDKDL],
ISNULL(h1.hgl,0)*(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0))*1.0/(BZ-isnull(tb1.STOPTIM,0))*
(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0)-isnull(tb3.STOPTIM,0))*1.0/(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0)) *
case when  isnull(tb4.CT,0)=0 then 1 else  tb4.CT*1.0/(BZ-isnull(tb1.STOPTIM,0)-isnull(tb2.STOPTIM,0)-isnull(tb3.STOPTIM,0)) end *100[OEE]
FROM   mtb left join hgltb h1 on mtb.MCHID=h1.JMCH  
left join tb1 on mtb.MCHID=tb1.MCHID  
left join tb2 on mtb.MCHID=tb2.MCHID  
left join tb3 on mtb.MCHID=tb3.MCHID  
left join tb4 on mtb.MCHID=tb4.MCHID  
 
END
GO


