-- ----------------------------
-- procedure structure for pr_gettire_sort_PCR_20240607
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pr_gettire_sort_PCR_20240607]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pr_gettire_sort_PCR_20240607]
GO

CREATE PROCEDURE [dbo].[pr_gettire_sort_PCR_20240607]
@barcode varchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   --设置事务为读
   SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

   DECLARE
      @itnbr       VARCHAR (50),
      @itdsc       VARCHAR (80),
      @is_hold     CHAR (1),
      @is_trial    CHAR (1),
      @is_xray     CHAR (1),
      @is_sds      CHAR (1),
      @is_recheck  CHAR (1),
      @is_freeinsp CHAR (1),
      @ub_mchine   VARCHAR (255),
      @prior_mch   VARCHAR (255),
      @cnt         INT,
      @cnt_prior   INT,
      @ufyn        CHAR (1),
      @dbyn        CHAR (1),
      @mchid       VARCHAR (20),
      @mchid_p     VARCHAR (20),
      
      @recheck_rule VARCHAR(2),
      @recheck_rule_val INT,
      @recheck_no  VARCHAR(30),
      @xray_rule   VARCHAR(2),
	  --@xray_rule_val INT,
      @xray_rule_val FLOAT,
      @sds_rule   VARCHAR(2),
      @sds_rule_val INT

   SET @itnbr = ''
   SET @itdsc = ''
   SET @is_hold = ''
   SET @is_trial = ''
   SET @is_xray = 'N'--默认不X光
   SET @is_sds = 'N'--默认不SDS
   SET @is_recheck = 'N'--默认不复检
   SET @is_freeinsp = 'N'--默认非免检
   SET @ub_mchine = ''
   SET @prior_mch = ''

   SET @cnt = 0
   SET @cnt_prior = 0
   SET @mchid = ''
   SET @ufyn = ''
   SET @dbyn = ''
   SET @mchid_p = ''
   SET @recheck_no = ''

   --获取条码信息
   SELECT TOP 1
          @itnbr = TB.MATERIALID,
          @itdsc = TB.MATERIALNAME,
          @is_trial =
             CASE WHEN (ISNULL (LT.CUSTATE, '') = '2' OR ISNULL (LT.ATTRIBUTE2, '') = 'Y')
                        THEN 'Y' ELSE 'N' END,
          @is_hold = ISNULL (WIP.LOCKYN, N'N')
   FROM tb_PP_CuringOutPut AS TB
        LEFT OUTER JOIN LTA0001 AS LT ON TB.TYRENO = LT.TYRENO
        LEFT OUTER JOIN WIP0010 AS WIP ON TB.TYRENO = WIP.TYRENO
   WHERE TB.TYRENO = @barcode

   --判断能去哪个UB机
   SELECT A.MCHID,
          A.LNUM,
          B.RIMNO,
          A.UFYN,
          A.DBYN
   INTO #TEMP_T1
   FROM CKA0003 A, QMB0203 B
   WHERE     A.MCHID = B.MCHID
         AND A.LNUM = B.RIMNO
         AND B.MCHID NOT IN ('02DJ001',
                             '02DJ002',
                             '02DJ003',
                             '02DJ004')                        --老区动均设备不参与自动分拣
         AND A.ITNBR = @itnbr


   SELECT @cnt = count (1) FROM #TEMP_T1

   IF @cnt > 0
      BEGIN
         DECLARE
            cur_temp1 CURSOR FOR SELECT MCHID, UFYN, DBYN FROM #TEMP_T1

         OPEN cur_temp1
         FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn

         WHILE @@FETCH_STATUS = 0
         BEGIN
            --若均匀性和动平衡为N,则为免检
            IF (@ufyn = 'N' AND @dbyn = 'N')
               BEGIN
                  SET @ub_mchine = ''
                  SET @is_freeinsp = 'Y'
                  BREAK
               END
            ELSE
               BEGIN
                  SET @ub_mchine = @ub_mchine + @mchid + ','
               END

            FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn        --下一个
         END

         IF @ub_mchine ! = ''
            BEGIN
               SET @ub_mchine = LEFT (@ub_mchine, LEN (@ub_mchine) - 1)
            END

         CLOSE cur_temp1
         DEALLOCATE cur_temp1
      END

   --设备优先.
   IF (@ub_mchine ! = '' AND @ub_mchine ! = 'NONE')
      BEGIN
         --SELECT DISTINCT MCHID
         --INTO #TEMP_T2
         --FROM CKA0004
         --WHERE itnbr = @itnbr AND ONEYN = 'Y'
         
        SELECT DISTINCT C1.MCHID INTO #TEMP_T2 FROM CKA0003 C1 LEFT JOIN CKA0004 C2
        ON C1.MCHID=C2.MCHID AND C1.TCOD=C2.TCOD AND C1.ITNBR=C2.ITNBR 
        WHERE C1.ITNBR=@itnbr AND C2.ONEYN = 'Y'

        SELECT @cnt_prior = count (1) FROM #TEMP_T2

         IF @cnt_prior > 0
            BEGIN
               DECLARE
                  cur_temp2 CURSOR FOR SELECT MCHID FROM #TEMP_T2

               OPEN cur_temp2
               FETCH NEXT FROM cur_temp2   INTO @mchid_p

               WHILE @@FETCH_STATUS = 0
               BEGIN
                  SET @prior_mch = @prior_mch + @mchid_p + ','
                  FETCH NEXT FROM cur_temp2   INTO @mchid_p              --下一个
               END

               IF @prior_mch ! = ''
                  BEGIN
                     SET @prior_mch = LEFT (@prior_mch, LEN (@prior_mch) - 1)
                  END

               CLOSE cur_temp2
               DEALLOCATE cur_temp2
            END
        DROP TABLE #TEMP_T2
      END

   --删除临时表
   DROP TABLE #TEMP_T1
   
   --判断是否复检,X光,SDS
   IF (@itnbr!='' and @itnbr is not null)
     BEGIN
      DECLARE @rchk_cnt_per INT,
              @rchk_sum_cnt INT,
              @xray_cnt_per INT,
              @xray_sum_cnt INT,
              @sds_cnt_per INT,
              @sds_sum_cnt INT
      --根据规格获取分拣策略
      SELECT @recheck_rule=RECHECK_RULE,
             @recheck_rule_val=RECHECK_RULE_VAL,
             @recheck_no=RECHECK_NO,
             @xray_rule = XRAY_RULE,
             @xray_rule_val = XRAY_RULE_VAL,
             @sds_rule = SDS_RULE,
             @sds_rule_val = SDS_RULE_VAL
             FROM CKA0006
             WHERE  ITNBR = @itnbr
             
      --判断复检口
      IF @recheck_rule = '0'--若规则是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
            SET @is_recheck = 'Y'
        END
      IF @recheck_rule = '2'--若规则是不检
        BEGIN
          SET @is_recheck = 'N'
          SET @recheck_no = ''
        END
      IF @recheck_rule = '1' --若规则是抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,1,0,0)
          ELSE
            UPDATE CKA0060 SET RECHECKSUMQTY = RECHECKSUMQTY+1 WHERE ITNBR = @itnbr
          SET @rchk_cnt_per = round(100/cast(@recheck_rule_val as float),0)--获取每多少个检测一个（复检）
          SELECT @rchk_sum_cnt = RECHECKSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
                SET @is_recheck = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_recheck = 'N'
              SET @recheck_no = ''
            END
        END
        
      --判断X光
      IF @xray_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
            SET @is_xray = 'Y'
        END
      IF @xray_rule = '2'--若不检
        BEGIN
          SET @is_xray = 'N'
        END
      IF @xray_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,1,0)
          ELSE
            UPDATE CKA0060 SET XRAYSUMQTY = XRAYSUMQTY+1 WHERE ITNBR = @itnbr
          SET @xray_cnt_per = round(100/cast(@xray_rule_val as float),0)--获取每多少个检测一个（X光）
          SELECT @xray_sum_cnt = XRAYSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@xray_sum_cnt % @xray_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
                SET @is_xray = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_xray = 'N'
            END
          --若物流调用记录中已存在<不冻结>并且<分X光>，则代表物流线由于某些原因（主要是X光道口满）上次没分X光，则之后不再分往X光。2021-10-01 质检车间要求
          IF EXISTS(SELECT BARCODE FROM CKA0009 WHERE BARCODE = @barcode AND IS_HOLD = 'N' AND IS_XRAY = 'Y')
            BEGIN
              SET @is_xray = 'N'
            END
        END
        
      --判断SDS
      IF @sds_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
            SET @is_sds = 'Y'
        END
      IF @sds_rule = '2'--若不检
        BEGIN
          SET @is_sds = 'N'
        END
      IF @sds_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,0,1)
          ELSE
            UPDATE CKA0060 SET SDSSUMQTY = SDSSUMQTY+1 WHERE ITNBR = @itnbr
          SET @sds_cnt_per = round(100/cast(@sds_rule_val as float),0)--获取每多少个检测一个（SDS）
          SELECT @sds_sum_cnt = SDSSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@sds_sum_cnt % @sds_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
                SET @is_sds = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_sds = 'N'
            END
        END
     END
   --记录物流线调用履历(先只记录需检X光的)
   IF(@is_xray = 'Y')
      BEGIN
        INSERT INTO CKA0009
       (FAC, BARCODE, ITNBR, ITDSC, IS_HOLD, IS_TRIAL, IS_XRAY, IS_RECHECK, IS_FREEINSP, UB_MCHINE, PRIOR_MCH, RECHECK_NO, IS_SDS, CALLTIM) 
       VALUES ('02', @barcode, @itnbr, @itdsc, @is_hold, @is_trial, @is_xray, @is_recheck, @is_freeinsp, @ub_mchine, @prior_mch, @recheck_no, @is_sds, getdate())
      END
   --若规格为空则返回空行.
   IF @itnbr='' or @itnbr is null
     BEGIN
         SELECT '' barcode,
                '' itnbr,
                '' itdsc,
                '' is_hold,
                '' is_trial,
                '' is_xray,
                '' is_recheck,
                '' is_freeinsp,
                '' ub_mchine,
                '' prior_mch,
                '' recheck_no,
                '' is_sds
                WHERE 0 = 1
     END
   ELSE
     BEGIN
         --返回测试代号.
         SELECT @barcode barcode,
                @itnbr itnbr,
                @itdsc itdsc,
                @is_hold is_hold,
                @is_trial is_trial,
                @is_xray is_xray,
                @is_recheck is_recheck,
                @is_freeinsp is_freeinsp,
                @ub_mchine ub_mchine,
                @prior_mch prior_mch,
                @recheck_no recheck_no,
                @is_sds is_sds
     END
END
GO


-- ----------------------------
-- procedure structure for GET_PPB0202_GTPRO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GET_PPB0202_GTPRO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GET_PPB0202_GTPRO]
GO

CREATE PROCEDURE [dbo].[GET_PPB0202_GTPRO] 
	 @MCHID NVARCHAR(30)
AS
BEGIN
	 
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
  
SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_GT WHERE MCHID=@MCHID AND (STA='2' OR STA='5');
if (exists(SELECT TOP 1 ITNBR FROM PAD0201_GT WHERE MCHID=@MCHID AND (STA='2' OR STA='4')))
begin
	 SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_GT WHERE MCHID=@MCHID AND (STA='2' OR STA='4');
end;

if(@VERSION='')
  begin
  SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR  AND SHFLAG='Y'; -- 2022-08-22 更改，审核过的最高版本，之前没有加审核;
  end;

  
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,PCSBOMWeight,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth INTO #T2 
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
 

if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='PD'))
begin 
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='PD' WHERE MCHID=@MCHID  AND  TCOD='4-1'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='WG' WHERE MCHID=@MCHID  AND  TCOD='4-1'
END 
		if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB'))
begin 
	if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='SB' AND Usage='Belt #4'))
	BEGIN
		UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
	ELSE
	BEGIN
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
END
		if(exists( select * from #T2 where ParentMatType=@outtypecod and SubMatTypeName='DE'  and Usage<>'Standard'))
begin 
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage ASC)  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage DESC)  WHERE MCHID=@MCHID  AND  TCOD='9-2'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-2'
END 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
--MERGE INTO #T2 a
--USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
-- on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  
--when matched then
--update set SubMatID=b.SubMatID;

select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,
CASE WHEN TYPECOD IN ('PTQ','BD') THEN 1.000   WHEN TYPECOD ='JL' THEN convert(decimal(9,3), PCSBOMWeight) WHEN PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1] 
from #T2 temp INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 ON 
temp.SubMatTypeName=T1.TYPECOD AND temp.Usage=T1.COMPLOCATION;
 
drop table #T2
END
GO


-- ----------------------------
-- procedure structure for LHGetShift
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LHGetShift]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[LHGetShift]
GO

CREATE PROCEDURE [dbo].[LHGetShift] @MCHID NVARCHAR(50)


as
declare @dTime datetime;
declare @STime datetime;
declare @ETime datetime;
declare @DateN datetime;
set @dTime=getdate();
set @DateN=getdate();
set @STime=getdate();
set @ETime=getdate();
declare @sht varchar(10);
declare @nsht varchar(10);
declare @ban varchar(10);
declare @fac varchar(10);
DECLARE @MGROUP NVARCHAR(20);
SELECT @MGROUP=ATTRVAL FROM EDC0011 e left join EDC0001 b on e.ITEMID=b.ID WHERE MCHID=@MCHID and ATTRCOD='R1'
SELECT top 1 @FAC=FAC FROM EDC0001 WHERE MCHID=@MCHID order by FAC
SET @sht='1';
SET @ban='A';
DECLARE @WDATE DATETIME, @SHT1 CHAR(1),@SHT2 CHAR(1),@SHT3 CHAR(1),@DT1 DATETIME,@DT2 DATETIME,@DT3 DATETIME  
declare cursor_edb03 CURSOR SCROLL FOR SELECT WDATE,SHT1,SHT2,SHT3,TIM1,TIM2,TIM3 FROM EDB0005 WHERE WDATE BETWEEN @dTime-1 and @dTime+1 AND MGROUP=@MGROUP AND FAC=@fac ORDER BY WDATE 
open cursor_edb03   
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
WHILE(@@FETCH_STATUS=0)
BEGIN 
		if(@dTime >= @DT1 and @dTime < @DT2)
		begin 
		   set @sht = '1' ;
		   set @nsht = '2' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT1;
		   set @STime = @DT1;
		   SET @ETime = DATEADD(Second,-1,@DT2);
		END 
		if(@dTime >= @DT2 and @dTime < @DT3 )
		begin 
		   set @sht = '2' ;
		   set @nsht = '3' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT2;
		   set @STime = @DT2;  
		   SET @ETime = DATEADD(Second,-1,@DT3);
		END  
		if(@dTime >= @DT3  )
		begin 
		   set @sht = '3' ;
		   set @nsht = '1' ;
		   set @DateN=@WDATE;
		   set @ban = @SHT3;
		   set @STime = @DT3;
		   SET @ETime = DATEADD(Second,-1,@DT1);
		end    
		IF(@sht=3 AND @stime<@DT1 AND @ETime<@STime)
		BEGIN 
		   SET @ETime = DATEADD(Second,-1,@DT1);
		END      
  
FETCH NEXT from cursor_edb03 into @WDATE,@SHT1,@SHT2,@SHT3,@DT1,@DT2,@DT3
END


CLOSE cursor_edb03
deallocate cursor_edb03  

SELECT @DateN WDATE,@sht SHT,@nsht NSHT,@ban BAN,@STime STIME,@ETime ETIME,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac=@FAC AND dcod=@sht) SHTNAM,(SELECT dnam FROM eda0004 WHERE div='sht' AND fac=@FAC AND dcod=@Nsht) NSHTNAM,@FAC AS FAC
GO


-- ----------------------------
-- procedure structure for pr_gettire_sort_PCR_Test
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pr_gettire_sort_PCR_Test]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pr_gettire_sort_PCR_Test]
GO

CREATE PROCEDURE [dbo].[pr_gettire_sort_PCR_Test]
@barcode varchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   --设置事务为读
   SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

   DECLARE
      @itnbr       VARCHAR (50),
      @itdsc       VARCHAR (80),
      @is_hold     CHAR (1),
      @is_trial    CHAR (1),
      @is_xray     CHAR (1),
      @is_sds      CHAR (1),
      @is_recheck  CHAR (1),
      @is_freeinsp CHAR (1),
      @ub_mchine   VARCHAR (255),
      @prior_mch   VARCHAR (255),
      @cnt         INT,
      @cnt_prior   INT,
      @ufyn        CHAR (1),
      @dbyn        CHAR (1),
      @mchid       VARCHAR (20),
      @mchid_p     VARCHAR (20),
      
      @recheck_rule VARCHAR(2),
      @recheck_rule_val INT,
      @recheck_no  VARCHAR(30),
      @xray_rule   VARCHAR(2),
	  --@xray_rule_val INT,
      @xray_rule_val FLOAT,
      @sds_rule   VARCHAR(2),
      @sds_rule_val INT

   SET @itnbr = ''
   SET @itdsc = ''
   SET @is_hold = ''
   SET @is_trial = ''
   SET @is_xray = 'N'--默认不X光
   SET @is_sds = 'N'--默认不SDS
   SET @is_recheck = 'N'--默认不复检
   SET @is_freeinsp = 'N'--默认非免检
   SET @ub_mchine = ''
   SET @prior_mch = ''

   SET @cnt = 0
   SET @cnt_prior = 0
   SET @mchid = ''
   SET @ufyn = ''
   SET @dbyn = ''
   SET @mchid_p = ''
   SET @recheck_no = ''

   --获取条码信息
   SELECT TOP 1
          @itnbr = TB.MATERIALID,
          @itdsc = TB.MATERIALNAME,
          @is_trial =
             CASE WHEN (ISNULL (LT.CUSTATE, '') = '2' OR ISNULL (LT.ATTRIBUTE2, '') = 'Y')
                        THEN 'Y' ELSE 'N' END,
          @is_hold = ISNULL (WIP.LOCKYN, N'N')
   FROM tb_PP_CuringOutPut AS TB
        LEFT OUTER JOIN LTA0001 AS LT ON TB.TYRENO = LT.TYRENO
        LEFT OUTER JOIN WIP0010 AS WIP ON TB.TYRENO = WIP.TYRENO
   WHERE TB.TYRENO = @barcode

   --判断能去哪个UB机
   SELECT A.MCHID,
          A.LNUM,
          B.RIMNO,
          A.UFYN,
          A.DBYN
   INTO #TEMP_T1
   FROM CKA0003 A, QMB0203 B
   WHERE     A.MCHID = B.MCHID
         AND A.LNUM = B.RIMNO
         AND B.MCHID NOT IN ('02DJ001',
                             '02DJ002',
                             '02DJ003',
                             '02DJ004')                        --老区动均设备不参与自动分拣
         AND A.ITNBR = @itnbr


   SELECT @cnt = count (1) FROM #TEMP_T1

   IF @cnt > 0
      BEGIN
         DECLARE
            cur_temp1 CURSOR FOR SELECT MCHID, UFYN, DBYN FROM #TEMP_T1

         OPEN cur_temp1
         FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn

         WHILE @@FETCH_STATUS = 0
         BEGIN
            --若均匀性和动平衡为N,则为免检
            IF (@ufyn = 'N' AND @dbyn = 'N')
               BEGIN
                  SET @ub_mchine = ''
                  SET @is_freeinsp = 'Y'
                  BREAK
               END
            ELSE
               BEGIN
                  SET @ub_mchine = @ub_mchine + @mchid + ','
               END

            FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn        --下一个
         END

         IF @ub_mchine ! = ''
            BEGIN
               SET @ub_mchine = LEFT (@ub_mchine, LEN (@ub_mchine) - 1)
            END

         CLOSE cur_temp1
         DEALLOCATE cur_temp1
      END

   --设备优先.
   IF (@ub_mchine ! = '' AND @ub_mchine ! = 'NONE')
      BEGIN
         --SELECT DISTINCT MCHID
         --INTO #TEMP_T2
         --FROM CKA0004
         --WHERE itnbr = @itnbr AND ONEYN = 'Y'
         
        SELECT DISTINCT C1.MCHID INTO #TEMP_T2 FROM CKA0003 C1 LEFT JOIN CKA0004 C2
        ON C1.MCHID=C2.MCHID AND C1.TCOD=C2.TCOD AND C1.ITNBR=C2.ITNBR 
        WHERE C1.ITNBR=@itnbr AND C2.ONEYN = 'Y'

        SELECT @cnt_prior = count (1) FROM #TEMP_T2

         IF @cnt_prior > 0
            BEGIN
               DECLARE
                  cur_temp2 CURSOR FOR SELECT MCHID FROM #TEMP_T2

               OPEN cur_temp2
               FETCH NEXT FROM cur_temp2   INTO @mchid_p

               WHILE @@FETCH_STATUS = 0
               BEGIN
                  SET @prior_mch = @prior_mch + @mchid_p + ','
                  FETCH NEXT FROM cur_temp2   INTO @mchid_p              --下一个
               END

               IF @prior_mch ! = ''
                  BEGIN
                     SET @prior_mch = LEFT (@prior_mch, LEN (@prior_mch) - 1)
                  END

               CLOSE cur_temp2
               DEALLOCATE cur_temp2
            END
        DROP TABLE #TEMP_T2
      END

   --删除临时表
   DROP TABLE #TEMP_T1
   
   --判断是否复检,X光,SDS
   IF (@itnbr!='' and @itnbr is not null)
     BEGIN
      DECLARE @rchk_cnt_per INT,
              @rchk_sum_cnt INT,
              @xray_cnt_per INT,
              @xray_sum_cnt INT,
              @sds_cnt_per INT,
              @sds_sum_cnt INT
      --根据规格获取分拣策略
      SELECT @recheck_rule=RECHECK_RULE,
             @recheck_rule_val=RECHECK_RULE_VAL,
             @recheck_no=RECHECK_NO,
             @xray_rule = XRAY_RULE,
             @xray_rule_val = XRAY_RULE_VAL,
             @sds_rule = SDS_RULE,
             @sds_rule_val = SDS_RULE_VAL
             FROM CKA0006
             WHERE  ITNBR = @itnbr
             
      --判断复检口
      IF @recheck_rule = '0'--若规则是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
            SET @is_recheck = 'Y'
        END
      IF @recheck_rule = '2'--若规则是不检
        BEGIN
          SET @is_recheck = 'N'
          SET @recheck_no = ''
        END
      IF @recheck_rule = '1' --若规则是抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,1,0,0)
          ELSE
            UPDATE CKA0060 SET RECHECKSUMQTY = RECHECKSUMQTY+1 WHERE ITNBR = @itnbr
          SET @rchk_cnt_per = round(100/cast(@recheck_rule_val as float),0)--获取每多少个检测一个（复检）
          SELECT @rchk_sum_cnt = RECHECKSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
                SET @is_recheck = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_recheck = 'N'
              SET @recheck_no = ''
            END
        END
        
      --判断X光
      IF @xray_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
            SET @is_xray = 'Y'
        END
      IF @xray_rule = '2'--若不检
        BEGIN
          SET @is_xray = 'N'
        END
      IF @xray_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,1,0)
          ELSE
            UPDATE CKA0060 SET XRAYSUMQTY = XRAYSUMQTY+1 WHERE ITNBR = @itnbr
          SET @xray_cnt_per = round(100/cast(@xray_rule_val as float),0)--获取每多少个检测一个（X光）
          SELECT @xray_sum_cnt = XRAYSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@xray_sum_cnt % @xray_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
                SET @is_xray = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_xray = 'N'
            END
          --若物流调用记录中已存在<不冻结>并且<分X光>，则代表物流线由于某些原因（主要是X光道口满）上次没分X光，则之后不再分往X光。2021-10-01 质检车间要求
          IF EXISTS(SELECT BARCODE FROM CKA0009 WHERE BARCODE = @barcode AND IS_HOLD = 'N' AND IS_XRAY = 'Y')
            BEGIN
              SET @is_xray = 'N'
            END
        END
        
      --判断SDS
      IF @sds_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
            SET @is_sds = 'Y'
        END
      IF @sds_rule = '2'--若不检
        BEGIN
          SET @is_sds = 'N'
        END
      IF @sds_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,0,1)
          ELSE
            UPDATE CKA0060 SET SDSSUMQTY = SDSSUMQTY+1 WHERE ITNBR = @itnbr
          SET @sds_cnt_per = round(100/cast(@sds_rule_val as float),0)--获取每多少个检测一个（SDS）
          SELECT @sds_sum_cnt = SDSSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@sds_sum_cnt % @sds_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
                SET @is_sds = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_sds = 'N'
            END
        END
     END
   --记录物流线调用履历(先只记录需检X光的)
   IF(@is_xray = 'Y')
      BEGIN
        INSERT INTO CKA0009
       (FAC, BARCODE, ITNBR, ITDSC, IS_HOLD, IS_TRIAL, IS_XRAY, IS_RECHECK, IS_FREEINSP, UB_MCHINE, PRIOR_MCH, RECHECK_NO, IS_SDS, CALLTIM) 
       VALUES ('02', @barcode, @itnbr, @itdsc, @is_hold, @is_trial, @is_xray, @is_recheck, @is_freeinsp, @ub_mchine, @prior_mch, @recheck_no, @is_sds, getdate())
      END
   --若规格为空则返回空行.MODIFYED By GCZhang 20240607 DC胎改为从无信息下胎口下胎
   --IF @itnbr='' or @itnbr is null
   IF @itnbr='' or @itnbr is null or @is_trial = 'Y'
     BEGIN
         SELECT '' barcode,
                '' itnbr,
                '' itdsc,
                '' is_hold,
                '' is_trial,
                '' is_xray,
                '' is_recheck,
                '' is_freeinsp,
                '' ub_mchine,
                '' prior_mch,
                '' recheck_no,
                '' is_sds
                WHERE 0 = 1
     END
   ELSE
     BEGIN
         --返回测试代号.
         SELECT @barcode barcode,
                @itnbr itnbr,
                @itdsc itdsc,
                @is_hold is_hold,
                @is_trial is_trial,
                @is_xray is_xray,
                @is_recheck is_recheck,
                @is_freeinsp is_freeinsp,
                @ub_mchine ub_mchine,
                @prior_mch prior_mch,
                @recheck_no recheck_no,
                @is_sds is_sds
     END
END
GO


-- ----------------------------
-- function structure for GetPLANNO_LH
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetPLANNO_LH]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetPLANNO_LH]
GO

CREATE FUNCTION [dbo].[GetPLANNO_LH]
(
	@WDATE DATETIME,			--早中晚
	@LR NVARCHAR(1),			--左右
	@MCHID NVARCHAR(30),			--机台号
	@SEQ NVARCHAR(3)  --顺序
)
RETURNS NVARCHAR(30)
AS 
BEGIN
	 DECLARE @Result NVARCHAR(30),@YMD NVARCHAR(8),@MaxNum INT,@Zero NVARCHAR(10),@Counts INT,@NumL INT,@NumR INT,@Maxnumppb INT
	 SET @Zero='';
	 SET @Counts=0;
	 SET @NumL=0;
	 SET @NumR=0;  
	 --获取当天工单号	
	 SELECT @Maxnumppb = CASE WHEN ISNULL(MAX(RIGHT(ORDERNOA,5))+1,0)=0 THEN 1 ELSE MAX(RIGHT(ORDERNOA,5))+1 END
			FROM PPB0201 AS p 
			WHERE p.WDATE=@WDATE AND ISNULL(ORDERNOA,'')<>'' 
	 --获取当天工单号	
	 SELECT @MaxNum = CASE WHEN ISNULL(MAX(RIGHT(ORDERNOA,5))+1,0)=0 THEN 1 ELSE MAX(RIGHT(ORDERNOA,5))+1 END
			FROM PLA0009 AS p 
			WHERE p.WDATE=@WDATE AND ISNULL(ORDERNOA,'')<>'' 
	 if(@MaxNum<=@Maxnumppb) 
	 begin
		set @MaxNum=@Maxnumppb;
	 end
	 --查询同机台号左机台计划数量
	 --判断如果是左边的，就去找右边的顺序相同并且同机台的工单号。反之就去找左边的 
	 IF @LR='L'
	 BEGIN
	 	SELECT @MaxNum=CASE WHEN RIGHT(ORDERNOA,5) IS NULL THEN @MaxNum ELSE RIGHT(ORDERNOA,5) END  FROM PLA0009 
                WHERE MCHID=@MCHID AND WDATE=@WDATE AND LR='R' AND SEQA=@SEQ
             ORDER BY ORDERNOA
	 END
	 ELSE
	 BEGIN
	 	
	 	SELECT @MaxNum=CASE WHEN RIGHT(ORDERNOA,5) IS NULL THEN @MaxNum ELSE RIGHT(ORDERNOA,5) END  FROM PLA0009 
                WHERE MCHID=@MCHID AND WDATE=@WDATE AND LR='L' AND SEQA=@SEQ
             ORDER BY ORDERNOA
	 
	 END
	 
			-- SELECT @NumL=COUNT(1) FROM PLA0009 AS p 
-- 			WHERE p.WDATE=@WDATE AND ISNULL(ORDERNOA,'')<>''  AND p.MCHID=@MCHID AND p.LR='L'
-- 			--查询同机台号右机台计划数量
-- 			SELECT @NumR=COUNT(1) FROM PLA0009 AS p 
-- 			WHERE p.WDATE=@WDATE AND ISNULL(ORDERNOA,'')<>''  AND p.MCHID=@MCHID AND p.LR='R'
-- 			IF @NumL=@NumR OR @NumL<@NumR
-- 				BEGIN
-- 					SET @MaxNum = @MaxNum+1;
-- 				END
     --获取年月日
     SELECT @YMD=SUBSTRING(CONVERT(NVARCHAR(4),YEAR(GETDATE())),3 , 2)
     	+CASE WHEN LEN(CONVERT(NVARCHAR(2),MONTH(@WDATE)))>1 THEN CONVERT(NVARCHAR(2),MONTH(@WDATE)) ELSE '0'+CONVERT(NVARCHAR(2),MONTH(@WDATE)) END
		+CASE WHEN LEN(CONVERT(NVARCHAR(2),DAY(@WDATE)))>1 THEN CONVERT(NVARCHAR(2),DAY(@WDATE)) ELSE '0'+CONVERT(NVARCHAR(2),DAY(@WDATE)) END;
	 --长度不足补零
	 SET @Counts = LEN(@MaxNum)
	 WHILE @Counts<5
	 BEGIN
	 	SET @ZERO =@Zero+'0';
	 	SET @Counts = @Counts+1;
	 END
     SET @Result=@YMD+@Zero+CONVERT(NVARCHAR(5),@MaxNum);
     RETURN @Result
END
GO


-- ----------------------------
-- procedure structure for SP_Scan_LocalWarehous_Checking
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_Scan_LocalWarehous_Checking]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SP_Scan_LocalWarehous_Checking]
GO

CREATE PROCEDURE [dbo].[SP_Scan_LocalWarehous_Checking]
@TYRENO varchar(20), 
@LOGINNAM varchar(20),
@FAC varchar(10),
@ENAM varchar(20),
@Storehouse varchar(10)
AS
BEGIN
DECLARE @_FAC varchar(10)
DECLARE @_LOCKYN varchar(10)
DECLARE @_TYRESTA varchar(10)
DECLARE @_DOT  varchar(10)
DECLARE @_NUMCOUNT INT
DECLARE @_LNOCOUNT INT
DECLARE @_WGRESNM varchar(10)
DECLARE @_ITNBR1 VARCHAR(50)
DECLARE @_ITNBR2 VARCHAR(50)
DECLARE @_LNO varchar(20)
DECLARE @_barCodeCount INT
DECLARE @_ShelfCount INT
DECLARE @_CargoCageQuantity INT
DECLARE @_QCSTATE decimal(18,2)

DECLARE @_GG VARCHAR(50)
DECLARE @_ZX VARCHAR(50)
DECLARE @_LZ VARCHAR(50)

 SET @_FAC =''
 SET @_LOCKYN =''
 SET @_TYRESTA =''
 SET @_DOT  =''
 SET @_NUMCOUNT =0
 SET @_LNOCOUNT =0
 SET @_WGRESNM =''
 SET @_ITNBR1=''
 SET @_ITNBR2=''
 SET @_LNO = ''
 SET @_barCodeCount=0
 SET @_ShelfCount = 0
 SET @_CargoCageQuantity = 0
 SET @_QCSTATE=0.0
  SET @_GG =''
 SET @_ZX=''
 SET @_LZ =''
 
/*验证开始*/
SELECT TOP 1 @_FAC = ISNULL(FAC,''),@_LOCKYN=LOCKYN,@_TYRESTA = TYRESTA,@_DOT=ISNULL(DOT,''),@_ITNBR1=ITNBR FROM WIP0010 WHERE TYRENO = @TYRENO
IF @_FAC='' Begin

IF EXISTS (SELECT TOP 1 TYRENO FROM STC0045 WHERE TYRENO = @TYRENO) 
BEGIN
SELECT TOP 1 @_GG=ITDSC,@_ZX=Operator,@_LZ =Warehousereceipt FROM STC0045 WHERE TYRENO = @TYRENO
INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'此胎已入库,请检查。',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
SELECT  '此胎已入库!<br/>请检查。'
RETURN 
END 

IF EXISTS (SELECT TOP 1 TYRENO FROM STC0017 WHERE TYRENO = @TYRENO AND GOODSSTATE != '3') 
BEGIN
SELECT TOP 1 @_GG=ITDSC,@_ZX=Operator,@_LZ =Warehousereceipt FROM STC0045 WHERE TYRENO = @TYRENO
INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'此胎已入物流园仓库,请检查。',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
SELECT  '此胎已入物流园仓库!<br/>请检查。'
RETURN 
END 

ELSE Begin


IF EXISTS (SELECT TYRENO FROM TB_PP_CURINGOUTPUT  WHERE TYRENO = @TYRENO) 
BEGIN
INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'不在车间库存中!',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
SELECT  '['+@TYRENO+']不在车间库存中!'
RETURN;
END 
ELSE 
BEGIN
INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'无硫化信息',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
SELECT  '['+@TYRENO+']无硫化信息!'
RETURN;
END



END
END
IF(@_LOCKYN='Y')
BEGIN
INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'在库存已被冻结!',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
SELECT '['+@TYRENO+']在库存已被冻结!'
RETURN
End
IF (@_DOT = '')BEGIN
INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'没有 DOT 信息,不能入本地库！',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
SELECT '['+@TYRENO+']没有 DOT 信息,不能入本地库！'
RETURN
END

IF(@_TYRESTA!='2')BEGIN   
  SELECT @_NUMCOUNT=COUNT(*) FROM STC0045 WHERE TYRENO = @TYRENO
  IF(@_NUMCOUNT>0)BEGIN
  INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'成品胎已经入本地库',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
  SELECT '['+@TYRENO+']已入本地库！'
  RETURN
  END 
END

SELECT TOP 1 @_QCSTATE=CAST(replace(CASE A.QCSTATE
WHEN '' THEN '9.0'
WHEN NULL THEN '9.0'
ELSE A.QCSTATE END,'W','1') AS decimal(18,2)) ,@_WGRESNM=(SELECT TOP 1 DNAM FROM EDA0004 
                    WHERE DIV = 'QC_RESULT' AND DCOD = A.QCSTATE ) FROM QMB0101 AS A WHERE A.TYRENO = @TYRENO
	IF(@_QCSTATE = 0.0)
      BEGIN
      INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'综合质量无数据信息,不能上架',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']综合质量无数据信息,不能上架！';
	RETURN;
      END 

IF(@_QCSTATE !=9.0 )
BEGIN
IF(@_QCSTATE !=1.3)
BEGIN
	IF(@_QCSTATE > 1.3)
	BEGIN
	INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'综合质量处于[ '+@_WGRESNM+' ]的状态,不能入本地库',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']综合质量处于[ '+@_WGRESNM+' ]的状态,不能入本地库！'
	RETURN
	END
END
END
ELSE
BEGIN
	INSERT INTO [STC0034](DIST,TyreNo,Describe,Storehouse,ENAM,LOGINNAM,CRTIM,STA)VALUES('2',@TYRENO,'综合质量处于[ 未检 ]的状态,不能入本地库',@Storehouse,@ENAM,@LOGINNAM,GETDATE(),'1')
	SELECT '['+@TYRENO+']综合质量处于[ 未检 ]的状态,不能入本地库！'
	RETURN
END
SELECT ''
RETURN
END
GO


-- ----------------------------
-- procedure structure for GET_PPB0202_GTPRO_BYPLANCOD
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GET_PPB0202_GTPRO_BYPLANCOD]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GET_PPB0202_GTPRO_BYPLANCOD]
GO

CREATE PROCEDURE [dbo].[GET_PPB0202_GTPRO_BYPLANCOD] 
	 @PLANCOD NVARCHAR(50)
AS
BEGIN

DECLARE @MCHID NVARCHAR(20)	 
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
  
SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_GT WHERE PLANCOD=@PLANCOD;
--if (exists(SELECT TOP 1 ITNBR FROM PAD0201_GT WHERE MCHID=@MCHID AND (STA='2' OR STA='4')))
--begin
--	 SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_GT WHERE MCHID=@MCHID AND (STA='2' OR STA='4');
--end;
if(@VERSION='')
  begin
  SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR  AND SHFLAG='Y';;
  end; 
 

--with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
--,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth)
--as
--(
----初始查询
--select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
--SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth
--from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
--union all
----递归条件
--select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
--a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth
--from EDD0061 a 
--inner join
--temp b
--on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
--and b.EditionNo=a.ParentMatEditionNo)
--)
--select distinct * INTO #T2  from temp 
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,PCSBOMWeight,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth INTO #T2 
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod

if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='PD'))
begin 
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='PD' WHERE MCHID=@MCHID  AND  TCOD='4-1'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='WG' WHERE MCHID=@MCHID  AND  TCOD='4-1'
END
if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB'))
begin 
	if(exists( select * from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='SB' AND Usage='Belt #4'))
	BEGIN
		UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
	ELSE
	BEGIN
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='ZB',COMPLOCATION=(select Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB')  WHERE MCHID=@MCHID  AND  TCOD='8-4'
	END
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='SB',COMPLOCATION='Belt #4'  WHERE MCHID=@MCHID  AND  TCOD='8-4'
END
if(exists( select * from #T2 where ParentMatType=@outtypecod and SubMatTypeName='DE'  and Usage<>'Standard'))
begin 
	--update #T2 set SubMatID=SubMatTypeName='SB'  and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	--update #T2 set PCSCuttinglength=(select PCSCuttinglength from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='ZB') WHERE ParentMatType=@outtypecod AND Usage='Belt #4' AND SubMatTypeName='SB'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage ASC)  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION=(select TOP 1 Usage from #T2 where ParentMatType=@outtypecod   and SubMatTypeName='DE' ORDER BY Usage DESC)  WHERE MCHID=@MCHID  AND  TCOD='9-2'
end
ELSE 
BEGIN
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-1'
	UPDATE QMA0014 SET TYPECOD='DE',COMPLOCATION='Standard'  WHERE MCHID=@MCHID  AND  TCOD='9-2'
END 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
--MERGE INTO #T2 a
--USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
-- on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  
--when matched then
--update set SubMatID=b.SubMatID;

select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,CASE   WHEN TYPECOD ='JL' THEN convert(decimal(9,3), PCSBOMWeight) 
WHEN TYPECOD IN ('PTQ','BD') THEN 1.000 WHEN  PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1]  from #T2 temp INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 ON temp.SubMatTypeName=T1.TYPECOD AND temp.Usage=T1.COMPLOCATION;
 
drop table #T2
END
GO


-- ----------------------------
-- procedure structure for pr_gettire_sort_PCR1
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[pr_gettire_sort_PCR1]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[pr_gettire_sort_PCR1]
GO

CREATE PROCEDURE [dbo].[pr_gettire_sort_PCR1]
@barcode varchar(20)
WITH EXEC AS CALLER
AS
BEGIN
   --设置事务为读
   SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

   DECLARE
      @itnbr       VARCHAR (50),
      @itdsc       VARCHAR (80),
      @is_hold     CHAR (1),
      @is_trial    CHAR (1),
      @is_xray     CHAR (1),
      @is_sds      CHAR (1),
      @is_recheck  CHAR (1),
      @is_freeinsp CHAR (1),
      @ub_mchine   VARCHAR (255),
      @prior_mch   VARCHAR (255),
      @cnt         INT,
      @cnt_prior   INT,
      @ufyn        CHAR (1),
      @dbyn        CHAR (1),
      @mchid       VARCHAR (20),
      @mchid_p     VARCHAR (20),
      
      @recheck_rule VARCHAR(2),
      @recheck_rule_val INT,
      @recheck_no  VARCHAR(30),
      @xray_rule   VARCHAR(2),
      @xray_rule_val INT,
      @sds_rule   VARCHAR(2),
      @sds_rule_val INT

   SET @itnbr = ''
   SET @itdsc = ''
   SET @is_hold = ''
   SET @is_trial = ''
   SET @is_xray = 'N'--默认不X光
   SET @is_sds = 'N'--默认不SDS
   SET @is_recheck = 'N'--默认不复检
   SET @is_freeinsp = 'N'--默认非免检
   SET @ub_mchine = ''
   SET @prior_mch = ''

   SET @cnt = 0
   SET @cnt_prior = 0
   SET @mchid = ''
   SET @ufyn = ''
   SET @dbyn = ''
   SET @mchid_p = ''
   SET @recheck_no = ''

   --获取条码信息
   SELECT TOP 1
          @itnbr = TB.MATERIALID,
          @itdsc = TB.MATERIALNAME,
          @is_trial =
             CASE WHEN (ISNULL (LT.CUSTATE, '') = '2' OR ISNULL (LT.ATTRIBUTE2, '') = 'Y')
                        THEN 'Y' ELSE 'N' END,
          @is_hold = ISNULL (WIP.LOCKYN, N'N')
   FROM tb_PP_CuringOutPut AS TB
        LEFT OUTER JOIN LTA0001 AS LT ON TB.TYRENO = LT.TYRENO
        LEFT OUTER JOIN WIP0010 AS WIP ON TB.TYRENO = WIP.TYRENO
   WHERE TB.TYRENO = @barcode

   --判断能去哪个UB机
   SELECT A.MCHID,
          A.LNUM,
          B.RIMNO,
          A.UFYN,
          A.DBYN
   INTO #TEMP_T1
   FROM CKA0003 A, QMB0203 B
   WHERE     A.MCHID = B.MCHID
         AND A.LNUM = B.RIMNO
         AND B.MCHID NOT IN ('02DJ001',
                             '02DJ002',
                             '02DJ003',
                             '02DJ004')                        --老区动均设备不参与自动分拣
         AND A.ITNBR = @itnbr


   SELECT @cnt = count (1) FROM #TEMP_T1

   IF @cnt > 0
      BEGIN
         DECLARE
            cur_temp1 CURSOR FOR SELECT MCHID, UFYN, DBYN FROM #TEMP_T1

         OPEN cur_temp1
         FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn

         WHILE @@FETCH_STATUS = 0
         BEGIN
            --若均匀性和动平衡为N,则为免检
            IF (@ufyn = 'N' AND @dbyn = 'N')
               BEGIN
                  SET @ub_mchine = ''
                  SET @is_freeinsp = 'Y'
                  BREAK
               END
            ELSE
               BEGIN
                  SET @ub_mchine = @ub_mchine + @mchid + ','
               END

            FETCH NEXT FROM cur_temp1   INTO @mchid, @ufyn, @dbyn        --下一个
         END

         IF @ub_mchine ! = ''
            BEGIN
               SET @ub_mchine = LEFT (@ub_mchine, LEN (@ub_mchine) - 1)
            END

         CLOSE cur_temp1
         DEALLOCATE cur_temp1
      END

   --设备优先.
   IF (@ub_mchine ! = '' AND @ub_mchine ! = 'NONE')
      BEGIN
         --SELECT DISTINCT MCHID
         --INTO #TEMP_T2
         --FROM CKA0004
         --WHERE itnbr = @itnbr AND ONEYN = 'Y'
         
        SELECT DISTINCT C1.MCHID INTO #TEMP_T2 FROM CKA0003 C1 LEFT JOIN CKA0004 C2
        ON C1.MCHID=C2.MCHID AND C1.TCOD=C2.TCOD AND C1.ITNBR=C2.ITNBR 
        WHERE C1.ITNBR=@itnbr AND C2.ONEYN = 'Y'

        SELECT @cnt_prior = count (1) FROM #TEMP_T2

         IF @cnt_prior > 0
            BEGIN
               DECLARE
                  cur_temp2 CURSOR FOR SELECT MCHID FROM #TEMP_T2

               OPEN cur_temp2
               FETCH NEXT FROM cur_temp2   INTO @mchid_p

               WHILE @@FETCH_STATUS = 0
               BEGIN
                  SET @prior_mch = @prior_mch + @mchid_p + ','
                  FETCH NEXT FROM cur_temp2   INTO @mchid_p              --下一个
               END

               IF @prior_mch ! = ''
                  BEGIN
                     SET @prior_mch = LEFT (@prior_mch, LEN (@prior_mch) - 1)
                  END

               CLOSE cur_temp2
               DEALLOCATE cur_temp2
            END
        DROP TABLE #TEMP_T2
      END

   --删除临时表
   DROP TABLE #TEMP_T1
   
   --判断是否复检,X光,SDS
   IF (@itnbr!='' and @itnbr is not null)
     BEGIN
      DECLARE @rchk_cnt_per INT,
              @rchk_sum_cnt INT,
              @xray_cnt_per INT,
              @xray_sum_cnt INT,
              @sds_cnt_per INT,
              @sds_sum_cnt INT
      --根据规格获取分拣策略
      SELECT @recheck_rule=RECHECK_RULE,
             @recheck_rule_val=RECHECK_RULE_VAL,
             @recheck_no=RECHECK_NO,
             @xray_rule = XRAY_RULE,
             @xray_rule_val = XRAY_RULE_VAL,
             @sds_rule = SDS_RULE,
             @sds_rule_val = SDS_RULE_VAL
             FROM CKA0006
             WHERE  ITNBR = @itnbr
             
      --判断复检口
      IF @recheck_rule = '0'--若规则是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
            SET @is_recheck = 'Y'
        END
      IF @recheck_rule = '2'--若规则是不检
        BEGIN
          SET @is_recheck = 'N'
          SET @recheck_no = ''
        END
      IF @recheck_rule = '1' --若规则是抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,1,0,0)
          ELSE
            UPDATE CKA0060 SET RECHECKSUMQTY = RECHECKSUMQTY+1 WHERE ITNBR = @itnbr
          SET @rchk_cnt_per = round(100/cast(@recheck_rule_val as float),0)--获取每多少个检测一个（复检）
          SELECT @rchk_sum_cnt = RECHECKSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@rchk_sum_cnt % @rchk_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo in ('21','22','23','24')) --若从没被分拣复检
                SET @is_recheck = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_recheck = 'N'
              SET @recheck_no = ''
            END
        END
	 
	 --判断复检口
	 IF @is_recheck = 'Y'
	   BEGIN
		 SELECT @recheck_no=RECHECK_NO FROM CKA0006 A 
LEFT JOIN LTA0001 B ON A.ITNBR = B.CUITNBR WHERE BARCODE=@barcode 
	   END
        
      --判断X光
      IF @xray_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
            SET @is_xray = 'Y'
        END
      IF @xray_rule = '2'--若不检
        BEGIN
          SET @is_xray = 'N'
        END
      IF @xray_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,1,0)
          ELSE
            UPDATE CKA0060 SET XRAYSUMQTY = XRAYSUMQTY+1 WHERE ITNBR = @itnbr
          SET @xray_cnt_per = round(100/cast(@xray_rule_val as float),0)--获取每多少个检测一个（X光）
          SELECT @xray_sum_cnt = XRAYSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@xray_sum_cnt % @xray_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '19') --若从没被分拣X光
                SET @is_xray = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_xray = 'N'
            END
          --若物流调用记录中已存在<不冻结>并且<分X光>，则代表物流线由于某些原因（主要是X光道口满）上次没分X光，则之后不再分往X光。2021-10-01 质检车间要求
          IF EXISTS(SELECT BARCODE FROM CKA0009 WHERE BARCODE = @barcode AND IS_HOLD = 'N' AND IS_XRAY = 'Y')
            BEGIN
              SET @is_xray = 'N'
            END
        END
        
      --判断SDS
      IF @sds_rule = '0'--若是全检
        BEGIN
          IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
            SET @is_sds = 'Y'
        END
      IF @sds_rule = '2'--若不检
        BEGIN
          SET @is_sds = 'N'
        END
      IF @sds_rule = '1'--若抽检
        BEGIN
          IF NOT EXISTS (SELECT ITNBR FROM CKA0060 WHERE ITNBR = @itnbr)
            INSERT INTO CKA0060(FAC,ITNBR,RECHECKSUMQTY,XRAYSUMQTY,SDSSUMQTY) VALUES ('02',@itnbr,0,0,1)
          ELSE
            UPDATE CKA0060 SET SDSSUMQTY = SDSSUMQTY+1 WHERE ITNBR = @itnbr
          SET @sds_cnt_per = round(100/cast(@sds_rule_val as float),0)--获取每多少个检测一个（SDS）
          SELECT @sds_sum_cnt = SDSSUMQTY FROM CKA0060 WHERE ITNBR = @itnbr
          IF (@sds_sum_cnt % @sds_cnt_per = 0) --取模计算是否达到检测数量,若达到
            BEGIN
              IF NOT EXISTS (select ID from CKA0007 where Barcode = @barcode and WayNo = '25') --若从没被分拣SDS
                SET @is_sds = 'Y'
            END
          ELSE --若未达到
            BEGIN
              SET @is_sds = 'N'
            END
        END
     END
   --记录物流线调用履历(先只记录需检X光的)
   IF(@is_xray = 'Y')
      BEGIN
        INSERT INTO CKA0009
       (FAC, BARCODE, ITNBR, ITDSC, IS_HOLD, IS_TRIAL, IS_XRAY, IS_RECHECK, IS_FREEINSP, UB_MCHINE, PRIOR_MCH, RECHECK_NO, IS_SDS, CALLTIM) 
       VALUES ('02', @barcode, @itnbr, @itdsc, @is_hold, @is_trial, @is_xray, @is_recheck, @is_freeinsp, @ub_mchine, @prior_mch, @recheck_no, @is_sds, getdate())
      END
   --若规格为空则返回空行.
   IF @itnbr='' or @itnbr is null
     BEGIN
         SELECT '' barcode,
                '' itnbr,
                '' itdsc,
                '' is_hold,
                '' is_trial,
                '' is_xray,
                '' is_recheck,
                '' is_freeinsp,
                '' ub_mchine,
                '' prior_mch,
                '' recheck_no,
                '' is_sds
                WHERE 0 = 1
     END
   ELSE
     BEGIN
         --返回测试代号.
         SELECT @barcode barcode,
                @itnbr itnbr,
                @itdsc itdsc,
                @is_hold is_hold,
                @is_trial is_trial,
                @is_xray is_xray,
                @is_recheck is_recheck,
                @is_freeinsp is_freeinsp,
                @ub_mchine ub_mchine,
                @prior_mch prior_mch,
                @recheck_no recheck_no,
                @is_sds is_sds
     END
END
GO


-- ----------------------------
-- procedure structure for SEMI_TYRENO_CHANGE
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SEMI_TYRENO_CHANGE]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SEMI_TYRENO_CHANGE]
GO

CREATE PROCEDURE [dbo].[SEMI_TYRENO_CHANGE]
	@NEWBARCODE NVARCHAR(50),@OLDBARCODE NVARCHAR(50)
AS
BEGIN 
	BEGIN transaction
    declare @nror int
    set @nror=0 
	UPDATE QMB0101 SET TYRENO=@NEWBARCODE,BARCODE=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
    UPDATE LTA0001	SET TYRENO=@NEWBARCODE,BARCODE=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE tb_PP_CuringOutPut SET TYRENO=@NEWBARCODE,GreenTyreNo=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
	UPDATE wip0010 SET TYRENO=@NEWBARCODE,BARCODE=@NEWBARCODE WHERE TYRENO=@OLDBARCODE;
	set @nror=@nror+@@error
	update LTA1001 set BARCODE=@NEWBARCODE,TYRENO=@NEWBARCODE where BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
	update QMB0012 set BARCODE=@NEWBARCODE,TYRENO=@NEWBARCODE where BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
	update QMB0006 set BARCODE=@NEWBARCODE,TYRENO=@NEWBARCODE where BARCODE=@OLDBARCODE;
	set @nror=@nror+@@error
	if @nror<>0
		begin 
			rollback transaction
        end
        else 
        begin 
            commit transaction
        end
END
GO


