SELECT @_barCodeCount=COUNT(*) FROM STC0064 (NOLOCK) WHERE TYRENO = @TYRENO
IF(@_barCodeCount>0)BEGIN
SELECT @_LNO=LNO FROM STC0064 (NOLOCK) WHERE TYRENO = @TYRENO
SELECT '成品胎已经在[ '+@_LNO+' ]货架上！';
RETURN;
END

SELECT @_ShelfCount=COUNT(LNO) FROM STC0064 (NOLOCK) WHERE LNO = @LNO AND ITNBR = @_ITNBR1 AND EQUIPID = @EqID AND [LEVEL] = '1' 
SELECT @_CargoCageQuantity=ISNULL(SUM(LQTY),0) FROM STC0004 (NOLOCK) WHERE ITNBR = @_ITNBR1
IF (@_CargoCageQuantity != 0)
BEGIN
    IF (@_ShelfCount > @_CargoCageQuantity)
    BEGIN
        SELECT '该货笼已经达到最大装胎数量，无法在装笼操作！';
        RETURN;
    END
END
ELSE
BEGIN
SELECT @_CargoCageQuantity =100;
IF (@FAC = '03' OR @FAC = '01')
    BEGIN
      SELECT @_CargoCageQuantity = 279;
   END
IF @_ShelfCount > @_CargoCageQuantity
   BEGIN
        SELECT '该货笼已经达到最大装胎数量，无法在装笼操作！';
        RETURN;
   END
END
SELECT '';
RETURN;
END
GO


-- ----------------------------
-- procedure structure for SETQCWIP0002_pcr
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SETQCWIP0002_pcr]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SETQCWIP0002_pcr]
GO

CREATE PROCEDURE [dbo].[SETQCWIP0002_pcr] 
AS
BEGIN
	 SET LOCK_TIMEOUT 5000
	 DECLARE @Now DATETIME = GETDATE();
	 merge into WIP0002 W
USING( 
--SELECT A.BARCODE,
--CASE WHEN DATEDIFF(HOUR,A.WTIME,GETDATE())>EXPTIM then 2
--when DATEDIFF(HOUR,A.WTIME,GETDATE()) < CYCLTIM then 4
--when DATEDIFF(HOUR,A.WTIME,GETDATE()) >= CYCLTIM and DATEDIFF(HOUR,A.WTIME,GETDATE()) <= exptim then 1 end STA
--FROM WIP0002 A LEFT JOIN EDD0001 B 
--ON A.ITNBR=B.ITNBR AND B.ITGRPCOD='GT' AND A.VERSION=B.VERSION
--WHERE ISNULL(A.IS_DELETE,0)=0 and A.STA<>6 and a.fac='02'
SELECT A.BARCODE,
CASE WHEN DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60>isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 2
when DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60 < isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) then 4
when DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60 >=  isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) and DATEDIFF(MINUTE,A.WTIME,@Now)* 1.0 / 60 <= isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 1 end STA
FROM WIP0002 A LEFT JOIN EDD1001 E1 ON A.ITNBR=E1.ITNBR AND E1.DIV='PGT' AND  E1.ATTRCOD='EXPTIM' 
 LEFT JOIN EDD1001 C1 ON A.ITNBR=C1.ITNBR AND C1.DIV='PGT' AND  C1.ATTRCOD='CYCLTIM' 
 LEFT JOIN EDD0003 D ON D.ITTYPECOD='PGT'   
WHERE ISNULL(A.IS_DELETE,'0')='0' and A.STA in ('1','2','4')  and a.fac='02'
) T1
ON W.BARCODE=T1.BARCODE AND  W.STA<>T1.STA 
WHEN MATCHED THEN 
UPDATE SET  STA=T1.STA 
OPTION (MAXDOP 1); 
END
GO


-- ----------------------------
-- procedure structure for Proc_GetZADlInfo
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Proc_GetZADlInfo]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Proc_GetZADlInfo]
GO

CREATE PROCEDURE [dbo].[Proc_GetZADlInfo]
	@tyreno varchar(20)
AS
BEGIN
SELECT T1.TYRENO,(T2.BRAND+' '+T1.MaterialName+' '+T2.PATTERN)AS MOLD,T2.BRAND,T1.MaterialName,T2.PATTERN,T2.[LOAD],
(SELECT TOP 1 CRTIM FROM STC0019 (NOLOCK) WHERE TYRENO=T1.TYRENO) AS OUTTIM 
FROM TB_PP_CURINGOUTPUT (NOLOCK) T1 
LEFT JOIN (SELECT * FROM(SELECT T0.*,ROW_NUMBER() OVER (PARTITION BY ITNBR ORDER BY [VERSION] DESC) AS PX FROM EDD0001 (NOLOCK) T0) AS NT WHERE NT.PX = 1) T2 
ON T1.MATERIALID = T2.ITNBR
WHERE T1.TyreNo = @tyreno
END
GO


-- ----------------------------
-- procedure structure for SP_EXEC_SQL_LIST
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_EXEC_SQL_LIST]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SP_EXEC_SQL_LIST]
GO

CREATE PROCEDURE [dbo].[SP_EXEC_SQL_LIST]
	@strsql NVARCHAR(MAX)
AS
BEGIN
	BEGIN TRANSACTION
    DECLARE @nror INT
    SET @nror=0 
	DECLARE cursor_1 CURSOR
	FOR
		 SELECT col FROM func_SplitToNvarchar(@strsql,',');
	OPEN cursor_1
	DECLARE @sql NVARCHAR(MAX)
	FETCH NEXT FROM cursor_1 INTO @sql
	WHILE (@@FETCH_STATUS <> -1)
	BEGIN
		 IF (@@FETCH_STATUS <> -2)
		 BEGIN    
			SELECT @sql = RTRIM(@sql)
			IF @sql<>''
			BEGIN
				EXEC (@sql)
				SET @nror=@nror+@@ERROR
			END
		 END
		 FETCH NEXT FROM cursor_1 INTO @sql
	END
	CLOSE cursor_1
	DEALLOCATE cursor_1
	IF @nror=0
	BEGIN 
		COMMIT TRANSACTION
		RETURN 1
    END
    ELSE 
    BEGIN 
        ROLLBACK TRANSACTION
		RETURN 0
    END 
END
GO


-- ----------------------------
-- procedure structure for SETQCWIP0001_pcr
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SETQCWIP0001_pcr]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SETQCWIP0001_pcr]
GO

CREATE PROCEDURE [dbo].[SETQCWIP0001_pcr] 
AS
BEGIN
	 merge into WIP0001 W
USING(
SELECT A.LOTID,a.wtime,a.itnbr,a.div,
CASE WHEN DATEDIFF(HOUR,A.WTIME,GETDATE())>isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 2
when DATEDIFF(HOUR,A.WTIME,GETDATE()) < isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) then 4
when DATEDIFF(HOUR,A.WTIME,GETDATE()) >=  isnull(isnull(C1.ATTRVAL,d.CYCLTIM),0) and DATEDIFF(HOUR,A.WTIME,GETDATE()) <= isnull(isnull(e1.ATTRVAL,d.EXPTIM),0) then 1 end STA
FROM WIP0001 A LEFT JOIN EDD1001 E1 ON A.ITNBR=E1.ITNBR AND E1.DIV=a.DIV AND  E1.ATTRCOD='EXPTIM' 
 LEFT JOIN EDD1001 C1 ON A.ITNBR=C1.ITNBR AND C1.DIV=a.DIV AND  C1.ATTRCOD='CYCLTIM' 
 LEFT JOIN EDD0003 D ON D.ITTYPECOD=a.DIV  
WHERE ISNULL(A.IS_DELETE,0)=0 and A.STA in (1,2,4) and a.fac='02'
) T1
ON W.LOTID=T1.LOTID AND  W.STA<>T1.STA
WHEN MATCHED THEN 
UPDATE SET  STA=T1.STA ;

END
GO


-- ----------------------------
-- function structure for func_SplitToNvarchar
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[func_SplitToNvarchar]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[func_SplitToNvarchar]
GO

CREATE FUNCTION [dbo].[func_SplitToNvarchar]
(
@StrSource  NVARCHAR(MAX),--源分隔字符串
@StrSeprate VARCHAR(10)--分隔符
)
RETURNS @temp TABLE(col NVARCHAR(MAX))
AS
BEGIN
	DECLARE @i INT
	SET @StrSource = RTRIM(LTRIM(@StrSource))
	SET @i = CHARINDEX(@StrSeprate, @StrSource)
	WHILE @i >= 1
	BEGIN
	  INSERT @temp
	  VALUES
	   (
		LEFT(@StrSource, @i -1)
	   )
	  SET @StrSource = SUBSTRING(@StrSource, @i + 1, LEN(@StrSource) -@i)
	  SET @i = CHARINDEX(@StrSeprate, @StrSource)
	END
	IF @StrSource <> '\'
	  INSERT @temp
	  VALUES
	   (
		@StrSource
	   )
	RETURN
END
GO


-- ----------------------------
-- procedure structure for GET_PPB0202_HALFPRO_test
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GET_PPB0202_HALFPRO_test]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GET_PPB0202_HALFPRO_test]
GO

CREATE PROCEDURE [dbo].[GET_PPB0202_HALFPRO_test] 
	 @MCHID NVARCHAR(30)
AS
BEGIN
	 
DECLARE @ITNBR NVARCHAR(100);
DECLARE @VERSION NVARCHAR(10);
declare @outtypecod NVARCHAR(10);
  
SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='5');
if (exists(SELECT TOP 1 ITNBR FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='4')))
begin
	 SELECT @MCHID=MCHID,@ITNBR=ITNBR,@VERSION=VERSION,@outtypecod=OUTTYPECOD FROM PAD0201_HALF WHERE MCHID=@MCHID AND (STA='2' OR STA='4');
end;


SELECT  @VERSION= MAX(CONVERT(INT,VERSION))  FROM EDD0001 WHERE ITNBR=@ITNBR AND SHFLAG='Y'; -- 2022-08-22 更改，审核过的最高版本，之前没有加审核 ;
 

with temp(ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo 
,SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle,PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight)
as
(
--初始查询
select ParentMatID,ParentMatEditionNo,ParentMatType,SubMatID,SubMatTypeName,EditionNo ,
SubMatNum,SubMatUnit,Usage,CompLocation,PCSCuttingAngle, PCSCuttinglength,PCSCuttingWidth,PCSBOMWeight
from EDD0061 where ParentMatID=@itnbr AND ParentMatEditionNo=@version   and ParentMatType=@outtypecod
union all
--递归条件
select a.ParentMatID,a.ParentMatEditionNo,a.ParentMatType,a.SubMatID,a.SubMatTypeName,a.EditionNo,
a.SubMatNum,a.SubMatUnit,a.Usage,a.CompLocation,a.PCSCuttingAngle,a.PCSCuttinglength,a.PCSCuttingWidth,a.PCSBOMWeight
from EDD0061 a 
inner join
temp b
on ( b.SubMatID=a.ParentMatID and b.SubMatTypeName=a.ParentMatType 
and b.EditionNo=a.ParentMatEditionNo)
)
select distinct * INTO #T2  from temp 
--2020-11-24更改，写死，但凡是父子物料相同的并且是SK更新 上级
MERGE INTO #T2 a
USING(SELECT * FROM #T2 WHERE SubMatTypeName='SK' AND ParentMatType='SK' ) b
 on a.SubMatID=b.ParentMatID and a.SubMatTypeName=b.ParentMatType  
when matched then
update set SubMatID=b.SubMatID;

--select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,CASE WHEN  PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1]  from #T2 temp INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 ON temp.SubMatTypeName=T1.TYPECOD AND temp.Usage=T1.COMPLOCATION;

select distinct SubMatID ITNBR,SubMatID ITDSC,tcod LDIV,TNAM,0 QTY,TYPECOD BOMDIV,CASE WHEN  PCSCuttinglength='' THEN 1.000 ELSE convert(decimal(9,3), PCSCuttinglength)/1000 END AS [ATTRIBUTE1]  from #T2 temp INNER JOIN (SELECT TCOD,TNAM,TYPECOD,TYPENAM,COMPLOCATION FROM QMA0014 WHERE MCHID=@MCHID) T1 ON temp.SubMatTypeName=T1.TYPECOD AND T1.COMPLOCATION like  '%'+temp.Usage+'%' ; 
drop table #T2
END
GO


