-- procedure structure for InsPlan_LH_RDERNOISNULL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[InsPlan_LH_RDERNOISNULL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[InsPlan_LH_RDERNOISNULL]
GO

CREATE PROCEDURE [dbo].[InsPlan_LH_RDERNOISNULL]
(
	@MCHID NVARCHAR(30),		--机台号
	@WDATE DATETIME,			--计划日期
	@ITNBR NVARCHAR(50),		--规格代码
	@ITDSC NVARCHAR(80),		--规格名称
	@LR NVARCHAR(1),			--左右机台
	@PLQTYA INT,				--早班计划量
	@PLQTYB INT,				--中班计划量
	@PLQTYC INT,				--晚班计划量
	@ENAM NVARCHAR(20),			--修改人
	@STQTY1 INT,				--定额1
	@STQTY2 INT,				--定额2
	@STQTY3 INT					--定额3
)
AS 
BEGIN
	DECLARE @FAC NVARCHAR(10),						--工厂代码
			@SEQ INT,								--计划顺序
			@VERSION NVARCHAR(10),					--版本号,
			@MCHTYPECOD NVARCHAR(10),				--设备类型代码
			@OUTTYPECOD NVARCHAR(10),				--产出物料类型
			@BUITNBR NVARCHAR(50),					--胎胚规格代码
			@BUITDSC NVARCHAR(50),					--胎胚规格名称
			@COLORLINE NVARCHAR(50),				--色线
			@COLORLINE2 NVARCHAR(50),				--色线2
			@SPEC NVARCHAR(20),						--胎胚SPEC号
			@GreenTyreMaterialID NVARCHAR(50),		--轮胎胎胚规格代码
			@SubMatEditionNo NVARCHAR(10),			--胎胚规格版本
			@CUITDSC NVARCHAR(100)			--硫化规格代码
	--初始化变量
	SET @SEQ = 1;
	SET @FAC='';
	SET @MCHTYPECOD='';
	SET @OUTTYPECOD='';
	SET @BUITNBR='';
	SET @BUITDSC='';
	SET @COLORLINE='';
	SET @COLORLINE2='';
	SET @SPEC='';
	SET @GreenTyreMaterialID='';
	SET @SubMatEditionNo='';
	SET @CUITDSC='';
	
	--获取设备类型代码,工厂代码                                                
		SELECT @MCHTYPECOD=TYPECOD,@FAC=e.FAC FROM EDC0001 AS e WHERE e.MCHID=@MCHID AND e.FAA='LH'
		
	--获取版本号，胎胚SPEC号，产出物料类型
		SELECT @VERSION=MAX([VERSION]),@SPEC=e.SPEC,@OUTTYPECOD=e.ITTYPECOD  FROM EDD0001 AS e 
		WHERE e.ITNBR=@ITNBR AND ITGRPCOD='FERT'  AND SHFLAG='Y'  and IS_USE=0 --e.FAC=@FAC AND
		GROUP BY e.SPEC,e.ITTYPECOD

		SELECT @CUITDSC=ITDSC FROM EDD0001 WHERE ITNBR=@ITNBR AND ITGRPCOD='FERT' AND [VERSION]=@VERSION--e.FAC=@FAC AND
		
	--获取色线
		SELECT TOP 1 @GreenTyreMaterialID=GreenTyreMaterialID,@SubMatEditionNo=SubMatEditionNo 
		FROM edd0006 T1 
		LEFT JOIN EDD0001 T2 ON T1.GreenTyreMaterialID=T2.ITNBR 
		WHERE TyreMaterialID=@ITNBR
		
 
		SELECT @COLORLINE=ATTRVAL  FROM EDD0002 WHERE ITEMID=
(SELECT MAX(ID) FROM EDD0001 WHERE FAC=@FAC AND ITNBR  =
( SELECT top 1 SubMatID  FROM EDD0061 AS e WHERE
 e.ParentMatID=@GreenTyreMaterialID AND SubmatTypeName='TD' ORDER BY CONVERT(INT,ParentMatEditionNo) DESC)) AND ATTRCOD='M96'
 
		SELECT @COLORLINE2=ATTRVAL  FROM EDD0002 WHERE ITEMID=
(SELECT MAX(ID) FROM EDD0001 WHERE FAC=@FAC AND ITNBR  =
( SELECT top 1 SubMatID  FROM EDD0061 AS e WHERE
 e.ParentMatID=@GreenTyreMaterialID AND SubmatTypeName='TD' ORDER BY CONVERT(INT,ParentMatEditionNo) DESC)) AND ATTRCOD='M12'
		set @COLORLINE=@COLORLINE+'('+@COLORLINE2+')';
	--获取计划顺序,当前机台当前左右的最大的顺序+1  
		SELECT @SEQ=CASE WHEN MAX(p.SEQA) IS NULL THEN 1 ELSE MAX(p.SEQA)+1 END FROM PLA0009 p 
		WHERE p.MCHID=@MCHID AND p.WDATE=@WDATE AND p.ATTRIBUTE1='FERT' AND LR=@LR --p.FAC=@FAC AND 
		
	--获取胎胚规格信息
		SELECT @BUITNBR=SPEC,@BUITDSC=ITDSC FROM edd0006 AS e 
		       LEFT JOIN EDD0001 AS e2 ON e.GreenTyreMaterialID=e2.ITNBR 
		WHERE e.TyreMaterialID=@ITNBR
		GROUP BY SPEC,ITDSC
    IF @CUITDSC<>''
	BEGIN
		SET @ITDSC=@CUITDSC
	END
	IF @LR='A'--左右机台
	BEGIN
		--左机台
		INSERT INTO PLA0009
		(
			ID,
			FAC,
			DIV,
			MCHTYPECOD,
			OUTTYPECOD,
			WDATE,
			MCHID,
			LR,
			ITNBR,
			ITDSC,
			PLQTY1,
			PLQTY2,
			PLQTY3,
			PLQTY,
			PLLOT1,
			PLLOT2,
			PLLOT3,
			PLLOT,
			[STATE],
			ENDCK,
			ENAM,
			ETIM,
			SEQA,
			SEQB,
			SEQC,
			VERSION,
			BUITNBR,
			BUITDSC,
			ATTRIBUTE1,
			ATTRIBUTE2,
			COLORLINE,
			SPEC,
			STQTY1,
			STQTY2,
			STQTY3,
			STQTY
		)
		VALUES
		(
			NEWID(),
			@FAC,
			'1',
			@MCHTYPECOD,
			@OUTTYPECOD,
			@WDATE,
			@MCHID,
			'L',
			@ITNBR,
			@ITDSC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			'1',
			'N',
			@ENAM,
			GETDATE(),
			@SEQ,
			@SEQ,
			@SEQ,
			@VERSION,
			@BUITNBR,
			@BUITDSC,
			'FERT',
			'N',
			@COLORLINE,
			@SPEC,
			@STQTY1,
			@STQTY2,
			@STQTY3,
			@STQTY1+@STQTY2+@STQTY3
		)
		--右机台
		INSERT INTO PLA0009
		(
			ID,
			FAC,
			DIV,
			MCHTYPECOD,
			OUTTYPECOD,
			WDATE,
			MCHID,
			LR,
			ITNBR,
			ITDSC,
			PLQTY1,
			PLQTY2,
			PLQTY3,
			PLQTY,
			PLLOT1,
			PLLOT2,
			PLLOT3,
			PLLOT,
			[STATE],
			ENDCK,
			ENAM,
			ETIM,
			SEQA,
			SEQB,
			SEQC,
			VERSION,
			BUITNBR,
			BUITDSC,
			ATTRIBUTE1,
			ATTRIBUTE2,
			COLORLINE,
			SPEC,
			STQTY1,
			STQTY2,
			STQTY3,
			STQTY
		)
		VALUES
		(
			NEWID(),
			@FAC,
			'1',
			@MCHTYPECOD,
			@OUTTYPECOD,
			@WDATE,
			@MCHID,
			'R',
			@ITNBR,
			@ITDSC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			'1',
			'N',
			@ENAM,
			GETDATE(),
			@SEQ,
			@SEQ,
			@SEQ,
			@VERSION,
			@BUITNBR,
			@BUITDSC,
			'FERT',
			'N',
			@COLORLINE,
			@SPEC,
			@STQTY1,
			@STQTY2,
			@STQTY3,
			@STQTY1+@STQTY2+@STQTY3
		)
	END
	ELSE IF @LR ='L'--左机台
	BEGIN
		INSERT INTO PLA0009
		(
			ID,
			FAC,
			DIV,
			MCHTYPECOD,
			OUTTYPECOD,
			WDATE,
			MCHID,
			LR,
			ITNBR,
			ITDSC,
			PLQTY1,
			PLQTY2,
			PLQTY3,
			PLQTY,
			PLLOT1,
			PLLOT2,
			PLLOT3,
			PLLOT,
			[STATE],
			ENDCK,
			ENAM,
			ETIM,
			SEQA,
			SEQB,
			SEQC,
			VERSION,
			BUITNBR,
			BUITDSC,
			ATTRIBUTE1,
			ATTRIBUTE2,
			COLORLINE,
			SPEC,
			STQTY1,
			STQTY2,
			STQTY3,
			STQTY
		)
		VALUES
		(
			NEWID(),
			@FAC,
			'1',
			@MCHTYPECOD,
			@OUTTYPECOD,
			@WDATE,
			@MCHID,
			@LR,
			@ITNBR,
			@ITDSC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			'1',
			'N',
			@ENAM,
			GETDATE(),
			@SEQ,
			@SEQ,
			@SEQ,
			@VERSION,
			@BUITNBR,
			@BUITDSC,
			'FERT',
			'N',
			@COLORLINE,
			@SPEC,
			@STQTY1,
			@STQTY2,
			@STQTY3,
			@STQTY1+@STQTY2+@STQTY3
		)
	END
	ELSE--右机台
	BEGIN
		INSERT INTO PLA0009
		(
			ID,
			FAC,
			DIV,
			MCHTYPECOD,
			OUTTYPECOD,
			WDATE,
			MCHID,
			LR,
			ITNBR,
			ITDSC,
			PLQTY1,
			PLQTY2,
			PLQTY3,
			PLQTY,
			PLLOT1,
			PLLOT2,
			PLLOT3,
			PLLOT,
			[STATE],
			ENDCK,
			ENAM,
			ETIM,
			SEQA,
			SEQB,
			SEQC,
			VERSION,
			BUITNBR,
			BUITDSC,
			ATTRIBUTE1,
			ATTRIBUTE2,
			COLORLINE,
			SPEC,
			STQTY1,
			STQTY2,
			STQTY3,
			STQTY
		)
		VALUES
		(
			NEWID(),
			@FAC,
			'1',
			@MCHTYPECOD,
			@OUTTYPECOD,
			@WDATE,
			@MCHID,
			@LR,
			@ITNBR,
			@ITDSC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			@PLQTYA,
			@PLQTYB,
			@PLQTYC,
			@PLQTYA+@PLQTYB+@PLQTYC,
			'1',
			'N',
			@ENAM,
			GETDATE(),
			@SEQ,
			@SEQ,
			@SEQ,
			@VERSION,
			@BUITNBR,
			@BUITDSC,
			'FERT',
			'N',
			@COLORLINE,
			@SPEC,
			@STQTY1,
			@STQTY2,
			@STQTY3,
			@STQTY1+@STQTY2+@STQTY3
		)
	END
END
GO


-- ----------------------------
-- procedure structure for SP_EXEC_SQL
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SP_EXEC_SQL]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SP_EXEC_SQL]
GO

CREATE PROCEDURE [dbo].[SP_EXEC_SQL]
	@sql NVARCHAR(MAX)
AS
BEGIN
	BEGIN TRANSACTION
    DECLARE @nror INT
    SET @nror=0 
	SELECT @sql = RTRIM(@sql)
	IF @sql<>''
	BEGIN
		EXEC (@sql)
		SET @nror=@nror+@@ERROR
	END
	IF @nror=0
	BEGIN 
		COMMIT TRANSACTION
		RETURN 1
    END
    ELSE 
    BEGIN 
        ROLLBACK TRANSACTION
		RETURN 0
    END 
END
GO


-- ----------------------------
-- procedure structure for SQMB0001_PCR
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SQMB0001_PCR]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SQMB0001_PCR]
GO

CREATE PROCEDURE [dbo].[SQMB0001_PCR]
  AS 
  DECLARE @WDATE   DATE                                                --工厂时间
   DECLARE @SHT   NVARCHAR (1)                                            --班次
   DECLARE @CRTIM1   DATETIME                                         --班次开始时间
   DECLARE @CRTIM2   DATETIME                                         --班次结束时间

     DECLARE @shifttb TABLE
                    (
                       WDATE      DATE,
                       SHT        NVARCHAR (20),
                       NSHT       NVARCHAR (20),
                       BAN        NVARCHAR (20),
                       STIME      DATETIME,
                       ETIME      DATETIME,
                       SHTNAM     NVARCHAR (20),
                       NSHTNAM    NVARCHAR (20)
                    )
   INSERT INTO @shifttb EXEC GetShift;
   
   SELECT @WDATE = WDATE,
          @SHT = SHT,
          @CRTIM1 = STIME,
          @CRTIM2 = ETIME
   FROM @shifttb;

      DECLARE @FAC   NVARCHAR (10) --工厂
   DECLARE @BCOD   NVARCHAR (20)  --缺陷代码
   DECLARE @BNAM   NVARCHAR (50)  --缺陷名称
   DECLARE @RESULT   NVARCHAR (10)  --判定结果
   DECLARE @BARCODE NVARCHAR (20)   --条码号
   
   --AND BARCODE NOT IN (SELECT DISTINCT NOW_BARCODE FROM SJC0003_PCR WHERE TXNTIME BETWEEN @CRTIM1 AND @CRTIM2) 

   declare tb_cursor cursor
   for
   SELECT DISTINCT fac,BADCOD,BADNAM,RESULT,BARCODE FROM QMB0001 nolock  where CHECKTIM between @CRTIM1 and @CRTIM2 and RESULT NOT IN ('1','1.9')  and BADCOD in (select ecode from qma0006 where IS_ALM=1)
   AND BARCODE NOT IN (select NOW_BARCODE FROM SJC0003_PCR nolock WHERE TXNTIME BETWEEN @CRTIM1 AND @CRTIM2 )
   open tb_cursor

   fetch next from tb_cursor into @fac,@bcod,@bnam,@result,@barcode
   while @@FETCH_STATUS=0
   begin
	if not exists (select TOP 1 * FROM SJC0003_PCR WHERE TXNTIME BETWEEN @CRTIM1 AND @CRTIM2 AND BARCODES LIKE '%'+@BARCODE+'%' )
	BEGIN
		 --如果是全钢，则FAC合并
	   IF(@FAC != '02')
		  BEGIN
			SET @FAC = '01,03'
		  END
	   --如果结果是次废品
	   IF(@RESULT = '2' or @RESULT = '3')
		  BEGIN
			EXEC dbo.sp_qc_alarm_scrap @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
			EXEC dbo.sp_qc_alarm_scraprepair @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
			EXEC dbo.sp_qc_alarm_scrappolished @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
			EXEC dbo.sp_qc_alarm_allquality @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
		  END
	   --如果结果是修理品
	   IF(@RESULT = 'W1' or @RESULT = 'W2')
		  BEGIN
			EXEC dbo.sp_qc_alarm_repair @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
			EXEC dbo.sp_qc_alarm_polishedrepair @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
		  END
	   --如果结果是打磨品
	   IF(@RESULT = 'W3')
		  BEGIN
			EXEC dbo.sp_qc_alarm_grind @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
		  END
	END
	
   fetch next from tb_cursor into @fac,@bcod,@bnam,@result,@barcode
   end

   close tb_cursor
   deallocate tb_cursor
GO


