			where a.ITTYPECOD='PCRTYRE' AND a.FAC in ('02','12') 
		) A 
		WHERE A.RowId=1 and SPEC<>'null' and SPEC<>''  and ITNBR like '%'+@itnbrdd+'%'
	),
	t_t2 as --停产时长
	(
		
		SELECT MaterialID,isnull(convert(nvarchar(10), DATEDIFF(day,MAX(WDATE),getdate())),999999) StopDay 
		FROM tb_PP_CuringOutPut 
		where BeginTime>( DATEADD(DAY,-300,GETDATE()) ) and FAC in ('02','12') and  MaterialID<>''
		 AND isnull(CUSTATE,'')  IN ('1','')  GROUP BY MaterialID 
	),
	t_t3 as --查例查基础规则获取自然天
