	--left join t2 on t_t1.ITNBR = t2.ITNBR
	--group by SPEC having max(cday)<0 or max(cday) is null	
	--),
	--t4 as  --取一个差额天数最大的推送一个，过滤掉已停产规格
	--(
	--	select tt.*,t3.cdayMIN cday from
