		--left join #l_t2 on t4.ITNBR=#l_t2.ITNBR 
		--left join t_t3  on t4.SPEC = t_t3.SPEC  
		--where StopDay=0
	    order by SPEC

	
	drop table #l_t1
	--drop table #l_t2


END
