-- ----------------------------
-- Triggers structure for table CKA0007
-- ----------------------------
CREATE TRIGGER [dbo].[TG_CUREBAD_ALARM]
ON [dbo].[CKA0007]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
   DECLARE @FAC nvarchar(5) --工厂
   DECLARE @BARCODE nvarchar(20)--条码
   DECLARE @SPEC nvarchar(30)--SPEC号
   DECLARE @BUITNBR nvarchar(30)--成型规格代码
   DECLARE @BUITDSC nvarchar(100)--成型规格名称
   DECLARE @cumch nvarchar(10)--硫化机台号
   DECLARE @cumchs nvarchar(255)--硫化机台号
   DECLARE @WAYNO nvarchar(30)--分拣道口号
   DECLARE @OPERATE nvarchar(20)--队列操作
   DECLARE @REASONDESC nvarchar(100)--详细原因描述
   
   DECLARE @cnt INT
   SET @cnt = 0
   
   SET @FAC = '02'
   SET @cumchs = ''
   SET @cumch = ''
   --在inserted表中查询已经插入记录信息
      SELECT @BARCODE = Barcode,
             @WAYNO = WayNo
   FROM inserted;
   --只有道口号16才继续
   IF(@WAYNO = '16')
     BEGIN
       SELECT @SPEC=SPEC,@BUITNBR=BUITNBR, @BUITDSC=BUITDSC FROM LTA0001 WHERE BARCODE = @BARCODE
       IF(@SPEC!='' and @SPEC is not null)
         BEGIN
           --按SPEC查询硫化机台
           --SELECT DISTINCT MCHID INTO #TEMP_TB FROM EQA0060 WHERE GTSPEC = @SPEC ORDER BY MCHID
		   SELECT DISTINCT A.MCHID INTO #TEMP_TB from (
SELECT H.MCHID,H.ITNBR,H.ITDSC FROM (
SELECT * FROM PPD0002  WITH(NOLOCK) 
WHERE [STATE] IN (3,4) AND FAC='02' ) H
WHERE H.CRTIM=(SELECT MAX(CRTIM) FROM (SELECT * FROM PPD0002  WITH(NOLOCK) WHERE [STATE] IN (3,4) AND FAC='02') I  
WHERE H.MCHID=I.MCHID AND H.LR=I.LR)
) A --最新已完成或进行中的模具组装任务
LEFT JOIN
(SELECT T.ATTRVAL,M.ITNBR FROM EDD0001 M WITH(NOLOCK)
LEFT JOIN EDD0002 T WITH(NOLOCK) 
ON M.ID=T.ITEMID
WHERE  VERSION=(SELECT MAX(VERSION) FROM EDD0001 WITH(NOLOCK) WHERE M.ITNBR=EDD0001.ITNBR) 
AND M.ITTYPECOD='PCRTYRE' AND T.ATTRCOD='GreenTyreSPEC') B --物料主数据主表JOIN从表取SPEC
ON A.ITNBR=B.ITNBR
WHERE B.ATTRVAL= @SPEC
ORDER BY A.MCHID
           SELECT @cnt = count (1) FROM #TEMP_TB
           IF @cnt > 0
             BEGIN
               DECLARE cur_temp CURSOR FOR SELECT MCHID FROM #TEMP_TB
               OPEN cur_temp
               FETCH NEXT FROM cur_temp INTO @cumch
               WHILE @@FETCH_STATUS = 0
               BEGIN
                  SET @cumchs = @cumchs+@cumch+','
                  FETCH NEXT FROM cur_temp INTO @cumch --下一个
               END
               
               IF (@cumchs !='' and @cumchs is not null)
                 BEGIN
                   SET @cumchs = LEFT (@cumchs, LEN (@cumchs) - 1)
                 END
               CLOSE cur_temp
               DEALLOCATE cur_temp
               --判断详细漏扫原因
               select top 1 @OPERATE=operate from lta0005_log where barcode = @BARCODE order by op_time desc
               IF (@OPERATE ='' or @OPERATE is null)
                BEGIN
                  SET @REASONDESC = '从未扫入队列'
                END
               ELSE IF(@OPERATE = 'Delete')
                BEGIN
                  SET @REASONDESC = '曾扫入队列但清除后未重扫'
                END
               ELSE
                BEGIN
                  SET @REASONDESC = '队列存在但未消耗'
                END
               --插入推送表
               INSERT INTO CKA0008 (FAC,CDIV,CONTENT,TXNTIME,HDFLAG,HDTIM) 
               VALUES (@FAC,'1','条码【'+@BARCODE+'】无硫化信息『'+@REASONDESC+'』，成型规格代码【'+@BUITNBR+'】，成型规格描述【'+@BUITDSC+'】，硫化机台【'+@cumchs+'】，请前往补正信息，谢谢。',getdate(),'N',null)
               --插入履历表
               INSERT INTO PLMES.dbo.LTA0010(FAC, DIV, BARCODE, MCHID, LR, CONTDESC, ETIM, ENAM) 
                VALUES (@FAC, '99', @BARCODE, NULL, NULL, '无硫化信息『'+@REASONDESC+'』', getdate(), 'MES')
             END
           --删除临时表
           DROP TABLE #TEMP_TB
         END
     END
END
GO


