-- ----------------------------
-- Triggers structure for table LTA0001
-- ----------------------------
CREATE TRIGGER [dbo].[APSGTPROTRIGGER]
ON [dbo].[LTA0001]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
insert into APSPRO_GT
(FAC,BARCODE,ITNBR,WDATE,WTIME,WSHT,WBAN,MCHID,VERSION,PLANCOD,OPDIV,WRTTIME,READFLAG)
select FAC, barcode, BUITNBR itnbr,BUDAT wdate,CRTIM wtime,BUSHT  wsht,
buban wban,BUMCH mchid,BUVERSION VERSION,BUPLANCOD PLANCOD,'1' opdiv,getdate() wrttime,'N' readflag
from inserted   i  WHERE  FAC IN ('01','03')

END
GO

DISABLE TRIGGER [dbo].[APSGTPROTRIGGER] ON [dbo].[LTA0001]
GO

CREATE TRIGGER [dbo].[APSGTPROTRIGGER2]
ON [dbo].[LTA0001]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
 DECLARE @ISDELETE NVARCHAR(10)
 SELECT @ISDELETE=i.IS_DELETE FROM inserted i
 if(@ISDELETE='1')
 begin
insert into APSPRO_GT
(FAC,BARCODE,ITNBR,WDATE,WTIME,WSHT,WBAN,MCHID,VERSION,PLANCOD,OPDIV,WRTTIME,READFLAG)
select FAC, barcode, BUITNBR itnbr,BUDAT wdate,CRTIM wtime,BUSHT  wsht,
buban wban,BUMCH mchid,BUVERSION VERSION,BUPLANCOD PLANCOD,'5' opdiv,getdate() wrttime,'N' readflag
from inserted   i  WHERE FAC IN ('01','03')
 end

END
GO

DISABLE TRIGGER [dbo].[APSGTPROTRIGGER2] ON [dbo].[LTA0001]
GO

CREATE TRIGGER [dbo].[trg_PreventDuplicateBarcode]
ON [dbo].[LTA0001]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;

    -- 检查是否有重复的条码在新插入的数据和现有数据之间
    IF EXISTS (
        SELECT 1
        FROM [LTA0001] i with(nolock)
         WHERE  BARCODE in (SELECT BARCODE FROM inserted)
		GROUP BY BARCODE
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入重复的条码。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
	IF EXISTS (
        SELECT 1
        FROM [tb_PP_CuringOutPut] i with(nolock) 
         WHERE  GreenTyreNo in (SELECT BARCODE FROM inserted)
		GROUP BY GreenTyreNo
        HAVING COUNT(*) >0
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入已经硫化的条码。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO


