      SELECT n.ID, n.FAC, n.EQUIPID, n.MCHID, n.LBARCODE, n.RBARCODE, n.LTYRENO, n.RTYRENO, n.LITNBR, n.LITDSC, n.RITNBR, n.RITDSC, n.FSTSTA,n.ETIM, @op, getdate(), 
      @@spid, 
