-- ----------------------------
-- Triggers structure for table LTC0001
-- ----------------------------
CREATE TRIGGER [dbo].[APSHALFPROTRIGGER]
ON [dbo].[LTC0001]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
insert into APSPRO_HALF
(FAC,BARCODE,ITNBR,WDATE,WTIME,WSHT,WBAN,MCHID,VERSION,PLANCOD,QTY,UNIT,OPDIV,WRTTIME,READFLAG)
select A.FAC,LOTID barcode, AITNBR itnbr,AUDAT wdate,A.CRTIM wtime,AUSHT  wsht,
AUBAN wban,AUMCH mchid,A.VERSION VERSION,ORDERNO PLANCOD,QTY,B.UNIT, '1' opdiv,getdate() wrttime,'N' readflag
from inserted A LEFT JOIN EDD0001 B ON A.AITNBR=B.ITNBR AND A.VERSION=B.VERSION  WHERE A.FAC IN ('01','03')

END
GO

DISABLE TRIGGER [dbo].[APSHALFPROTRIGGER] ON [dbo].[LTC0001]
GO

CREATE TRIGGER [dbo].[APSHALFPROTRIGGER2]
ON [dbo].[LTC0001]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
 DECLARE @ISDELETE int
 SELECT @ISDELETE=i.IS_DELETE FROM inserted i  WHERE FAC IN ('01','03')
 if(@ISDELETE=1)
 begin
	insert into APSPRO_HALF
(FAC,BARCODE,ITNBR,WDATE,WTIME,WSHT,WBAN,MCHID,VERSION,PLANCOD,QTY,UNIT,OPDIV,WRTTIME,READFLAG)
select A.FAC,LOTID barcode, AITNBR itnbr,AUDAT wdate,A.CRTIM wtime,AUSHT  wsht,
AUBAN wban,AUMCH mchid,A.VERSION VERSION,ORDERNO PLANCOD,QTY,B.UNIT, '5' opdiv,getdate() wrttime,'N' readflag
from inserted A LEFT JOIN EDD0001 B ON A.AITNBR=B.ITNBR AND A.VERSION=B.VERSION 
 end

END
GO

DISABLE TRIGGER [dbo].[APSHALFPROTRIGGER2] ON [dbo].[LTC0001]
GO

CREATE TRIGGER [dbo].[trg_Checklotid]
ON [dbo].[LTC0001]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;
	 
    -- 检查是否有重复的条码在新插入的数据和现有数据之间
    IF EXISTS (
        SELECT 1
        FROM ltc0001  
        WHERE  LOTID = (SELECT LOTID FROM inserted)
		GROUP BY LOTID
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入重复的条码。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO

DISABLE TRIGGER [dbo].[trg_Checklotid] ON [dbo].[LTC0001]
GO


