-- ----------------------------
-- Triggers structure for table PAC0006
-- ----------------------------
CREATE TRIGGER [dbo].[TRPAC0006_OPLOG]
ON [dbo].[PAC0006]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE, DELETE
AS
BEGIN
	 declare @di table(et varchar(200),pt varchar(200),ei varchar(max))
	insert into @di exec('dbcc inputbuffer(@@spid)')
	SET NOCOUNT ON;
	declare @op varchar(10)
   select @op=case when exists(select 1 from inserted) and exists(select 1 from deleted)
                   then 'Update'
                   when exists(select 1 from inserted) and not exists(select 1 from deleted)
                   then 'Insert'
                   when not exists(select 1 from inserted) and exists(select 1 from deleted)
                   then 'Delete' END
   if @op in('Insert')
   begin
   insert into pac0006_oplog
     (OPDIV,OPSID,prog_name,hostname,OPIP,runsql,OPTIM,
	 ID,fac,div,loginname,[NAME],[MCHID],ETIM,POSCOD )
     select @op,@@spid, 
       (select program_name from sys.dm_exec_sessions where session_id=@@spid),
       (select hostname from sys.sysprocesses where spid=@@spid),
       (select client_net_address from sys.dm_exec_connections where session_id=@@spid),
       (select top 1 isnull(ei,'') from @di),
       getdate(),	
	ID,fac,div,loginname,[NAME],[MCHID],ETIM,POSCOD 
     from inserted n
   end
   else
   begin
     insert into PAC0006_oplog
     (OPDIV,OPSID,prog_name,hostname,OPIP,runsql,OPTIM,
	 ID,fac,div,loginname,[NAME],[MCHID],ETIM,POSCOD )
     select @op,@@spid, 
       (select program_name from sys.dm_exec_sessions where session_id=@@spid),
       (select hostname from sys.sysprocesses where spid=@@spid),
       (select client_net_address from sys.dm_exec_connections where session_id=@@spid),
       (select top 1 isnull(ei,'') from @di),
       getdate(),	 
	ID,fac,div,loginname,[NAME],[MCHID],ETIM,POSCOD 
     from deleted o 
   end

END
GO

DISABLE TRIGGER [dbo].[TRPAC0006_OPLOG] ON [dbo].[PAC0006]
GO


