-- ----------------------------
-- Triggers structure for table PPB0103
-- ----------------------------
CREATE TRIGGER [dbo].[trg_PPB0103_Delete]
ON [dbo].[PPB0103]
WITH EXECUTE AS CALLER
FOR DELETE
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [ifdb].[MES_Interface].[dbo].[MES_X_Plan] (
        MatCode, 
        MatName, 
        EquipId, 
        PlanId, 
        PlanDate, 
        ShiftId, 
        WorkOrder, 
        SetNum, 
		Weight,
        WriteTime, 
        RW_Flag, 
        MES_Flag
    )
    SELECT 
        d.ITNBR,            -- 物料代码
        d.ITDSC,            -- 物料名称
        d.MCHID,            -- 机台编号
        ISNULL(d.ORDERNO, ''), 
        CONVERT(VARCHAR(10), d.WDATE, 120), 
        d.WSHT,             
        CAST(d.SEQ AS INT), 
        CAST(d.PLLOT AS INT), 
		ISNULL(l.Weight, 0),
        GETDATE(),          
        '0',                
        '2'                 -- 交互标识 (2=删除)
    FROM deleted d
	LEFT JOIN EDD0074 l ON l.MatCode = d.ITNBR AND l.EquipId = d.MCHID and l.Is_Delete ='0';
END;
GO

DISABLE TRIGGER [dbo].[trg_PPB0103_Delete] ON [dbo].[PPB0103]
GO

CREATE TRIGGER [dbo].[trg_PPB0103_Insert]
ON [dbo].[PPB0103]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [ifdb].[MES_Interface].[dbo].[MES_X_Plan] (
        MatCode, 
        MatName, 
        EquipId, 
        PlanId, 
        PlanDate, 
        ShiftId, 
        WorkOrder, 
        SetNum, 
		Weight,
        WriteTime, 
        RW_Flag, 
        MES_Flag
    )
    SELECT 
        i.ITNBR,            -- 物料代码 (规格代码)
        i.ITDSC,            -- 物料名称 (规格名称)
        i.MCHID,            -- 机台编号 (机台)
        ISNULL(i.ORDERNO, ''), -- 计划编号 (工单号)
        CONVERT(VARCHAR(10), i.WDATE, 120), -- 计划日期 (格式化为 yyyy-MM-dd)
        i.WSHT,             -- 班次
        CAST(i.SEQ AS INT), -- 计划顺序 (decimal -> int)
        CAST(i.PLLOT AS INT), -- 计划车数 (decimal -> int)
		ISNULL(l.Weight, 0),
        GETDATE(),          -- 写入时间 (当前时间)
        '0',                -- 读写标识 (固定为0)
        '0'                 -- 交互标识 (0=插入)
    FROM inserted i
	LEFT JOIN EDD0074 l ON l.MatCode = i.ITNBR AND l.EquipId = i.MCHID and l.Is_Delete ='0';
END;
GO

DISABLE TRIGGER [dbo].[trg_PPB0103_Insert] ON [dbo].[PPB0103]
GO

CREATE TRIGGER [dbo].[trg_PPB0103_Update]
ON [dbo].[PPB0103]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO [ifdb].[MES_Interface].[dbo].[MES_X_Plan] (
        MatCode, 
        MatName, 
        EquipId, 
        PlanId, 
        PlanDate, 
        ShiftId, 
        WorkOrder, 
        SetNum, 
		Weight,
        WriteTime, 
        RW_Flag, 
        MES_Flag
    )
    SELECT 
        i.ITNBR,            -- 物料代码
        i.ITDSC,            -- 物料名称
        i.MCHID,            -- 机台编号
        ISNULL(i.ORDERNO, ''), 
        CONVERT(VARCHAR(10), i.WDATE, 120), 
        i.WSHT,             
        CAST(i.SEQ AS INT), 
        CAST(i.PLLOT AS INT), 
		ISNULL(l.Weight, 0),
        GETDATE(),          
        '0',                
        '1'                 -- 交互标识 (1=修改)
    FROM inserted i
	LEFT JOIN EDD0074 l ON l.MatCode = i.ITNBR AND l.EquipId = i.MCHID and l.Is_Delete ='0';
END;
GO

DISABLE TRIGGER [dbo].[trg_PPB0103_Update] ON [dbo].[PPB0103]
GO


