-- ----------------------------
-- Triggers structure for table PPB0201
-- ----------------------------
CREATE TRIGGER [dbo].[trg_Checkorderno]
ON [dbo].[PPB0201]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;
	 
    -- 检查是否有重复的条码在新插入的数据和现有数据之间
    IF EXISTS (
        SELECT 1
        FROM [PPB0201]  
        WHERE  ORDERNOA = (SELECT ORDERNOA FROM inserted)
		GROUP BY ORDERNOA
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入重复的计划号。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
	 IF EXISTS (
        SELECT 1
        FROM [PPB0201]  
        WHERE  ORDERNOB = (SELECT ORDERNOB FROM inserted)
		GROUP BY ORDERNOB
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入重复的计划号。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
	 IF EXISTS (
        SELECT 1
        FROM [PPB0201]  
        WHERE  ORDERNOC = (SELECT ORDERNOC FROM inserted)
		GROUP BY ORDERNOC
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入重复的计划号。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO


