-- ----------------------------
-- Triggers structure for table QMB0001
-- ----------------------------
CREATE TRIGGER [dbo].[TG_QC_ALARM]
ON [dbo].[QMB0001]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
   DECLARE @FAC   NVARCHAR (10) --工厂
   DECLARE @BCOD   NVARCHAR (20)  --缺陷代码
   DECLARE @BNAM   NVARCHAR (50)  --缺陷名称
   DECLARE @RESULT   NVARCHAR (10)  --判定结果
   DECLARE @BARCODE NVARCHAR (20)   --条码号
   --在inserted表中查询已经插入记录信息
   SELECT @FAC = FAC,
          @BCOD = BADCOD,
          @BNAM = BADNAM,
          @RESULT = RESULT,
          @BARCODE = BARCODE
   FROM inserted;
   --如果是全钢，则FAC合并
   IF(@FAC != '02')
      BEGIN
        SET @FAC = '01,03'
      END
   --如果结果是次废品
   IF(@RESULT = '2' or @RESULT = '3')
      BEGIN
        EXEC dbo.sp_qc_alarm_scrap @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
      END
   --如果结果是修理品
   IF(@RESULT = 'W1' or @RESULT = 'W2')
      BEGIN
        EXEC dbo.sp_qc_alarm_repair @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
      END
   --如果结果是打磨品
   IF(@RESULT = 'W3')
      BEGIN
        EXEC dbo.sp_qc_alarm_grind @FAC,@BCOD,@BNAM,@RESULT,@BARCODE;
      END
END
GO

DISABLE TRIGGER [dbo].[TG_QC_ALARM] ON [dbo].[QMB0001]
GO


