-- ----------------------------
-- Triggers structure for table QMB0012
-- ----------------------------
CREATE TRIGGER [dbo].[TG_CHECK_DUP]
ON [dbo].[QMB0012]
WITH EXECUTE AS CALLER
INSTEAD OF INSERT
AS
BEGIN
  DECLARE @errmsg VARCHAR(500)
  DECLARE @BARCODE VARCHAR(20)
  DECLARE @DIV VARCHAR(2)
  DECLARE @FAC VARCHAR(5)
  
  SELECT @FAC = FAC,
          @BARCODE = BARCODE,
          @DIV = DIV
  FROM inserted;
  IF(@FAC = '02')
    BEGIN
        IF EXISTS(select*from qmb0012 
        where BARCODE =@BARCODE 
        AND DIV = @DIV
        AND FAC = @FAC)
          BEGIN
            ROLLBACK TRANSACTION;
            SET @errmsg='duplicate data!!';
            RAISERROR(@errmsg,16,1);
          END
        ELSE
          BEGIN
            INSERT INTO PLMES.dbo.QMB0012
            (FAC, BARCODE, DEPCOD, DEPNAM, [PERCENT], PERSON1, PERSON2, PERSON3, PERSONRAT1, PERSONRAT2, PERSONRAT3, ENAM, LOGINNAM, ETIM, CRTIM, CRDATE, DIV, RESULT, BCOD, TYRENO) 
            select FAC, BARCODE, DEPCOD, DEPNAM, [PERCENT], PERSON1, PERSON2, PERSON3, PERSONRAT1, PERSONRAT2, PERSONRAT3, ENAM, LOGINNAM, ETIM, CRTIM, CRDATE, DIV, RESULT, BCOD, TYRENO
            from inserted;
          END
    END
  ELSE--其它工厂直接插入
    BEGIN
      INSERT INTO PLMES.dbo.QMB0012
      (FAC, BARCODE, DEPCOD, DEPNAM, [PERCENT], PERSON1, PERSON2, PERSON3, PERSONRAT1, PERSONRAT2, PERSONRAT3, ENAM, LOGINNAM, ETIM, CRTIM, CRDATE, DIV, RESULT, BCOD, TYRENO) 
      select FAC, BARCODE, DEPCOD, DEPNAM, [PERCENT], PERSON1, PERSON2, PERSON3, PERSONRAT1, PERSONRAT2, PERSONRAT3, ENAM, LOGINNAM, ETIM, CRTIM, CRDATE, DIV, RESULT, BCOD, TYRENO
      from inserted;
    END
END
GO

DISABLE TRIGGER [dbo].[TG_CHECK_DUP] ON [dbo].[QMB0012]
GO


