-- ----------------------------
-- Triggers structure for table QMB0101
-- ----------------------------
CREATE TRIGGER [dbo].[trg_CheckTyrenoqmb0101]
ON [dbo].[QMB0101]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;
	 
    -- 检查是否有重复的条码在新插入的数据和现有数据之间
    IF EXISTS (
        SELECT 1
        FROM qmb0101  
        WHERE  TyreNo IN (SELECT TyreNo FROM inserted)
		GROUP BY TyreNo
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入重复的条码。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO


