-- ----------------------------
-- Triggers structure for table STC0017
-- ----------------------------
CREATE TRIGGER [dbo].[trg_Checkstc0017]
ON [dbo].[STC0017]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;
	 
    -- 检查是否有重复的条码在新插入的数据和现有数据之间
    IF EXISTS (
        SELECT 1
        FROM STC0017  
        WHERE  Transfercardnumber IN (SELECT Transfercardnumber FROM inserted)
		AND ShelfNumber IN  (SELECT ShelfNumber FROM inserted)
		AND TyreNo IN  (SELECT TyreNo FROM inserted)
		AND GOODSSTATE IN  (SELECT GOODSSTATE FROM inserted)
		GROUP BY GOODSSTATE,Transfercardnumber,ShelfNumber,TyreNo
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('存在重复数据。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO

DISABLE TRIGGER [dbo].[trg_Checkstc0017] ON [dbo].[STC0017]
GO


