-- ----------------------------
-- Triggers structure for table STD0014
-- ----------------------------
CREATE TRIGGER [dbo].[TRSTD0014_OPLOG]
ON [dbo].[STD0014]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE, DELETE
AS
BEGIN
    DECLARE @di TABLE(et VARCHAR(200),pt VARCHAR(200),ei VARCHAR(max))
	INSERT INTO @di EXEC('dbcc inputbuffer(@@spid)')
	SET NOCOUNT ON;
	DECLARE @op VARCHAR(10)
    SELECT @op=CASE WHEN EXISTS(select 1 from inserted) AND EXISTS(select 1 from deleted)
                   THEN 'Update'
                   WHEN EXISTS(select 1 from inserted) AND NOT EXISTS(select 1 from deleted)
                   THEN 'Insert'
                   WHEN NOT EXISTS(select 1 from inserted) AND EXISTS(select 1 from deleted)
                   THEN 'Delete' END
    IF @op IN('Insert','Update')
    BEGIN
	INSERT INTO STD0014_OPLOG([ID], [FAC], [DIV], [LOTID], [MCHID], [WSHT], [WBAN], [ITNBR], [ITDSC], [TOOLNO], [WT], [CHECODE], [STA], [STIME], [ETIME], [WDATE], [WTIME], [LOCKYN], [STKSTS], [STONO], [STOAREA], [SPEC], [REMARK], [USEMCH], [IS_DELETE], [QTY], [OPTIM], [OPSID], [OPIP], [OPDIV], [prog_name], [hostname], [RUNSQL])
	SELECT [ID], [FAC], [DIV], [LOTNO], '', '', '', [ITNBR], [ITDSC], [REMAKE1], [WT], '', [STA], [STARTTIME], [ENDTIME], '', '', [LOCKYN], [STKSTS], [STONO], [STOAREA], '', [REMARK], [USEMCH], [IS_DELETE], [QTY], GETDATE(), @@spid, (select client_net_address from sys.dm_exec_connections where session_id=@@spid), @op, (select program_name from sys.dm_exec_sessions where session_id=@@spid), (select hostname from sys.sysprocesses where spid=@@spid), (select top 1 isnull(ei,'') from @di) FROM inserted n 
    END
    ELSE
    BEGIN
	INSERT INTO STD0014_OPLOG([ID], [FAC], [DIV], [LOTID], [MCHID], [WSHT], [WBAN], [ITNBR], [ITDSC], [TOOLNO], [WT], [CHECODE], [STA], [STIME], [ETIME], [WDATE], [WTIME], [LOCKYN], [STKSTS], [STONO], [STOAREA], [SPEC], [REMARK], [USEMCH], [IS_DELETE], [QTY], [OPTIM], [OPSID], [OPIP], [OPDIV], [prog_name], [hostname], [RUNSQL])
	SELECT [ID], [FAC], [DIV], [LOTNO], '', '', '', [ITNBR], [ITDSC], [REMAKE1], [WT], '', [STA], [STARTTIME], [ENDTIME], '', '', [LOCKYN], [STKSTS], [STONO], [STOAREA], '', [REMARK], [USEMCH], [IS_DELETE], [QTY], GETDATE(), @@spid, (select client_net_address from sys.dm_exec_connections where session_id=@@spid), @op, (select program_name from sys.dm_exec_sessions where session_id=@@spid), (select hostname from sys.sysprocesses where spid=@@spid), (select top 1 isnull(ei,'') from @di) FROM deleted o     
    END
	IF @op  ='Update'
    BEGIN
	INSERT INTO STD0014_OPLOG([ID], [FAC], [DIV], [LOTID], [MCHID], [WSHT], [WBAN], [ITNBR], [ITDSC], [TOOLNO], [WT], [CHECODE], [STA], [STIME], [ETIME], [WDATE], [WTIME], [LOCKYN], [STKSTS], [STONO], [STOAREA], [SPEC], [REMARK], [USEMCH], [IS_DELETE], [QTY], [OPTIM], [OPSID], [OPIP], [OPDIV], [prog_name], [hostname], [RUNSQL])
	SELECT [ID], [FAC], [DIV], [LOTNO],  '', '', '', [ITNBR], [ITDSC], [REMAKE1], [WT], '', [STA], [STARTTIME], [ENDTIME], '', '', [LOCKYN], [STKSTS], [STONO], [STOAREA], '', [REMARK], [USEMCH], [IS_DELETE], [QTY], GETDATE(), @@spid, (select client_net_address from sys.dm_exec_connections where session_id=@@spid), @op, (select program_name from sys.dm_exec_sessions where session_id=@@spid), (select hostname from sys.sysprocesses where spid=@@spid), (select top 1 isnull(ei,'') from @di) FROM inserted n 
    END
	ELSE IF @op  ='Delete'
    BEGIN
	INSERT INTO STD0014_OPLOG([ID], [FAC], [DIV], [LOTID], [MCHID], [WSHT], [WBAN], [ITNBR], [ITDSC], [TOOLNO], [WT], [CHECODE], [STA], [STIME], [ETIME], [WDATE], [WTIME], [LOCKYN], [STKSTS], [STONO], [STOAREA], [SPEC], [REMARK], [USEMCH], [IS_DELETE], [QTY], [OPTIM], [OPSID], [OPIP], [OPDIV], [prog_name], [hostname], [RUNSQL])
	SELECT [ID], [FAC], [DIV], [LOTNO],  '', '', '', [ITNBR], [ITDSC], [REMAKE1], [WT], '', [STA], [STARTTIME], [ENDTIME], '', '', [LOCKYN], [STKSTS], [STONO], [STOAREA], '', [REMARK], [USEMCH], [IS_DELETE], [QTY], GETDATE(), @@spid, (select client_net_address from sys.dm_exec_connections where session_id=@@spid), @op, (select program_name from sys.dm_exec_sessions where session_id=@@spid), (select hostname from sys.sysprocesses where spid=@@spid), (select top 1 isnull(ei,'') from @di) FROM deleted o     
    END
END
GO


