-- ----------------------------
-- Triggers structure for table tb_PP_CuringOutPut
-- ----------------------------
CREATE TRIGGER [dbo].[APSPROTRIGGER]
ON [dbo].[tb_PP_CuringOutPut]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
 insert into APSPRO_FT
(FAC,BARCODE,ITNBR,WDATE,WTIME,WSHT,WBAN,MCHID,LR,OPDIV,WRTTIME,READFLAG)
select FAC,GreenTyreNo barcode,MaterialID itnbr,WDATE,BeginTime wtime,SulfShift wsht,
SulfTeam wban,SulfEquipCode mchid,LeftOrRight LR,'1' opdiv,getdate() wrttime,'N' readflag
from inserted   i

END
GO

DISABLE TRIGGER [dbo].[APSPROTRIGGER] ON [dbo].[tb_PP_CuringOutPut]
GO

CREATE TRIGGER [dbo].[trg_CheckTyreno]
ON [dbo].[tb_PP_CuringOutPut]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;
	 
    -- 检查是否有重复的条码在新插入的数据和现有数据之间
    IF EXISTS (
        SELECT 1
        FROM [tb_PP_CuringOutPut]  
        WHERE  TyreNo in (SELECT TyreNo FROM inserted)
		GROUP BY TyreNo
        HAVING COUNT(*) > 1
    )
    BEGIN
        -- 如果存在重复条码，则抛出错误并回滚事务
        RAISERROR ('不能插入重复的条码。', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO

CREATE TRIGGER [dbo].[TRIDK]
ON [dbo].[tb_PP_CuringOutPut]
WITH EXECUTE AS CALLER
FOR INSERT, DELETE
AS
BEGIN
	
	 if EXISTS (SELECT 1 FROM inserted)
	begin
	declare @lr nvarchar(10),@mchid nvarchar(10),@itnbr nvarchar(50),@barcode nvarchar(50),@tyreno nvarchar(50),@wtime datetime,@dot nvarchar(10),@ITDSC NVARCHAR(200),@NORMALSTA NVARCHAR(10);
	declare @CARVEDYN1 nvarchar(10), @CARVEDYN2 nvarchar(10), @CARVEDYN3 nvarchar(10), @CARVEDYN4 nvarchar(10), @CARVEDYN5 nvarchar(10), @CARVEDYN6 nvarchar(10), 
@CARVEDYN7 nvarchar(10), @CARVEDYN10 nvarchar(10), @CARVEDYN13 nvarchar(10), @CARVEDYN16 nvarchar(10), @CARVEDYN19 nvarchar(10),  
@CARVEDYN8 nvarchar(10), @CARVEDYN11 nvarchar(10), @CARVEDYN14 nvarchar(10), @CARVEDYN17 nvarchar(10), @CARVEDYN20 nvarchar(10), 
@CARVEDYN9 nvarchar(10), @CARVEDYN12 nvarchar(10), @CARVEDYN15 nvarchar(10), @CARVEDYN18 nvarchar(10);
	select @lr=LeftOrRight,@tyreno=TyreNo,@barcode=GreenTyreNo,@mchid=SulfEquipCode,@itnbr=MaterialID,@wtime= BeginTime,@dot=DOT,@ITDSC=MaterialName,@NORMALSTA=NORMALSTA from inserted

	--先判断规格是否符合
	if(EXISTS(select 1 from EDD0701_COPY WHERE ITNBR=@itnbr))
		BEGIN
		--如果符合就插入雕刻追溯表

		--1.去设备雕刻配置表取值
		declare @dotyn nvarchar(10),@codeyn nvarchar(10),@isfst nvarchar(10);
		SET @dotyn='N';
		set @codeyn='N';
		set @isfst='N';
		
		if(EXISTS(select 1 from edc0024 where mchid=@mchid and lr=@lr and useyn='Y' and ITNBR=@itnbr and UPDTIM<@wtime))
		begin
			select @isfst=attribute1 from edc0024 where mchid=@mchid and lr=@lr and useyn='Y' and ITNBR=@itnbr
			select @dotyn=dotdk,@codeyn=codedk,
			@CARVEDYN1=CARVEDYN1,@CARVEDYN5=CARVEDYN5,@CARVEDYN9=CARVEDYN9,@CARVEDYN13=CARVEDYN13,@CARVEDYN17=CARVEDYN17,
			@CARVEDYN2=CARVEDYN2,@CARVEDYN6=CARVEDYN6,@CARVEDYN10=CARVEDYN10,@CARVEDYN14=CARVEDYN14,@CARVEDYN18=CARVEDYN18,
			@CARVEDYN3=CARVEDYN3,@CARVEDYN7=CARVEDYN7,@CARVEDYN11=CARVEDYN11,@CARVEDYN15=CARVEDYN15,@CARVEDYN19=CARVEDYN19,
			@CARVEDYN4=CARVEDYN4,@CARVEDYN8=CARVEDYN8,@CARVEDYN12=CARVEDYN12,@CARVEDYN16=CARVEDYN16,@CARVEDYN20=CARVEDYN20
			from edc0024 where mchid=@mchid and lr=@lr and useyn='Y' and ITNBR=@itnbr
 
			begin try
			INSERT INTO QMB0010(TYRERADIUS,DOTRADIUS,SECHEIGHT,
			RADIUSMAKE1,CARVEDANGLE1,CARVEDTEXT1,CARVEDYN1,
			RADIUSMAKE2,CARVEDANGLE2,CARVEDTEXT2,CARVEDYN2,
			RADIUSMAKE3,CARVEDANGLE3,CARVEDTEXT3,CARVEDYN3,
			RADIUSMAKE4,CARVEDANGLE4,CARVEDTEXT4,CARVEDYN4,
			RADIUSMAKE5,CARVEDANGLE5,CARVEDTEXT5,CARVEDYN5,
			RADIUSMAKE6,CARVEDANGLE6,CARVEDTEXT6,CARVEDYN6,
			RADIUSMAKE7,CARVEDANGLE7,CARVEDTEXT7,CARVEDYN7,
			RADIUSMAKE8,CARVEDANGLE8,CARVEDTEXT8,CARVEDYN8,
			RADIUSMAKE9,CARVEDANGLE9,CARVEDTEXT9,CARVEDYN9,
			RADIUSMAKE10,CARVEDANGLE10,CARVEDTEXT10,CARVEDYN10,
			RADIUSMAKE11,CARVEDANGLE11,CARVEDTEXT11,CARVEDYN11,
			RADIUSMAKE12,CARVEDANGLE12,CARVEDTEXT12,CARVEDYN12,
			RADIUSMAKE13,CARVEDANGLE13,CARVEDTEXT13,CARVEDYN13,
			RADIUSMAKE14,CARVEDANGLE14,CARVEDTEXT14,CARVEDYN14,
			RADIUSMAKE15,CARVEDANGLE15,CARVEDTEXT15,CARVEDYN15,
			RADIUSMAKE16,CARVEDANGLE16,CARVEDTEXT16,CARVEDYN16,
			RADIUSMAKE17,CARVEDANGLE17,CARVEDTEXT17,CARVEDYN17,
			RADIUSMAKE18,CARVEDANGLE18,CARVEDTEXT18,CARVEDYN18,
			RADIUSMAKE19,CARVEDANGLE19,CARVEDTEXT19,CARVEDYN19,
			RADIUSMAKE20,CARVEDANGLE20,CARVEDTEXT20,CARVEDYN20,
			CARVEDUD1,CARVEDUD2,CARVEDUD3,CARVEDUD4,CARVEDUD5,
			CARVEDUD6,CARVEDUD7,CARVEDUD8,CARVEDUD9,CARVEDUD10,
			CARVEDUD11,CARVEDUD12,CARVEDUD13,CARVEDUD14,CARVEDUD15,
			CARVEDUD16,CARVEDUD17,CARVEDUD18,CARVEDUD19,CARVEDUD20,
			DKYN,DKUD,ZKINC,ECE,R117 ,FERCODE,
			 TYRENO, WTIME,BARCODE,ITNBR,ITDSC, LHMCHID, LR , CARVEQC , carveYN ,DOT,isfst)
			selecT TYRERADIUS,DOTRADIUS,SECHEIGHT,
			RADIUSMAKE1,CARVEDANGLE1,CARVEDTEXT1,@CARVEDYN1 CARVEDYN1,
			RADIUSMAKE2,CARVEDANGLE2,CARVEDTEXT2,@CARVEDYN2 CARVEDYN2,
			RADIUSMAKE3,CARVEDANGLE3,CARVEDTEXT3,@CARVEDYN3 CARVEDYN3,
			RADIUSMAKE4,CARVEDANGLE4,CARVEDTEXT4,@CARVEDYN4 CARVEDYN4,
			RADIUSMAKE5,CARVEDANGLE5,CARVEDTEXT5,@CARVEDYN5 CARVEDYN5,
			RADIUSMAKE6,CARVEDANGLE6,CARVEDTEXT6,@CARVEDYN6 CARVEDYN6,
			RADIUSMAKE7,CARVEDANGLE7,CARVEDTEXT7,@CARVEDYN7 CARVEDYN7,
			RADIUSMAKE8,CARVEDANGLE8,CARVEDTEXT8,@CARVEDYN8 CARVEDYN8,
			RADIUSMAKE9,CARVEDANGLE9,CARVEDTEXT9,@CARVEDYN9 CARVEDYN9,
			RADIUSMAKE10,CARVEDANGLE10,CARVEDTEXT10,@CARVEDYN10 CARVEDYN10,
			RADIUSMAKE11,CARVEDANGLE11,CARVEDTEXT11,@CARVEDYN11 CARVEDYN11,
			RADIUSMAKE12,CARVEDANGLE12,CARVEDTEXT12,@CARVEDYN12 CARVEDYN12,
			RADIUSMAKE13,CARVEDANGLE13,CARVEDTEXT13,@CARVEDYN13 CARVEDYN13,
			RADIUSMAKE14,CARVEDANGLE14,CARVEDTEXT14,@CARVEDYN14 CARVEDYN14,
			RADIUSMAKE15,CARVEDANGLE15,CARVEDTEXT15,@CARVEDYN15 CARVEDYN15,
			RADIUSMAKE16,CARVEDANGLE16,CARVEDTEXT16,@CARVEDYN16 CARVEDYN16,
			RADIUSMAKE17,CARVEDANGLE17,CARVEDTEXT17,@CARVEDYN17 CARVEDYN17,
			RADIUSMAKE18,CARVEDANGLE18,CARVEDTEXT18,@CARVEDYN18 CARVEDYN18,
			RADIUSMAKE19,CARVEDANGLE19,CARVEDTEXT19,@CARVEDYN19 CARVEDYN19,
			RADIUSMAKE20,CARVEDANGLE20,CARVEDTEXT20,@CARVEDYN20 CARVEDYN20,
			CARVEDUD1,CARVEDUD2,CARVEDUD3,CARVEDUD4,CARVEDUD5,
			CARVEDUD6,CARVEDUD7,CARVEDUD8,CARVEDUD9,CARVEDUD10,
			CARVEDUD11,CARVEDUD12,CARVEDUD13,CARVEDUD14,CARVEDUD15,
			CARVEDUD16,CARVEDUD17,CARVEDUD18,CARVEDUD19,CARVEDUD20,
			'Y' DKYN,DKUD,ZKINC,ECE,R117 ,FERCODE,
			@tyreno TYRENO,@wtime WTIME,@barcode BARCODE,@itnbr ITNBR,@ITDSC itdsc,@mchid LHMCHID,@lr LR ,2 CARVEQC ,'N' carveYN,@DOT DOT,@isfst [ISFST] from EDD0701_COPY where ITNBR=@itnbr
			 END TRY
			BEGIN CATCH
			 -- 记录错误信息到 ErrorLog 表
			-- insert into LSLOG_OTHERLOG(id,WTIME,USERID,USERNAM,LOGTEXT) values (NEWID(),GETDATE(),'dk_err','雕刻错误,胎号:'+@tyreno,ERROR_MESSAGE());
			-- INSERT INTO QMB0010_error(TYRERADIUS,DOTRADIUS,SECHEIGHT,
			--RADIUSMAKE1,CARVEDANGLE1,CARVEDTEXT1,CARVEDYN1,
			--RADIUSMAKE2,CARVEDANGLE2,CARVEDTEXT2,CARVEDYN2,
			--RADIUSMAKE3,CARVEDANGLE3,CARVEDTEXT3,CARVEDYN3,
			--RADIUSMAKE4,CARVEDANGLE4,CARVEDTEXT4,CARVEDYN4,
			--RADIUSMAKE5,CARVEDANGLE5,CARVEDTEXT5,CARVEDYN5,
