	LR,
	REMARK,
	IS_DELETE,
	TOOLSTA,
	ERPCODE
     from inserted n
   end
   else
   begin
     insert into WIP0001_OPLOG
     (OPDIV,OPSID,prog_name,hostname,OPIP,runsql,OPTIM,	
