-- ----------------------------
-- Triggers structure for table WIP0010
-- ----------------------------
CREATE TRIGGER [dbo].[TRWIP0010_OPLOG]
ON [dbo].[WIP0010]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE, DELETE
AS
BEGIN
	 declare @di table(et varchar(200),pt varchar(200),ei varchar(max))
	insert into @di exec('dbcc inputbuffer(@@spid)')
	SET NOCOUNT ON;
	declare @op varchar(10)
   select @op=case when exists(select 1 from inserted) and exists(select 1 from deleted)
                   then 'Update'
                   when exists(select 1 from inserted) and not exists(select 1 from deleted)
                   then 'Insert'
                   when not exists(select 1 from inserted) and exists(select 1 from deleted)
                   then 'Delete' END
   if @op in('Insert')
   begin
   insert into WIP0010_OPLOG
     (OPDIV,OPSID,prog_name,hostname,OPIP,runsql,OPTIM,
	 [ID]
           ,[FAC]
           ,[BARCODE]
           ,[MCHID]
           ,[LRFLAG]
           ,[WSHT]
           ,[WBAN]
           ,[ITNBR]
           ,[ITDSC]
           ,[STA]
           ,[WDATE]
           ,[WTIME]
           ,[STKSTS]
           ,[CRTIM]
           ,[UPDTIM]
           ,[STOAREA]
           ,[INLOC]
           ,[TYRENO]
           ,[STODIV]
           ,[LOCKYN]
           ,[REMARK]
           ,[TYRESTA]
           ,[DOT]
           ,[IS_DELETE]
           ,[MCHDIV])
     select @op,@@spid, 
       (select program_name from sys.dm_exec_sessions where session_id=@@spid),
       (select hostname from sys.sysprocesses where spid=@@spid),
       (select client_net_address from sys.dm_exec_connections where session_id=@@spid),
       (select top 1 isnull(ei,'') from @di),
       getdate(),	
	[ID]
           ,[FAC]
           ,[BARCODE]
           ,[MCHID]
           ,[LRFLAG]
           ,[WSHT]
           ,[WBAN]
           ,[ITNBR]
           ,[ITDSC]
           ,[STA]
           ,[WDATE]
           ,[WTIME]
           ,[STKSTS]
           ,[CRTIM]
           ,[UPDTIM]
           ,[STOAREA]
           ,[INLOC]
           ,[TYRENO]
           ,[STODIV]
           ,[LOCKYN]
           ,[REMARK]
           ,[TYRESTA]
           ,[DOT]
           ,[IS_DELETE]
           ,[MCHDIV]
     from inserted n
   end
   else
   begin
     insert into WIP0010_OPLOG
     (OPDIV,OPSID,prog_name,hostname,OPIP,runsql,OPTIM,	
	 [ID]
           ,[FAC]
           ,[BARCODE]
           ,[MCHID]
           ,[LRFLAG]
           ,[WSHT]
           ,[WBAN]
           ,[ITNBR]
           ,[ITDSC]
           ,[STA]
           ,[WDATE]
           ,[WTIME]
           ,[STKSTS]
           ,[CRTIM]
           ,[UPDTIM]
           ,[STOAREA]
           ,[INLOC]
           ,[TYRENO]
           ,[STODIV]
           ,[LOCKYN]
           ,[REMARK]
           ,[TYRESTA]
           ,[DOT]
           ,[IS_DELETE]
           ,[MCHDIV])
     select @op,@@spid, 
       (select program_name from sys.dm_exec_sessions where session_id=@@spid),
       (select hostname from sys.sysprocesses where spid=@@spid),
       (select client_net_address from sys.dm_exec_connections where session_id=@@spid),
       (select top 1 isnull(ei,'') from @di),
       getdate(),	
	  [ID]
           ,[FAC]
           ,[BARCODE]
           ,[MCHID]
           ,[LRFLAG]
           ,[WSHT]
           ,[WBAN]
           ,[ITNBR]
           ,[ITDSC]
           ,[STA]
           ,[WDATE]
           ,[WTIME]
           ,[STKSTS]
           ,[CRTIM]
           ,[UPDTIM]
           ,[STOAREA]
           ,[INLOC]
           ,[TYRENO]
           ,[STODIV]
           ,[LOCKYN]
           ,[REMARK]
           ,[TYRESTA]
           ,[DOT]
           ,[IS_DELETE]
           ,[MCHDIV]
     from deleted o 
   end

END
GO


